		["{npc:3961}, in the inn"] = "{npc:3961}, im Gasthaus",
		["{npc:3970}: {quest:95737}, for {npc:1480} in {area:150}"] = "{npc:3970}: {quest:95737}, für {npc:1480} in {area:150}",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch. He is level 32, above you here, among level 29-30 satyrs: grouping up is advised."] = "{npc:4619} führt die Satyrn von {area:429} an; er trägt den Zweig. Er ist Stufe 32, hier über deiner Stufe, umgeben von Satyrn der Stufe 29-30: Eine Gruppe wird empfohlen.",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, der Käseladen in {object:2096}",
		["{npc:4959} and {npc:482}"] = "{npc:4959} und {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, in der Kathedrale des Lichts",
		["{object:2652}, inside"] = "{object:2652}, drinnen",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: für {npc:3961} in {area:415}",
		["{quest:1012}, taken alone"] = "{quest:1012}, allein angenommen",
		["{quest:1031}, taken alone"] = "{quest:1031}, allein angenommen",
		["{quest:95646}: the root core, inside"] = "{quest:95646}: der Wurzelkern, drinnen",
		["{quest:98815}: the hides, inside"] = "{quest:98815}: die Häute, drinnen",
		["{quest:98824}: {npc:5387} stands in the {object:32356}, north-east of the {object:32372}."] = "{quest:98824}: {npc:5387} steht in {object:32356}, nordöstlich von {object:32372}.",
		["{zone:1453} flight master"] = "Flugmeister von {zone:1453}",
		["{zone:1455} priests"] = "Priester in {zone:1455}",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to {area:42}"] = "Zurück nach {area:42}",
		["Below ground"] = "Unter der Erde",
		["Fly to {area:150}"] = "Flieg nach {area:150}",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Für {npc:1212} in {zone:1453}, im nächsten Guide",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Für {npc:482} in {zone:1453}, im nächsten Guide",
		["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it. {npc:300} is inside the ogre mound's cave: go in by the cave mouth on the mound's west side."] = "Geh von {area:42} nach Südwesten zum Ogerhügel. {object:119} steht im Lager an dessen Eingang; Splitterfaust-Oger bewachen es. {npc:300} ist in der Höhle des Ogerhügels: Geh durch den Höhleneingang an der Westseite des Hügels hinein.",
		["Hearth back to {area:42} (bound at the start of this guide): {npc:311}'s camp is at the far west of {zone:1431}."] = "Mit dem Ruhestein zurück nach {area:42} (am Anfang dieses Guides gesetzt): {npc:311}s Lager liegt ganz im Westen von {zone:1431}.",
		["Inside"] = "Drinnen",
		["Nightbane Dark Runners"] = "Dunkelläufer der Nachtheuler",
		["Nightbane Shadow Weavers"] = "Schattenwirker der Nachtheuler",
		["Nightbane Vile Fangs and Tainted Ones"] = "Faulreißer der Nachtheuler und Verderbte",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "Nur falls ein {npc:272273} {quest:96138} fallen ließ: Rechtsklick darauf",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Die Dunkelläufer streifen durch die Wälder südlich der Straße, westlich von {area:42}.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "Das Lager der Defias liegt im Südwesten des {zone:1431}, südlich von {area:94} nahe der Grenze zu {zone:1436}. Die Geldkassette steht zwischen den Zelten.",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs."] = "Die Plague Spreaders laufen in der nördlichen Hälfte des {area:492} umher. {npc:522}, ein Elite, wandert zwischen den Gräbern: Halte Abstand zu ihm.\nSkeletal Raiders, Healers und Warders halten den westlichen Teil des Friedhofs, direkt östlich des Lagers von {npc:311}.\nVorsicht: Die Skelette in den Katakomben stehen dicht beieinander, sodass du leicht zusätzliche Mobs ziehst.",
		["The grave stands among the skeletons at the cemetery's north-west corner, on the way to {npc:311}. Its quest and the next are talk-only, to {npc:268} and Commander Althea in {area:42}: level 35 quests, but no fight."] = "Das Grab steht zwischen den Skeletten an der Nordwestecke des Friedhofs, auf dem Weg zu {npc:311}. Diese Quest und die nächste sind reine Gespräche mit {npc:268} und Commander Althea in {area:42}: Quests der Stufe 35, aber ohne Kampf.",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}.\nCareful: {spell:8282} lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance.\nCareful: Gutspill, a level 32 abomination, walks these woods: let it pass."] = "Die stärksten Worgen streifen durch die Wälder südlich von {area:42}, westlich und südlich des {area:121}.\nVorsicht: {spell:8282} hält 10 Minuten an und erhöht jeden physischen Schaden, den du erleidest, um 13.\nVorsicht: Einige Worgen vor der Höhle stehen in Gruppen, darunter ein Lager mit vier. Um zusätzliche Mobs zu vermeiden, zieh sie einzeln von der erhöhten Stelle neben dem Höhleneingang.\nVorsicht: Gutspill, eine Monstrosität der Stufe 32, läuft durch diese Wälder: Lass sie vorbeiziehen.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Die Worgen halten die Wälder des Schattenhains, westlich von {area:42} und nördlich der Straße. Zieh sie einzeln.",
		["The {npc:511}"] = "{npc:511}",
		["The {npc:511} hides in the small crypt by the {area:121}, south of {area:42}. {npc:663}'s Nightbane Vile Fangs and Tainted Ones (level 29-31) roam the woods around it: they come at the end of this guide, a level later."] = "{npc:511} versteckt sich in der kleinen Gruft am {area:121}, südlich von {area:42}. {npc:663}s Faulreißer der Nachtheuler und Verderbte (Stufe 29-31) streifen durch die Wälder darum herum: Sie kommen am Ende dieses Guides, eine Stufe später.",
		["Wait a moment, then speak with her again"] = "Warte einen Moment und sprich sie dann erneut an",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Das hast du beim früheren Besuch der Route hier verpasst: Es kommt jetzt zuerst. Es geht schnell und öffnet die Quests danach.",
		["{area:42} flight master"] = "Flugmeister von {area:42}",
		["{area:492}: kill these as you meet them"] = "{area:492}: Töte diese, wenn sie dir begegnen",
		["{area:93}: kill these as you meet them"] = "{area:93}: Töte diese, sobald sie dir begegnen",
		["{item:1946}; inside"] = "{item:1946}; drinnen",
		["{item:5947}; inside"] = "{item:5947}; drinnen",
		["{npc:263}, in the town hall"] = "{npc:263}, im Rathaus",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, im Haus hinter dem Rathaus",
		["{npc:276}'s house stands at the east end of town, on the way to the flight master."] = "Das Haus von {npc:276} steht am Ostende der Stadt, auf dem Weg zum Flugmeister.",
		["{npc:276}, inside"] = "{npc:276}, drinnen",
		["{npc:311}'s Camp"] = "{npc:311}s Lager",
		["{npc:661}, by {npc:633}'s house; inside"] = "{npc:661}, beim Haus von {npc:633}; drinnen",
		["{npc:663} and {npc:661}"] = "{npc:663} und {npc:661}",
		["{npc:663}, by the town hall"] = "{npc:663}, beim Rathaus",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Taverne Zum Scharlachroten Raben",
		["{npc:840} walks around {area:42}: look inside the circle on the map"] = "{npc:840} läuft um {area:42} herum: Schau in den Kreis auf der Karte",
		["{npc:840}, at the north entrance of town; walks around {area:42}: look inside the circle on the map"] = "{npc:840}, am Nordeingang der Stadt; läuft um {area:42} herum: Schau in den Kreis auf der Karte",
		["{quest:377}, from your {area:717} run: {npc:270} is in the town hall, beside Commander Althea."] = "{quest:377} aus deinem Run durch {area:717}: {npc:270} ist im Rathaus, neben Commander Althea.",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A report for {object:2117}; inside"] = "Ein Bericht für {object:2117}; drinnen",
		["Back down the road to {area:205}: {npc:1075} wants the {object:147516} explosives under the far end of the span destroyed."] = "Zurück die Straße hinunter nach {area:205}: {npc:1075} will die Sprengstoffe von {object:147516} am fernen Ende der Brücke zerstört haben.",
		["Back east along the road to the {area:1025}: {npc:270637} camps among the Fenrunners, just west of {npc:1244}. Then west again to Menethil for the boat."] = "Zurück nach Osten entlang der Straße zum {area:1025}: {npc:270637} lagert zwischen den Fenrunners, direkt westlich von {npc:1244}. Dann wieder nach Westen nach Menethil zum Boot.",
		["Back over the span and down the road through {area:205} on the way south."] = "Zurück über die Brücke und die Straße durch {area:205} nach Süden.",
		["Back south to Menethil: {npc:1217} stands in the {area:2104}."] = "Zurück nach Süden nach Menethil: {npc:1217} steht in der {area:2104}.",
		["Back to the same murlocs; not every one drops a head."] = "Zurück zu denselben Murlocs; nicht jeder lässt einen Kopf fallen.",
		["Beat {npc:4961} and his thugs: they give up"] = "Besiege {npc:4961} und seine Schläger: Sie geben auf",
		["Below ground"] = "Unter der Erde",
		["Boat to {area:271}"] = "Schiff nach {area:271}",
		["Cathedral of Light"] = "Kathedrale des Lichts",
		["Daggerspine naga"] = "Naga der Säbelflossen",
		["Druid training"] = "Druidenausbildung",
		["Ebenezer Rustlocke"] = "Ebenezer Rustlocke",
		["Farren"] = "Farren",
		["Fly to {area:1537}"] = "Flieg nach {area:1537}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["For {npc:1284} in {zone:1453}, at the end of this guide"] = "Für {npc:1284} in {zone:1453}, am Ende dieses Guides",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Für {npc:2916} in {zone:1455}, am Ende dieses Guides",
		["Inside"] = "Drinnen",
		["Level 30 and 32 spells"] = "Zauber der Stufen 30 und 32",
		["Level 30.8"] = "Stufe 30,8",
		["Maddened Rotclaws roam the {area:1025} around {npc:1244}; one of them drops the flesh. {npc:1244} takes the quest only with {quest:98283}'s head too."] = "Maddened Rotclaws streifen durch den {area:1025} rund um {npc:1244}; einer von ihnen lässt das Fleisch fallen. {npc:1244} gibt die Quest nur, wenn du auch den Kopf von {quest:98283} hast.",
		["Murloc heads"] = "Murlocköpfe",
		["North along the coast from Menethil to the wreck of the Intrepid: {npc:1160} (30) is aboard, and the locked strongbox sits in the wreck. Careful: {npc:270589}, a level 31-32 elite, roams the {zone:1437}: give it a wide berth."] = "Von Menethil nach Norden entlang der Küste zum Wrack der Intrepid: {npc:1160} (30) ist an Bord, und die verschlossene Geldkassette steht im Wrack. Vorsicht: {npc:270589}, ein Elite der Stufe 31-32, streift durch das {zone:1437}: Mach einen großen Bogen um ihn.",
		["North along the road from {area:205} towards the {area:880}: Ebenezer Rustlocke's corpse lies under the span. Rustlocke's parchment goes back to {npc:1075}.\nTwo elite Dark Iron Saboteurs stand by the corpse inside the span: pull them one at a time, or loot the corpse and run out."] = "Nach Norden entlang der Straße von {area:205} in Richtung {area:880}: Ebenezer Rustlockes Leiche liegt unter dem Brückenbogen. Rustlockes Pergament geht zurück an {npc:1075}.\nZwei Elite-Dark-Iron-Saboteurs stehen bei der Leiche innerhalb der Brücke: Zieh sie einzeln, oder plündere die Leiche und lauf hinaus.",
		["North along the road to {area:205}. {npc:1071} and {npc:1075} stand together in the dwarves' camp on the east side of the road; the {object:147516} ruins west of it are full of elites."] = "Nach Norden entlang der Straße nach {area:205}. {npc:1071} und {npc:1075} stehen zusammen im Lager der Zwerge an der Ostseite der Straße; die Ruinen von {object:147516} westlich davon sind voller Elites.",
		["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "Geh nach Nordosten zu den {area:1038}: {npc:271338} steht an den Toren (benutze {item:279996}).",
		["Off the boat, walk up the pier into town: {npc:2711} and Lieutenant Farren stand by the inn, {npc:2430} upstairs, {npc:2382} east of it; the flight master is at the north end, {npc:2381} and {npc:2438} between her and the inn, Maleb in the town hall at the west side.\n{npc:2366} may not offer {quest:98463} on Forever: if she doesn't, skip it."] = "Geh vom Boot aus den Pier hinauf in die Stadt: {npc:2711} und Lieutenant Farren stehen beim Gasthaus, {npc:2430} oben, {npc:2382} östlich davon; der Flugmeister ist am Nordende, {npc:2381} und {npc:2438} zwischen ihr und dem Gasthaus, Maleb im Rathaus an der Westseite.\n{npc:2366} bietet {quest:98463} auf Forever vielleicht nicht an: Falls nicht, überspring sie.",
		["On the top floor"] = "Im obersten Stockwerk",
		["Over the {area:880}: the Dark Irons' cache of explosives sits by its Arathi end."] = "Über die {area:880}: Das Sprengstofflager der Dunkeleisen liegt an ihrem Arathi-Ende.",
		["Razormaw nests"] = "Razormaw-Nester",
		["Skipped {quest:474} and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the {area:133} dungeon or the {area:796} dungeon (Graveyard) instead."] = "{quest:474} übersprungen und noch unter 30,8? Töte die Bluegill-Murlocs an der Küste südlich von Menethil, bis du Stufe 30,8 hast. Oder lauf mit einer Gruppe stattdessen den Dungeon {area:133} oder den Dungeon {area:796} (Friedhof).",
		["Snapjaws"] = "Schnappkiefer",
		["South-east from Menethil to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "Nach Südosten von Menethil zum {area:1036} der Drachenmaul: Das erste Katapult steht auf dem Weg, und das {object:671518} liegt im Lager.",
		["The Perfect Razormaw Eggs for {quest:98246} lie in the raptors' nests in the hills around {quest:98283}."] = "Die Perfect Razormaw Eggs für {quest:98246} liegen in den Raptornestern in den Hügeln rund um {quest:98283}.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "Die Schnappkiefer-Schildkröten sonnen sich am Fluss östlich von {area:271}, südlich von {area:272} (Horde).",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "Die Torn-Fin-Murlocs wimmeln im {area:295}, südwestlich von {area:271}.\nVorsicht: Ein Lager enthält eine dichte Gruppe von Oracles, die alle gemeinsam angreifen.",
		["The cheese shop in the {object:2096}."] = "Der Käseladen im {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "Die Naga halten das Ufer südöstlich von {area:271}.",
		["The root core from your {area:17732} run: {npc:1244} stands by the river, just east of {npc:270637}."] = "Der Wurzelkern aus deinem Run durch {area:17732}: {npc:1244} steht am Fluss, gleich östlich von {npc:270637}.",
		["The whelps nest in the hills north-east of the {area:1036}; {quest:98283} prowls further north, and the Razormaw raptors hunt the highlands on the way north to {area:205}.\n{quest:98283} is elite: grouping up is advised."] = "Die Welpen nisten in den Hügeln nordöstlich des {area:1036}; {quest:98283} streift weiter nördlich umher, und die Razormaw-Raptoren jagen im Hochland auf dem Weg nach Norden zu {area:205}.\n{quest:98283} ist ein Elite: Eine Gruppe wird empfohlen.",
		["The yetis live in the cave in the hills north of {area:271}.\nStay in the {area:277}: the cave further north has Mountain and Giant Yetis (32-34) in pairs and {npc:13602}, a level 36 elite."] = "Die Yetis leben in der Höhle in den Hügeln nördlich von {area:271}.\nBleib in {area:277}: In der Höhle weiter nördlich gibt es Berg- und Riesenyetis (32-34) in Paaren und {npc:13602}, eine Elite der Stufe 36.",
		["The {item:270865} from your {area:17732} run: {npc:1077} is below ground in his dig, south of the road west."] = "{item:270865} aus deinem Run durch {area:17732}: {npc:1077} ist unter der Erde in seiner Ausgrabung, südlich der Straße nach Westen.",
		["The {object:2704}"] = "Die {object:2704}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. Dark Iron Dwarves, Tunnelers, Saboteurs and Demolitionists (27-31) fill the ruins west of the camp; {npc:1364} (34, elite) walks among them."] = "Das sind Elite-Mobs: Sich zusammenzutun wird empfohlen, such dir Leute dafür. Dunkeleisenzwerge, Tunnelgräber, Saboteure und Demolierer (27-31) füllen die Ruinen westlich des Lagers; {npc:1364} (34, Elite) läuft zwischen ihnen umher.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. South-east of Dun Modr, about 500 yards, the Dark Irons camp on {area:1016}: the {item:280806} lie among their tents. Then back past the camp and north to the {area:880}."] = "Das sind Elite-Mobs: Sich zusammenzutun wird empfohlen, such dir Leute dafür. Südöstlich von Dun Modr, etwa 500 Meter, liegt das Lager der Dunkeleisen auf {area:1016}: Die {item:280806} liegen zwischen ihren Zelten. Dann zurück an dem Lager vorbei und nach Norden zur {area:880}.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. The {npc:271481} is held at the far west end of the {object:147516} ruins, past level 27-30 elite dwarves, and {npc:1364} (34, elite) can be among them. Lead it east out of the ruins, then hand it in to {npc:1072} in the camp. Skip it if you are alone."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. Der {npc:271481} wird am äußersten Westende der Ruinen von {object:147516} festgehalten, hinter Elite-Zwergen der Stufe 27-30, und {npc:1364} (34, Elite) kann unter ihnen sein. Führ ihn nach Osten aus den Ruinen und gib ihn dann bei {npc:1072} im Lager ab. Überspring ihn, wenn du allein bist.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2091} is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:2091} ist ein Elite der Stufe 32: Die meisten Klassen schaffen ihn allein auf Stufe 34, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.\nVorsicht: Shadowcasters stehen zu beiden Seiten von ihm, und mindestens einer ist mit ihm verbunden und greift ein, wenn er gezogen wird. Nicht-Elite-Centurions und -Captains stehen verteilt um seinen Zeltring.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:271462}, {npc:271338}, {npc:271458} and {npc:271460} are level 32 elites, each called up by using the {item:279996} beside it. Skip them if you are alone. {npc:271462} stands in the south-eastern hills."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:271462}, {npc:271338}, {npc:271458} und {npc:271460} sind Elites der Stufe 32, die jeweils beschworen werden, indem du den {item:279996} neben ihnen benutzt. Überspring sie, wenn du allein bist. {npc:271462} steht in den südöstlichen Hügeln.",
		["Torn Fin murlocs"] = "Murlocs der Fetzenflossen",
		["Underwater"] = "Unter Wasser",
		["Use the {item:279386} at the {area:287} council."] = "Benutze den {item:279386} beim Rat von {area:287}.",
		["West along the road to Menethil."] = "Nach Westen die Straße entlang nach Menethil.",
		["West from {area:271} to the {area:286} farms."] = "Von {area:271} nach Westen zu den Farmen von {area:286}.",
		["With {quest:98283}'s head and the flesh"] = "Mit dem Kopf von {quest:98283} und dem Fleisch",
		["Yeti cave"] = "Yetihöhle",
		["grind on {npc:1418}"] = "Grinde an {npc:1418}",
		["in the camp, beside {npc:1075}"] = "im Lager, neben {npc:1075}",
		["the same corpse"] = "dieselbe Leiche",
		["{area:1038}: kill these as you meet them"] = "{area:1038}: Töte diese, sobald sie dir begegnen",
		["{area:271} flight master"] = "Flugmeister von {area:271}",
		["{area:287} council"] = "Rat von {area:287}",
		["{item:2629}, from {npc:1160}"] = "{item:2629}, von {npc:1160}",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, von {npc:2381}",
		["{npc:1073}, in the camp"] = "{npc:1073}, im Lager",
		["{npc:1074}, in the camp"] = "{npc:1074}, im Lager",
		["{npc:1075} again"] = "Noch einmal {npc:1075}",
		["{npc:1077}, below ground"] = "{npc:1077}, unter der Erde",
		["{npc:1077}: for {npc:5387} in {zone:1455}, at the end of this guide"] = "{npc:1077}: für {npc:5387} in {zone:1455}, am Ende dieses Guides",
		["{npc:1356}, {npc:2916} and {npc:5637} stand in the {object:32356}, north-east of the flight master."] = "{npc:1356}, {npc:2916} und {npc:5637} stehen im {object:32356}, nordöstlich des Flugmeisters.",
		["{npc:2094} stands by the docks; {npc:1239} sits in the {area:2104}, south of the keep."] = "{npc:2094} steht an den Docks; {npc:1239} sitzt in der {area:2104}, südlich der Burg.",
		["{npc:2104} stands on the top floor of {area:2103}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2104} steht im obersten Stockwerk von {area:2103}: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:2104}: for {npc:270637}, back east along the road"] = "{npc:2104}: für {npc:270637}, zurück nach Osten entlang der Straße",
		["{npc:2228}, inside"] = "{npc:2228}, drinnen",
		["{npc:2382}: the lions come later"] = "{npc:2382}: Die Löwen kommen später",
		["{npc:2430}, upstairs"] = "{npc:2430}, oben",
		["{npc:2438} makes a yeti fur cloak for anyone who brings a {item:3719} ({skill:165}) and a {item:2997} ({skill:197}); no vendor sells either, so this step shows only when you carry both."] = "{npc:2438} fertigt einen Yeti-Fellumhang für alle, die einen {item:3719} ({skill:165}) und einen {item:2997} ({skill:197}) bringen; kein Händler verkauft eines von beiden, deshalb erscheint dieser Schritt nur, wenn du beide bei dir hast.",
		["{npc:2438}, between the flight master and the inn: he wants a {item:3719} and a {item:2997} too"] = "{npc:2438}, zwischen dem Flugmeister und dem Gasthaus: Er will auch einen {item:3719} und einen {item:2997}",
		["{npc:251493} stands north-west of the flight master, on the way north to the yeti cave.\n{quest:98059}: {npc:251493} hands you a {item:279386} for the {area:287} council, in the farms west of {area:271}."] = "{npc:251493} steht nordwestlich des Flugmeisters, auf dem Weg nach Norden zur Yetihöhle.\n{quest:98059}: {npc:251493} gibt dir eine {item:279386} für den Rat von {area:287} in den Farmen westlich von {area:271}.",
		["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}: für König Magni, beim selben Halt in {zone:1455}",
		["{npc:2708} and {npc:4078} are in the {object:2164}; {npc:5081} south of the {object:2101}."] = "{npc:2708} und {npc:4078} sind im {object:2164}; {npc:5081} südlich des {object:2101}.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: Seine Spur führt nach Arathi",
		["{npc:271458} stands in the hills between the {area:1038} and {area:205} (use the {item:279996})."] = "{npc:271458} steht in den Hügeln zwischen dem {area:1038} und {area:205} (benutze den {item:279996}).",
		["{npc:271460} stands in the ruins of {area:205} (use the {item:279996})."] = "{npc:271460} steht in den Ruinen von {area:205} (benutze den {item:279996}).",
		["{npc:4078}: the Saltstone Basilisks at the {area:2240} drop the scales, in the next guide"] = "{npc:4078}: Die Saltstone Basilisks an der {area:2240} lassen die Schuppen fallen, im nächsten Guide",
		["{npc:4455}, by the keep's door: for {quest:1132} in Theramore, in the next guide"] = "{npc:4455}, an der Tür der Festung: für {quest:1132} in Theramore, im nächsten Guide",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} wartet in der Taverne „Zum Schwein und Pfeife“ in {object:2100}; er und seine zwei Schläger greifen dich an, hören aber auf, sobald sie besiegt sind.",
		["{object:2652}, inside"] = "{object:2652}, drinnen",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: für {npc:2104}",
		["{quest:303} is a group quest: 30 elite Dark Irons (27-31) in the ruins west of the camp. Skip it if you are alone."] = "{quest:303} ist eine Gruppenquest: 30 Elite-Dunkeleisen (27-31) in den Ruinen westlich des Lagers. Überspring sie, wenn du allein bist.",
		["{quest:88756} is a group quest: the {item:280806} lie in the {object:147516} camp on {area:1016}, south-east of {area:205}, among the same elite dwarves. Skip it if you are alone."] = "{quest:88756} ist eine Gruppenquest: Die {item:280806} liegen im Lager der {object:147516} auf {area:1016}, südöstlich von {area:205}, zwischen denselben Elite-Zwergen. Überspring sie, wenn du allein bist.",
		["{quest:98246}: the eggs"] = "{quest:98246}: die Eier",
		["{zone:1455} flight master"] = "Flugmeister von {zone:1455}",
		["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455} hat keinen Druidenlehrer: {npc:5504} steht in {zone:1453}, nordwestlich des {object:2101}.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Boat to {area:17203}"] = "Boot nach {area:17203}",
		["Escort {npc:5644}"] = "{npc:5644} eskortieren",
		["Fly to {area:442}"] = "Flieg nach {area:442}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Folge der Straße nach Westen an {area:460} (Horde) vorbei und nach Südwesten durch {area:465} nach {zone:1443}; {area:608} liegt oben am Pass.",
		["For {npc:5638}, at the end of this guide"] = "Für {npc:5638}, am Ende dieses Guides",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "Ihr Bruder {npc:5643} (36) läuft mit den Kultisten der Brennenden Klinge (30-33) durch die Festung: Zieh ihn allein. Der {npc:13019} hält das Zepter im Hauptgebäude der Festung. {npc:5642} will vier von jeder Art Kultist auf dem Weg.",
		["Inside"] = "Drinnen",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Führ {npc:5644} aus der Festung; sie geht ihrer Wege, sobald ihr draußen seid. {npc:5642} nimmt die Abgabe am Ende des Guides in {area:608} entgegen.",
		["Malem chest"] = "Truhe der Malems",
		["Out of Thunder Axe Fortress"] = "Raus aus der Festung Thunder Axe",
		["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "Schwimm hinaus nach {area:2406} vor der äußersten Nordspitze: {object:177786} steht am Ufer neben der {object:177673}. Öffne sie mit beiden Schlüsseln; lass die Statue in Ruhe.",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks."] = "Die Hatefury-Satyrn halten die Ruinen von {area:603}, östlich von {area:608}.\nVorsicht: Hatefury Rogues spawnen getarnt, und Hatefury Tricksters haben bei ihren Angriffen einen Gift-Proc.",
		["The chest lies in the ruins south-west of {area:608}."] = "Die Truhe liegt in den Ruinen südwestlich von {area:608}.",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "Das Schiffswrack liegt direkt südwestlich von {npc:11863}s Turm; seine Truhe steht neben {object:177787}.",
		["on an Aged, Dying or {npc:4702} in the graveyard; don't kill it"] = "an einem Aged Kodo, Dying Kodo oder {npc:4702} auf dem Friedhof; töte es nicht",
		["the tamed kodo, at {npc:11596}'s camp: talk to it, five times"] = "das gezähmte Kodo, im Lager von {npc:11596}: sprich fünfmal mit ihm",
		["{area:608} flight master"] = "Flugmeister von {area:608}",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, von den Trockenschnappkrabben",
		["{item:6767}; inside"] = "{item:6767}; drinnen",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}s Lager liegt an der Straße südlich von {area:609}, beim {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}s Turm steht auf dem Hügel westlich von {area:599}: Nimm zuerst seine Quest an, das Zepter, das er will, ist in der Festung.",
		["{npc:5396}, beside {npc:5752}"] = "{npc:5396}, neben {npc:5752}",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}: Die Truhe des Wracks liegt unterhalb von {npc:11863}s Turm, auf dem Weg nach {area:599}",
		["{npc:5642}: the Burning Blade in {area:599}, where her search leads"] = "{npc:5642}: die Brennende Klinge in {area:599}, wohin ihre Suche führt",
		["{npc:5643} and the Seer"] = "{npc:5643} und der Seher",
		["{npc:5644}, inside"] = "{npc:5644}, drinnen",
		["{npc:5752}: the Kolkar are at the end of this guide"] = "{npc:5752}: Die Kolkar kommen am Ende dieses Guides",
		["{quest:5741}; on the top floor"] = "{quest:5741}; im obersten Stockwerk",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Boat to {area:35}"] = "Boot nach {area:35}",
		["Crystalized Scale, from the Saltstone Basilisks: eight for {npc:4078} in {zone:1453}"] = "Crystalized Scale, von den Saltstone Basilisks: acht für {npc:4078} in {zone:1453}",
		["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "Nach Osten durch die Schluchten. {area:484}, ein Hordenlager mit Wachen, liegt hier auf dem Tafelberg: Bleib unten in der Schlucht und halte großen Abstand zum Fuß seiner Aufzüge.",
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Fly to {area:150}"] = "Flieg nach {area:150}",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Folge den Schluchten nach Osten zur Salzebene. Die Goblins und Gnome der {area:2240} sind neutral und geben beiden Fraktionen Quests.",
		["For {npc:1416} in {zone:1453}, after Stranglethorn"] = "Für {npc:1416} in {zone:1453}, nach Schlingendorn",
		["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "Für {quest:1132} im Gasthaus von Theramore, wohin das Boot dieses Guides fährt",
		["For {quest:5762} in Stranglethorn, later"] = "Für {quest:5762} im Schlingendorntal, später",
		["From the raceway follow the road south out of the {area:439} into {zone:1446}."] = "Folge von der Rennstrecke der Straße nach Süden aus {area:439} hinaus nach {zone:1446}.",
		["Inside"] = "Drinnen",
		["Into {zone:1413}"] = "Hinein nach {zone:1413}",
		["Into {zone:1446}"] = "Hinein nach {zone:1446}",
		["Lightforge Ingots"] = "Lichtschmiedeblöcke",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "Auf der Straße nach Süden durch das {zone:1413} lagert {npc:6244} östlich der Straße, nordöstlich von {area:378}; komm von Osten und halte dich von den Wachen der Horde fern.",
		["Tapoke Jahn (34) slips out of the tavern once you take {quest:1248}: stay close behind him. He turns on you outside, a friend joins him, and he gives up once badly hurt. If you lose him the quest fails: abandon it and take it again from {npc:4963}."] = "Tapoke Jahn (34) schleicht sich aus der Taverne, sobald du {quest:1248} annimmst: Bleib dicht hinter ihm. Draußen greift er dich an, ein Freund schließt sich ihm an, und er gibt auf, sobald er schwer verletzt ist. Verlierst du ihn, schlägt die Quest fehl: Brich sie ab und nimm sie erneut bei {npc:4963} an.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Die Murlocs der Blaukiemen am Strand südwestlich von Menethil tragen die Blöcke.",
		["The canyons east of {area:482}"] = "Die Schluchten östlich von {area:482}",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "Der Flugmeister steht am Tor von {area:514}; {npc:5083} und {npc:4964} sind in der Zitadelle.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "Das Wrack der Flying Osprey liegt im seichten Wasser südlich der Burg.",
		["Theramore"] = "Theramore",
		["{area:2240}: kill these as you meet them"] = "{area:2240}: Töte diese, sobald sie dir begegnen",
		["{area:976} flight master"] = "Flugmeister von {area:976}",
		["{area:976} is a short walk down the road; keep to it. {npc:7823}, the Alliance flight master, stands inside the walls."] = "{area:976} ist ein kurzer Fußweg die Straße hinunter; bleib auf ihr. {npc:7823}, der Flugmeister der Allianz, steht hinter den Mauern.",
		["{item:2702}; underwater"] = "{item:2702}; unter Wasser",
		["{item:5795}, from the Sparkleshell Tortoises"] = "{item:5795}, von den Spiegelpanzerschildkröten",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217} steht in der {area:2104} südlich der Burg, wo auch {npc:4963} und {npc:5082} warten.",
		["{npc:4454}: for Martek in the {zone:1418}, at the end of 30-40"] = "{npc:4454}: für Martek in {zone:1418}, am Ende von 30-40",
		["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455} steht an der Tür von {area:2103}, direkt nördlich des Flugmeisters.",
		["{npc:4456}'s next errand goes to {area:415}, off this route: leave it."] = "Der nächste Auftrag von {npc:4456} führt nach {area:415}, abseits dieser Route: Lass ihn aus.",
		["{npc:4964}, on the top floor"] = "{npc:4964}, im obersten Stockwerk",
		["{npc:5083}, on the top floor"] = "{npc:5083}, im obersten Stockwerk",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}, im Gasthaus im Norden der Stadt",
		["{quest:1132}: the wyverns are in {zone:1441}, later in this guide"] = "{quest:1132}: Die Wyverns sind in {zone:1441}, weiter hinten in diesem Guide",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: in {zone:1440}, auf dem Weg nach {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: der Inkubus, neben dem Sukkubus; das {item:190309} liegt nahe {quest:1738}",
		["{zone:1453} flight master"] = "Flugmeister von {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back east to Nesingwary's camp on the way north to the {area:99}."] = "Zurück nach Osten zu Nesingwarys Lager auf dem Weg nach Norden zum {area:99}.",
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Zurück nach Süden an Nesingwary vorbei: Panther und Schlingendornraptoren laufen auf den Lichtungen westlich des Lagers Richtung Küste; die Alten Schlingendorntiger halten die Hügel im Südwesten.",
		["Boat to {area:35}"] = "Boot nach {area:35}",
		["Both roam the grass around the camp and along the road north."] = "Beide streifen durch das Gras um das Lager und entlang der Straße nach Norden.",
		["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Vorsicht: Trollcamps liegen nahe beim Tigergebiet, und Trolle können in einen Kampf eingreifen, wenn du unvorsichtig ziehst.\nVorsicht: Im Raptornest sind junge Raptoren, die in den Kampf eingreifen, wenn du die ausgewachsenen angreifst.",
		["Class training"] = "Klassentraining",
		["Fly to {area:415}"] = "Flieg nach {area:415}",
		["Fly to {area:467}"] = "Flieg zum {area:467}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the main road north the length of the jungle, past the {object:3202} turn-off, to the hunters' camp just west of the road."] = "Folge der Hauptstraße nach Norden durch den ganzen Dschungel, an der Abzweigung zum {object:3202} vorbei, zum Jägerlager direkt westlich der Straße.",
		["From Nesingwary's camp head west to the {area:310} near the coast; the Crystal Spine Basilisks around it drop the shards.\nThe haunted island lies just off the coast south-west of the mine: just reach its edge. Careful: its Lesser Water Elementals are 36-37: don't stay. The Bloodscalp ruins of Zul'Kunda to the north wait for the second Stranglethorn loop."] = "Von Nesingwarys Lager westwärts zur {area:310} nahe der Küste; die Kristallrückenbasilisken um sie herum lassen die Splitter fallen.\nDie Spukinsel liegt direkt vor der Küste südwestlich der Mine: Erreiche einfach ihr Ufer. Vorsicht: ihre Geringen Wasserelementare sind 36-37: Bleib nicht stehen. Die Blutskalp-Ruinen von Zul'Kunda im Norden warten auf die zweite Schlingendorntal-Runde.",
		["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then take the road west to Stonetalon."] = "Von {area:415} geh nach Nordwesten in die Hügel: {quest:1738} ist ein leuchtender Baum nördlich der Straße nach {area:413}. Falls du {quest:65602} angenommen hast, liegt die {item:190309} in einem Haus zwischen den Bäumen nördlich von {area:413} (26.6,22.0). Nimm dann die Straße nach Westen zum Steinkrallengebirge.",
		["Gluggle (37, rare) on the coast west of camp drops the {item:4614}: four levels over you, leave him unless you are grouped"] = "Gluckser (37, Rare) an der Küste westlich des Lagers lässt den {item:4614} fallen: vier Stufen über dir, lass ihn aus, außer du bist in einer Gruppe",
		["Hearth back to {area:35}."] = "Kehr per Ruhestein nach {area:35} zurück.",
		["Level 33.2"] = "Stufe 33,2",
		["North to {area:100}"] = "Nach Norden zur {area:100}",
		["Panthers, raptors and elder tigers"] = "Panther, Raptoren und Alte Tiger",
		["River Crocolisks (30-31) swim the river right beside Nesingwary's camp and up toward the {area:99}."] = "Flusskrokilisken (30-31) schwimmen im Fluss direkt neben Nesingwarys Lager und hinauf Richtung {area:99}.",
		["River crocolisks"] = "Flusskrokilisken",
		["Stranglethorn Tigers"] = "Schlingendorntiger",
		["Take the road north; the camp sits in the hills to the west.\n{npc:738} offers {quest:215} only while he is out of the camp: about every half hour he walks down the path to the road, where two Kurzen's Agents ambush him. Help him kill them and take the quest at once, before he walks back up. He isn't there? Leave it: the guide passes {quest:200}, which follows from it, as well.\n{npc:738} spends most of his time at the top of the {area:99}'s path, by the huts, and now and then walks down it to the road and back (about eight minutes). If he isn't at the arrow, look along that path."] = "Nimm die Straße nach Norden; das Lager liegt in den Hügeln im Westen.\n{npc:738} bietet {quest:215} nur an, solange er außerhalb des Lagers ist: Etwa jede halbe Stunde geht er den Pfad zur Straße hinab, wo zwei Kurzens Agenten ihm auflauern. Hilf ihm, sie zu töten, und nimm die Quest sofort an, bevor er wieder hinaufgeht. Ist er nicht da? Lass es: Der Guide kommt später auch bei {quest:200} vor, das daran anschließt.\n{npc:738} verbringt die meiste Zeit oben am Ende des Pfads des {area:99}, bei den Hütten, und geht hin und wieder hinab zur Straße und zurück (etwa acht Minuten). Ist er nicht beim Pfeil, suche entlang dieses Pfads.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. {quest:200}'s records lie in a hut on the compound's west side. Careful: Kurzen Elites and Witch Doctors (36) hold the compound's eastern half, by the cave: stay on its west side."] = "Die Kurzen-Rebellen halten das Lager östlich des {area:99}; arbeite am Außenrand, wo Jungle Fighters und Medicine Men stehen, und plündere die Vorratskisten bei den Zelten. Die Aufzeichnungen von {quest:200} liegen in einer Hütte an der Westseite des Komplexes. Vorsicht: Elitekämpfer und Hexendoktoren der Kurzen (36) halten die östliche Hälfte des Komplexes, bei der Höhle: Bleib auf seiner Westseite.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Die ausgewachsenen Tiger streifen durch die Hügel gleich südlich und westlich des Lagers.",
		["The boat from {area:392}'s dock crosses to {area:35}, on Stranglethorn's southern cape."] = "Das Boot vom Steg von {area:392} fährt nach {area:35}, auf Schlingendorntals südlicher Landspitze.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Die Alten Schlingendorntiger kommen später, auf dem Rückweg vom {area:99}",
		["The elder tigers next are 34-35: short of 33.2? Keep on the Kurzen Jungle Fighters and Medicine Men around the compound's outer edge until level 33.2. Or, with a group, run the {area:796} dungeon (Library) instead."] = "Die Alten Tiger als Nächstes sind 34-35: Noch unter 33,2? Bleib bei Kurzens Dschungelkämpfern und Medizinmännern am Außenrand des Komplexes, bis du Stufe 33,2 hast. Oder lauf mit einer Gruppe stattdessen den Dungeon {area:796} (Bibliothek).",
		["The haunted island"] = "Die Spukinsel",
		["The hunters' tents stand just west of the road. {npc:773}'s {quest:201} only asks you to look around it."] = "Die Zelte der Jäger stehen direkt westlich der Straße. {npc:773}s {quest:201} will nur, dass du dich dort umsiehst.",
		["The road to {area:608}"] = "Die Straße nach {area:608}",
		["The strongbox is deeper in, by the cave: on the northern loop (04b)"] = "Die Geldkassette ist weiter drinnen, bei der Höhle: auf der nördlichen Runde (04b)",
		["Warlocks fly to {area:415} for the {quest:1738}, on the way west."] = "Hexenmeister fliegen auf dem Weg nach Westen für {quest:1738} nach {area:415}.",
		["You know the {area:467} flight: it lands closer to {zone:1443} than {area:415} does. From the peak, follow the road south through the mountains to the {area:465}."] = "Du kennst die Flugroute zum {area:467}: Sie landet näher an {zone:1443} als {area:415}. Folge vom Gipfel der Straße nach Süden durch die Berge ins {area:465}.",
		["Young tigers and panthers"] = "Junge Tiger und Panther",
		["Your level 34 ranks: the class trainers stand around the {object:2096}, {object:2100}, the Cathedral and the {object:2101}; {npc:5504}, the druid trainer, stands north-west of the {object:2101}. Shamans train in {zone:1455}, later in 30-40."] = "Deine Ränge für Stufe 34: Die Klassenlehrer stehen um {object:2096}, {object:2100}, die Kathedrale und das {object:2101}; {npc:5504}, der Druidenlehrer, steht nordwestlich des {object:2101}. Schamanen lernen in {zone:1455}, später in 30-40.",
		["grind on {npc:937}"] = "Grinde an {npc:937}",
		["keep it: the Lashtail Raptors come on the second loop (04b), around {npc:729}'s hill"] = "Behalte sie: Die Schmetterschwänze kommen in der zweiten Runde (04b), rund um den Hügel von {npc:729}",
		["keep it: the Shadowmaw Panthers (37-38) wait for the 40-50 Stranglethorn guide"] = "Behalte sie: Die Schattentatzenpanther (37-38) warten auf den Schlingendorn-Guide für 40-50",
		["{area:101}: kill these as you meet them"] = "{area:101}: Töte diese, sobald sie dir begegnen",
		["{area:35} flight master"] = "Flugmeister von {area:35}",
		["{area:442} flight master"] = "Flugmeister von {area:442}",
		["{item:190309}, north of {area:413}"] = "{item:190309}, nördlich von {area:413}",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, aus einer Kiste von {object:263}",
		["{npc:2495}, by the bank; inside"] = "{npc:2495}, bei der Bank; drinnen",
		["{npc:2495}, inside"] = "{npc:2495}, drinnen",
		["{npc:2495}: the Snapjaw Crocolisks, on the northern loop"] = "{npc:2495}: die Snapjaw Crocolisks, auf der nördlichen Runde",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, oben in der Taverne",
		["{npc:2496}: the water elementals rise around the haunted island, on the northern loop"] = "{npc:2496}: Die Wasserelementare steigen rund um die Geisterinsel auf, auf der nördlichen Runde",
		["{npc:2498}, inside"] = "{npc:2498}, drinnen",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, im {object:56910}; oben",
		["{npc:4078} is in the {object:2164}, in the {object:2101}."] = "{npc:4078} ist im {object:2164}, im {object:2101}.",
		["{npc:469}, in the hut"] = "{npc:469}, in der Hütte",
		["{npc:469}: {quest:200}'s records lie at the edge of {area:101}, next"] = "{npc:469}: Die Aufzeichnungen von {quest:200} liegen am Rand von {area:101}, als Nächstes",
		["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}, {object:56910}; oben",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, aus {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} sammelt die {item:2755}: Die Seiten lässt fast jeder Humanoide im Dschungel fallen. Füg die Seiten unterwegs zu Kapiteln zusammen.",
		["{npc:737}'s Bloodscalp ears wait for the second Stranglethorn loop: keep the quest."] = "Die Bloodscalp-Ohren für {npc:737} warten auf die zweite Runde durch Schlingendorn: Behalte die Quest.",
		["{npc:737}, in the tavern"] = "{npc:737}, in der Taverne",
		["{npc:738}, at the foot of the path"] = "{npc:738}, am Fuß des Pfads",
		["{npc:738}: at the top of the path by the huts, or on his walk down it"] = "{npc:738}: oben am Ende des Pfads bei den Hütten, oder auf seinem Weg hinab",
		["{npc:770}: for {npc:773} in {area:35}, later in this guide"] = "{npc:770}: für {npc:773} in {area:35}, weiter hinten in diesem Guide",
		["{npc:773}, from {npc:770}"] = "{npc:773}, von {npc:770}",
		["{npc:773}, in the tavern; upstairs: {npc:738} is at the {area:99}, on the way"] = "{npc:773}, in der Taverne; oben: {npc:738} ist beim {area:99}, auf dem Weg",
		["{npc:773}, upstairs"] = "{npc:773}, oben",
		["{npc:773}: Nesingwary's camp, on the way"] = "{npc:773}: Nesingwarys Lager, auf dem Weg",
		["{object:287}, in the hut"] = "{object:287}, in der Hütte",
		["{object:661516}, a looted crate west of Nesingwary's camp: the Stolen Shipments lie in the Bloodscalp ruins on the coast, for the second Stranglethorn loop"] = "{object:661516}, eine geplünderte Kiste westlich von Nesingwarys Lager: Die Gestohlenen Lieferungen liegen in den Ruinen der Bloodscalp an der Küste, für die zweite Runde durch Schlingendorn",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: Sieh dich einfach im Lager der Jäger um",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434}: Töte diese, sobald sie dir begegnen",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "„Sea Wolf“ MacKinley, im obersten Stockwerk",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "Nach Osten zu {area:101}: Herods Aufzeichnungen liegen in einer Hütte auf der Westseite.",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["For Archmage Ansirem in {zone:1416}"] = "Für Erzmagier Ansirem im {zone:1416}",
		["For characters of 35 to 36, but several quests here are level 37-38: on purpose, for their experience. The water elementals are 36-37: pull them one at a time."] = "Für Charaktere der Stufe 35 bis 36, aber mehrere Quests hier sind Stufe 37-38: mit Absicht, wegen ihrer Erfahrung. Die Wasserelementare sind 36-37: Zieh sie einzeln.",
		["For {npc:4631} in {area:35}, at the end of this loop"] = "Für {npc:4631} in {area:35}, am Ende dieser Runde",
		["From {zone:1431} take the road south; the camp sits in the hills west of the road."] = "Nimm von {zone:1431} die Straße nach Süden; das Lager liegt in den Hügeln westlich der Straße.",
		["In the {object:2164}, if you still carry it"] = "Im {object:2164}, falls du es noch bei dir hast",
		["Into {zone:1434}"] = "Hinein nach {zone:1434}",
		["North along the coast to the ruins on the hill: the last two tablets lie there. {npc:268992}, a goblin, is caged beside the third tablet: any Bloodscalp can drop his {item:277957}, then lead him out of the ruins. The Stolen Shipments lie at the ruins' east edge. Pick up Green Hills pages as they drop.\nCareful: the Bloodscalp Berserkers, Headhunters and Witch Doctors (36-37) hold the ruins' core: pull them one at a time."] = "Nach Norden die Küste entlang zu den Ruinen auf dem Hügel: Dort liegen die letzten beiden Tafeln. {npc:268992}, ein Goblin, sitzt neben der dritten Tafel in einem Käfig: Jeder Bloodscalp kann seinen {item:277957} fallen lassen; führ ihn dann aus den Ruinen. Die Gestohlenen Lieferungen liegen am Ostrand der Ruinen. Sammle Green-Hills-Seiten ein, wenn sie fallen.\nVorsicht: Die Berserker, Kopfjäger und Hexendoktoren der Bloodscalp (36-37) halten das Zentrum der Ruinen: Pull sie einzeln.",
		["North-east up the road to the {area:99}, then back south through the jungle."] = "Nach Nordosten die Straße hinauf zum {area:99}, dann zurück nach Süden durch den Dschungel.",
		["Snapjaw Crocolisks"] = "Schnappkieferkrokilisken",
		["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to {area:35}."] = "Schnappkieferkrokilisken sonnen sich am Fluss mitten im Dschungel, auf dem Weg nach Süden nach {area:35}.",
		["South along the road: the hunters' tents stand just west of it. {npc:717} and Hemet gave you these on the first loop: take them now only if you didn't."] = "Nach Süden entlang der Straße: Die Zelte der Jäger stehen gleich westlich davon. {npc:717} und Hemet haben dir diese in der ersten Runde gegeben: Nimm sie jetzt nur an, falls nicht.",
		["The Lashtail raptors"] = "Die Schmetterschwanzraptoren",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "Die Spukinsel liegt direkt vor der Küste westlich der zweiten Tafel: Die Geringen Wasserelementare steigen aus dem Wasser um sie herum.",
		["The jungle ruins"] = "Die Dschungelruinen",
		["The {area:102}"] = "Die {area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west.\nCareful: the Saltscale murlocs on the shore near the second tablet are elite (35-37): swim to the tablet from the water and keep clear of them."] = "Nach Westen durch den Dschungel zu den Trollruinen: Jede birgt eine Steintafel der Trolllegenden, die ersten beiden in den Ruinen südwestlich von Nesingwarys Lager, die letzten beiden auf dem Hügel im Nordwesten.\nVorsicht: Die Saltscale-Murlocs am Ufer nahe der zweiten Tafel sind Elites (35-37): Schwimm vom Wasser aus zur Tafel und halte Abstand zu ihnen.",
		["keep it: the Skullsplitter Witch Doctors (41-42) wait for the 40-50 Stranglethorn guide"] = "behalten: Die Hexendoktoren der Skullsplitter (41-42) warten auf den Schlingendorntal-Guide 40-50",
		["{item:2006}: {object:58}; underwater"] = "{item:2006}: {object:58}; unter Wasser",
		["{item:277957}, from the Bloodscalp trolls"] = "{item:277957}, von den Blutskalptrollen",
		["{npc:218230}, a cook, is caged at the compound's western edge: take his quest now and keep it, his cage key and the fighter's uniform come on the 40-50 Stranglethorn guide, when the Subchiefs and Elites are your level. Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}. {npc:813}, an elite of 39-40, stands at the compound's north end: leave him be."] = "{npc:218230}, ein Koch, sitzt am Westrand des Komplexes in einem Käfig: Nimm seine Quest jetzt an und behalte sie. Sein Käfigschlüssel und die Kämpferuniform kommen im Schlingendorn-Guide für 40-50, wenn die Unterhäuptlinge und Elites deine Stufe haben. Kopfschrumpfer stehen tiefer im Komplex; die Kommandosoldaten lauern getarnt rundherum und in der Höhle, und Herods Geldkassette liegt am Höhleneingang. Sammle Green-Hills-Seiten ein, wenn sie fallen.\nVorsicht: Kurzens Kommandosoldaten sind Stufe 34-35, keine Elites, und spawnen oft getarnt; kurz vor dem Tod benutzen sie {spell:7964}. {npc:813}, ein Elite der Stufe 39-40, steht am Nordende des Komplexes: Lass ihn in Ruhe.",
		["{npc:218230}, in his cage"] = "{npc:218230}, in seinem Käfig",
		["{npc:2495}, inside"] = "{npc:2495}, drinnen",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, oben in der Taverne",
		["{npc:2498}, inside"] = "{npc:2498}, drinnen",
		["{npc:268992}, in his cage beside the third tablet"] = "{npc:268992}, in seinem Käfig neben der dritten Tafel",
		["{npc:4631}, on the docks"] = "{npc:4631}, an den Docks",
		["{npc:715}: the Jungle Stalkers come in 40-50"] = "{npc:715}: Die Dschungelpirscher kommen in 40-50",
		["{npc:733}: the Commandos and Headshrinkers fell in the compound"] = "{npc:733}: Die Commandos und Headshrinkers im Komplex erledigen",
		["{npc:737}, upstairs"] = "{npc:737}, oben",
		["{npc:773}, upstairs"] = "{npc:773}, oben",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773}, oben: Diese optionale Quest braucht vier {item:4278}. Bau Geringe Blutsteinablagerungen in {zone:1417} mit {skill:186} 75 ab, kauf das Erz im Auktionshaus oder frag einen befreundeten Bergarbeiter. Die Kobolde lassen es nicht fallen; überspring diese Quest, wenn du nicht an das Erz kommst.",
		["{npc:941}, below ground"] = "{npc:941}, unter der Erde",
		["{object:287}, upstairs"] = "{object:287}, oben",
		["{object:288}, below ground"] = "{object:288}, unter der Erde",
		["{zone:1453} flight master"] = "Flugmeister von {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A group stop: two level 40 water elementals ambush {npc:2768}'s escort, and the Daggerspine naga in the reef are 38-40, with Sorceresses among them. Grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nSouth along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Ein Gruppenhalt: Zwei Wasserelementare der Stufe 40 überfallen die Eskorte von {npc:2768}, und die Naga der Dolchrücken im Riff sind 38-40, darunter Zauberinnen. Eine Gruppe wird empfohlen, such dir Mitspieler dafür. Überspring es, wenn du allein bist.\nNach Süden entlang der Westküste zur Bucht der Goblins; Lolo hält auf den Felsen darüber Wache.",
		["A {npc:2434} (37-38) lurks stealthed on the edge of {area:271}, and few players find him. Careful: he is a level or two over you; fight him only at full health, or leave him. His contract goes to {npc:2276}. Don't wait for him: the rest of this step doesn't need him."] = "Ein {npc:2434} (37-38) lauert getarnt am Rand von {area:271}, und nur wenige Spieler finden ihn. Vorsicht: Er ist ein oder zwei Stufen über dir; kämpfe nur mit voller Gesundheit gegen ihn oder lass ihn in Ruhe. Sein Vertrag geht an {npc:2276}. Warte nicht auf ihn: Der Rest dieses Schritts braucht ihn nicht.",
		["Back out of the grate to Modera's camp on the lake shore."] = "Durch das Gitter zurück nach draußen zu Moderas Lager am Seeufer.",
		["Back west through {zone:1430} to {area:42}."] = "Zurück nach Westen durch {zone:1430} nach {area:42}.",
		["Below ground"] = "Unter der Erde",
		["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps north of the village. Leave him be."] = "Vorsicht: Spione und Auftragsmörder des Syndikats können getarnt sein. Auftragsmörder vergiften dich außerdem.\nVorsicht: {npc:2306} (40) taucht jeweils an einem Ort auf: im Keller des Gasthauses von {area:280} oder in einem der Zeltlager des Syndikats nördlich des Dorfes. Lass ihn in Ruhe.",
		["City of Dalaran"] = "City of Dalaran",
		["Crushridge ogres"] = "Crushridge-Oger",
		["East along the road to the {area:76}. The {quest:1389} are the glowing blue crystals among the Lost Ones' tents: click them. Any {npc:254797} counts for {npc:254775}, and the Lost One Fishermen on the sanctuary's west side carry {npc:254770}'s {item:258530}. {quest:1392} walks a long path through the ruins; his cudgel starts a quest for {npc:1776}. Don't wait for him.\nCareful: Noboru is level 39, two over you here: fight him only with a friend or from level 38; otherwise let him pass."] = "Nach Osten die Straße entlang zum {area:76}. Die {quest:1389} sind die leuchtend blauen Kristalle zwischen den Zelten der Verirrten: Klick sie an. Jeder {npc:254797} zählt für {npc:254775}, und die Angler der Verirrten auf der Westseite des Refugiums tragen {npc:254770}s {item:258530}. {quest:1392} läuft einen langen Weg durch die Ruinen; sein Knüppel startet eine Quest für {npc:1776}. Warte nicht auf ihn.\nVorsicht: Noboru ist Stufe 39, zwei über dir: Kämpf nur mit einem Freund oder ab Stufe 38 gegen ihn; sonst lass ihn vorbeiziehen.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "Nach Osten von {quest:681} quer durch den Norden des Hochlands; die Splitter glitzern auf dem Hügel bei {area:333}, nördlich von {area:314}.",
		["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Eskortiere den Professor den Hügel hinauf zur Höhle über der Bucht und beschütze ihn, während er arbeitet. Zwei Wasserelementare der Stufe 40 greifen ihn dort aus dem Hinterhalt an, und sie sind immun gegen Frost. Halt sie am Höhleneingang fest, weg von ihm: Findet der Kampf in der Höhle statt, mischt er sich ein, statt zu arbeiten, und es kommen immer mehr Elementare nach.",
		["Fly to {area:144}"] = "Flieg nach {area:144}",
		["Fly to {area:271}"] = "Flieg nach {area:271}",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings."] = "Folge der Straße von {area:271} nach Norden in die Berge. Berglöwen streifen über die Hänge; das Syndikat in {area:280} trägt die Siegelringe.",
		["Follow the road north to the draenei of the {area:657}. {npc:254775} and {npc:254770} stand beside {npc:1776}: their Lost Ones are the ones you meet in the {area:76} anyway."] = "Folge der Straße nach Norden zu den Draenei der {area:657}. {npc:254775} und {npc:254770} stehen neben {npc:1776}: Ihre Verirrten sind die, denen du im {area:76} ohnehin begegnest.",
		["For your City of Dalaran run, next: the {npc:269127} wants the arcane remnants in the city thinned out and a mote from the heart of the disruption. {quest:92458} brings the {item:277507}, which opens the grate."] = "Für deinen Run durch die City of Dalaran, als Nächstes: {npc:269127} will, dass du die arkanen Überreste in der Stadt ausdünnst, und ein Partikel aus dem Herzen der Störung. {quest:92458} bringt dir {item:277507}, der das Gitter öffnet.",
		["For {npc:1356} in {zone:1455}, at the end of this guide"] = "Für {npc:1356} in {zone:1455}, am Ende dieses Guides",
		["For {npc:1440} in {zone:1453}: keep it"] = "Für {npc:1440} in {zone:1453}: behalten",
		["For {npc:2487} in {area:35}: keep it"] = "Für {npc:2487} in {area:35}: behalten",
		["For {npc:2542} in {area:35}: keep it"] = "Für {npc:2542} in {area:35}: behalten",
		["For {npc:2711} in {area:271}"] = "Für {npc:2711} in {area:271}",
		["From the Syndicate camp, follow the road east over {area:1057} to {area:320}."] = "Folge vom Lager des Syndikats der Straße nach Osten über {area:1057} nach {area:320}.",
		["From {npc:2712}'s camp, a short way north-east to the {object:2691}, by the shards' hill north of {area:314}. The {object:2702}, where the three keys go, stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Vom Lager von {npc:2712} ein kurzes Stück nach Nordosten zum {object:2691}, beim Hügel der Splitter nördlich von {area:314}. Der {object:2702}, wo die drei Schlüssel hingehören, steht westlich von {area:320}.\nVorsicht: Jeder mittlere Stein wird von etwa drei Elementaren nahe Stufe 39 bewacht, die gemeinsam angreifen, wenn du den Stein anklickst, ohne sie zu töten: Brennende Verbannte am westlichen, Donnernde Verbannte am äußeren, Schäumende Verbannte am östlichen Stein.",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Nimm von {zone:1455} aus den Tunnel nach Osten durch {zone:1426} nach {zone:1432} und folge der Straße nach {area:144}.",
		["Hay Weevils crawl about the north end of {quest:681}'s farm: catch one with the tool from {npc:217412}'s {item:213565}."] = "Hay Weevils kriechen am Nordende der Farm von {quest:681} umher: Fang eines mit dem Werkzeug aus dem {item:213565} von {npc:217412}.",
		["Lost Ones: Hunters, Muckdwellers, Seers and Riftseekers all count"] = "Verirrte: Jäger, Schlammbewohner, Seher und Risssucher zählen alle",
		["North out of {area:271} to the Syndicate camp on the Alterac border, west of {area:272} (Horde): its Footpads and Thieves are the Syndicate Maleb wants, and the documents lie in the camp. Then back to the road and east to Arathi.\nCareful: a few Syndicate Wizards (34-35) stand among the tents and cast from range: pull them one at a time."] = "Von {area:271} nach Norden zum Lager des Syndikats an der Grenze zu Alterac, westlich von {area:272} (Horde): Seine Straßenräuber und Diebe sind das Syndikat, das Maleb will, und die Dokumente liegen im Lager. Dann zurück zur Straße und nach Osten ins Arathihochland.\nVorsicht: Einige Hexer des Syndikats (34-35) stehen zwischen den Zelten und zaubern aus der Ferne: Zieh sie einzeln.",
		["North-west of Watcher Biggs, {npc:255597} (level 34) waits by the road: lead him north to the {area:657}, on your way there. Stay close to him and clear what attacks him; if he falls, abandon the quest and go on."] = "Nordwestlich von Wächter Biggs wartet {npc:255597} (Stufe 34) an der Straße: Führ ihn auf deinem Weg dorthin nach Norden zur {area:657}. Bleib nah bei ihm und erledige, was ihn angreift; stirbt er, brich die Quest ab und zieh weiter.",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "Nach Nordwesten aus dem Witherbark-Tal hinaus; {npc:2712} und {npc:2713} lagern in den Hügeln direkt nördlich von {area:314}.",
		["Off the flight, straight to the {area:271} inn. Then {npc:2276} and {npc:2277}, in the town hall, take the Syndicate camp's quests and send you north to {area:280}."] = "Nach dem Flug direkt ins Gasthaus von {area:271}. Dann nehmen {npc:2276} und {npc:2277} im Rathaus die Quests zum Lager des Syndikats an und schicken dich nach Norden nach {area:280}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Nur wenn Gluckser dir im Schlingendorntal den Anhänger gegeben hat",
		["Phizzlethorpe"] = "Phizzlethorpe",
		["South down the road to {npc:5476}, on the way west out of the swamp."] = "Südlich die Straße hinunter zu {npc:5476}, auf dem Weg nach Westen aus dem Sumpf.",
		["South-east along the loch to the dig site."] = "Nach Südosten am See entlang zur Ausgrabungsstätte.",
		["South-east through the hills: {npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley.\nCareful: {npc:2793} is level 39, a caster, one or two over you here: clear the cave mouth first, then pull him alone at full health."] = "Nach Südosten durch die Hügel: {npc:2793}, ein Ogermagier, hält die Höhle am südlichen Ende des Tals der Bleichborken.\nVorsicht: {npc:2793} ist Stufe 39, ein Zauberwirker, hier ein oder zwei Stufen über dir: Säubere zuerst den Höhleneingang und zieh ihn dann allein mit voller Gesundheit.",
		["South-west from {npc:2793}'s cave to the {area:880}: {npc:2696} stands on a broken section of the bridge; jump down to him from its north end. {quest:647} must reach {npc:2705} in {area:271} within 15 minutes: go straight back to {area:320} and fly to {area:271}."] = "Südwestlich von der Höhle von {npc:2793} zur {area:880}: {npc:2696} steht auf einem zerbrochenen Abschnitt der Brücke; spring von ihrem Nordende zu ihm hinunter. {quest:647} muss {npc:2705} in {area:271} innerhalb von 15 Minuten erreichen: Geh direkt zurück nach {area:320} und flieg nach {area:271}.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Nach Südwesten zum Lager der Kirin Tor am Seeufer westlich von {area:279}, gleich hinter der Grenze in {zone:1421}: Dort steht {npc:269127}. Erzmagier Ansirem steht südöstlich davon, bei der Kuppel.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Bleib bei {npc:2713}, während sie sich nach {area:314} schleicht und zurück; Orcs der Horde greifen dich unterwegs an.\nVorsicht: Orcs, die auf wenig Gesundheit fallen, laufen weg. {npc:2713} folgt ihnen und kann weitere Mobs ziehen, also töte oder verlangsame Flüchtende schnell.",
		["Syndicate camp"] = "Syndikatslager",
		["The City of Dalaran is a dungeon for a group of five at about level 28 to 33: at your level it goes quickly. Its way in is the sewer grate in the city's western wall, by the lake, 30 yards from Modera's camp.\nInside: the Seeking Remnants, Saturated Remnants and Mana Echoes are Modera's {quest:92457}; the {item:251961} for {quest:92458} drops inside too."] = "Die City of Dalaran ist ein Dungeon für eine Gruppe aus fünf Spielern, etwa Stufe 28 bis 33: Auf deiner Stufe geht er schnell. Der Weg hinein ist das Kanalgitter in der Westmauer der Stadt, am See, 30 Meter von Moderas Lager.\nDrinnen: Die Seeking Remnants, Saturated Remnants und Mana Echoes sind für Moderas {quest:92457}; {item:251961} für {quest:92458} droppt ebenfalls drinnen.",
		["The Crushridge ogres hold the hills north of {area:280}. Careful: Nagaz (40) stands far to the north-west by a worn wooden chest, with Syndicate guards: stay with the ogres.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up."] = "Die Crushridge-Oger halten die Hügel nördlich von {area:280}. Vorsicht: Nagaz (40) steht weit im Nordwesten bei einer abgenutzten Holztruhe, mit Wachen des Syndikats: Bleib bei den Ogern.\nDie Crushridge-Raufer, -Magier, -Vollstrecker und -Kriegshetzer (36-39) sind Elites; die Crushridge-Oger und -Rohlinge (34-35) nicht und lassen die Knöchelchen ebenfalls fallen: Zieh einzeln, oder bilde eine Gruppe.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Die Kobolde der Trockenstoppel graben in der Schlucht östlich von {area:321} (Horde); umgeh den Ort im Norden. Sie lassen die Körner von Myzrael fallen, nicht Krazeks Erz. Geringe Blutsteinablagerungen brauchen {skill:186} 75: Bau vier Erz ab, kauf sie im Auktionshaus oder frag einen befreundeten Bergarbeiter. Das Erz-Ziel ist optional; mach mit Myzrael weiter, wenn du es nicht bekommst. Vorsicht: Jede Koboldart rennt bei wenig Gesundheit um Hilfe (Kobolde bei 30%, Feldvermesser und Buddler bei 15%), was weitere anlocken kann.",
		["The Syndicate hold the farm north-west of {area:320}.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "Das Syndikat hält die Farm nordwestlich von {area:320}.\nVorsicht: Syndicate Highwaymen sind Stufe 30-31 und können außerhalb des Kampfes Schleichen wirken, sodass sie oft getarnt und schwer zu erkennen sind.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "Der Kurier geht mit zwei Wachen die Straße von {area:314} nach Westen quer durch das Hochland bis etwa 24,45 und wieder zurück: Der Pfeil folgt der Straße nach Westen, bis du ihn triffst. Lock sie von der Straße weg.",
		["The shards lie at the far end of {area:318}."] = "Die Splitter liegen am hinteren Ende von {area:318}.",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up."] = "Die Folianten liegen in der zerstörten Festung westlich von {area:280}; Argus Shadow Mages halten die Ruinen.\nVorsicht: Crushridge Warmongers rufen nahe Verbündete im Umkreis von 15 Metern, sobald sie unter die Hälfte ihrer Gesundheit fallen.\nDie Crushridge Maulers, Mages, Enforcers und Warmongers (36-39) sind Elites; die Crushridge Ogres und Brutes (34-35) nicht und tragen die Folianten ebenfalls: Zieh einzeln, oder bilde eine Gruppe.",
		["The western swamp"] = "Der westliche Sumpf",
		["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "Die Truhe der zerstörten Karawane liegt am Nordende des {area:76}, neben dem Käfig von {npc:5391}.\nVorsicht: Das Lager ist voller Lost Ones um Stufe 38. Sie stehen in verbundenen Gruppen zu 2-3, viele sind Zauberwirker, und sie respawnen schnell.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "Dies sind Elitegegner: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:2417} ist ein Elitegegner der Stufe 40: Die meisten Klassen schaffen ihn auf Stufe 42 allein, aber vielleicht brauchst du Hilfe. Lass ihn aus, wenn du allein bist: Die Route lässt dich die EP wieder hereinholen.\n{npc:2417} geht vom Pfeil aus nach Nordosten durch die Ruinen bis etwa 40,47 und zurück: Wenn er nicht am Pfeil ist, folge seinem Weg.",
		["To {area:144}"] = "Nach {area:144}",
		["Tram to {zone:1455}"] = "Tiefenbahn nach {zone:1455}",
		["West along the road from {npc:5391}'s strongbox to the {area:657}."] = "Nach Westen entlang der Straße von der Geldkassette von {npc:5391} zum {area:657}.",
		["West along the road to {area:320}."] = "Nach Westen entlang der Straße nach {area:320}.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Junge Sägezahnkrokilisken, Trauerspinner und Sumpfjaguare streifen alle durch den Sumpf um die Straße.",
		["from {quest:1392}: he walks a path through the ruins"] = "von {quest:1392}: Er läuft einen Weg durch die Ruinen",
		["{area:280}: kill these as you meet them"] = "{area:280}: Töte diese, sobald sie dir begegnen",
		["{area:281}: kill these as you meet them"] = "{area:281}: Töte diese, sobald sie dir begegnen",
		["{area:318}: kill these as you meet them"] = "{area:318}: Töte diese, sobald sie dir begegnen",
		["{area:320} flight master"] = "Flugmeister von {area:320}",
		["{area:328}: kill these as you meet them"] = "{area:328}: Töte diese, sobald sie dir begegnen",
		["{area:35} flight master"] = "Flugmeister von {area:35}",
		["{item:2321}, from {npc:2381}"] = "{item:2321}, von {npc:2381}",
		["{item:258530}, from a {npc:757}"] = "{item:258530}, von einem {npc:757}",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: Crushridge-Oger",
		["{item:3659}: the {object:1760}, beside Muckrake (40, elite): get it with a group, or abandon {quest:540}; inside"] = "{item:3659}: {object:1760} neben Muckrake (40, Elite): Hol es mit einer Gruppe oder brich {quest:540} ab; drinnen",
		["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "{item:4435} von {npc:2572}, {npc:2573} und {npc:2574}, bei diesem Halt",
		["{item:4492}; underwater"] = "{item:4492}; unter Wasser",
		["{item:4525}; below ground"] = "{item:4525}; unter der Erde",
		["{item:5040}; below ground"] = "{item:5040}; unter der Erde",
		["{item:6071}, the blue crystals by the tents"] = "{item:6071}, die blauen Kristalle bei den Zelten",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, Straße zum {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Kathedrale des Lichts",
		["{npc:1356}: for {npc:1344} in {zone:1432}, next"] = "{npc:1356}: für {npc:1344} in {zone:1432}, als Nächstes",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, die Königliche Bibliothek in der Burg",
		["{npc:1470}, below ground"] = "{npc:1470}, unter der Erde",
		["{npc:1776}: Noboru's cudgel"] = "{npc:1776}: Noboros Knüppel",
		["{npc:1776}: {npc:255597}'s escort"] = "{npc:1776}: Eskorte von {npc:255597}",
		["{npc:1776}: {quest:93464}, for {npc:11863} in {zone:1443}, on the {zone:1443} guide at the end of 30-40"] = "{npc:1776}: {quest:93464}, für {npc:11863} in {zone:1443}, im {zone:1443}-Guide am Ende von 30-40",
		["{npc:185335}, at the same circle"] = "{npc:185335}, am selben Kreis",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: drei Kleintiere zum Fangen im Arathihochland, in {zone:1443} und im Schlingendorntal",
		["{npc:2276}, inside"] = "{npc:2276}, drinnen",
		["{npc:2276}: the signet rings are in {area:280}"] = "{npc:2276}: Die Siegelringe sind in {area:280}",
		["{npc:2434}, if you spot him"] = "{npc:2434}, wenn du ihn entdeckst",
		["{npc:2438} stands between the flight master and the inn; {npc:2381} beside him sells {item:2321} if you have none."] = "{npc:2438} steht zwischen dem Flugmeister und dem Gasthaus; {npc:2381} neben ihm verkauft {item:2321}, falls du keinen hast.",
		["{npc:2595}, underwater"] = "{npc:2595}, unter Wasser",
		["{npc:2596}, underwater"] = "{npc:2596}, unter Wasser",
		["{npc:2705}, below ground"] = "{npc:2705}, unter der Erde",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} und {npc:2713}",
		["{npc:2713}'s errand"] = "Auftrag von {npc:2713}",
		["{npc:2789}: {npc:2793}'s cave, west past the {object:2689}"] = "{npc:2789}: Die Höhle von {npc:2793}, westlich am {object:2689} vorbei",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards. Careful: on the walk out the camp's Lost One Riftseekers (37-38) and their pets, with the Lost Ones around them, turn on {npc:5391}: clear the cage and the start of his path first, stay beside him and pull every attacker onto yourself. Many players lose him the first time; if he dies, abandon the quest and take it again at his cage."] = "{npc:5391} ist am Nordende des Refugiums eingesperrt. Befreie ihn und halte ihn auf dem Weg hinaus am Leben; seine Geldkassette wartet danach an der Straße. Vorsicht: Auf dem Weg hinaus greifen die Kluftsucher der Verlorenen (37-38) des Lagers und ihre Tiere, mit den Verlorenen um sie herum, {npc:5391} an: Räum zuerst den Käfig und den Anfang seines Wegs frei, bleib neben ihm und zieh jeden Angreifer auf dich. Viele Spieler verlieren ihn beim ersten Mal; stirbt er, brich die Quest ab und nimm sie an seinem Käfig erneut an.",
		["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him.\n{npc:217412} may not be here on Forever: if {npc:217412} doesn't offer {quest:93176}, skip it."] = "{npc:5476} bewacht die Straßenkreuzung im Westen des Sumpfes. {npc:217412} steht ein kurzes Stück nördlich von ihm.\n{npc:217412} ist auf Forever vielleicht nicht hier: Falls {npc:217412} {quest:93176} nicht anbietet, überspring sie.",
		["{npc:5677}, at the summoning circle"] = "{npc:5677}, am Beschwörungskreis",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} bindet den Inkubus an dich",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} wartet im Keller von {object:2164} in {object:2101}. Benutze {item:6913} am Beschwörungskreis dort und besiege den herbeigerufenen Sukkubus. Wenn du {quest:65602} angenommen hast, gib ihm auch {item:190309}, stelle sie am selben Kreis ab und besiege den Inkubus.",
		["{object:2707}; underwater"] = "{object:2707}; unter Wasser",
		["{object:2708}; underwater"] = "{object:2708}; unter Wasser",
		["{object:2709}; underwater"] = "{object:2709}; unter Wasser",
		["{object:2710}; underwater"] = "{object:2710}; unter Wasser",
		["{quest:651} is a group quest at this level: three Cresting Exiles (38-39) guard the {object:2691} and attack together. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "{quest:651} ist auf dieser Stufe eine Gruppenquest: Drei Schäumende Verbannte (38-39) bewachen den {object:2691} und greifen gemeinsam an. Eine Gruppe wird empfohlen, such dir Mitspieler dafür. Überspring sie, wenn du allein bist.",
		["{quest:65602}, if you took it"] = "{quest:65602}, falls du sie angenommen hast",
		["{quest:92457}: the remnants and echoes, inside"] = "{quest:92457}: die Überreste und Echos, drinnen",
		["{quest:92458}: the {item:251961}, inside"] = "{quest:92458}: {item:251961}, drinnen",
		["{zone:1455} flight master"] = "Flugmeister von {zone:1455}",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Buzzards circle the plain to the east. Careful: the Dustbelcher Maulers, Shamans and Wyrmhunters (40-43) camp far to the south-west: leave them.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: the Stonevault Bonesnappers are 39-40 and the Shamans 40-41, a level or two over you here: pull them from the camp's edge, one at a time.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Bussarde kreisen über der Ebene im Osten. Vorsicht: Die Raufer, Schamanen und Wyrmjäger der Staubspeier (40-43) lagern weit im Südwesten: Lass sie in Ruhe.\nDas zerschlagene Skelett liegt am Rand des Lagers der Steingrufttroggs; {quest:739}, der Mörder von Agmond, läuft zwischen den Knochenknackern umher.\nVorsicht: Die Knochenknacker der Steingrufttroggs sind 39-40 und die Schamanen 40-41, ein bis zwei Stufen über dir: Zieh sie einzeln vom Rand des Lagers.\nVorsicht: Lords der Staubspeier sind Stufe 44-45. Sie benutzen {spell:5242} und {spell:1160}, und unter 50 % Gesundheit rufen sie Verbündete im Umkreis von 15 Metern zu Hilfe. Sieben von ihnen stehen etwa 750 Meter südlich von {area:340}.",
		["East from the {area:1877} to {area:346}: {npc:2860} takes the scrap metal."] = "Vom {area:1877} nach Osten zu {area:346}: {npc:2860} nimmt den Metallschrott an.",
		["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "Für {npc:4454} an der {area:2240}: Der Guide für {zone:1446} kommt bei Stufe 45 an ihm vorbei, behalte es",
		["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Geh zurück nach Westen zur Straße und folge ihr nach Süden aus {zone:1432} durch den Pass in die {zone:1418}. {npc:2910} und {npc:2860} lagern Seite an Seite an der Grabungsstätte.",
		["Head north to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "Geh nach Norden zum Eingang von {area:1517} im Norden von {zone:1418}: Die Truhe liegt gleich hinter dem Höhleneingang. {npc:2932} und die Obsidian Golems (38) stehen daneben, und Shadowforge Diggers (35-36) arbeiten im Tunnel, alle Elite: Halte deine Gruppe zusammen.",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Geh nach Nordosten zur verlassenen Grabungsstätte; die Versorgungskiste liegt dort zwischen den Ogern der Staubbäuche.",
		["Head south to {area:345}."] = "Geh nach Süden zu {area:345}.",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Geh nach Westen in die {area:1878}; {npc:2921} arbeitet in der Mitte bei seinen Maschinen.",
		["Into {zone:1418}"] = "Hinein nach {zone:1418}",
		["Lesser Rock Elementals"] = "Kleine Felselementare",
		["Rock Elementals"] = "Felselementare",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "Ryedols nächster Auftrag führt nach {area:1517}: Überspring ihn.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards. The Dustbelcher Ogres (38-39) on the {area:1878}'s west side drop {npc:2860}'s scrap. Careful: a {npc:269756}, a level 42 elite, drifts about the {area:1878}: give it a wide berth.\nCareful: the Lesser Rock Elementals are 37-39 and hit hard: fight them one at a time."] = "Die Kleinen Felselementare streifen durch {area:1878} westlich von {npc:2921}; jeder Felselementar kann die Felselementarsplitter für {npc:1470} fallen lassen. Die Oger der Staubspeier (38-39) auf der Westseite von {area:1878} lassen den Schrott für {npc:2860} fallen. Vorsicht: Eine {npc:269756}, ein Elite der Stufe 42, treibt durch {area:1878}: Mach einen großen Bogen darum.\nVorsicht: Die Kleinen Felselementare sind 37-39 und schlagen hart zu: Kämpf einzeln gegen sie.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west. Careful: a {npc:269756}, a level 42 elite, drifts about the {area:1878}: give it a wide berth."] = "Die Felselementare streifen südöstlich von {npc:2921} umher; Riesenbussarde und Alte Klippenkojoten teilen sich die Ebene westlich davon. Vorsicht: Eine {npc:269756}, ein Elite der Stufe 42, treibt durch {area:1878}: Mach einen großen Bogen darum.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Das zerschlagene Skelett liegt gleich östlich der Oger, am Rand des Lagers der Steingrufttroggs; die Knochenknacker und Schamanen drumherum lassen die Splitter fallen. Theldurin sitzt weiter südlich beim zerstörten Lager.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Die Muscheln liegen an der Nordwestküste des Schlingendorntals, im nächsten Guide: Behalte sie",
		["The excavation crate"] = "Die Ausgrabungskiste",
		["The {object:126260}"] = "{object:126260}",
		["Theldurin sits by the ruined camp south of the trogg camp. His tablet lies just inside {area:1517}'s cave mouth, beside level 38 elites: a quest for a group."] = "Theldurin sitzt beim zerstörten Lager südlich des Troggenlagers. Seine Tafel liegt gleich hinter dem Höhleneingang von {area:1517}, neben Elites der Stufe 38: eine Quest für eine Gruppe.",
		["To {area:2101}"] = "Zum {area:2101}",
		["for {npc:2786} in {zone:1455}: keep it"] = "für {npc:2786} in {zone:1455}: behalte sie",
		["{area:345}: kill these as you meet them"] = "{area:345}: Töte diese, sobald sie dir begegnen",
		["{area:346}: kill these as you meet them"] = "{area:346}: Töte diese, sobald sie dir begegnen",
		["{item:278402}, from the Shadowforge diggers and the Bonesnappers"] = "{item:278402}, von den Buddlern der Schattenschmiede und den Knochenknackern",
		["{item:278403}, in the Shadowforge camp"] = "{item:278403}, im Lager der Schattenschmiede",
		["{item:4630}, from the Dustbelcher Ogres"] = "{item:4630}, von den Ogern der Staubspeier",
		["{item:4631}; below ground"] = "{item:4631}; unter der Erde",
		["{item:7847}, if you still need one: the Buzzards east of {area:345} drop it only rarely"] = "{item:7847}, falls du noch einen brauchst: Die Bussarde östlich von {area:345} lassen ihn nur selten fallen",
		["{item:7847}: the Starving Buzzards (35-37) circling the hills north of the digsite drop it most often; leave the Giant Buzzards (39-41) of the far west"] = "{item:7847}: Die Verhungernden Bussarde (35-37), die über den Hügeln nördlich der Ausgrabungsstätte kreisen, lassen ihn am häufigsten fallen; lass die Riesenbussarde (39-41) im fernen Westen in Ruhe",
		["{npc:1470}, in the inn; below ground"] = "{npc:1470}, im Gasthaus; unter der Erde",
		["{npc:269577} of the Explorers' League camps at the foot of the pass. His artifacts drop from the Shadowforge diggers at {area:346} and the Stonevault Bonesnappers at {area:345}, and the helmet lies in the Shadowforge camp."] = "{npc:269577} von der Forscherliga lagert am Fuß des Passes. Seine Artefakte lassen die Buddler der Schattenschmiede bei {area:346} und die Knochenknacker der Steingrufttroggs bei {area:345} fallen, und der Helm liegt im Lager der Schattenschmiede.",
		["{npc:269577}: keep it, the {item:278404} waits for the 40-50 {zone:1418} visit"] = "{npc:269577}: behalten, die {item:278404} wartet auf den Besuch in {zone:1418} mit 40-50",
		["{npc:4618} and {npc:2817} camp in the {area:1877}, on the road between {area:1517} and {area:345}."] = "{npc:4618} und {npc:2817} lagern im {area:1877}, auf der Straße zwischen {area:1517} und {area:345}.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} und {npc:2817} lagern zusammen im {area:1877}, mitten im {zone:1418}.",
		["{quest:739} himself (42) walks among the Bonesnappers: leave him for the later {zone:1418} guide at 43, and kill the Bonesnappers for this quest now."] = "{quest:739} selbst (42) läuft zwischen den Bonesnappers umher: Lass ihn für den späteren Guide für {zone:1418} auf Stufe 43 übrig und töte jetzt die Bonesnappers für diese Quest.",
} end)()
t.guides["forever/alliance/30-40/06b-desolace"] = (function() return {
		["A long trip out to Kalimdor"] = "Eine lange Reise nach Kalimdor",
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s {item:213565}."] = "Ein {npc:217590} krabbelt im {area:596} herum: Fang einen mit dem Werkzeug aus {item:213565} von {npc:217412}.",
		["Back at the coven on the way west: the Mana Eaters (37-38) on its north edge and the Mage Hunters (38-39) further in drop the brains. {npc:5760} (40, elite) walks among the Mage Hunters: pull them out to you."] = "Zurück am Zirkel auf dem Weg nach Westen: Die Manafresser (37-38) am Nordrand und die Magierjäger (38-39) weiter drinnen lassen die Gehirne fallen. {npc:5760} (40, Elite) läuft zwischen den Magierjägern: Zieh sie zu dir heraus.",
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Fly to {area:150}"] = "Flieg nach {area:150}",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Folge der Straße nach Norden zu {area:608}: {npc:5396} steht am Südende, {npc:5638} in der Mitte, {npc:1182} im Norden.",
		["Follow the road south to {area:2407}."] = "Folge der Straße nach Süden zu {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Folge der Straße nach Westen durch den Norden von {zone:1443} zu den Ruinen von {area:2405}. Dort steht {npc:11863}s Turm auf dem Hügel, auf dem Weg zum Wrack.",
		["Kodo bones, demons and lost treasure in south {zone:1443}."] = "Kodoknochen, Dämonen und verlorene Schätze im Süden von {zone:1443}.",
		["Maraudine centaurs"] = "Zentauren der Maraudine",
		["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "Geh vom Boot aus den Pier hinauf zu Baldruc, dem Flugmeister am Tor von {area:514}.",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "Rackmores Truhe liegt gleich südöstlich von {object:177673}.",
		["Short: about one level of quests"] = "Kurz: etwa eine Stufe an Quests",
		["Stays on the main route"] = "Bleibt auf der Hauptroute",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Die Zentauren der Maraudine halten das {area:607} westlich des Friedhofs; jede Art lässt die Totems fallen.",
		["The demons gather at the {area:602} in southern {zone:1443}. Nether Maidens (37-38) hold its north-west side and drop the wings; Doomwarder Captains (38) stand at the south end and drop the blood.\nCareful: Nether Sorceresses (39-40) stand beside the Doomwarder Captains, and {npc:5760}, a level 40 elite, walks the coven's middle: pull the captains away from them. Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "Die Dämonen sammeln sich im {area:602} im Süden von {zone:1443}. Nethermaiden (37-38) halten die Nordwestseite und lassen die Flügel fallen; Captains der Verdammniswächter (38) stehen am Südende und lassen das Blut fallen.\nVorsicht: Netherzauberinnen (39-40) stehen neben den Captains der Verdammniswächter, und {npc:5760}, ein Elite der Stufe 40, läuft durch die Mitte des Zirkels: Zieh die Captains von ihnen weg. Die meisten Mobs hier laufen Patrouillen, du ziehst also leicht zusätzliche Mobs.",
		["The ghost magnets"] = "Die Geistermagneten",
		["The next guide starts in Theramore."] = "Der nächste Guide beginnt in Theramore.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "Die Truhe des Schiffswracks liegt gleich südwestlich von {npc:11863}s Turm.",
		["The {area:2657}"] = "{area:2657}",
		["Then on to {zone:1434}"] = "Danach weiter ins {zone:1434}",
		["Theramore flight master"] = "Flugmeister von Theramore",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:6134}'s magnets draw the Magrami Spectres a few yards from the Magram Necrokhans and Corpsefeeders (45, elite) in the {area:2657}. Skip it if you are alone."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Leute dafür. Die Magneten von {quest:6134} locken die Magrami-Gespenster ein paar Meter von den Nekrokhans und Leichenfressern der Magram (45, Elite) im {area:2657} weg. Überspring sie, wenn du allein bist.",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven: the arrow leads to their western edge. Careful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields further east, with Magram Necromancers (42): pull the Ravagers to you, away from them."] = "Untote Verheerer streifen über die Knochenfelder südlich des Dorfes der Magram, östlich des Zirkels: Der Pfeil führt zu ihrem Westrand. Vorsicht: Nekrokhane und Leichenfresser der Magram (45, Elite) laufen mit Totenbeschwörern der Magram (42) weiter östlich über die Knochenfelder: Zieh die Verheerer zu dir, weg von ihnen.",
		["Underwater"] = "Unter Wasser",
		["Use the {item:15848} at its arrow, on the fields' eastern side, to draw the Magrami Spectres; the Necrokhans and Corpsefeeders (45, elite) walk close by: keep the group together."] = "Benutze {item:15848} an seinem Pfeil, auf der Ostseite der Felder, um die Magrami-Gespenster anzulocken; die Nekrokhane und Leichenfresser (45, Elite) laufen ganz in der Nähe: Bleibt als Gruppe zusammen.",
		["escort {npc:12277} back toward the graveyard"] = "eskortiere {npc:12277} zurück zum Friedhof",
		["for {npc:3980} in {area:271}: keep it"] = "für {npc:3980} in {area:271}: behalte sie",
		["for {npc:5637} in {zone:1455}: keep it"] = "für {npc:5637} in {zone:1455}: behalte sie",
		["{area:144} flight master"] = "Flugmeister in {area:144}",
		["{area:598}: kill these as you meet them"] = "{area:598}: Töte diese, sobald sie dir begegnen",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, an {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, von den Naga der Schlitterklingen",
		["{item:6251}, from the Nether Maidens"] = "{item:6251}, von den Nethermaiden",
		["{item:6252}, from the Doomwarder Captains"] = "{item:6252}, von den Captains der Verdammniswächter",
		["{npc:11863}: {quest:93464}, from Magtoor in the {zone:1435}"] = "{npc:11863}: {quest:93464}, von Magtoor in den {zone:1435}",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} wird im Zentaurenlager westlich des Friedhofs festgehalten. Befreie sie und halte sie auf dem Weg hinaus am Leben; sie bleibt am Friedhof stehen.\nVorsicht: Die geskripteten Gruppen sind verbunden und erscheinen nur während der Eskorte, du kannst sie also nicht vorher räumen oder einzeln ziehen. Die normalen Zentauren auf dem Pfad vor dem Start zu räumen hilft dagegen.",
		["{object:177787} lies beside {object:35251}, if you didn't take it on your first {zone:1443} visit. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} liegt neben {object:35251}, falls du es nicht bei deinem ersten Besuch in {zone:1443} mitgenommen hast. Sein silberner Schlüssel wird von den Trockenschnappkrebsen rund um das Wrack fallen gelassen; der goldene stammt von den Naga der Schlitterklingen an der Nordwestküste, als Nächstes.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "„Sea Wolf“ MacKinley, im obersten Stockwerk",
		["\"Stinky\" Ignatz"] = "Stinki Ignatz",
		["An {npc:217588} crawls in the jungle south-east of Nesingwary's camp, on the way to the {area:99}: catch one with the tool from {npc:217412}'s {item:213565}."] = "Eine {npc:217588} kriecht im Dschungel südöstlich von Nesingwarys Lager, auf dem Weg zum {area:99}: Fang eine mit dem Werkzeug aus dem {item:213565} von {npc:217412}.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "Auf Stufe 40 kannst du mit 100 Gold das Reiten lernen, und beim Lernen bekommst du ein Reittier. Himmelsgeborene lernen es bei {npc:265756}, dem Stallmeister und Reitlehrer in den {area:17684} in {area:16638} auf Zephras Isle, der auch die Galestrider verkauft: Das Himmelsboot zur Insel legt etwa alle fünf Minuten an der Nordseite von {area:279} ab. Sammlungen, Reittiere · Stufe 40 listet die Galestrider auf.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4732} lehrt Menschen in {area:88} im östlichen {zone:1429}, neben den Pferden von {npc:384}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4753} lehrt Nachtelfen in {zone:1457}, neben den Säblern von {npc:4730}: das Boot vom {area:17203} nach {area:442}, dann der Flug nach {area:702}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt), etwa bei {npc:4732} in {area:88} im {zone:1429}. Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4772} lehrt Zwerge in {area:803}, östlich von {area:131} an der Straße nach {zone:1432}, neben den Widdern von {npc:1261}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:7954} lehrt Gnome in {area:189}, gleich östlich von {area:131}, neben den Roboschreitern von {npc:7955}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["Bloodsail camp"] = "Lager der Blutsegelbukaniere",
		["Bloodsail pirates: kill these as you meet them"] = "Blutsegelbukaniere: Töte diese, sobald sie dir begegnen",
		["Boat to {area:150}"] = "Schiff nach {area:150}",
		["Boat to {area:17203}"] = "Boot nach {area:17203}",
		["Boat to {area:35}"] = "Boot nach {area:35}",
		["Corrosive Swamp Oozes"] = "Ätzende Sumpfbrühschlammer",
		["Defeat the challengers and {npc:6238}"] = "Besiege die Herausforderer und {npc:6238}",
		["East from the stalkers' slopes to the ruins of Zul'Mamwe: the Skullsplitter Mystics (39-40) in its northern half carry {npc:739}'s fetishes. Careful: the Witch Doctors, Berserkers and Headhunters (41-44) hold the ruins' southern half: stay north. Then north-west toward the coast: the Shadowmaw Panthers (37-38) prowl the jungle west of the ruins, often stealthed."] = "Von den Hängen der Pirscher nach Osten zu den Ruinen von Zul'Mamwe: Die Mystiker der Skullsplitter (39-40) in der nördlichen Hälfte tragen die Fetische für {npc:739}. Vorsicht: Die Hexendoktoren, Berserker und Kopfjäger (41-44) halten die südliche Hälfte der Ruinen: Bleib im Norden. Dann nach Nordwesten Richtung Küste: Die Schattentatzenpanther (37-38) streifen durch den Dschungel westlich der Ruinen, oft getarnt.",
		["East from the {area:99} to {area:101}: {npc:218230} is caged at its western edge. The Kurzen Subchiefs (35-36) and Elites (36-37) carry his cage key; the fighter's uniform lies in a supply crate in the compound's eastern part.\nCareful: {npc:813}, an elite of 39-40, stands at the compound's north end beside three of the Subchiefs: take the key from the Subchiefs and Elites further south and leave him be."] = "Vom {area:99} nach Osten zu {area:101}: {npc:218230} ist an dessen Westrand eingesperrt. Kurzens Stabschefs (35-36) und Elitesoldaten (36-37) tragen seinen Käfigschlüssel; die Kämpferuniform liegt in einer Vorratskiste im Ostteil des Lagers.\nVorsicht: {npc:813}, ein Elite der Stufe 39-40, steht am Nordende des Lagers neben drei der Stabschefs: Hol dir den Schlüssel von den Stabschefs und Elitesoldaten weiter südlich und lass ihn in Ruhe.",
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["Fly to {area:442}"] = "Flieg nach {area:442}",
		["Fly to {area:702}"] = "Flieg nach {area:702}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Folge der Straße nach Osten zurück nach Theramore. Die Offiziere sind in {area:514}.",
		["Follow the road south to {area:35}."] = "Folge der Straße nach Süden nach {area:35}.",
		["For {npc:218229} in {area:35}, at the end of the jungle loop"] = "Für {npc:218229} in {area:35}, am Ende der Dschungelrunde",
		["Go on north-west to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Geh weiter nach Nordwesten zur Bucht an der Nordwestküste. Die Riesenmuscheln liegen auf ihrem Grund und enthalten die Perlen; {npc:2624} schwimmt zwischen ihnen und lässt {item:4034} fallen.",
		["Gorilla hills"] = "Gorillahügel",
		["Head east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Geh nach Osten; die Wuchernden Schrecken unterwegs lassen auch die Aufsätze fallen. Durchsuche den Rand des {area:74}, wo die Ruinen des Tempels aus dem Wasser ragen.",
		["Head north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale."] = "Geh nach Nordosten an Nesingwarys Lager vorbei und folge der Straße nach Norden zum Lager am oberen Ende des Tals.",
		["Head south to the giant's hut in the middle of the marsh."] = "Geh nach Süden zur Hütte des Riesen mitten im Sumpf.",
		["Jungle Stalkers"] = "Dschungelpirscher",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks.\nCareful: the Bloodsail Mages and Warlocks here are level 40-43 and cast from range: pull one at a time and fight with your back to the open beach."] = "Verlass den Ort durch den Tunnel und folge der Küste nach Norden; der Brief liegt im Lager der Blutsegelbukaniere am Strand, wo Schönling Duncan umhergeht.\nVorsicht: Die Magier und Hexenmeister der Blutsegelbukaniere hier sind Stufe 40-43 und wirken aus der Ferne: Zieh sie einzeln und kämpfe mit dem Rücken zum offenen Strand.",
		["Level 40 with 100 gold later on? {npc:4732} teaches riding at {area:88} in {zone:1429}: Collectibles, Mounts · Level 40 has the trip."] = "Später Stufe 40 und 100 Gold? {npc:4732} lehrt Reiten in {area:88} in {zone:1429}: Sammelobjekte, Reittiere · Stufe 40 hat die Reise.",
		["Mirefin murlocs"] = "Murlocs der Schlammflossen",
		["North-east from the bay toward Nesingwary's camp: {npc:729}, the great tiger (37), lairs on the hilltop just south-west of the camp."] = "Von der Bucht nach Nordosten Richtung Nesingwarys Lager: {npc:729}, der große Tiger (37), haust auf der Hügelkuppe direkt südwestlich des Lagers.",
		["On the top floor"] = "Im obersten Stockwerk",
		["On the way back east, the Corrosive Swamp Oozes (38-40) creep through the marsh south of the road, between the middle of the marsh and Theramore: one of them carries Jameson's training sword. Careful: Elder Daggermaws (48-49) lurk in the water among them, and the larger Bubbling Swamp Oozes (39-40) are elite: leave both alone."] = "Auf dem Rückweg nach Osten kriechen die Ätzenden Sumpfbrühschlammer (38-40) durch den Sumpf südlich der Straße, zwischen der Sumpfmitte und Theramore: Einer von ihnen trägt Jamesons Übungsschwert. Vorsicht: Uralte Dolchmäuler (48-49) lauern zwischen ihnen im Wasser, und die größeren Brodelnden Sumpfbrühschlammer (39-40) sind Elite: Lass beide in Ruhe.",
		["Paladin: {quest:1661}"] = "Paladin: {quest:1661}",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Reiten und Galestrider: {npc:265756}, in den {area:17684} in {area:16638} auf Zephras Isle.",
		["Riding at 40"] = "Reiten mit 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "Seehorns nächster Auftrag führt zurück nach Arathi: Überspring ihn.",
		["Skyboat to Zephras Isle: the north side of {area:279}, about every five minutes."] = "Himmelsboot nach Zephras Isle: die Nordseite von {area:279}, etwa alle fünf Minuten.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Stinki wartet westlich des Anwesens, im Sumpf unterhalb von {area:504}. Führ ihn zu seinen Sumpfbohnenblättern und halte die Sumpfkreaturen von ihm fern.",
		["Stormwind City"] = "Sturmwind",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three {quest:1218}: if you passed {npc:4897}, buy them from her in Theramore first."] = "Nimm die Straße nach Norden zum Herrenhaus in Ruinen; Jarl wohnt in der Hütte daneben, und die lockere Erde ist an der Hausecke. Jarl will drei {quest:1218}: Falls du an {npc:4897} vorbeigekommen bist, kauf sie zuerst bei ihr in Theramore.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Die Darkmist-Spinnen nisten rund um die Höhle im Nordwesten des Sumpfes; jede Spinne lässt Augen fallen.\nVorsicht: Darkmist Lurkers bewegen sich getarnt und benutzen im Kampf Gift. Die Spinnen stehen dicht beieinander, daher sind zusätzliche Mobs üblich; einzelne Ziele vom Außenrand zu ziehen verringert das.",
		["The Jungle Stalkers roam the slopes west of the mine."] = "Die Jungle Stalkers streifen über die Hänge westlich der Mine.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Die Murlocs der Schlammflossen drängen sich an der Nordküste hinter {area:497}.",
		["The Silt Crawlers (40-41) crowd the north end of the eastern shore, and the driftwood washes up along it from there.\nCareful: the big Monstrous Crawlers (43-44) further south on the shore are over you: take the legs at the north end and pick up the driftwood without pulling them."] = "Die Schlickkriecher (40-41) drängen sich am Nordende des Ostufers, und das Treibholz wird von dort aus am Ufer angespült.\nVorsicht: Die großen Monströsen Kriecher (43-44) weiter südlich am Ufer sind über deiner Stufe: Hol dir die Beine am Nordende und sammle das Treibholz ein, ohne sie zu pullen.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Die Skullsplitter-Trolle halten die Ruinen direkt östlich der Mine; jeder von ihnen kann Hauer fallen lassen, ihre Panther immer.\nFolge der Straße nach Nordosten zum Lager der Venture Co. an der {area:310}; die Miners, Surveyors und Foremen lassen die Kristalle fallen.\nVorsicht: Getarnte Shadowmaw Panthers und Stranglethorn Tigresses streifen durch das Gebiet rund um das Lager.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "Das abgebrannte Gasthaus Zur süßen Ruh steht an der Straße nach Westen, Richtung {zone:1413}; die Plakette der Wache liegt in der Asche.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Die Deserteure lagern südlich der Straße, westlich von {npc:4503}s Hütte.",
		["The north-west coast"] = "Die Nordwestküste",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "Die Schriftrolle liegt im Sumpf nördlich von Biggs. Die Sumpfwandler nördlich davon können Khadgars Aufsätze fallen lassen.",
		["The sunken temple"] = "Der versunkene Tempel",
		["Theramore"] = "Theramore",
		["Theramore flight master"] = "Flugmeister von Theramore",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:728} ist ein Elite der Stufe 40: Die meisten Klassen schaffen ihn allein auf Stufe 42, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:730} ist ein Elite der Stufe 43: Die meisten Klassen schaffen ihn allein auf Stufe 45, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:731} ist ein Elite der Stufe 43: Die meisten Klassen schaffen ihn allein auf Stufe 45, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.\nVorsicht: Tiger und getarnte Shadowmaw Panthers streifen in seiner Nähe umher. Räum sie, bevor du ihn ziehst. Wenn er gezogen wird, ruft {npc:731} Kreaturen im Umkreis von 20 Metern zu Hilfe.",
		["Tram to {zone:1455}"] = "Tiefenbahn nach {zone:1455}",
		["Upstairs"] = "Oben",
		["Warlock: {quest:4488}"] = "Hexenmeister: {quest:4488}",
		["Zul'Mamwe's Mystics and the Shadowmaw Panthers"] = "Die Mystiker von Zul'Mamwe und die Schattentatzenpanther",
		["for {npc:5635} at {area:348}: keep it"] = "für {npc:5635} in {area:348}: Behalte es",
		["for {npc:770} at the {area:99}, on the northern loop"] = "für {npc:770} beim {area:99}, auf der nördlichen Runde",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "nur wenn du einen {item:3853} dabeihast (von Schmieden hergestellt)",
		["with the spices from Theramore"] = "mit den Gewürzen aus Theramore",
		["{area:103}: kill these as you meet them"] = "{area:103}: Töte diese, sobald sie dir begegnen",
		["{area:1438} flight master"] = "Flugmeister von {area:1438}",
		["{area:150} flight master"] = "Flugmeister von {area:150}",
		["{area:35} flight master"] = "Flugmeister von {area:35}",
		["{area:392} flight master"] = "Flugmeister in {area:392}",
		["{area:42} flight master"] = "Flugmeister von {area:42}",
		["{area:442} flight master"] = "Flugmeister von {area:442}",
		["{area:702} flight master"] = "Flugmeister von {area:702}",
		["{item:1524}, from the trolls of the ruins"] = "{item:1524}, von den Trollen der Ruinen",
		["{item:216616}, from the Subchiefs (or the Elites)"] = "{item:216616}, von den Stabschefs (oder den Elitesoldaten)",
		["{item:2466}, from the Skullsplitter Mystics"] = "{item:2466}, von den Mystikern der Skullsplitter",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, für Sumpfauge Jarl",
		["{item:4611}; underwater"] = "{item:4611}; unter Wasser",
		["{item:5938}, from the Silt Crawlers"] = "{item:5938}, von den Schlickkriechern",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} kocht im {object:2169}; {npc:5384} ist im {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: andere Farben, 20g",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, Königliche Bibliothek in {object:2117}",
		["{npc:218230}, back at his cage on the way out"] = "{npc:218230}, auf dem Rückweg wieder an seinem Käfig",
		["{npc:218230}, in his cage, if you didn't take it on the 30-40 loop"] = "{npc:218230}, in seinem Käfig, falls du sie nicht schon in der Runde 30-40 angenommen hast",
		["{npc:2486}'s Stranglethorn Fever ({npc:1514}) waits for the level-48 {area:35} stop: leave it for now."] = "Das Schlingendornfieber von {npc:2486} ({npc:1514}) wartet auf den Halt in {area:35} auf Stufe 48: Lass es vorerst liegen.",
		["{npc:2487}, top floor: {quest:669}, if you did {area:327} with a group"] = "{npc:2487}, oberstes Stockwerk: {quest:669}, falls du {area:327} mit einer Gruppe gemacht hast",
		["{npc:2488}, on the top floor"] = "{npc:2488}, im obersten Stockwerk",
		["{npc:2542}, upstairs"] = "{npc:2542}, oben",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} schwimmt vor der Nordwestküste, auf der nördlichen Runde",
		["{npc:271167}: {quest:98233}, from the oozes on the way back east"] = "{npc:271167}: {quest:98233}, von den Schlammern auf dem Rückweg nach Osten",
		["{npc:384}: other colours, 20g"] = "{npc:384}: andere Farben, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, im {object:2164}: {npc:6251} in {area:392} nimmt es am Ende des nächsten Guides an",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: andere Farben, 20g",
		["{npc:4794}, inside"] = "{npc:4794}, drinnen",
		["{npc:4794}: the crawlers are on the {zone:1435} shore, keep it"] = "{npc:4794}: Die Crawler sind am Ufer von {zone:1435}, behalte es",
		["{npc:4944}, on the top floor"] = "{npc:4944}, im obersten Stockwerk",
		["{npc:4948}, on the top floor"] = "{npc:4948}, im obersten Stockwerk",
		["{npc:4964}, on the top floor of {area:514}"] = "{npc:4964}, im obersten Stockwerk von {area:514}",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} hält den Turm mit ein paar Deserteuren. Er wendet sich gegen dich: Schlag ihn, bis er aufgibt.\nVorsicht: Hendel hat zwei Wachen, die in den Kampf eingreifen, wenn er feindlich wird. Die Wachen fliehen, sobald er sich ergibt.\n{npc:4967} und {npc:4968} warten neben dem Turm: Sobald er aufgibt, gib bei beiden direkt vor Ort ab.",
		["{npc:4967}, at the tower"] = "{npc:4967}, am Turm",
		["{npc:5385}, upstairs"] = "{npc:5385}, oben",
		["{npc:5464}, by the flight master"] = "{npc:5464}, beim Flugmeister",
		["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476} steht an der Straßenkreuzung im Westen des Sumpfes.",
		["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637} ist in der Halle der Reclaimers beim {object:32356}, {npc:2786} in der {object:32383}.",
		["{npc:5694}: for {npc:5464} in {area:42}, on the way to the swamp"] = "{npc:5694}: für {npc:5464} in {area:42}, auf dem Weg zum Sumpf",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, in der Kathedrale des Lichts",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} bietet als Nächstes Der Windbehüter (1791) an: Die Questreihe um die Waffe für Wirbelwind, mit einem Elite am Ende, steht im Kriegerklassen-Guide „Wirbelwaffe“.",
		["{npc:718}, beside him"] = "{npc:718}, neben ihm",
		["{npc:737}, upstairs"] = "{npc:737}, oben",
		["{npc:737}, upstairs: the Skullsplitter trolls, on the northern loop"] = "{npc:737}, oben: die Skullsplitter-Trolle, auf der nördlichen Runde",
		["{npc:739}: the {area:301} report bundle for {npc:2277} in {area:271}, on the {zone:1418} & {zone:1425} guide: keep it"] = "{npc:739}: das Berichtsbündel von der {area:301} für {npc:2277} in {area:271}, im Guide {zone:1418} & {zone:1425}: Behalte sie",
		["{npc:773}, upstairs"] = "{npc:773}, oben",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: für {quest:2864} in {zone:1446}, behalte es",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: andere Farben, 20g",
		["{quest:1218}: {npc:4897} in Theramore, if you left without them"] = "{quest:1218}: {npc:4897} in Theramore, falls du ohne sie aufgebrochen bist",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} steht nahe dem Gasthaus; {npc:4897}, ein Handwerkswarenhändler ein paar Schritte südlich, verkauft die Gewürze, die Jarl will.",
		["{quest:1260}, inside"] = "{quest:1260}, drinnen",
		["{zone:1453} flight master"] = "Flugmeister von {zone:1453}",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} hat keinen Schamanenlehrer",
} end)()
t.guides["forever/alliance/40-50/01b-riverglades"] = (function() return {
		["About 90 quests in Forever's new zone, from {area:16724}: the level for its port and Western Front."] = "Etwa 90 Quests im neuen Gebiet von Forever, ab {area:16724}: die richtige Stufe für seinen Hafen und die Westfront.",
		["Back east along the road to {area:16744}."] = "Zurück nach Osten die Straße entlang nach {area:16744}.",
		["Back east through the town to Elbrim's farm: the doll and the locket are in the burnt farmhouse beside it."] = "Zurück nach Osten durch die Stadt zu Elbrims Hof: Die Puppe und das Medaillon liegen im abgebrannten Bauernhaus daneben.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Zurück nach Norden am Ufer entlang: Gib die Murlocs und die Haut auf dem Weg zu den Krabblern an den Docks ab.",
		["Back past {area:16744} and south to the Holmsbys' farm by the river."] = "Zurück an {area:16744} vorbei und nach Süden zum Hof der Holmsbys am Fluss.",
		["Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for {npc:258317} (they drop {npc:256438}'s heads) and the {npc:258588} in the shallows for the shells. {npc:258935}, one of {npc:256438}'s lumberjacks, is stuck on the bank just north-west of the murlocs; {npc:259049}'s hat lies on the riverbank among them; the fresh manure is in the fields of {area:16735}, between the river and the farm. {npc:263380}, an elite (level 42), prowls the river: if he comes your way, back off and let him pass."] = "Zurück nach Südwesten den Fluss entlang: Töte die Krieger und Orakel der Schlickflossen an den Ufern für {npc:258317} (sie lassen die Köpfe für {npc:256438} fallen) und die {npc:258588} im seichten Wasser für die Panzer. {npc:258935}, einer der Holzfäller von {npc:256438}, sitzt am Ufer gleich nordwestlich der Murlocs fest; der Hut von {npc:259049} liegt zwischen ihnen am Flussufer; der frische Mist liegt auf den Feldern von {area:16735}, zwischen Fluss und Hof. {npc:263380}, ein Elite (Stufe 42), streift am Fluss umher: Kommt er auf dich zu, zieh dich zurück und lass ihn vorbei.",
		["Back through the port"] = "Zurück durch den Hafen",
		["Back to the port, from the north pier west through the docks."] = "Zurück zum Hafen, vom Nordpier nach Westen durch die Docks.",
		["Back to the port."] = "Zurück zum Hafen.",
		["Back to {area:16724}"] = "Zurück nach {area:16724}",
		["Coyote pelts"] = "Kojotenfelle",
		["Down to the port."] = "Hinunter zum Hafen.",
		["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Nach Osten die Klippen entlang zum hinteren Ende des Piratenlagers: {npc:260390} wartet am Wasser, {npc:260391} neben ihm.",
		["East along the road towards {area:16724}: hand {npc:258317} his murlocs as you pass {area:16725}."] = "Nach Osten die Straße entlang Richtung {area:16724}: Gib {npc:258317} seine Murlocs ab, wenn du an {area:16725} vorbeikommst.",
		["East down the road to {area:16727}, the goblins' harbour. {npc:255897} keeps a stall at the west end of the docks; {npc:263120}, {npc:255894} and {npc:259962} are at the inn, and {npc:259961} works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from {npc:260487}, the degreaser and the old poison from {npc:260565} and {npc:260560}, by {npc:255897}'s stall."] = "Nach Osten die Straße hinunter nach {area:16727}, dem Hafen der Goblins. {npc:255897} hat einen Stand am Westende der Docks; {npc:263120}, {npc:255894} und {npc:259962} sind im Gasthaus, und {npc:259961} arbeitet am Nordpier. Zizplinks Getränk braucht drei Dinge, die die Händler des Hafens verkaufen: den Köder von {npc:260487}, den Fettlöser und das alte Gift von {npc:260565} und {npc:260560}, neben dem Stand von {npc:255897}.",
		["Finish the {item:268632}"] = "Sammle die restlichen {item:268632}",
		["Fly from {zone:1455} to {area:69} in Redridge, then follow the road north out of town and up through {area:2417}: it comes down into the western {zone:2548} by the {area:16737}."] = "Flieg von {zone:1455} nach {area:69} im Rotkammgebirge, folge dann der Straße nach Norden aus dem Ort hinaus und hoch durch {area:2417}: Sie führt bei {area:16737} hinunter in die westlichen {zone:2548}.",
		["Fly to {area:144}"] = "Flieg nach {area:144}",
		["Follow the road east to {area:16744}, the Alliance outpost above the river. The gnolls you passed on the way in are Captain Dalton's job: you go back for them after the lumber camp."] = "Folge der Straße nach Osten nach {area:16744}, dem Außenposten der Allianz über dem Fluss. Die Gnolle, an denen du auf dem Weg hinein vorbeigekommen bist, sind Captain Daltons Sache: Du kehrst nach dem Holzfällerlager für sie zurück.",
		["Free him, then get him out: {npc:259057} fights his way out of {area:16726}, and you keep the ogres off him. If he falls, take the quest from him again."] = "Befreie ihn und bring ihn raus: {npc:259057} kämpft sich aus {area:16726} heraus, und du hältst ihm die Oger vom Leib. Stirbt er, nimm die Quest erneut bei ihm an.",
		["From the inn: {npc:260070} on the way in, then {npc:257558} and {npc:257591} in the keep."] = "Vom Gasthaus aus: {npc:260070} auf dem Weg hinein, dann {npc:257558} und {npc:257591} in der Burg.",
		["Holmsby farm"] = "Hof der Holmsbys",
		["Into the {zone:2548}"] = "In die {zone:2548}",
		["Leave {zone:1453}"] = "{zone:1453} verlassen",
		["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42), Komuk (a Horde elite, 45) and {npc:263380} (elite, 42) range over the zone's wilds: take your beasts away from them."] = "Die meisten Wildtiere in {zone:2548} lassen {item:268632} für {npc:260231} fallen: die Uferkriecher an dieser Küste und die Eber auf dem Kamm westlich der Piraten.\nVorsicht: {npc:257001} (Elite, 42), Komuk (ein Horde-Elite, 45) und {npc:263380} (Elite, 42) streifen durch die Wildnis des Gebiets: Zieh deine Wildtiere von ihnen weg.",
		["No class trainer stands in the {zone:2548}, and the {zone:1418} & {zone:1425} guide passes none: {npc:257087} flies to {zone:1453}, where you train before you go on."] = "Im {zone:2548} gibt es keinen Klassenlehrer, und der Guide für {zone:1418} & {zone:1425} kommt an keinem vorbei: {npc:257087} fliegt nach {zone:1453}, wo du trainierst, bevor du weiterziehst.",
		["No class trainer stands in the {zone:2548}: train here in {zone:1453} before you fly on."] = "Im {zone:2548} gibt es keinen Klassenlehrer: Trainiere hier in {zone:1453}, bevor du weiterfliegst.",
		["No flight path to {area:144} yet: go to {zone:1455} (by the {area:2257} from {zone:1453}), ride out of its gates east through {zone:1426} and the tunnel into {zone:1432}, and on along the road to {area:144}."] = "Noch keine Flugroute nach {area:144}: Geh nach {zone:1455} (mit der {area:2257} von {zone:1453} aus), reite aus den Toren nach Osten durch {zone:1426} und den Tunnel nach {zone:1432} und weiter die Straße entlang nach {area:144}.",
		["No shaman trainer stands in the {zone:2548} or in {zone:1453}, and the {zone:1418} & {zone:1425} guide passes none: fly to {area:1537} and train there; {area:144} is a short flight on."] = "Weder im {zone:2548} noch in {zone:1453} gibt es einen Schamanenlehrer, und der Guide für {zone:1418} & {zone:1425} kommt an keinem vorbei: Flieg nach {area:1537} und trainiere dort; {area:144} ist nur ein kurzer Flug weiter.",
		["North along the beach from the docks: the crawlers drop the meat for {npc:259962} and the spittle for Zizplink, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "Von den Docks nach Norden den Strand entlang: Die Krabbler droppen das Fleisch für {npc:259962} und den Speichel für Zizplink, und ihre Eingeweide zählen für {npc:260231}. {npc:260235}, eine große Krabbe, huscht über die Felsen östlich der Docks. {npc:259758}, ein Rare-Elite der Stufe 49, streift an dieser Küste von den Docks bis zum Piratenlager umher: Falls du ihn siehst, halte großen Abstand.",
		["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. They stand close together: pull them one at a time. {npc:259758}, a rare elite of level 49, roams these cliffs and the beach below: if you see him, keep well away."] = "Vom Hafen nach Norden die Küste entlang: Die Plünderer und Bombardiere der Eastsea haben sich an den Hängen westlich des Freibeuterlagers zwischen ihren Pulverfässern verschanzt. Sie stehen dicht beieinander: Zieh sie einzeln. {npc:259758}, ein Rare-Elite der Stufe 49, streift über diese Klippen und den Strand darunter: Wenn du ihn siehst, halte dich fern.",
		["North of the camps the cult works ogre miners in a mine, driven by the Twilight Subjugators.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in, and pull the miners and Subjugators back out to you."] = "Nördlich der Lager lässt der Kult Ogerminenarbeiter in einer Mine schuften, angetrieben von den Unterwerfern des Schattenhammers.\nVorsicht: Twilight-Vollstrecker (Elite, Stufe 45) laufen auf ihrem Weg durch die Lager am Mineneingang vorbei. Warte, bis einer vorbei ist, bevor du hineingehst, und zieh die Arbeiter und Unterwerfer zu dir nach draußen.",
		["North past {area:16729}: fill {npc:262031}'s phial in the marsh water north-east of the tower."] = "Nach Norden an {area:16729} vorbei: Füll die Phiole von {npc:262031} im Sumpfwasser nordöstlich des Turms.",
		["North up the long valley towards {area:16685}: {npc:258023} holds a small camp below the Twilight cult's fortress."] = "Nach Norden das lange Tal hinauf Richtung {area:16685}: {npc:258023} hält ein kleines Lager unterhalb der Festung des Schattenhammerkults.",
		["North up the road to the lumber camp."] = "Nach Norden die Straße hinauf zum Holzfällerlager.",
		["North up the road to the lumber camp. {npc:256438} runs it; his third job, the saplings, comes once his plant food is in."] = "Nach Norden die Straße hoch zum Holzfällerlager. {npc:256438} leitet es; sein dritter Auftrag, die Setzlinge, kommt, sobald sein Pflanzendünger abgegeben ist.",
		["North up the track towards {area:16729}: the foreman's crate lies by the road."] = "Nach Norden den Pfad hinauf Richtung {area:16729}: Die Kiste des Vorarbeiters liegt am Weg.",
		["North-east across the fields to {area:16725}: {npc:258317} wants the Mudfin murlocs on the river thinned out, the same murlocs whose heads {npc:256438} needs, so one pass along the river does both."] = "Nach Nordosten über die Felder nach {area:16725}: {npc:258317} will, dass die Murlocs der Schlickflossen am Fluss dezimiert werden, dieselben Murlocs, deren Köpfe {npc:256438} braucht, also erledigt ein Durchgang am Fluss beides.",
		["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "Nach Nordosten die Küste entlang zum Lager der Piraten auf den Klippen. Die Freibeuter und Musketiere tragen die Schmuggelware. Auch {npc:259758} streift durch das Lager: Halte nach ihm Ausschau.",
		["North-east of Elbrim's farm, the Horde drills its trainees in the fields north of {area:16743}. Stay north of the fort: its guards are far above your level. The supply crates lie around the drill grounds. Three elites work this ground: {npc:263071} (42) walks among the trainees, {npc:263615} (42) lurks at the north end, and Komuk (45), a Horde elite, patrols the hills to the east; give each of them room.\nCareful: Rog'mar Grunts (55) guard the fort's north wall, around 59,39 to 61,41. Leave the crates and trainees by the wall and take the ones further north, around 57-61,34-37."] = "Nordöstlich von Elbrims Hof drillt die Horde ihre Rekruten auf den Feldern nördlich von {area:16743}. Bleib nördlich der Festung: Ihre Wachen liegen weit über deiner Stufe. Die Vorratskisten liegen rund um die Übungsplätze. Drei Elites streifen hier umher: {npc:263071} (42) läuft zwischen den Rekruten, {npc:263615} (42) lauert am Nordende, und Komuk (45), ein Elite der Horde, patrouilliert in den Hügeln im Osten; halte Abstand zu allen dreien.\nVorsicht: Grunzer von Rog'mar (55) bewachen die Nordmauer der Festung, etwa bei 59,39 bis 61,41. Lass die Kisten und Rekruten an der Mauer liegen und nimm die weiter nördlich, etwa bei 57-61,34-37.",
		["North-east to {npc:263367}'s workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "Nach Nordosten zur Werkstatt von {npc:263367}. Der Belastungstest von {npc:263367} ist ein Kampf gegen seinen G45-B4G neben der Werkstatt: Gib die Quest ab, sobald er besiegt ist.",
		["North-west to {area:16726}, the ogres' town. Its ogres side with the Horde and attack you on sight, and Clugfist on his hill in the middle is an elite (level 50): keep to the town's north-eastern edge, where {npc:259057} hides."] = "Nach Nordwesten nach {area:16726}, der Stadt der Oger. Ihre Oger stehen auf der Seite der Horde und greifen dich sofort an, und Clugfist auf seinem Hügel in der Mitte ist Elite (Stufe 50): Halte dich am nordöstlichen Rand der Stadt, wo sich {npc:259057} versteckt.",
		["On east along the road to {area:16724}. {npc:257087}, the gryphon master, stands at its western gate; {npc:260070} and {npc:260080} are on the way in, {npc:263613} tends the wounded by the barracks, {npc:257558} and {npc:257591} wait in the keep at the east end, and the inn is in the south of the walls."] = "Weiter nach Osten die Straße entlang nach {area:16724}. {npc:257087}, die Greifenmeisterin, steht am Westtor; {npc:260070} und {npc:260080} sind auf dem Weg hinein, {npc:263613} versorgt die Verwundeten bei der Kaserne, {npc:257558} und {npc:257591} warten in der Burg am Ostende, und das Gasthaus liegt im Süden innerhalb der Mauern.",
		["One of Benjy's horses ran north up the river, past the farm. Give it the feed, then lead it home."] = "Eines von Benjys Pferden ist am Hof vorbei nach Norden den Fluss hinauf gelaufen. Gib ihm das Futter und führ es dann nach Hause.",
		["Rotflesh Mushrooms"] = "Faulfleischpilze",
		["Saplings"] = "Setzlinge",
		["Search around the stables south of the farmhouse for the horses' tracks; the bundles of hay lie around the farm."] = "Such um die Ställe südlich des Bauernhauses nach den Spuren der Pferde; die Heubündel liegen auf dem Hof verteilt.",
		["Shaman trainer"] = "Schamanenlehrer",
		["South across the plains to {area:16724}: {npc:257591} and {npc:257558} stand together in the keep at the east end, {npc:257591} first, her news is what Brant's next orders wait on. With {area:16723} saved, {npc:263089} by the orchard and {npc:263613} by the barracks have work for you too."] = "Nach Süden über die Ebene nach {area:16724}: {npc:257591} und {npc:257558} stehen zusammen in der Burg am Ostende, zuerst {npc:257591}, denn Brants nächste Befehle warten auf ihre Nachrichten. Da {area:16723} gerettet ist, haben auch {npc:263089} beim Obstgarten und {npc:263613} bei der Kaserne Aufgaben für dich.",
		["South back to {area:16724}."] = "Zurück nach Süden zur {area:16724}.",
		["South-east out of the hills towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "Nach Südosten aus den Hügeln Richtung Hafen: Die Uferkriecher am Strand nördlich der Docks liefern die Innereien am schnellsten. Auch {npc:259758} wandert zu diesem Strand hinunter.",
		["South-east, round {area:16743}'s east side, to {npc:263367}'s workshop on the hill. Komuk and the {area:16726} ogres walk the road east of the fort: let them pass before you cross it."] = "Nach Südosten, an der Ostseite von {area:16743} vorbei, zur Werkstatt von {npc:263367} auf dem Hügel. Komuk und die Oger von {area:16726} laufen die Straße östlich der Festung ab: Lass sie vorbeiziehen, bevor du sie überquerst.",
		["South-west across the plains to {area:16724}: {npc:257558} in the keep at the east end."] = "Nach Südwesten über die Ebene nach {area:16724}: {npc:257558} in der Burg am östlichen Ende.",
		["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "Vom Hafen nach Südwesten am Ufer entlang: Die Salzwassermurlocs lagern an den Stränden. Unterwegs ist neben dem Pfad eine bemalte Haut aufgespannt: Sie startet {quest:95260} für {npc:260231} an den Docks.",
		["South-west past {area:16744}: {npc:262399}, a prospector, has camped by the Cinderscale dragonkin's hollow."] = "Südwestlich an {area:16744} vorbei: {npc:262399}, eine Prospektorin, lagert bei der Senke der Drachkin der Glutschuppen.",
		["The Cinderscale hollow"] = "Die Senke der Glutschuppen",
		["The Eastsea pirates"] = "Die Ostmeerpiraten",
		["The Plains Coyotes roam west and south-west of the keep, towards {area:16725}."] = "Die Ebenenkojoten streifen westlich und südwestlich der Burg umher, in Richtung {area:16725}.",
		["The Rog'mar Poachers hunt the plains north of the tower; the Wildplains lions roam among them. A picked carcass lies in the grass east of the tower: its skull starts {quest:95983}.\nCareful: {npc:263380}, an elite (level 42), hunts along the river west of the plains: keep an eye on the riverbank."] = "Die Wilderer von Rog'mar jagen in der Ebene nördlich des Turms; die Löwen der Wildplains streifen zwischen ihnen umher. Ein abgenagter Kadaver liegt östlich des Turms im Gras: Sein Schädel startet {quest:95983}.\nVorsicht: {npc:263380}, ein Elite (Stufe 42), jagt westlich der Ebene am Fluss: Behalte das Ufer im Auge.",
		["The Roving Tallstriders graze the meadows south-west of the workshop; further south-west the marsh bubbles with gas: fill the vials at the vents."] = "Die Umherstreifenden Weitschreiter grasen auf den Wiesen südwestlich der Werkstatt; weiter südwestlich blubbert Gas im Sumpf: Füll die Phiolen an den Gasquellen.",
		["The Stranglethorn guide leaves Dwarves and Gnomes at their riding trainer in {zone:1426}: ride back west into {zone:1455}, where the flight to {area:69} leaves from the gryphon master."] = "Der Schlingendorntal-Guide lässt Zwerge und Gnome bei ihrem Reitlehrer in {zone:1426} zurück: Reite zurück nach Westen nach {zone:1455}, wo der Flug nach {area:69} beim Greifenmeister startet.",
		["The Twilight camps"] = "Die Lager des Schattenhammers",
		["The Twilight cult"] = "Der Schattenhammerkult",
		["The cathedral"] = "Die Kathedrale",
		["The coyote den"] = "Der Kojotenbau",
		["The coyotes den in the hills south of the farm: {npc:258522}, the big dark one, sits at the back of it; the Plains Coyotes around it drop the pelts."] = "Die Kojoten hausen in den Hügeln südlich des Hofs: {npc:258522}, der große dunkle, sitzt ganz hinten; die Ebenenkojoten drumherum lassen die Felle fallen.",
		["The crawlers and {npc:260235}"] = "Die Krabbler und {npc:260235}",
		["The cult's camps fill the valley north and west of Riftan. Free the captive Farholde Scouts as you find them, and kill a {npc:258652} for {npc:257591}: her soulstone takes it. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. {npc:256881} and {npc:256891} (elites, 46) hold the fortress at the valley's head: pull the cultists away from them."] = "Die Lager des Kults füllen das Tal nördlich und westlich von Riftan. Befreie die gefangenen Späher von Farholde, wenn du sie findest, und töte einen {npc:258652} für {npc:257591}: Ihr Seelenstein nimmt ihn auf. Twilight-Vollstrecker (Elite, Stufe 45) patrouillieren durch die Lager: Achte vor jedem Pull auf ihre Laufwege. {npc:256881} und {npc:256891} (Elite, 46) halten die Festung am Ende des Tals: Zieh die Kultisten von ihnen weg.",
		["The cultists fill the streets and fields of {area:16723}. Start at the ritual circles in the middle (fill Claire's catalyst there), work west through the burnt houses to the edge of town, then back north-east to the loose soil west of Elbrim's farm: bury the {item:266148} the Twilight Raiders drop there. The charms, pages and finger bones drop from the cultists.\nKeep the {item:4338} they drop: {npc:263613} in {area:16724} asks for twenty when you are back there. Now and then a cultist drops the {quest:94885}: right-click it to start the quest.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass; players died here more than anywhere else in the zone.\n{npc:263380}, the river's elite (level 42), can wander up from the south-western fields: let him pass."] = "Die Kultisten füllen die Straßen und Felder von {area:16723}. Beginne bei den Ritualkreisen in der Mitte (fülle dort Claires Katalysator), arbeite dich nach Westen durch die verbrannten Häuser bis zum Dorfrand, dann zurück nach Nordosten zur lockeren Erde westlich von Elbrims Hof: Vergrabe dort die {item:266148}, die die Twilight-Räuber fallen lassen. Die Talismane, Seiten und Fingerknochen droppen von den Kultisten.\nBehalte den {item:4338}, den sie fallen lassen: {npc:263613} in der {area:16724} will zwanzig, wenn du zurück bist. Ab und zu droppt ein Kultist {quest:94885}: Rechtsklicke darauf, um die Quest zu starten.\nVorsicht: {npc:256899}, ein Elite-Oger (Stufe 41), läuft durch die westlichen Straßen von {area:16723}, etwa bei 44-47,47-52. Zieh die Kultisten zu dir heraus und lass ihn vorbeiziehen; hier sind mehr Spieler gestorben als irgendwo sonst im Gebiet.\n{npc:263380}, der Elite vom Fluss (Stufe 42), kann von den südwestlichen Feldern heraufwandern: Lass ihn vorbeiziehen.",
		["The lost horse"] = "Das verlorene Pferd",
		["The meadows"] = "Die Wiesen",
		["The murlocs, south-west"] = "Die Murlocs im Südwesten",
		["The next guide starts in the {zone:1418}, south of {zone:1432}: fly to {area:144}."] = "Der nächste Guide beginnt im {zone:1418}, südlich von {zone:1432}: Flieg nach {area:144}.",
		["The next guide starts in the {zone:1418}, south of {zone:1432}: fly to {area:144}. {zone:1453}'s gryphon master stands in the {object:2096}."] = "Der nächste Guide beginnt im {zone:1418}, südlich von {zone:1432}: Flieg nach {area:144}. Der Greifenmeister von {zone:1453} steht im Bereich {object:2096}.",
		["The ogre mine"] = "Die Ogermine",
		["The pirates' second wave"] = "Die zweite Welle der Piraten",
		["The pirates' ships"] = "Die Schiffe der Piraten",
		["The plains"] = "Die Ebene",
		["The stables"] = "Die Ställe",
		["The tallstriders and the marsh"] = "Die Weitschreiter und der Sumpf",
		["The western {zone:2548}"] = "Die westlichen {zone:2548}",
		["The whelps nest all over the hollow; the warriors (level 41-42) guard its back, by the {item:271611}. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."] = "Die Welpen nisten überall in der Senke; die Krieger (Stufe 41-42) bewachen ihren hinteren Teil bei der {item:271611}. Scaldaron, ein seltener Elitedrache, kann auch hier oben sein: Lass ihn in Ruhe, außer du hast eine Gruppe.",
		["The {area:16737}"] = "{area:16737}",
		["The {area:16743} training grounds"] = "Die Übungsplätze von {area:16743}",
		["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "{npc:260244} streift durch das seichte Wasser südwestlich des Hafens, unterhalb der Strände der Murlocs. {npc:257001}, ein Elite, läuft ganz in der Nähe am Ufer entlang: Halte Abstand zu ihm.",
		["The {object:628948} poster by the inn"] = "Das Plakat {object:628948} beim Gasthaus",
		["The {object:628948} poster by the inn: {npc:260235}"] = "Das Plakat {object:628948} beim Gasthaus: {npc:260235}",
		["Train before the {zone:1418}"] = "Vor dem {zone:1418} trainieren",
		["Use {npc:256438}'s {item:266161} on bare ground around the camp: five saplings."] = "Benutze das {item:266161} von {npc:256438} auf kahlem Boden rund ums Lager: fünf Setzlinge.",
		["West across the river to {area:16736}: the Peasant Woodpiles around the camp give the wood bundles.\nCareful: {npc:263380}, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass."] = "Nach Westen über den Fluss nach {area:16736}: Die Holzstapel der Bauern rund um das Lager geben die Holzbündel.\nVorsicht: {npc:263380}, ein Elite (Stufe 42), streift am Fluss beim Lager umher: Kommt er in deine Richtung, zieh dich zurück und lass ihn vorbeiziehen.",
		["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "Westlich vom nördlichen Schiff den Grat hinauf: Die Faulfleischpilze wachsen zwischen den Felsen, nahe dem Lager der Oger des Schattenhammers. Die Ausgewachsenen Bleichhauer auf dem Grat geben ebenfalls Innereien.",
		["West into the {area:16737}: the Redridge gnolls camp on the slopes all the way from the hills west of the lumber camp to the pass you came in by. The stolen saw blades lie only in the western camps, near the pass.\nCareful: {npc:255906}, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."] = "Nach Westen nach {area:16737}: Die Gnolle des Rotkammgebirges lagern an den Hängen von den Hügeln westlich des Holzfällerlagers bis zum Pass, durch den du gekommen bist. Die gestohlenen Sägeblätter liegen nur in den westlichen Lagern nahe dem Pass.\nVorsicht: {npc:255906}, ein Elite-Gnoll (Stufe 40), streift durch die südwestlichen Lager: Zieh die Gnolle von ihm weg.",
		["West of the port, the wildflowers grow in the meadows below {npc:263367}'s workshop."] = "Westlich des Hafens wachsen die Wildblumen auf den Wiesen unterhalb der Werkstatt von {npc:263367}.",
		["West through the keep: {npc:263089} by the orchard, then the cathedral and {npc:259859} south of the inn if you have their errands."] = "Nach Westen durch die Burg: {npc:263089} beim Obstgarten, dann die Kathedrale und {npc:259859} südlich des Gasthauses, falls du Aufträge für sie hast.",
		["West to {area:16725}: {npc:258317} stands by the farmhouse."] = "Nach Westen zu {area:16725}: {npc:258317} steht beim Bauernhaus.",
		["Your class trainer"] = "Dein Klassenlehrer",
		["Your hearthstone is bound at {area:16724}'s inn: use it, or ride back south to the keep."] = "Dein Ruhestein ist im Gasthaus von {area:16724} gebunden: Benutze ihn oder reite zurück nach Süden zur Burg.",
		["fill the {item:269990} at the ritual circles"] = "fülle den {item:269990} an den Ritualkreisen",
		["find {npc:257250} and talk to him"] = "Finde {npc:257250} und sprich mit ihm",
		["free five captive Farholde Scouts"] = "Befreie fünf gefangene Späher von Farholde",
		["go with {npc:258963} to save {npc:258935}"] = "geh mit {npc:258963}, um {npc:258935} zu retten",
		["grind on {npc:257901}"] = "farme {npc:257901}",
		["help {npc:259057} break out of {area:16726}"] = "Hilf {npc:259057}, aus {area:16726} auszubrechen",
		["kill a {npc:258652}"] = "Töte einen {npc:258652}",
		["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "Führ {npc:259158} aus {area:16723} hinaus zu seinem Schatz westlich der Stadt",
		["the middle ship"] = "das mittlere Schiff",
		["the northern ship"] = "das nördliche Schiff",
		["the stress test: beat G45-B4G beside the workshop"] = "der Belastungstest: Besiege G45-B4G neben der Werkstatt",
		["the {object:645166} poster"] = "das Plakat {object:645166}",
		["walk it back to {area:16725}"] = "führ es zurück nach {area:16725}",
		["{area:16724}, the west side"] = "{area:16724}, die Westseite",
		["{area:16735} and the river"] = "{area:16735} und der Fluss",
		["{item:17028}, from {npc:272437}"] = "{item:17028}, von {npc:272437}",
		["{item:268505}, the southern ship"] = "{item:268505}, das südliche Schiff",
		["{item:268632} as you go"] = "{item:268632} nebenbei",
		["{item:269997}, on the graves"] = "{item:269997}, auf den Gräbern",
		["{item:271653}, from {npc:260565}"] = "{item:271653}, von {npc:260565}",
		["{item:271654}, from {npc:260560}"] = "{item:271654}, von {npc:260560}",
		["{item:271657}, from {npc:260487}"] = "{item:271657}, von {npc:260487}",
		["{item:272126}, on the Wounded Soldiers beside him"] = "{item:272126}, an den Verwundeten Soldaten neben ihm",
		["{npc:255906} is an elite gnoll (level 40) who roams the south-western camps of the {area:16737}: grouping up is advised."] = "{npc:255906} ist ein Elite-Gnoll (Stufe 40), der durch die südwestlichen Lager von {area:16737} streift: Eine Gruppe wird empfohlen.",
		["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881} ist ein Elite (Stufe 46) in der Festung am Ende des Tals, umgeben von den Vollstreckern: Eine Gruppe wird empfohlen.",
		["{npc:256899}, the two-headed ogre, is an elite (level 41) at the western edge of {area:16723}: grouping up is advised. Claire then has the filled catalyst for {npc:257591} in {area:16724}."] = "{npc:256899}, der zweiköpfige Oger, ist ein Elite (Stufe 41) am Westrand von {area:16723}: Eine Gruppe wird empfohlen. Claire hat danach den gefüllten Katalysator für {npc:257591} in der {area:16724}.",
		["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001} ist ein Elite (Stufe 42) am Südufer: Eine Gruppe ist ratsam.",
		["{npc:257087} flies to {zone:1453}. {npc:278088} waits in the {object:2098}."] = "{npc:257087} fliegt nach {zone:1453}. {npc:278088} wartet auf dem {object:2098}.",
		["{npc:257087}, at the western gate"] = "{npc:257087}, am Westtor",
		["{npc:257250} lies wounded among the camps at the valley's western edge.\nCareful: {npc:256881} and {npc:256891} (elites, 46) hold the fortress north of him: come at Ryan from the south."] = "{npc:257250} liegt verwundet zwischen den Lagern am Westrand des Tals.\nVorsicht: {npc:256881} und {npc:256891} (Elite, 46) halten die Festung nördlich von ihm: Nähere dich Ryan von Süden.",
		["{npc:257558}, in the keep"] = "{npc:257558}, in der Burg",
		["{npc:257558}: Kilgar's head for {npc:1748} in {object:2117}"] = "{npc:257558}: Kilgars Kopf für {npc:1748} in {object:2117}",
		["{npc:257591}: {quest:94881}, for later in this guide"] = "{npc:257591}: {quest:94881}, für später in diesem Guide",
		["{npc:257595}, at the inn"] = "{npc:257595}, im Gasthaus",
		["{npc:258963} stands at the camp's south end. He sets off for {npc:258935}, south-east of the camp, as soon as you take {quest:94861}: go with him and keep the attackers off, and wait if {npc:263380} is in sight. If it fails, {npc:258963} offers the quest again."] = "{npc:258963} steht am Südende des Lagers. Er bricht zu {npc:258935} südöstlich des Lagers auf, sobald du {quest:94861} annimmst: Geh mit ihm, halte die Angreifer fern und warte, wenn {npc:263380} in Sicht ist. Schlägt es fehl, bietet {npc:258963} die Quest erneut an.",
		["{npc:259051} keeps the west end of {area:16744}."] = "{npc:259051} steht am Westende von {area:16744}.",
		["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158} will raus aus {area:16723}: Führ ihn nach Westen zu seinem Schatz am Stadtrand und halte die Kultisten von ihm fern.",
		["{npc:259352} holds {area:16729}, the tower on the plains north-east of the crate."] = "{npc:259352} hält {area:16729}, den Turm in der Ebene nordöstlich der Kiste.",
		["{npc:259352}'s tower stands just south-west of the marsh."] = "Der Turm von {npc:259352} steht gleich südwestlich des Sumpfs.",
		["{npc:259352}'s tower."] = "Turm von {npc:259352}.",
		["{npc:259863}, by the inn: {quest:95330}, for {area:16736} later in this guide"] = "{npc:259863}, beim Gasthaus: {quest:95330}, für {area:16736} später in diesem Guide",
		["{npc:262031} keeps the old cathedral at the south-west corner of {area:16724}. The bats roost in its upper floor; {npc:272437} sells the holy candles beside it; the graves are in the chapel graveyard.\n{npc:271742}, an elite of level 53, stands in the cathedral: he leaves you be, so never attack him, and pull the bats away from him."] = "{npc:262031} hütet die alte Kathedrale in der Südwestecke von {area:16724}. Die Fledermäuse nisten im Obergeschoss; {npc:272437} verkauft daneben die heiligen Kerzen; die Gräber liegen auf dem Kapellenfriedhof.\n{npc:271742}, ein Elite der Stufe 53, steht in der Kathedrale: Er lässt dich in Ruhe, also greif ihn nie an und zieh die Fledermäuse von ihm weg.",
		["{npc:262031}, in the cathedral at the keep's south-west corner."] = "{npc:262031}, in der Kathedrale an der Südwestecke der Festung.",
		["{npc:263071} is an elite (level 42) at the Horde's training grounds north of {area:16743}, where this guide goes later: grouping up is advised."] = "{npc:263071} ist ein Elite (Stufe 42) auf dem Übungsgelände der Horde nördlich von {area:16743}, wohin dieser Guide später geht: Eine Gruppe wird empfohlen.",
		["{npc:263071}, the elite, walks the training grounds."] = "{npc:263071}, der Elite, läuft über die Übungsplätze.",
		["{npc:263089} stands west of the inn, by the orchard: the apples hang on the trees around it."] = "{npc:263089} steht westlich des Gasthauses beim Obstgarten: Die Äpfel hängen an den Bäumen ringsum.",
		["{npc:263315}, an elite lion (level 41), prowls the plains north of {area:16729}, on your way back north: grouping up is advised."] = "{npc:263315}, ein Elite-Löwe (Stufe 41), streift durch die Ebenen nördlich von {area:16729}, auf deinem Rückweg nach Norden: Eine Gruppe ist ratsam.",
		["{npc:263367}'s workshop"] = "Werkstatt von {npc:263367}",
		["{npc:263380} is an elite (level 42) who hunts along the river between {area:16725} and {area:16729}, on your way north later in this guide: grouping up is advised. The poster hangs by the keep; {npc:259859}, who takes the fang, stands south of the inn."] = "{npc:263380} ist ein Elite (Stufe 42), der am Fluss zwischen {area:16725} und {area:16729} jagt, auf deinem späteren Weg nach Norden in diesem Guide: Eine Gruppe wird empfohlen. Das Plakat hängt bei der Feste; {npc:259859}, der den Fangzahn annimmt, steht südlich des Gasthauses.",
		["{npc:263380}, the elite, hunts along the river between {area:16725} and {area:16729}, on your way north."] = "{npc:263380}, der Elite, jagt am Fluss zwischen {area:16725} und {area:16729}, auf deinem Weg nach Norden.",
		["{npc:263613} tends the wounded beside the barracks: bandage three of his soldiers, then he has a note for {npc:262031} in the cathedral."] = "{npc:263613} versorgt die Verwundeten neben der Kaserne: Verbinde drei seiner Soldaten, dann hat er eine Nachricht für {npc:262031} in der Kathedrale.",
		["{npc:263613}: twenty {item:4338}, from {area:16723}'s cultists and the pirates; hand it in when you are back"] = "{npc:263613}: zwanzig {item:4338}, von den Kultisten in {area:16723} und den Piraten; gib die Quest ab, wenn du zurück bist",
		["{npc:263749} (level 44) carries the key: he paces the lanes south of {npc:259057}'s hut.\nThe {item:275043} lies just west of the lanes: its fighters (elites, 41-45) only fight in a bout, so leave them be."] = "{npc:263749} (Stufe 44) trägt den Schlüssel: Er läuft die Gassen südlich der Hütte von {npc:259057} ab.\nDer {item:275043} liegt gleich westlich der Gassen: Seine Kämpfer (Elite, 41-45) kämpfen nur in einem Duell, also lass sie in Ruhe.",
		["{object:621813}, west of Elbrim's farm: each grave takes one of the {item:266148} the Twilight Raiders drop, so loot five first"] = "{object:621813}, westlich von Elbrims Farm: Jedes Grab braucht eines der {item:266148}, die die Twilight-Raider fallen lassen, also plündere erst fünf",
		["{quest:94877}: for later in this guide"] = "{quest:94877}: für später in diesem Guide",
		["{quest:94879}, for later in this guide"] = "{quest:94879}, für später in diesem Guide",
		["{quest:94884}: for {npc:257591} in {area:16724}"] = "{quest:94884}: für {npc:257591} in der {area:16724}",
		["{quest:94885}: only if a cultist dropped the log"] = "{quest:94885}: nur falls ein Kultist das Logbuch fallen gelassen hat",
		["{quest:94886}: for later in this guide"] = "{quest:94886}: für später in diesem Guide",
		["{quest:94887}: for later in this guide"] = "{quest:94887}: für später in diesem Guide",
		["{quest:94891}: for {npc:257591}"] = "{quest:94891}: für {npc:257591}",
		["{quest:94892}: for {npc:257558} in {area:16724}"] = "{quest:94892}: für {npc:257558} in {area:16724}",
		["{quest:94893}: for {npc:278088} in {zone:1453}"] = "{quest:94893}: für {npc:278088} in {zone:1453}",
		["{quest:94907}: for later in this guide"] = "{quest:94907}: für später in diesem Guide",
		["{quest:94928}: for {area:16727}, keep it"] = "{quest:94928}: für {area:16727}, behalte es",
		["{quest:95059}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95059}: für {npc:257558} in {area:16724}, behalte es",
		["{quest:95064}: for later, at the Horde's training grounds north of {area:16743}"] = "{quest:95064}: für später, auf dem Übungsgelände der Horde nördlich von {area:16743}",
		["{quest:95066}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95066}: für {npc:257558} in {area:16724}, behalte es",
		["{quest:95122}: for later in this guide"] = "{quest:95122}: für später in diesem Guide",
		["{quest:95123}: for later in this guide"] = "{quest:95123}: für später in diesem Guide",
		["{quest:95148}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95148}: für {npc:257558} in {area:16724}, behalte es",
		["{quest:95261}: the beasts' entrails come as you go; the mushrooms are for later"] = "{quest:95261}: Die Eingeweide der Bestien kommen unterwegs; die Pilze sind für später",
		["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267}: ein großes Ungeheuer im seichten Wasser südwestlich des Hafens, nahe {npc:257001}, dem Elite",
		["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293}: für {npc:260390} im Lager der Piraten",
		["{quest:95329}: for {npc:259352} at {area:16729}, keep it"] = "{quest:95329}: für {npc:259352} bei {area:16729}, behalte es",
		["{quest:95426}: for later, the same training grounds"] = "{quest:95426}: für später, dasselbe Übungsgelände",
		["{quest:95961}: for {npc:263120} in {area:16727}, keep it"] = "{quest:95961}: für {npc:263120} in {area:16727}, behalte es",
		["{quest:95975}: for later, the wildflowers west of the port"] = "{quest:95975}: für später, die Wildblumen westlich des Hafens",
		["{quest:95984}: for later, where the tallstriders graze by {npc:263367}'s workshop; keep it"] = "{quest:95984}: für später, wo die Weitschreiter bei der Werkstatt von {npc:263367} grasen; behalte es",
		["{quest:96009}: for {area:16736} later in this guide"] = "{quest:96009}: für {area:16736}, später in diesem Guide",
		["{quest:96084}: for later in this guide"] = "{quest:96084}: für später in diesem Guide",
		["{quest:96125}: for {npc:259057} in {area:16726}, keep it"] = "{quest:96125}: für {npc:259057} in {area:16726}, behalte es",
		["{zone:1453} flight master"] = "Flugmeister von {zone:1453}",
		["{zone:1455} flight master"] = "Flugmeister von {zone:1455}",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Back through the pass: the Stonevault troggs dig outside {area:1517} at the {zone:1418}' northern edge. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "Zurück durch den Pass: Die Stonevault-Troggs graben vor {area:1517} am nördlichen Rand von {zone:1418}. Die geschnitzten Urnen und die magentafarbenen Pilzgruppen stehen in ihren Höhlen und Tunneln, außerhalb des Dungeons selbst.",
		["Back to {zone:1432}"] = "Zurück nach {zone:1432}",
		["Fly to {area:150}"] = "Flieg nach {area:150}",
		["Fly to {area:271}"] = "Flieg nach {area:271}",
		["From Theramore, ride north into the {zone:1413} to {area:392}, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "Reite von Theramore nach Norden ins {zone:1413} nach {area:392}, oder flieg, falls du die Flugroute kennst. {npc:6251} lehrt im Haus neben der Bank.",
		["Into {zone:1418}"] = "Hinein nach {zone:1418}",
		["Into {zone:1432}"] = "Nach {zone:1432}",
		["Mudsprocket"] = "Morastwinkel",
		["Raleigh's next errand is in the {area:796}: skip it."] = "Raleighs nächster Auftrag ist im {area:796}: Überspring ihn.",
		["Ride back east to {area:1898}."] = "Reite zurück nach Osten zu {area:1898}.",
		["Ride back north to Ironband's camp."] = "Reite zurück nach Norden zu Ironbands Lager.",
		["Ride north through the pass into {zone:1432} and east along the south shore to Ironband's camp."] = "Reite nach Norden durch den Pass nach {zone:1432} und nach Osten entlang des Südufers zu Ironbands Lager.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Reite auf der Straße nach Nordosten aus {area:271} ins {zone:1425}; {area:348} liegt gleich hinter der Grenze. {npc:5635} hält oben Hof, {quest:1450} kümmert sich um den Greifenhorst und {npc:7884} steht beim Gasthaus.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Reite nach Süden aus {zone:1432} durch den Pass ins {zone:1418}; {npc:2860} lagert bei der Ausgrabung.",
		["Ride west along the loch to {area:144}."] = "Reite am See entlang nach Westen nach {area:144}.",
		["Take the road south-west out of Theramore to Mudsprocket, the goblin camp at the edge of the {area:511}. {npc:270723} and {npc:270727} stand together in the camp."] = "Nimm die Straße südwestlich aus Theramore nach Morastwinkel, dem Goblinlager am Rand des {area:511}. {npc:270723} und {npc:270727} stehen zusammen im Lager.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "Talonaxes nächste Aufgabe wartet auf einen späteren Guide für das {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Die Brühenden Welpen nisten in der Klamm östlich von {npc:2888}; lass die Versengten Wächter (Elite) in Ruhe. {item:4612} fällt selten: Nimm es mit, wenn es beim Grinden kommt.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace.\nCareful: {npc:270772} (49) and his Hexed Larvae (45) keep to the huts of the western village, around 25,64: take the necklaces from the trolls outside."] = "Die ersten beiden Käfige stehen zusammen im Dorf der Witherbark südlich von {npc:5634}; der dritte ist im nächsten Dorf östlich davon. Jeder Troll der Witherbark kann eine Halskette fallen lassen.\nVorsicht: {npc:270772} (49) und seine Verhexten Larven (45) halten sich in den Hütten des westlichen Dorfs auf, bei etwa 25,64: Hol dir die Halsketten von den Trollen draußen.",
		["The {area:1517} dig"] = "Die Ausgrabung bei {area:1517}",
		["The {area:511}"] = "{area:511}",
		["The {item:280092} grows in the bog east of the camp: gather it first. Then the Searing Hatchlings and Whelps (41-43) and the Firemane dragonkin nest in the bog north and west of Mudsprocket, on the way back; all of them drop the shed scales.\nCareful: the Firemane Scalebanes and Flamecallers are 43-44 and cast fire: pull them one at a time."] = "Die {item:280092} wächst im Sumpf östlich des Lagers: Sammle sie zuerst. Dann nisten die Sengenden Jungtiere und Welpen (41-43) und die Drachkin der Feuermähnen im Sumpf nördlich und westlich von Morastwinkel, auf dem Rückweg; alle lassen die abgeworfenen Schuppen fallen.\nVorsicht: Die Bannschuppen und Flammenrufer der Feuermähnen sind 43-44 und wirken Feuerzauber: Zieh sie einzeln.",
		["Then ride back north-east to Theramore's flight master."] = "Reite dann zurück nach Nordosten zum Flugmeister von Theramore.",
		["Theramore"] = "Theramore",
		["Theramore flight master"] = "Flugmeister von Theramore",
		["Warlock: {quest:3631}"] = "Hexenmeister: {quest:3631}",
		["Witherbark villages"] = "Dörfer der Witherbark",
		["{area:144} flight master"] = "Flugmeister in {area:144}",
		["{area:348} flight master"] = "Flugmeister von {area:348}",
		["{item:8047}; below ground"] = "{item:8047}; unter der Erde",
		["{npc:1470} is below ground in {area:144}, by the inn, where the flight lands. His mushrooms grow in the {area:1517} dig at the {zone:1418}' northern edge, on this guide's loop back north."] = "{npc:1470} ist unter der Erde in {area:144}, beim Gasthaus, wo der Flug landet. Seine Pilze wachsen an der Ausgrabung von {area:1517} am Nordrand des {zone:1418}, auf der Runde dieses Guides zurück nach Norden.",
		["{npc:1470}, below ground"] = "{npc:1470}, unter der Erde",
		["{npc:2277} stands in {area:271}, by the inn."] = "{npc:2277} steht in {area:271}, beim Gasthaus.",
		["{npc:269577} camps at the foot of the pass into {zone:1432}, on the way north."] = "{npc:269577} lagert am Fuß des Passes nach {zone:1432}, auf dem Weg nach Norden.",
		["{npc:269577}'s {item:278404} lies in the middle of the Stonevault trogg camp, where {quest:739} walks."] = "Die {item:278404} für {npc:269577} liegt mitten im Lager der Steingewölbetroggs, wo {quest:739} umherläuft.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "Die nächste Quest von {npc:2817} gibt keine Erfahrung: Überspring sie.",
		["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817}: Blue Pearls aus Schlingendorntal",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} lagert allein in {area:1898}, südöstlich der Ausgrabungsstätte.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "Die nächste Aufgabe von {npc:2888} ist eine Elitejagd: Überspring sie.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} bleibt nicht bei {area:342}: Er läuft mit seinen Wachen eine lange Runde durch das {zone:1418}, vom Lager im Westen am Südrand der Zone entlang bis etwa 61,69, nach Norden bis etwa 49,49 und zurück nach Westen zum Lager. Der Pfeil folgt seiner Runde von hier aus nach Westen, bis du ihn triffst.",
		["{npc:3980} preaches by the inn."] = "{npc:3980} predigt beim Gasthaus.",
		["{npc:3980}, upstairs"] = "{npc:3980}, oben",
		["{npc:4794}, inside"] = "{npc:4794}, drinnen",
		["{npc:4944}, on the top floor"] = "{npc:4944}, im obersten Stockwerk",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} lagert an der Straße östlich von {area:348}.",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, neben dem Flugmeister ganz oben; drinnen",
		["{npc:7884}, inside"] = "{npc:7884}, drinnen",
		["{object:2743}; below ground"] = "{object:2743}; unter der Erde",
		["{quest:1450}, inside"] = "{quest:1450}, drinnen",
		["{quest:706}: its {item:4612} is a rare drop, so the work and hand-in are optional too"] = "{quest:706}: {item:4612} ist ein seltener Drop, daher sind das Sammeln und die Abgabe ebenfalls optional",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the coast"] = "Zurück zur Küste",
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Zurück zu den {area:1117}. Jeder Naga der Hasskämme dort kann Schuppen droppen.",
		["Boat to {area:1108}"] = "Boot nach {area:1108}",
		["Boat to {area:1116}"] = "Boot nach {area:1116}",
		["Boats to and from the island"] = "Boote zur Insel und zurück",
		["Careful: {npc:222286}, an elite of level 43, stands at the camp's north-east edge, around 67,39: pull the Naturalists, Raiders and Shamans away from her."] = "Vorsicht: {npc:222286}, ein Elite der Stufe 43, steht am Nordostrand des Lagers, bei etwa 67,39: Zieh die Naturalists, Raiders und Shamans von ihr weg.",
		["Coming from the south: {npc:7877} and {npc:7878} first, then {npc:7900} beside {npc:7880}'s building, then the stairs. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:7852} is by the flight master, on the way out."] = "Von Süden kommend: zuerst {npc:7877} und {npc:7878}, dann {npc:7900} neben dem Gebäude von {npc:7880}, dann die Treppe. {npc:7880} steht im Obergeschoss seines Gebäudes: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden. {npc:7852} ist beim Flugmeister, auf dem Weg hinaus.",
		["Feathermoon flight master"] = "Flugmeister von Feathermoon",
		["Feathermoon's isle, ogres, yetis and the {area:1121}."] = "Mondfederinsel, Oger, Yetis und die {area:1121}.",
		["Fly to {area:489}"] = "Flieg nach {area:489}",
		["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Reite von {area:489} nach Westen entlang der Straße zum Lager der Grimtotem nördlich davon. {npc:7956} wartet davor; befreie die Sprite Darters aus dem Pferch in der Mitte und halte {npc:7956} und mindestens sechs von ihnen am Leben.",
		["Gordunni ogres"] = "Oger der Gordunni",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["Grimtotem tauren"] = "Tauren der Grimmtotem",
		["Grind to 45"] = "Grinde bis 45",
		["Hatecrest naga"] = "Naga der Hasskämme",
		["Into {zone:1413}"] = "Hinein nach {zone:1413}",
		["Ironfur bears"] = "Eisenfellbären",
		["No flight path to {area:489} yet: take the boat back to the coast and ride east along the road to {area:489}, on the {zone:1441} border."] = "Noch keine Flugroute nach {area:489}: Nimm das Boot zurück zur Küste und reite nach Osten die Straße entlang nach {area:489}, an der Grenze zu {zone:1441}.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north.\nCareful: the {npc:5236} are 44-45 and the Warlocks 43-44, casters a level or two over you here: pull them one at a time from the camp's edge, and take the Brutes (42-43) on the slopes first."] = "Reite nach Osten zum Lager der Gordunni in den Hügeln südöstlich des Yetitals: Hexenmeister und Schamanen halten das Lager, Schläger streifen über die Hänge drumherum und weiter nördlich.\nVorsicht: Die {npc:5236} sind Stufe 44-45 und die Hexenmeister 43-44, Zauberwirker also ein oder zwei Stufen über dir: Zieh sie einzeln vom Rand des Lagers und nimm dir zuerst die Schläger (42-43) an den Hängen vor.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Reite nach Norden ins Yetital. Jeder Wildschrammyeti kann einen dicken Yetibalg droppen; {npc:5346} (Stufe 48) streift durch die Mitte.",
		["Ride north out of {area:1105}: the Ironfur Bears (41-42) at the foot of the {area:1136} drop Rhapsody's last liver.\nCareful: Ironfur Patriarchs (48-49) and the Rage Scar yetis (46-49) roam the hills further north: stay at their edge."] = "Reite nach Norden aus dem {area:1105}: Die Eisenfellbären (41-42) am Fuß der {area:1136} droppen Rhapsodys letzte Leber.\nVorsicht: Eisenfellpatriarchen (48-49) und die Yetis von Rage Scar (46-49) streifen weiter nördlich durch die Hügel: Bleib an ihrem Rand.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Reite nach Nordosten zum Außenposten der Nachtelfen an der Grenze zu {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Reite nach Südosten zu den Gnollen der Waldpfoten; die Rucksäcke des Kuriers liegen in ihrem südlichen Lager, und ein Paket darin startet eine Lieferung nach {area:489}. Der Stock der Zukk'ash liegt gleich südlich: Kämpf dich hinunter zur Kapsel, in der Raschal steckt, befreie ihn und halte ihn auf dem Weg nach draußen am Leben.",
		["Ride to {area:489}"] = "Reite nach {area:489}",
		["Ride west into {area:1105}: its yetis are 43-45. The Rage Scar yetis in the hills to the north are 46-49: leave them. Or, with a group, run the {area:978} dungeon instead."] = "Reite nach Westen in das {area:1105}: Seine Yetis sind 43-45. Die Yetis von Rage Scar in den Hügeln im Norden sind 46-49: Lass sie in Ruhe. Oder lauf mit einer Gruppe stattdessen den Dungeon {area:978}.",
		["Stays on the main route"] = "Bleibt auf der Hauptroute",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Nimm das Boot zum Gebiet {area:1108} und folge dem Ufer nach Süden zum zerstörten Ruderboot am Strand.",
		["The courier's boat"] = "Das Boot des Kuriers",
		["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "Die {area:1121} ist die Insel direkt südlich von {area:1120}: Schwimm hinüber. Hatecrest Serpent Guards und Sorceresses halten sie; {npc:8136} (Stufe 47) wartet in der Höhle an ihrem Südende. Zieh zuerst seine Wachen.",
		["Then on to {zone:1446}"] = "Dann weiter nach {zone:1446}",
		["Two new flight paths for later"] = "Zwei neue Flugrouten für später",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Geh auf der Insel nach Süden zu den Ruinen der Naga; der Pavillon steht zwischen ihnen.",
		["You came into {zone:1444} from {zone:2652}, so {area:489}'s flight path is still to learn: take the boat back to the coast and ride east along the road; you pick up the flight path when this guide ends at {area:489}."] = "Du bist aus {zone:2652} nach {zone:1444} gekommen, daher fehlt dir noch die Flugroute von {area:489}: Nimm das Boot zurück zur Küste und reite nach Osten die Straße entlang; die Flugroute holst du dir, wenn dieser Guide in {area:489} endet.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "für Tyrande in {zone:1457}: Die Route führt dich mit 47 dorthin",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "grinde an {npc:5292} im {area:1105}, {zone:1444}",
		["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{area:1116} liegt auf {area:1120}, vor der {area:1108}: Das Boot vom Steg der Küste setzt dorthin über. {npc:7880} steht im Obergeschoss seines Gebäudes: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{area:489} flight master"] = "Flugmeister von {area:489}",
		["{item:11463}, from the backpacks"] = "{item:11463}, aus den Rucksäcken",
		["{item:9248}; below ground"] = "{item:9248}; unter der Erde",
		["{npc:3936}, beside him"] = "{npc:3936}, neben ihm",
		["{npc:4048} walks around {area:489}: look inside the circle on the map"] = "{npc:4048} läuft um {area:489} herum: Schau in den Kreis auf der Karte",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: Seine Antwort wartet später in {area:702}",
		["{npc:7852}'s next order, Improved Quality, wants Rage Scar hides from yetis of 46-49: skip it."] = "Der nächste Auftrag von {npc:7852}, Verbesserte Qualität, verlangt Häute von Narbenwut-Yetis der Stufe 46-49: Überspring ihn.",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, oben in der Festung",
		["{npc:7879}, upstairs"] = "{npc:7879}, oben",
		["{npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:7880} steht im Obergeschoss seines Gebäudes: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} wartet bis zum Ende der Runde auf dem Festland.",
		["{object:164954}, inside"] = "{object:164954}, drinnen",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["\"Sea Wolf\" MacKinley in {area:35}: the route takes you there at the end of the {zone:1425} guide, keep it"] = "„Sea Wolf“ MacKinley in {area:35}: Die Route bringt dich am Ende des Guides für {zone:1425} dorthin, behalte es",
		["Boat to {area:150}"] = "Schiff nach {area:150}",
		["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "Vorsicht: Diebe wirken Entwaffnen. Schurken bleiben mit Schleichen versteckt. Assassinen benutzen Hinrichten, wenn deine Gesundheit bei 20 % oder darunter liegt.",
		["Class trainer"] = "Klassenlehrer",
		["Fly to {area:271}"] = "Flieg nach {area:271}",
		["Fly to {area:348}"] = "Flieg nach {area:348}",
		["Fly to {area:442}"] = "Flieg nach {area:442}",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Folge der Küste nach Süden zur Piratenbucht. Südmeerpiraten drängen sich am Strand und auf den Booten: Arbeite dich am Rand entlang und zieh einzeln. {npc:7883} steht auf der anderen Seite; die gestohlene Fracht von {npc:7881} liegt im Lager.\nVorsicht: Zwei oder drei Piraten stehen bei {npc:7883}, und viele weitere Piraten aus der Stadt greifen in den Kampf ein, sobald er beginnt.",
		["For your {area:978} run, later in this guide: {quest:2864} wants scarab shells, {npc:7407}, by the water tower, his {quest:2768} back, and Trenton Lighthammer Troll Temper from the Sandfury trolls."] = "Für deinen Run durch {area:978}, später in diesem Guide: {quest:2864} will Skarabäuspanzer, {npc:7407} beim Wasserturm seinen {quest:2768} zurück, und Trenton Lighthammer Troll Temper von den Trollen der Sandfury.",
		["From {npc:6015}, {area:977} is just west along the shore."] = "Von {npc:6015} aus liegt {area:977} gleich westlich am Ufer entlang.",
		["Gives the {item:8585}"] = "Gibt dir den {item:8585}",
		["No flight path to {area:348} yet: ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border."] = "Noch keine Flugroute nach {area:348}: Reite auf der Straße nach Nordosten aus {area:271} hinaus ins {zone:1425}; {area:348} liegt gleich hinter der Grenze.",
		["Pool by {area:979}"] = "Teich bei der {area:979}",
		["Portal to {zone:1438}"] = "Portal nach {zone:1438}",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Reite zurück nach Westen in Richtung {area:976}. Die Wastewander-Banditen und -Diebe halten die Dünen auf dem Weg; jeder von ihnen kann einen Wasserbeutel tragen.\nVorsicht: Wastewander Rogues (Stufe 43-44) bewegen sich getarnt, sodass sie sich unbemerkt nähern können.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Reite nach Osten über die Dünen zum Goblinhafen an der Nordostküste.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool to tap it; the trolls stand close, so pull the nearest first.\nCareful: tapping the pool brings Scarabs (level 44-47) out of the sand to attack you: tap it, then step away from the trolls and fight the Scarabs one by one."] = "Reite nach Nordwesten zum Trolllager der Sandfury bei der {area:979}. Benutze den {item:8584} am Rand des Teichs, um ihn anzuzapfen; die Trolle stehen dicht beieinander, also zieh zuerst den nächsten.\nVorsicht: Beim Anzapfen kommen Skarabäen (Stufe 44-47) aus dem Sand und greifen dich an: Zapf ihn an, geh dann von den Trollen weg und bekämpfe die Skarabäen einzeln.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Reite nach Süden zum Grabungslager an der {area:1938}. {npc:7771} gibt dir einen Detektorhelm: Trag ihn, um die Hügel von {quest:3161} zu sehen, die dicht im Sand rund um das Lager und nach Südwesten Richtung Oger liegen.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Reite vom Gebiet {area:439} nach Südosten nach {zone:1446}. {area:976} liegt gleich hinter der Grenze.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Reite nach Südosten zum {area:985}. {npc:7847} steht in der Mitte des südlichen Wastewander-Lagers: Räum zuerst um ihn herum.\nVorsicht: Zwei getarnte Wastewander Rogues begleiten ihn, wohin er auch geht. An seinem Spawn-Lager sind zwei Schattenmagier und ihre Diener nah genug, um in einen Kampf mit ihm einzugreifen. Draußen bei den Türmen kannst du ihn ohne sie bekämpfen.",
		["Ride south-west to the ogre compound and keep to its south end; the compound's quest waits for the Un'Goro guide.\nWhy the grind to 47: {npc:5955} waits at the edge of the {quest:3362} (mobs of 48-50). Grind it on the Dunemaul Ogres (45-46) at the compound's south end, the safer camp, not on the Brutes and Enforcers (46-48) inside."] = "Reite nach Südwesten zum Ogergelände und halte dich an dessen Südende; die Quest des Geländes wartet auf den Un'Goro-Guide.\nWarum bis 47 grinden: {npc:5955} wartet am Rand von {quest:3362} (Mobs der Stufe 48-50). Grinde an den Ogern der Dünenbrecher (45-46) am Südende des Geländes, dem sichereren Lager, nicht an den Schlägern und Vollstreckern (46-48) drinnen.",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Tritt durch das Portal nach {zone:1457}. Der Tempel des Mondes liegt im Süden der Stadt.",
		["Take the boat from {area:442}'s dock to {area:702}; {npc:3838}, the hippogryph master, stands on the rise just east of the landing: learn the flight path on the way up to the village."] = "Nimm das Boot vom Steg in {area:442} nach {area:702}; {npc:3838}, der Hippogryphenmeister, steht auf der Anhöhe gleich östlich der Anlegestelle: Lerne die Flugroute auf dem Weg hinauf zum Dorf.",
		["Temple of the Moon"] = "Tempel des Mondes",
		["The Wanted poster beside him"] = "Der Steckbrief neben ihm",
		["The pool by {area:979}"] = "Der Teich bei der {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "Derselbe Steckbrief: {npc:7847} kommt viel später, nach {area:976}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Die stärkeren Wastewander-Schurken, -Schattenmagier und -Assassinen lagern südöstlich von {area:976}, südlich der Banditen. Lass {npc:7847} in der Mitte des südlichen Lagers für später übrig.\nVorsicht: Wastewander Rogues bleiben außerhalb des Kampfes im Schleichen, sodass versteckte Schurken in einen Kampf eingreifen können, den du an einem Lager beginnst.",
		["The {area:1938}"] = "Die {area:1938}",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}: {npc:7407}, beim Wasserturm.",
		["The {quest:3042}: {npc:7804}, in town."] = "{quest:3042}: {npc:7804}, in der Stadt.",
		["Your {area:978} scarab shells: {npc:7876}, on the north side of town."] = "Deine Skarabäuspanzer aus {area:978}: {npc:7876}, auf der Nordseite der Stadt.",
		["grind on {npc:5471}, at the compound's south end"] = "Grinde an {npc:5471}, am Südende des Lagers",
		["keep it: the {area:982}'s Centipaar (48-50) wait for the Un'Goro guide's {area:976} landing at about 49.5"] = "Behalte sie: Die Centipaar (48-50) im {area:982} warten auf die Landung in {area:976} im Un'Goro-Guide bei etwa 49,5",
		["the book on her table"] = "das Buch auf ihrem Tisch",
		["the soil comes from {zone:1449}, later"] = "die Erde kommt später aus {zone:1449}",
		["{area:1336}: kill these as you meet them"] = "{area:1336}: Töte diese, sobald sie dir begegnen",
		["{area:150} flight master"] = "Flugmeister von {area:150}",
		["{area:1937}: kill these as you meet them"] = "{area:1937}: Töte diese, sobald sie dir begegnen",
		["{area:702} flight master"] = "Flugmeister von {area:702}",
		["{area:976} flight master"] = "Flugmeister von {area:976}",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the pool.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978} ist ein Dungeon für eine Gruppe aus fünf Spielern; seine Quests hier sind Stufe 45 bis 47. Das Tor liegt etwa 400 Meter nördlich des Teichs.\nDrinnen: Die Skarabäen lassen die Panzer fallen, jeder Troll der Sandfury kann {quest:3042} fallen lassen, und {npc:7604} trägt {quest:2768} bei sich.",
		["{item:278186}, from any Dunemaul ogre"] = "{item:278186}, von jedem Oger der Dünenbrecher",
		["{npc:11758}: keep it, the {area:983} waits for the same landing"] = "{npc:11758}: Behalte sie, das {area:983} wartet auf dieselbe Landung",
		["{npc:270263}, just east of the aviary: {quest:86616}, from the {area:355}'s Soothsayers"] = "{npc:270263}, gleich östlich des Greifenhorsts: {quest:86616}, von den Sterndeutern am {area:355}",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, oben im Baum",
		["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454}: {quest:1137}, von Martek in {zone:1418}",
		["{npc:5636}, beside the flight master"] = "{npc:5636}, neben dem Flugmeister",
		["{npc:5636}: {quest:86620}, the eggs in the hills just east of {area:348}"] = "{npc:5636}: {quest:86620}, die Eier in den Hügeln gleich östlich von {area:348}",
		["{npc:5955}'s escort"] = "Eskorte von {npc:5955}",
		["{npc:5955}, beside her: Oasis"] = "{npc:5955}, neben ihr: Oase",
		["{npc:7407}, by the water tower"] = "{npc:7407}, beim Wasserturm",
		["{npc:7408}, next to him"] = "{npc:7408}, neben ihm",
		["{npc:7564}: keep it for the same landing"] = "{npc:7564}: Behalte sie für dieselbe Landung",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: Seine Kiste geht später nach {area:702}",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, in der Taverne des Hafens; drinnen",
		["{npc:7881}, inside"] = "{npc:7881}, drinnen",
		["{npc:7882}, inside"] = "{npc:7882}, drinnen",
		["{npc:7882}: {quest:97530}, the bangles come from the ogres on your way south"] = "{npc:7882}: {quest:97530}, die Armreife bekommst du von den Ogern auf deinem Weg nach Süden",
		["{npc:7884}, inside"] = "{npc:7884}, drinnen",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} steht oben, über {npc:7916}: Geh drinnen hinauf, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "Der nächste Auftrag von {npc:7907} führt nach {zone:1446}: Überspring ihn.",
		["{npc:7916}: the feathers lie in the {zone:1425}, next"] = "{npc:7916}: Die Federn liegen im {zone:1425}, als Nächstes",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, drinnen",
		["{quest:2864}, north side of town"] = "{quest:2864}, an der Nordseite der Stadt",
		["{quest:2864}: keep it, the {quest:3362} waits for the Un'Goro guide's {area:976} landing"] = "{quest:2864}: Behalte sie, {quest:3362} wartet auf die Landung in {area:976} im Un'Goro-Guide",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: die Skarabäen, drinnen",
		["{quest:2873}; upstairs"] = "{quest:2873}; oben",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: die Trolle der Sandfury, drinnen",
		["{zone:1457} first, while you are on this side of the sea: Troyas' answer, {npc:7763}'s crate, Tyrande and the soil errand, then the boat from {area:442} to {area:150} and the gryphon to {area:348}."] = "Zuerst {zone:1457}, solange du auf dieser Seite des Meeres bist: Troyas' Antwort, die Kiste von {npc:7763}, Tyrande und der Auftrag mit der Erde, dann das Schiff von {area:442} nach {area:150} und der Greif nach {area:348}.",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "„Sea Wolf“ MacKinley, im obersten Stockwerk",
		["Class trainer"] = "Klassenlehrer",
		["Fly to {area:1537}"] = "Flieg nach {area:1537}",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Gorilla hills"] = "Gorillahügel",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last.\nCareful: three waves of gorillas come one after another with little rest between, then {npc:1514}. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy."] = "Gib die Fangzähne ab und bleib da: Drei Wellen Gorillas kommen, {npc:1514} zuletzt.\nVorsicht: Drei Wellen Gorillas kommen kurz hintereinander, danach {npc:1514}. Fang mit voller Gesundheit und vollem Mana an und bleib in Unbagwas Nähe. Manche Klassen tun sich allein schwer: Mit einem Freund ist es einfach.",
		["Inside"] = "Drinnen",
		["Leave town by the tunnel and ride north along the coast past the Bloodsail camp: the naga comb the beaches beyond it and drop the reeds."] = "Verlass die Stadt durch den Tunnel und reite an der Küste nach Norden am Lager der Blutsegel vorbei: Die Naga durchkämmen die Strände dahinter und lassen das Schilf fallen.",
		["Lost Gryphon Eggs"] = "Verlorene Greifeneier",
		["MacKinley's next task sends you after elite ogres: skip it."] = "MacKinleys nächster Auftrag schickt dich zu Elite-Ogern: Überspring ihn.",
		["Naga Explorers"] = "Forscher der Naga",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the way back to {area:348}: the lost gryphon eggs lie in the hills just east of the aviary."] = "Auf dem Rückweg nach {area:348}: Die verlorenen Greifeneier liegen in den Hügeln gleich östlich des Greifenhorsts.",
		["Ride back down to town."] = "Reite zurück hinunter in die Stadt.",
		["Ride back south-east to the Mistvale gorilla hills above {area:35}. {npc:1449} sits among the gorillas: take ten Gorilla Fangs from the Elder Mistvale Gorillas first."] = "Reite zurück nach Südosten zu den Gorillahügeln des Nebeltals oberhalb von {area:35}. {npc:1449} sitzt zwischen den Gorillas: Hol dir zuerst zehn Gorillafangzähne von den Alten Nebeltalgorillas.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Reite nach Norden zum {area:351} in der Mitte von {zone:1425}. Green Sludges und Jade Oozes kriechen rundherum.\nVorsicht: Panther bewegen sich getarnt durch das Gebiet.",
		["Ride on north along the coast to Zanzil's village. Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Reite weiter an der Küste nach Norden zu Zanzils Dorf. Jeder Anhänger Zanzils kann die Mixtur fallen lassen; {npc:2537} läuft im Süden des Lagers umher.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Reite nach Südosten zum {area:355}, dem Stufentempel der Vilebranch im Süden von {zone:1425}, und steig ganz nach oben. Qiaga und {npc:8636} (Elite, 50) stehen dort oben: Berühre die Spitze und komm direkt wieder herunter.\nVorsicht: Elite-Trolle bewachen die oberste Plattform, darunter {npc:7996} und {npc:8636}, zusammen mit mehreren Vilebranch Soothsayers. Die Soothsayers wirken Zauber und sind mit dem Rest der Gruppe verbunden.",
		["Set your hearth at the {object:26486}: the {zone:1427} guide starts with the hearth back here and the gryphon to {area:144}."] = "Binde deinen Ruhestein bei {object:26486}: Der Guide für {zone:1427} beginnt mit dem Ruhestein zurück hierher und dem Greif nach {area:144}.",
		["The Bloodsail captains"] = "Die Kapitäne der Blutsegelbukaniere",
		["The charts and orders lie in the pirate camp on the {area:43}, just south of {area:35}; its Swashbucklers walk the shore. The Warlocks and Swashbucklers (41-43) are under you now."] = "Die Karten und Befehle liegen im Piratenlager an der {area:43}, gleich südlich von {area:35}; seine Säbelrassler laufen am Ufer entlang. Die Hexenmeister und Säbelrassler (41-43) liegen jetzt unter deiner Stufe.",
		["The three Bloodsail ships lie at anchor off the coast just south of {area:35}: {npc:2550} (45) and {npc:2548} (46) on the nearer decks, {npc:2546} (48) on the flagship, each with a crew of 42-45 pirates. Swim out, clear each deck from the edge and pull one at a time."] = "Die drei Blutsegel-Schiffe liegen vor der Küste direkt südlich von {area:35} vor Anker: {npc:2550} (45) und {npc:2548} (46) auf den näheren Decks, {npc:2546} (48) auf dem Flaggschiff, jeweils mit einer Besatzung von 42-45 Piraten. Schwimm hinaus, räum jedes Deck vom Rand aus und zieh einzeln.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:1494} (Elite der Stufe 52) braucht eine Gruppe von 2. Überspring ihn, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {quest:8552} braucht eine Gruppe von 2. Überspring sie, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["Tram to {zone:1453}"] = "Tiefenbahn nach {zone:1453}",
		["Unbagwa's ritual"] = "Unbagwas Ritual",
		["Vilebranch Soothsayers"] = "Sterndeuter der Vilebranch",
		["Wildkin feathers"] = "Wildekinfedern",
		["Zanzil's village"] = "Zanzils Dorf",
		["for {npc:2616} in Theramore: keep it, the Un'Goro guide lands there"] = "für {npc:2616} in Theramore: Behalte es, der Un'Goro-Guide endet dort",
		["{area:1537} inn"] = "Gasthaus von {area:1537}",
		["{area:348} flight master"] = "Flugmeister von {area:348}",
		["{area:43}: kill these as you meet them"] = "{area:43}: Töte diese, sobald sie dir begegnen",
		["{npc:1449}, inside {area:1742}"] = "{npc:1449}, in {area:1742}",
		["{npc:2487}, top floor"] = "{npc:2487}, oberstes Stockwerk",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}s nächster Zanzil-Auftrag beginnt in {zone:1441}: Überspring ihn.",
		["{npc:2498}, inside"] = "{npc:2498}, drinnen",
		["{npc:2535} and {npc:2536} stand together in the hills just north of Zanzil's village."] = "{npc:2535} und {npc:2536} stehen zusammen in den Hügeln gleich nördlich von Zanzils Dorf.",
		["{npc:270263}, just east of the aviary"] = "{npc:270263}, gleich östlich des Greifenhorsts",
		["{npc:5636}, inside"] = "{npc:5636}, drinnen",
		["{npc:7916}'s Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam: pick them up as you ride between the altar and {area:351}."] = "Die Wildekinfedern für {npc:7916} liegen überall im {zone:1425} am Boden, südlich und östlich von {area:348}, wo die Eulenbestien umherstreifen: Heb sie auf, während du zwischen dem Altar und {area:351} hin und her reitest.",
		["{zone:1453} flight master"] = "Flugmeister von {zone:1453}",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Below ground"] = "Unter der Erde",
		["Carry the {object:149047} south along the rim of the Cauldron and light the four Sentry Braziers, from the south-west round to the south-east."] = "Trag die {object:149047} am Rand des Kessels entlang nach Süden und entzünde die vier Wachkohlenbecken, vom Südwesten herum bis zum Südosten.",
		["Class trainer"] = "Klassenlehrer",
		["Dorius stands by the road beside the {area:247}. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "Dorius steht an der Straße neben der {area:247}. Eskortiere ihn nach Nordosten nach {area:1959} und halte ihn am Leben; wenn es vorbei ist, lies den {object:175704}, den er auf der Straße zurücklässt.",
		["Fly to {area:144}"] = "Flieg nach {area:144}",
		["Fly to {area:1537}"] = "Flieg nach {area:1537}",
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "Für {npc:8256} in {zone:1455}, am Ende dieses Guides",
		["Four rune rubbings in {zone:1447}: keep it"] = "Vier Runenabriebe in {zone:1447}: Behalte sie",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}: the {area:247} is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "Reite von {area:144} nach Süden in das {zone:1418}, dann nach Westen an der Stadt {area:340} der Horde vorbei (halt Abstand) und den Pfad hinauf nach {zone:1427}: Die {area:247} liegt gleich hinter dem Eingang, im Südosten. Der Gefangene im hölzernen Abort will 15 {item:4306} und acht tote Dark Iron Geologists von der Grabungsstätte drumherum. Der Abort lässt sich auch mit dem Schlüssel öffnen, falls du einen gefunden hast.",
		["Golems and elementals"] = "Golems und Elementare",
		["Heavy War Golems patrol the floor of the Cauldron below {npc:8479}; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Schwere Kriegsgolems patrouillieren unterhalb von {npc:8479} über den Boden des Kessels; Magmaelementare treiben zwischen ihnen. Golems und Elementare droppen das Öl, Elementare die Herzen.",
		["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan."] = "Falls du {item:3985} oder Facing Negolash übersprungen hast, grinde hier bis Stufe 48,27, um im Plan der Route zu bleiben.",
		["Into {zone:1427}"] = "Hinein nach {zone:1427}",
		["Level 48.27"] = "Stufe 48,27",
		["Level 48.66"] = "Stufe 48,66",
		["Level 48.98"] = "Stufe 48,98",
		["Listen to {npc:8479}'s story once more."] = "Hör dir die Geschichte von {npc:8479} noch einmal an.",
		["Ride west along the north of the Gorge to {area:1446}, the scaffolded camp on the north-west rim."] = "Reite nach Westen entlang des Nordens der Schlucht nach {area:1446}, dem Gerüstlager am nordwestlichen Rand.",
		["Searing Lava Spiders"] = "Versengende Lavaspinnen",
		["Sentry Braziers"] = "Wachkohlenbecken",
		["The Grimesilt outhouse"] = "Das Grimesilt-Nebengebäude",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "Die nächste Aufgabe des Gefangenen, Geschäftsbuch aus {zone:1446}, schickt dich in die {zone:1435} und in die {zone:1445}: Überspring sie.",
		["The spiders roam the plateaus and lava pools south of {npc:8436}, on the way to {npc:8479}."] = "Die Spinnen streifen über die Plateaus und Lavatümpel südlich von {npc:8436}, auf dem Weg zu {npc:8479}.",
		["The {object:149502} it gives holds a {item:10575}: keep it for {npc:9459} in the {zone:1428}"] = "Der {object:149502}, den sie dir gibt, enthält eine {item:10575}: Behalte sie für {npc:9459} in der {zone:1428}",
		["The {object:179827} board"] = "Das Brett {object:179827}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:14621} ist ein Elite der Stufe 50: Die meisten Klassen schaffen ihn allein auf Stufe 52, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:5860} (Elite der Stufe 50) braucht eine Gruppe von 3. Überspring ihn, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:8436} stands inside the Twilight camp at {area:1442}, west of {area:1446}, among Twilight Fire Guards, Idolaters and Geomancers (level 48-49 elites), with {npc:8282} (level 51, rare elite) beside him: {quest:3377} needs a group of 4. Skip it if you are alone."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:8436} steht im Twilight-Lager bei {area:1442}, westlich von {area:1446}, zwischen Twilight-Feuerwachen, Twilight-Götzendienern und Twilight-Geomanten (Elites der Stufe 48-49), mit {npc:8282} (Stufe 51, Rare-Elite) neben sich: {quest:3377} braucht eine Gruppe von 4. Überspring sie, wenn du allein bist.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {quest:3181} braucht eine Gruppe von 2. Überspring sie, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["To {zone:1455}"] = "Zum {zone:1455}",
		["Xiggs waits in the {object:32359}."] = "Xiggs wartet im {object:32359}.",
		["grind on {npc:5839}"] = "Grinde an {npc:5839}",
		["grind on {npc:9318}"] = "Grinde an {npc:9318}",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} öffnet sich im Norden des Kessels. Die Geheimpläne liegen auf ihrem oberen Vorsprung; Incendosaurier schwimmen weiter drinnen in den Lavateichen, also zieh sie an den Rand. Halte dich von {npc:14621} und seinen Elitewachen tief drinnen fern.",
		["{area:1446} flight master"] = "Flugmeister von {area:1446}",
		["{item:18922}; below ground"] = "{item:18922}; unter der Erde",
		["{npc:8479} stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "{npc:8479} steht am Rand des Kessels, südlich von {area:1446}. Hör dir seine Geschichte an.",
		["{npc:8509} and the dragonflight's hoard are beside {npc:8479}, on the rim south of {area:1446}."] = "{npc:8509} und der Hort des Drachenschwarms befinden sich neben {npc:8479}, am Rand südlich von {area:1446}.",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: Die Schlammbestien sind im {zone:1448}, behalte sie",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} liegt zu Füßen von {npc:8479} auf dem Boden; {quest:3462} steht neben ihm.",
		["{quest:3462}: hand it in on the way back to {area:1446}"] = "{quest:3462}: Gib sie auf dem Rückweg zur {area:1446} ab",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427}: Töte diese, sobald sie dir begegnen",
		["{zone:1455} flight master"] = "Flugmeister von {zone:1455}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Back east to {npc:9619} with the glands."] = "Zurück nach Osten zu {npc:9619} mit den Drüsen.",
		["Crystal clusters stand all over the crater. The pits' Tar Lords (53-54) and the oozes around them (50-54) are over you: take the clusters on the jungle's north-eastern edge, among the Lashers and young beasts (48-50)."] = "Kristallansammlungen stehen überall im Krater. Die Teerfürsten der Gruben (53-54) und die Schlammbestien um sie herum (50-54) sind über dir: Nimm die Ansammlungen am Nordostrand des Dschungels, zwischen den Peitschern und jungen Tieren (48-50).",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Endet bei {npc:9298} in {zone:1452}: Behalte es",
		["Fly to {area:150}"] = "Flieg nach {area:150}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {area:976}"] = "Flieg nach {area:976}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Für {npc:7775} in {zone:1444}: Behalte es",
		["Lar'korwi Mates and the raft"] = "Lar'korwi-Weibchen und das Floß",
		["Level 50"] = "Stufe 50",
		["Ride back north-east to {area:976}: {npc:11758} stands on the east side of town."] = "Reite zurück nach Nordosten nach {area:976}: {npc:11758} steht auf der Ostseite der Stadt.",
		["Ride east into the eastern jungle: Bloodpetal Lashers and Threshers (48-50) drop the petals and {quest:3764}. Crystal clusters stand all over the crater, many around the foot of {area:537}: take a few extra of each colour.\nCareful: the Living Blazes (54-55) walk the top of {area:537}, and the Bloodpetal Flayers and Trappers (51-53) hold the jungle's south: take your crystals from the ridge's foot and your petals in the north.\n{npc:9998}'s scales: the {npc:9165} (48-50) glide over the north-east of the jungle and the Young Diemetradons (49-50) graze beside them. There are only ten of those: the Diemetradons (51) on the jungle's western edge, a short way west of the Threshers, drop the scales too. They are a level over you: take them one at a time."] = "Reite nach Osten in den östlichen Dschungel: Blutblütenpeitscher und -drescher (48-50) lassen die Blüten und {quest:3764} fallen. Kristallansammlungen stehen überall im Krater, viele am Fuß des {area:537}: Nimm von jeder Farbe ein paar mehr mit.\nVorsicht: Lebendige Feuer (54-55) laufen oben auf dem {area:537} umher, und Blutblütenschinder und -fallensteller (51-53) halten den Süden des Dschungels: Hol dir die Kristalle am Fuß des Kamms und die Blüten im Norden.\nSchuppen für {npc:9998}: {npc:9165} (48-50) gleiten über den Nordosten des Dschungels, und Junge Dimetrodons (49-50) grasen daneben. Davon gibt es nur zehn: Die Dimetrodons (51) am Westrand des Dschungels, ein Stück westlich der Drescher, lassen die Schuppen auch fallen. Sie sind eine Stufe über dir: Nimm sie einzeln.",
		["Ride north-west to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every {npc:271301} and {object:157936} you pass from here on."] = "Reite nach Nordwesten zum Zufluchtsort.\nHalte weiten Abstand zu den Elite-Teufelssauriern und Stegodons. Heb von hier an jeden {npc:271301} und jeden {object:157936} auf, an dem du vorbeikommst.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Reite südlich am {area:1938} vorbei zum {area:981}, den Tunneln der Hazzali; die Ausrüstung von Scrimshank liegt tief drinnen.\nVorsicht: Ein Käfer bewacht die Ausrüstung. Viele Käfer patrouillieren in den Tunneln, einige davon Stufe 50, sodass Kämpfe oft zusätzliche Adds ziehen.",
		["Ride south to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Reite nach Süden zum Ogergelände. Schläger und Vollstrecker (46-48) füllen es; {npc:12046} (49) steht in der Mitte mit Wachen um sich: Räum diese zuerst.",
		["Ride west into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley.\nCareful: the thistleshrubs wander a lot, so you can easily pull extra mobs."] = "Reite nach Westen ins {quest:3362}. Die Tausammler droppen die Drüsen; nur manche sind voll, also behalte die gefüllte. Knorrige Distelwandler und Wurzelformer teilen sich das Tal.\nVorsicht: Die Distelwandler laufen viel umher, du ziehst leicht zusätzliche Mobs.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Reite nach Westen aus {area:976} hinaus zur langen Rampe hinab in den {zone:1449}. {npc:9619} lagert am Fuß der Rampe, in der Südostecke des Kraters.",
		["Ride west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Reite nach Westen zum Bau der Centipaar in den Dünen. Jeder Centipaar kann Insektenteile droppen.\nVorsicht: Schwärmer der Centipaar wirken {npc:4196} im und außerhalb des Kampfes, was kleine Adds bringt, die dich unterbrechen.",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Die Lar'korwi-Weibchen streifen durch den Dschungel westlich von {npc:9619}. Das zerstörte Floß liegt dort am Seeufer; das kleine Bündel liegt daneben im Wasser. Behalte Kompass, Karte und Schlüssel für {npc:8737}. Jedes Wildtier im Krater kann {item:11116} fallen lassen: Rechtsklick darauf.",
		["The dead Threshadon lies by the water north of {npc:9619}.\nCareful: Venomhide Ravasaurs (50-51) hunt along the water there: pull them one at a time before you loot the carcass.\nAny ravasaur may drop a {item:280459}: right-click it, {npc:9619} takes it."] = "Der tote Dreschadon liegt am Wasser nördlich von {npc:9619}.\nVorsicht: Gifthautravasaurier (50-51) jagen dort am Wasser: Zieh sie einzeln, bevor du den Kadaver plünderst.\nJeder Ravasaurus kann eine {item:280459} droppen: Rechtsklick darauf, {npc:9619} nimmt sie an.",
		["Theramore"] = "Theramore",
		["Theramore flight master"] = "Flugmeister von Theramore",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Das hast du beim früheren Besuch der Route hier verpasst: Es kommt jetzt zuerst. Es geht schnell und öffnet die Quests danach.",
		["grind on {npc:6511}"] = "grinde {npc:6511}",
		["{area:392} flight master"] = "Flugmeister in {area:392}",
		["{area:537} and the eastern jungle"] = "{area:537} und der östliche Dschungel",
		["{item:11316}, from the Lashers and Threshers"] = "{item:11316}, von den Peitschern und Dreschern",
		["{item:8593}; below ground"] = "{item:8593}; unter der Erde",
		["{npc:12046}, below ground"] = "{npc:12046}, unter der Erde",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} steht an den Docks, wo das Schiff anlegt.",
		["{npc:5594}, inside"] = "{npc:5594}, drinnen",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, hinten in der Zuflucht",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, hinten in der Höhle; unter der Erde",
		["{npc:9117}, below ground"] = "{npc:9117}, unter der Erde",
		["{npc:9998}: his scales come from the young beasts of the eastern jungle"] = "{npc:9998}: Seine Schuppen stammen von den jungen Tieren im östlichen Dschungel",
		["{object:161504}, underwater"] = "{object:161504}, unter Wasser",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362}: Töte diese, sobald sie dir begegnen",
		["{quest:3764}, from the Threshers and the dirt piles"] = "{quest:3764}, von den Dreschern und den Erdhaufen",
		["{quest:87494}, if a ravasaur dropped the scale"] = "{quest:87494}, falls ein Ravasaurus die Schuppe gedroppt hat",
		["{zone:1455} flight master"] = "Flugmeister von {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus steht neben König Magni im {object:171709}.",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "Archesonus steht neben König Magni im {object:171709}: Die Relikte, die du in der Steppe gelesen hast, gehören ihm.",
		["Ardalan is inside {area:1438}."] = "Ardalan ist in {area:1438}.",
		["Back south-west to {area:3137}."] = "Zurück nach Südwesten zur {area:3137}.",
		["Back to the {zone:1419}"] = "Zurück in die {zone:1419}",
		["Back up through {npc:8395}'s teleport."] = "Wieder hinauf durch den Teleport von {npc:8395}.",
		["Below ground"] = "Unter der Erde",
		["East along the road to {area:1235}"] = "Nach Osten die Straße entlang zu {area:1235}",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Endet bei {quest:4808} in {area:2255}, {zone:1452}: Behalte es",
		["Fly to {area:1438}"] = "Flieg nach {area:1438}",
		["Fly to {area:144}"] = "Flieg nach {area:144}",
		["Fly to {area:150}"] = "Flieg nach {area:150}",
		["Fly to {area:1537}"] = "Flieg nach {area:1537}",
		["Fly to {area:2418}"] = "Flieg nach {area:2418}",
		["Fly to {area:271}"] = "Flieg nach {area:271}",
		["Fly to {area:348}"] = "Flieg nach {area:348}",
		["Fly to {area:415}"] = "Flieg nach {area:415}",
		["Fly to {area:69}"] = "Flieg nach {area:69}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Folge der Straße nach Westen und klettere dann nach Norden zum Goblinlager am {area:251}.",
		["From {area:415}, ride east along the road past {area:2358} into {zone:1447}: {area:1235} lies just over the border, in {zone:1447}'s south-west corner."] = "Reite von {area:415} nach Osten die Straße entlang, an {area:2358} vorbei, nach {zone:1447}: {area:1235} liegt gleich hinter der Grenze, in der Südwestecke von {zone:1447}.",
		["Get off your mount before you talk to {npc:8395}: he teleports you up to {npc:8379}'s tower on the cliff above his camp."] = "Steig von deinem Reittier ab, bevor du mit {npc:8395} sprichst: Er teleportiert dich hinauf zum Turm von {npc:8379} auf der Klippe über seinem Lager.",
		["Hearth back to {zone:1455}'s inn."] = "Ruhestein zurück zum Gasthaus von {zone:1455}.",
		["Into {zone:1447}"] = "Nach {zone:1447}",
		["Just north-east of the shrine: {npc:239822} and {npc:240482} keep the Alliance camp at {area:3137}."] = "Gleich nordöstlich des Schreins: {npc:239822} und {npc:240482} halten das Lager der Allianz an der {area:3137}.",
		["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have. Come at her hill straight from the keep, along the road, and leave by the same way.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%.\nCareful: {npc:247015}, a level 55 elite, stands by Kum'isha's hill (about 50,35) and to the west (about 39,32), and the Dreadmaul and Shadowsworn camps around it are 53-55: take the fragments from the mobs on the way from the keep, not beside him."] = "Kum'isha wartet am {area:2517}, dem Hügel südwestlich der Festung. Die Mobs in den {zone:1419} auf dem Weg lassen die Unvollständigen Draenethystfragmente fallen; bring ihr, was du hast. Komm direkt von der Festung über die Straße zu ihrem Hügel und geh auf demselben Weg wieder.\nVorsicht: Felcular, {npc:7664} und Ilifar sind alle Elites der Stufe 60. Razelikh wirkt {spell:2691}, {spell:8255} und Dezimieren, und wenn seine Gesundheit sinkt, kommen {object:141891}, {spell:10854} und bei 15 % Wutanfall hinzu.\nVorsicht: {npc:247015}, ein Elite der Stufe 55, steht bei Kum'ishas Hügel (etwa 50,35) und im Westen (etwa 39,32), und die Lager der Dreadmaul und Shadowsworn ringsum sind 53-55: Hol dir die Fragmente von den Mobs auf dem Weg von der Festung, nicht neben ihm.",
		["Listen to his tale, then ride back south to Kum'isha."] = "Hör dir seine Geschichte an und reite dann zurück nach Süden zu Kum'isha.",
		["Mosshoof Coursers"] = "Mooshufrenner",
		["Mosshoof Runners"] = "Mooshufläufer",
		["On the road back south, {npc:235903} takes the satyrs."] = "Auf der Straße zurück nach Süden nimmt {npc:235903} die Satyrn an.",
		["Ride back east along the road to the Vigil."] = "Reite die Straße zurück nach Osten zur Wacht.",
		["Ride back south to the camp."] = "Reite zurück nach Süden zum Lager.",
		["Ride back west to {npc:8395}'s camp and get off your mount: he teleports you up to Xylem again."] = "Reite zurück nach Westen zum Lager von {npc:8395} und steig von deinem Reittier ab: Er teleportiert dich wieder zu Xylem hinauf.",
		["Ride east out of {area:69} and up the pass into the {zone:1428}: {area:2418} stands at the top."] = "Reite nach Osten aus {area:69} hinaus und den Pass hinauf in die {zone:1428}: {area:2418} liegt oben.",
		["Ride north from {area:271} into Alterac and west to the walls of {area:279}: {npc:34365} stands outside them. Her quest goes to {npc:266524} in {area:1438}, where this guide flies later."] = "Reite von {area:271} nach Norden ins Alteracgebirge und nach Westen zu den Mauern von {area:279}: {npc:34365} steht davor. Ihre Quest geht an {npc:266524} in {area:1438}, wohin dieser Guide später fliegt.",
		["Ride north from {area:271} up the road through Alterac to {area:3197}."] = "Reite von {area:271} nach Norden die Straße durch Alterac entlang bis {area:3197}.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "Reite nach Norden aus den {zone:1419} hinaus in die {zone:1435}: Der {npc:10996} steht an der Straße, die aus den {zone:1419} kommt. Halte dich von {area:75} fern, der Stadt der Horde im Nordosten.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Reite vom Schrein nach Nordosten: {npc:8405} lagert beim {area:1224}, in den Hügeln über der Straße.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "Schwimm zur kleinen Insel vor der Südspitze von {zone:1447}. Ist {npc:8392} nicht da, feuere deine {item:10444} ab, um ihm ein Signal zu geben, und warte, bis er landet.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it. {npc:222478} is held in the satyrs' camp: free her and walk her out."] = "Die Geister der Hochgeborenen spuken in den Ruinen um den Schrein; die Satyrn der Haldarr halten das Lager gleich nördlich davon. {npc:222478} wird im Lager der Satyrn gefangen gehalten: Befreie sie und geleite sie hinaus.",
		["The Mosshoof Runners (45-47) graze the hills north of {area:3137}, on the way to the satyrs."] = "Die Mooshufläufer (45-47) grasen in den Hügeln nördlich der {area:3137}, auf dem Weg zu den Satyrn.",
		["The Spitelash Sirens wander the ruins and the beach around the {area:1223}, just south of {npc:8395}. Only the Sirens carry the coral, not the Screamers."] = "Die Spitelash Sirens streifen durch die Ruinen und über den Strand um {area:1223}, gleich südlich von {npc:8395}. Nur die Sirens tragen die Koralle, nicht die Screamers.",
		["The Spitelash Warriors (46-47) and Screamers (47-48) hold the western shore north-east of the satyrs."] = "Die Krieger der Grollflossen (46-47) und Kreischer (47-48) halten die Westküste nordöstlich der Satyrn.",
		["The apprentice at the top of the tower sends you back down."] = "Der Lehrling oben im Turm schickt dich wieder nach unten.",
		["The blood elves are at the {area:1220}, on the way to {npc:8420}"] = "Die Blutelfen sind im {area:1220}, auf dem Weg zu {npc:8420}",
		["The bloodmages"] = "Die Blutmagier",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "Die zweite Stufe der Blutmagier bezahlt dieselben Teile mit einem Buff-Gegenstand und ohne Erfahrung: Überspring sie.",
		["The relics are in the {zone:1428}: keep it"] = "Die Relikte sind in der {zone:1428}: Behalte es",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered. Take the ones on the ruins' southern edge, nearest {area:251}.\nCareful: the ruins' War Reavers and Thaurissan Firewalkers are 53-55, and {npc:8978} (57) holds the {object:147516} camp south-west of {area:251}: take the relics at the edge of the ruins, pull one at a time, and keep away from the camp."] = "Die Relikte sind die geschnitzten Steine, die über {area:250} um {area:251} verstreut liegen: Klicke sie an, bis die Informationen wiederhergestellt sind. Nimm die am Südrand der Ruinen, am nächsten zu {area:251}.\nVorsicht: Die Kriegshäscher und Thaurissanischen Feuerwandler der Ruinen sind 53-55, und {npc:8978} (57) hält das Lager {object:147516} südwestlich von {area:251}: Nimm die Relikte am Rand der Ruinen, zieh die Gegner einzeln und halte dich vom Lager fern.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "Der Schrein liegt in der Südwestecke von {zone:1447}, südlich von {area:3137}.",
		["The western shore"] = "Die Westküste",
		["The {area:1221}"] = "{area:1221}",
		["The {area:1223}"] = "{area:1223}",
		["To {zone:1455}"] = "Zum {zone:1455}",
		["Xylem's last task, Destroy Morphaz, is in the {area:1417}: skip it."] = "Xylems letzte Aufgabe, Destroy Morphaz, liegt im {area:1417}: Überspring sie.",
		["{area:144} flight master"] = "Flugmeister in {area:144}",
		["{area:197}: kill these as you meet them"] = "{area:197}: Töte sie, wenn du ihnen begegnest",
		["{area:2418} flight master"] = "Flugmeister von {area:2418}",
		["{area:2418} sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "{area:2418} liegt im Südosten der Steppe, oben am Pass von Rotkammgebirge herauf.",
		["{area:250}: kill these as you meet them"] = "{area:250}: Töte sie, wenn du ihnen begegnest",
		["{area:3197} flight master"] = "Flugmeister in {area:3197}",
		["{area:348} flight master"] = "Flugmeister von {area:348}",
		["{area:442} flight master"] = "Flugmeister von {area:442}",
		["{item:10575}, from the hoard"] = "{item:10575}, aus dem Hort",
		["{item:20028}, from the blood elf surveyors and reclaimers"] = "{item:20028}, von den Blutelfen-Vermessern und -Rückgewinnern",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: der {npc:7864}, etwa 10%",
		["{npc:10838} stands in the middle of the camp."] = "{npc:10838} steht mitten im Lager.",
		["{npc:222478}, in the camp"] = "{npc:222478}, im Lager",
		["{npc:235903} camps by the road north to {npc:8420}: his satyrs are in {npc:8420}'s camp."] = "{npc:235903} lagert an der Straße nach Norden zu {npc:8420}: Seine Satyrn sind im Lager von {npc:8420}.",
		["{npc:3546}: {quest:87295}, the scales come from the basilisks ahead"] = "{npc:3546}: {quest:87295}, die Schuppen stammen von den Basilisken vor dir",
		["{npc:7034}, below ground"] = "{npc:7034}, unterirdisch",
		["{npc:7363} walks around here: look inside the circle on the map"] = "{npc:7363} läuft hier umher: Schau in den Kreis auf der Karte",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "Die nächste Aufgabe von {npc:8022}, {item:9471}, ist eine Quest für {area:978}: Überspring sie.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him.\nCareful: the Blood Elf Surveyors are 51-52 and the Reclaimers 52-53, with {npc:6647} (53) among them: take the equipment from the camp's edge and pull the elves one at a time.\n{npc:235903}'s satyrs, rogues and hellcallers (51-53) are the Legashi around {npc:8420}'s camp; the Legashi Soulstealers, Hellraisers and Blackguards (53) further east are not part of it: stay west of them."] = "{npc:8420} lagert am {area:1219} im Norden; seine Ausrüstung liegt überall im {area:1220} gleich südöstlich von ihm.\nVorsicht: Die Blutelfenfeldmesser sind 51-52 und die Rückeroberer 52-53, mit {npc:6647} (53) unter ihnen: Nimm die Ausrüstung vom Rand des Lagers und zieh die Elfen einzeln.\nDie Satyrn, Schurken und Höllenrufer (51-53) für {npc:235903} sind die Legashi um das Lager von {npc:8420}; die Seelenräuber, Höllenschürer und Schwarzgardisten der Legashi (53) weiter östlich gehören nicht dazu: Bleib westlich von ihnen.",
		["{npc:9177}' next tasks ({npc:9176}, and fifty Blackrock Medallions) send you among the Blackrock orcs of 55-58 at the foot of {area:254}: skip them."] = "Die nächsten Aufgaben von {npc:9177} ({npc:9176} und fünfzig Medaillons der Blackrock) schicken dich zu den Orcs der Blackrock (55-58) am Fuß des {area:254}: Überspring sie.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, oben in der Burg",
		["{quest:3701} is a group quest at this level: its relics stand among War Reavers and Firewalkers of 53-55, with {npc:8978} (57) close by, two to five over you, and the route has no later {zone:1428} visit. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "{quest:3701} ist auf dieser Stufe eine Gruppenquest: Ihre Relikte stehen zwischen Kriegshäschern und Feuerwandlern der Stufe 53-55, mit {npc:8978} (57) in der Nähe, zwei bis fünf Stufen über dir, und die Route kehrt nicht mehr in die {zone:1428} zurück. Gruppenspiel wird empfohlen, such dir Leute dafür. Überspring sie, wenn du allein bist.",
		["{zone:1419}: kill these as you meet them"] = "{zone:1419}: Töte diese, sobald sie dir begegnen",
		["{zone:1447}: kill these as you meet them"] = "{zone:1447}: Töte sie, wenn du ihnen begegnest",
		["{zone:1455} flight master"] = "Flugmeister von {zone:1455}",
		["{zone:1455} inn"] = "Gasthaus von {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Back to {npc:14637} on the dock."] = "Zurück zu {npc:14637} am Steg.",
		["Below ground"] = "Unter der Erde",
		["Boat to {area:1108}"] = "Boot nach {area:1108}",
		["Careful: {npc:9454} (54) stands at the back of the {area:2481}, at about 32.2,67.1, with Shadowstalkers around him: clear them one at a time, then pull him alone at full health."] = "Vorsicht: {npc:9454} (54) steht hinten in den {area:2481}, bei etwa 32.2,67.1, mit Schattenpirschern um sich: Räum sie einzeln weg und zieh ihn dann allein mit voller Gesundheit.",
		["First crater"] = "Erster Krater",
		["Fly to {area:702}"] = "Flieg nach {area:702}",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them.\nCareful: an {npc:7136} (53, elite) stands among the craters: walk round it."] = "Folge der Straße nach Norden ins Kratertal und geh zu jedem Krater; töte dabei die Entropischen Bestien und Schrecken dazwischen.\nVorsicht: Ein {npc:7136} (53, Elite) steht zwischen den Kratern: Geh um ihn herum.",
		["From {area:702}, fly to {area:1116}."] = "Flieg von {area:702} zur {area:1116}.",
		["Into {zone:1452}"] = "Nach {zone:1452}",
		["Lead {npc:7774} back to {npc:7765} at walking pace: she wanders off, so ring the bell to call her back (not in combat), and clear the harpies on the way before she reaches them."] = "Führ {npc:7774} im Schritttempo zurück zu {npc:7765}: Sie läuft immer wieder davon, also läute die Glocke, um sie zurückzurufen (nicht im Kampf), und räume die Harpyien auf dem Weg, bevor sie sie erreicht.",
		["Portal to {zone:1438}"] = "Portal nach {zone:1438}",
		["Putrescent organs: kill these as you meet them"] = "Faulige Organe: Töte diese, sobald sie dir begegnen",
		["Ride east along the road to {area:2255}."] = "Reite auf der Straße nach Osten nach {area:2255}.",
		["Ride north up the road from the Sanctuary, all the way to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Reite vom Heiligtum die Straße nach Norden hinauf, ganz bis zum Höhleneingang der {area:1769}; {npc:15395} bewacht ihn.",
		["Ride south-east from {area:1763} to the {area:2479}, the druids' camp by the road in southern {zone:1448}."] = "Reite von {area:1763} nach Südosten zum {area:2479}, dem Lager der Druiden an der Straße im Süden von {zone:1448}.",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "Reite nach Westen in die Ruinen von Rabenwind: {npc:7774} versteckt sich im kleinen runden Gebäude ganz hinten. Öffne die Truhe neben ihr für {item:9189}: Es hält 15 Minuten, genau wie die Quest.",
		["Second crater"] = "Zweiter Krater",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains."] = "Die Satyrn von Jadefire halten das Tal westlich der Straße, mit {npc:9454} an dessen Ende.\nVorsicht: Jadefire Shadowstalkers (Stufe 51-52) nutzen Sneak und {spell:7992} und sind getarnt, sodass sie oft ungebeten in Kämpfe geraten.\nCursed Oozes gleiten durch die Bäche des Tals: Töte sie und benutze Laris's Empty Ooze Jar an ihren Überresten.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Die Wucherborkentreants im {area:1767}, östlich der {area:2618}, tragen die {item:11503}.",
		["The giant {npc:7765} sits just north-west of {npc:7775}'s camp."] = "Der Riese {npc:7765} sitzt gleich nordwestlich vom Lager von {npc:7775}.",
		["The {area:2479}"] = "{area:2479}",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "Die {item:11242} wächst in einem zerfallenen Gebäude nördlich von {npc:7765}: Kletter vom Felsvorsprung daneben durch das Loch in der Wand hinein.",
		["Third crater"] = "Dritter Krater",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}."] = "Benutze {item:12922} am verderbten Mondbrunnen mitten in {area:1763}.",
		["{area:1108}: kill these as you meet them"] = "{area:1108}: Töte diese, sobald sie dir begegnen",
		["{area:1763} again"] = "Wieder {area:1763}",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}.\nCareful: {npc:10648} (55) stands at the valley's far end with Hellcallers (53-54) around him: clear them one at a time before you pull him."] = "{area:2618} ist das Satyrtal im Nordwesten, mit {npc:10648} an seinem hinteren Ende. Er lässt {quest:939} fallen; jeder Jadefeuersatyr kann {item:11674} fallen lassen.\nVorsicht: {npc:10648} (55) steht am hinteren Ende des Tals mit Höllenrufern (53-54) um sich: Räum sie einzeln weg, bevor du ihn ziehst.",
		["{area:2618}: kill these as you meet them"] = "{area:2618}: Töte sie, wenn du ihnen begegnest",
		["{area:702} flight master"] = "Flugmeister von {area:702}",
		["{item:11949}: Tainted Oozes slide about {area:1763}'s fel pools"] = "{item:11949}: Tainted Oozes gleiten durch die Teufelsteiche von {area:1763}",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904}, auf die Wellen- und Tiefenschreiter im Wasser",
		["{item:18958}, from the Sea Sprays"] = "{item:18958}, von den Meeresschauern",
		["{npc:10920}: {quest:86577}, from the bears and wolves you meet in {zone:1448}"] = "{npc:10920}: {quest:86577}, von den Bären und Wölfen, die dir in {zone:1448} begegnen",
		["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "{npc:11554} der Furbolg steht an der Straße, gleich südlich vom {area:2479}.",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} steht direkt am Ausgang des Tunnels von {area:1769} nach {zone:1452}, wo du herauskommst.",
		["{npc:11558}: walks around here: look inside the circle on the map"] = "{npc:11558}: läuft hier umher: Schau in den Kreis auf der Karte",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} wartet am Nordende des {zone:1448}",
		["{npc:4217}, upstairs"] = "{npc:4217}, oben",
		["{npc:7740}: {quest:162}, from {area:976}"] = "{npc:7740}: {quest:162}, aus {area:976}",
		["{npc:9116}, inside"] = "{npc:9116}, drinnen",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, in den Ruinen gleich östlich von {npc:11554}",
		["{zone:1448}'s Angerclaw bears and Felpaw wolves carry the putrescent organs {npc:10920} wants: the Bears and Wolves (47-48) of the south and the Maulers and Scavengers (49-50) along the road north of {area:1763}. Kill them as you ride between the stops."] = "Die Zornklauenbären und Teufelspfotenwölfe von {zone:1448} tragen die fauligen Organe, die {npc:10920} will: die Bären und Wölfe (47-48) im Süden und die Zerfleischer und Aasfresser (49-50) an der Straße nördlich von {area:1763}. Töte sie, während du zwischen den Stationen reitest.",
		["{zone:1455} has no druid trainer"] = "{zone:1455} hat keinen Druidenlehrer",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Below ground"] = "Unter der Erde",
		["Bones and equipment"] = "Knochen und Ausrüstung",
		["Careful: Ancient Irontree Walkers, level 59 elites, stand among the {quest:5086}: work the Horrors at the camp's north-east tip (about 50.6,22.4), one at a time, and look for a walker before each pull."] = "Vorsicht: Ancient Irontree Walkers, Elites der Stufe 59, stehen zwischen den {quest:5086}: Bekämpfe die Horrors an der Nordostspitze des Lagers (etwa 50.6,22.4) einzeln und halte vor jedem Pull nach einem Walker Ausschau.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Durchquere den Süden des Kraters zu {npc:9619} an der Rampe.",
		["Eastern Pylon and the crate"] = "Östlicher Pylon und die Kiste",
		["Escort {npc:9999}"] = "Eskortiere {npc:9999}",
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Fly to {area:2255}"] = "Flieg nach {area:2255}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {area:415}"] = "Flieg nach {area:415}",
		["Fly to {area:541}"] = "Flieg nach {area:541}",
		["Fly to {area:976}"] = "Flieg nach {area:976}",
		["From Theramore, ride west into the {zone:1413} and north up the coast to {area:392}."] = "Reite von Theramore nach Westen in {zone:1413} und die Küste nach Norden hinauf bis {area:392}.",
		["Into {zone:1452}"] = "Nach {zone:1452}",
		["Lead her out of {area:1770} and keep her alive until she is outside the cave: clear the way back first."] = "Führ sie aus {area:1770} hinaus und halte sie am Leben, bis sie draußen vor der Höhle ist: Räume zuerst den Weg zurück.",
		["Northern Pylon"] = "Nördlicher Kristallpylon",
		["Pristine Yeti Horns"] = "Makellose Yetihörner",
		["Ride back south-east to the Sanctuary."] = "Reite zurück nach Südosten zum Refugium.",
		["Ride east along the road to {area:2255}."] = "Reite auf der Straße nach Osten nach {area:2255}.",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Reite nach Osten zum {area:1943}, wo der Roboter zwischen den Gorillas steht. Bleib dort aus der tiefen Höhle fern.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Reite nach Osten zum {area:537}, klettere hinauf und benutze {npc:10541} an den Lavaschloten nahe dem Gipfel.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Reite an der Ostseite nach Norden zum Gorillaplateau. {npc:9622}, ein Gorilla der Stufe 55, sitzt in dessen tiefster Höhle: Säubere zuerst die Gorillas am Höhleneingang.",
		["Ride north out of {area:415} into {zone:1448} to the {area:2479}, the druids' camp by the road."] = "Reite von {area:415} nach Norden hinaus nach {zone:1448} zum {area:2479}, dem Lager der Druiden an der Straße.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Reite nach Südwesten zum Lager von {npc:7771} bei {area:1938}.",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Tar Beasts suhlen sich im {area:538}; die Feuerelementare von {area:537} in der Mitte tragen die Asche; die Gorishi-Wespen des {area:540} im Süden tragen die Drüse. Jede Kreatur im Krater kann {item:11018} fallen lassen.\nVorsicht: Gorishi Workers, die unter 45 % Gesundheit fallen, rufen mit 50 % Wahrscheinlichkeit Verbündete in 25 yd Umkreis zu Hilfe.",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "Die Teerbestien und Teerlords suhlen sich in den {area:538}, südlich der Zuflucht auf dem Weg hinab in den Krater.",
		["The crater"] = "Der Krater",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Die Gorillas leben auf {area:1943}, östlich von {area:541}. Behalte ihre Felle für {npc:9619}. Halte dich aus der tiefsten Höhle fern: {npc:9622} ist Stufe 55.\nVorsicht: Un'Goro Gorillas (Stufe 50-51) rufen Verbündete in 20 yd Umkreis zu Hilfe, sobald sie auf 25 % Gesundheit fallen. In der Gegend gibt es eine Höhle voller Affen, und ein Kampf dort bringt viele Adds.",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Die Gorillas leben auf dem {area:1943}, gleich östlich des Pylons: Sammle die Felle für {npc:9619} jetzt, solange du hier oben bist. Halte dich von der tiefsten Höhle fern: {npc:9622} ist Stufe 55.\nVorsicht: Un'Goro-Gorillas (Stufe 50-51) rufen Verbündete im Umkreis von 20 Metern zu Hilfe, sobald sie auf 25 % Gesundheit fallen. In der Gegend gibt es eine Höhle voller Affen, und Kämpfe dort ziehen viele zusätzliche Gegner an.",
		["The pelts come from the gorillas on {area:1943}"] = "Die Felle stammen von den Gorillas auf {area:1943}",
		["The pylon stands on the eastern cliffs above {npc:9684}'s lair; the expedition's {item:11113} sits at the abandoned camp in the eastern jungle."] = "Der Pylon steht auf den östlichen Klippen über dem Bau von {npc:9684}; die {item:11113} der Expedition steht im verlassenen Lager im östlichen Dschungel.",
		["The pylon stands on the western cliffs."] = "Der Pylon steht auf den westlichen Klippen.",
		["The wooden sign beside {npc:9997}"] = "Das Holzschild neben {npc:9997}",
		["The {area:2479}"] = "{area:2479}",
		["The {item:280417} is a short ride west of {npc:9619}'s camp."] = "Der {item:280417} liegt ein kurzes Stück westlich von {npc:9619}s Lager.",
		["The {quest:5086}"] = "{quest:5086}",
		["Wait a moment for {npc:9116}"] = "Warte kurz auf {npc:9116}",
		["West along the south of the crater: the Gorishi hive fills it. Use the Scraping Vial on a hatchery, a chamber with hanging larvae."] = "Nach Westen am Südrand des Kraters entlang: Der Gorishi-Bau füllt ihn. Benutze die Schabphiole an einer Brutstätte, einer Kammer mit hängenden Larven.",
		["Western Pylon"] = "Westlicher Kristallpylon",
		["{area:1770} braziers"] = "Kohlenbecken in {area:1770}",
		["{area:1942}: kill these as you meet them"] = "{area:1942}: Töte sie, wenn du ihnen begegnest",
		["{area:1943}: kill these as you meet them"] = "{area:1943}: Töte diese, wenn du ihnen begegnest",
