		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: für {npc:1702} bei {area:189}",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: für {npc:2326} in {area:2102}",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: für {npc:5392} bei {area:189}",
		["{npc:2756}, inside"] = "{npc:2756}, drinnen",
		["{npc:276003} along the way to {npc:1253}"] = "{npc:276003} auf dem Weg zu {npc:1253}",
		["{npc:276003} on the way"] = "{npc:276003} auf dem Weg",
		["{npc:276003}, around the small lake"] = "{npc:276003}, rund um den kleinen See",
		["{npc:4256} works at the {object:32372}'s north end, and {npc:1573} keeps the gryphons in the {object:32372}, where the flight from {area:144} lands."] = "{npc:4256} arbeitet am Nordende der {object:32372}, und {npc:1573} hütet die Greifen in der {object:32372}, wo der Flug aus {area:144} landet.",
		["{npc:4256}, in the {object:32372}"] = "{npc:4256}, in der Großen Schmiede",
		["{npc:460}, inside {area:77}"] = "{npc:460}, in {area:77}",
		["{npc:5392} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5392} nimmt sie entgegen, sobald deine Fertigkeit in {skill:186} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:5392}, at the depot"] = "{npc:5392}, am Depot",
		["{npc:5413} in {zone:1453} takes it"] = "{npc:5413} in {zone:1453} nimmt es an",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} bildet Krieger in {object:2100} aus, nahe Osrics Laden; die Bahn aus {zone:1455} kommt in {object:28027} an, nördlich davon. {npc:6089} und {npc:6090} stehen dort zusammen bei {object:2152}. {npc:6090} kämpft mit dir um seinen Krug. Falls {npc:5480} {quest:1638} nicht anbietet, geh direkt zu {npc:6089}: Er gibt dir {quest:1639} auch ohne sie.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} steht im Wizard's Sanctum, dem Turm in {object:2101}; sie gibt dir eine Flasche für den Wasserfall von {quest:1861}.",
		["{npc:5505} in {zone:1453}; {zone:1426} has no druid trainer"] = "{npc:5505} in {zone:1453}; {zone:1426} hat keinen Druidenlehrer",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: {npc:6122} in {zone:1453} nimmt sie an",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} wartet im Keller von {object:2164} in {object:2101}.",
		["{npc:6806}, inside"] = "{npc:6806}, drinnen",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, neben {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}s Lager liegt am Westende des Tals. {item:10438} liegt im Schnee südlich davon, Felix' Truhe bei der Trollhöhle und Felix' Bolzeneimer östlich der Höhle: Schnapp sie dir im Vorbeigehen.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} und {npc:12738} lagern am Südwestrand des Tals, unterhalb der Trollhöhle.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} ist in der Trollhöhle östlich von {npc:786}s Lager, nicht auf dem Hügel darüber: Geh am Eingang hinein und folge dem Tunnel bis ganz nach hinten.",
		["{npc:836}, inside {area:77}; below ground"] = "{npc:836}, in {area:77}; unterirdisch",
		["{npc:837}, inside {area:77}"] = "{npc:837}, in {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, der Priesterlehrer",
		["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}, an der Tür auf dem Weg nach draußen; drinnen",
		["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}, an der Tür von {area:77}; drinnen",
		["{npc:8508}, on the dock"] = "{npc:8508}, am Steg",
		["{npc:912}, the warrior trainer"] = "{npc:912}, der Kriegerlehrer",
		["{npc:916}, the rogue trainer"] = "{npc:916}, der Schurkenlehrer",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, der Magierlehrer, in {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, beim Briefkasten in {object:171524}",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688}: Ihr Halsband und The Binding gehören zur Runde durchs östliche Elwynn im Guide für {zone:1436}",
		["{zone:1426}: kill these as you meet them"] = "{zone:1426}: Töte sie, wenn du ihnen begegnest",
		["{zone:1453} flight master"] = "Flugmeister von {zone:1453}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "Tantchen Bernice Stonefield",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Zurück zu {npc:6122}. Benutze {item:6928} am Beschwörungskreis im Keller von {object:2164} und besiege den Leerwandler, den er ruft.",
		["Back to {zone:1429}"] = "Zurück nach {zone:1429}",
		["Billy plays in the {area:64}, east of the mine."] = "Billy spielt in {area:64}, östlich der Mine.",
		["Chunks of Boar Meat"] = "Brocken Eberfleisch",
		["Class trainer"] = "Klassenlehrer",
		["Crystal Kelp Fronds"] = "Kristalltangwedel",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Abtrünnige Hexer der Defias lagern an den Ufern von {area:86}; sie lassen auch die Roten Leinenkopftücher fallen. {object:56} liegt im Murlocdorf am Nordostufer.\nVorsicht: Die Abtrünnigen Hexer zaubern aus der Ferne und eine {npc:6866} (10) läuft mit ihnen am Ufer entlang: Zieh sie einzeln.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Rohlinge der Defias lagern auf der Lichtung östlich der Abtei und entlang der Ostseite des Tals.",
		["Druid trainer"] = "Druidenlehrer",
		["Follow the hills south to the tower, on the road west."] = "Folge den Hügeln nach Süden zum Turm, an der Straße nach Westen.",
		["Follow the hills south to the tower."] = "Folge den Hügeln nach Süden zum Turm.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Folge der Straße nach Osten am {area:91} vorbei bis zur Brücke. Erledige die Prowlers und Young Forest Bears am Fluss südlich davon.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Folge der Straße nach Norden von {area:87} nach {zone:1453}. {npc:5497} steht im Magiersanktum, dem Turm in {object:2101}; sie gibt dir eine Flasche für den Wasserfall am {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Folge der Straße nach Norden von {area:87} nach {zone:1453}. {npc:6122} wartet im Keller von {object:2164} in {object:2101}.",
		["Follow the road south out of the valley to {area:87}. {npc:240} stands outside the smithy on the west side of the road, {npc:241} by the road south of it, and {npc:295} and {npc:253} in the Lion's Pride Inn across the road."] = "Folge der Straße nach Süden aus dem Tal hinaus nach {area:87}. {npc:240} steht vor der Schmiede auf der Westseite der Straße, {npc:241} an der Straße südlich davon, und {npc:295} und {npc:253} im Lion's Pride Inn auf der anderen Straßenseite.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Folge der Straße nach Süden aus {area:87} hinaus zu {area:64}. {npc:251} wartet beim Haus.",
		["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Folge der Straße nach Süden zum {area:120}, auf dem Weg nach {zone:1436}. {npc:963} steht vor der Kaserne; {npc:955} steht drinnen. Er hat {quest:91738} nur, solange du {item:247824} bei dir hast: Sprich ihn an, und es geht direkt zur Abgabe.",
		["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Folge der Straße nach Westen zurück nach {area:87}; {npc:6306} steht am Seeufer vor der Stadt. {npc:377} (Priester), {npc:328} (Magier) und {npc:917} (Schurken) stehen oben im Gasthaus: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Fun with Elementals: {npc:248464}"] = "Spaß mit Elementaren: {npc:248464}",
		["He stands by the river west of the farm."] = "Er steht am Fluss westlich des Hofs.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Geh zurück durch {area:87} und östlich entlang der Straße zur {area:62}. {npc:881} (Stufe 9) steht beim Bauernhaus.",
		["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "Geh aus {area:87} nach Osten am Seeufer entlang. {npc:383} steht am Ufer nordöstlich der Stadt.",
		["Heal and fortify {npc:12423}"] = "Heile und stärke {npc:12423}",
		["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Wenn du {quest:91740} übersprungen hast, grinde hier bis Stufe 8,85, um im Plan der Route zu bleiben.",
		["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Wenn du {quest:91775} übersprungen hast, grinde hier bis Stufe 8,39, um im Plan der Route zu bleiben.",
		["Inside"] = "Drinnen",
		["Inside {area:34}"] = "In {area:34}",
		["It lies by the river north-west of the logging camp."] = "Er liegt am Fluss nordwestlich des Holzfällerlagers.",
		["Large Candles"] = "Große Kerzen",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Verlass {zone:1453} durch das Haupttor. Der Wasserfall am {quest:1861} liegt südwestlich der Tore, auf dem Weg nach Westen nach {zone:1436}: Füll {item:7207} an seinem Fuß.",
		["Level 8.39"] = "Stufe 8,39",
		["Level 8.85"] = "Stufe 8,85",
		["Lost Books: Kobold Miners and Tunnelers"] = "Verlorene Bücher: Koboldminenarbeiter und Koboldtunnelgräber",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Magier: {npc:198}, der Magierlehrer, steht oben in der Abtei: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Murlocs und Murlocbachläufer halten das Ostufer; die Schrotthaufen liegen in ihrem Lager. Vorsicht: Die Murlocs stehen dicht beieinander, daher zieht ein Kampf leicht zwei oder drei auf einmal: Lock sie einzeln vom Rand des Lagers weg und verfolge keinen bis in die nächste Gruppe.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Nordöstlich des Holzfällerlagers. Abtrünnige Hexer der Defias lagern an den Ufern des Sees.\nVorsicht: Die Abtrünnigen Hexer zaubern aus der Ferne und eine {npc:6866} (10) läuft mit ihnen am Ufer entlang: Zieh sie einzeln.",
		["Painted Gnoll Armbands"] = "Bemalte Gnollarmbinden",
		["Red Burlap Bandanas"] = "Rote Sackleinenkopftücher",
		["Red Linen Bandanas"] = "Rote Leinenkopftücher",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Riverpaw Runts und Outrunners halten die Hügel südlich der Garnison, entlang der Grenze zu {zone:1436}.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Gnolle der Flusspfoten lagern in den Hügeln westlich von {area:86}; {quest:91725} liegen in ihren Lagern.",
		["Shaman trainer"] = "Schamanenlehrer",
		["She stands by her cart at the vineyard east of the Abbey."] = "Sie steht bei ihrem Karren am Weinberg östlich der Abtei.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Glänzende rote Äpfel von {npc:894} für {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Setz dich (/sit) an sein Lagerfeuer, bis du {spell:1229451} hast",
		["South down the road to the {area:64}."] = "Die Straße hinunter nach Süden zu {area:64}.",
		["Subdue the voidwalker"] = "Bezwinge den Leerwandler",
		["Tame {npc:1922}"] = "Zähme {npc:1922}",
		["Tame {npc:524}"] = "Zähme {npc:524}",
		["Tame {npc:822}"] = "Zähme {npc:822}",
		["The Defias camp"] = "Das Lager der Defias",
		["The Fishing Traps sit along the west shore of the lake."] = "Die Fischfallen stehen am Westufer des Sees.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "Der Hof der Stonefields liegt westlich der Mine. Ma und „Auntie“ Bernice stehen am Haus.\nSie sitzt im Bauernhaus.",
		["The bridge"] = "Die Brücke",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it.\nCareful: Elmpaw, a level 12 elite gnoll, walks the woods and hills from the logging camp north to {area:86} and the gnoll camps: keep clear of him when you see him coming."] = "Das Lager liegt nordöstlich der Brücke. Holzbündel liegen im Lager und in den Wäldern nördlich davon.\nVorsicht: Elmpaw, ein Gnoll-Elite der Stufe 12, läuft durch die Wälder und Hügel vom Holzfällerlager nach Norden bis {area:86} und zu den Gnolllagern: Halte Abstand, wenn du ihn kommen siehst.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Die Traubenkisten liegen in den Weinbergen hinter den Defias. {npc:103} wartet bei der Hütte am Ostende des Tals.",
		["The gnoll camps"] = "Die Gnolllager",
		["The kobold camp"] = "Das Koboldlager",
		["The lake shore"] = "Das Seeufer",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "Die Mine liegt südwestlich der Gnolllager. {item:247816} liegen nahe dem Eingang; Koboldgeomanten halten die Tunnel.\nVorsicht: {npc:471} (7-10), die Minenspinnen (7-9) und {npc:248474} (7) sind Elitegegner tief in der Mine: Zieh die Kobolde nahe dem Eingang einzeln und zieh dich zurück, wenn eine Elite kommt; zu zweit sind sie leichter.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "Die Mine liegt westlich der Weinberge. Koboldminenarbeiter und Koboldtunnelgräber füllen beide Ebenen; {npc:248464}, ein Kobold mit Namen, hat das Bilderbuch in den unteren Tunneln. {npc:248464} ist Elite: Eine Gruppe wird empfohlen.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too.\nCareful: {npc:276180}, a level 11 rare murloc, walks the river by {npc:261}' bridge, east of the Prowlers' woods: leave him be."] = "Die Murlocs am Ostufer lassen den Tang fallen. Kürschner: Graue Forstwölfe streifen durch die Wälder zwischen dem See und {area:91}; Streuner weiter östlich liefern ebenfalls Felle.\nVorsicht: {npc:276180}, ein seltener Murloc der Stufe 11, läuft den Fluss bei der Brücke von {npc:261} entlang, östlich des Walds der Streuner: Lass ihn in Ruhe.",
		["The vineyards and {npc:103}"] = "Die Weinberge und {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Young Forest Bears on the way; the Prowlers (level 9-10) wait for the walk back to {npc:261}, after the logging camp and the mine. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group; otherwise leave him: it's optional."] = "{item:247813}, die Durchnässte Axt und der Durchnässte Werkzeugkasten liegen im Fluss südlich der Brücke. {npc:330}, ein großer Eber, wühlt in {area:62} westlich des Flusses mit ihrem {npc:390}: Lock zuerst die Ferkel weg. Töte unterwegs Junge Waldbären; die Streuner (Stufe 9-10) heben wir uns für den Rückweg zu {npc:261} auf, nach dem Holzfällerlager und der Mine. Vorsicht: {npc:248278} ist ein Elite der Stufe 11 am Murlocufer. Hol dir seinen Kopf nur mit einer Gruppe; sonst lass ihn in Ruhe: Die Quest ist optional.",
		["The {quest:91736}"] = "{quest:91736}",
		["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "{quest:91736} steht nördlich vom {area:120}. Klicke es an, während du vier Shiny Red Apples in deinen Taschen hast: Es nimmt sie und gibt dir auf der Stelle {item:247824} (die Quest erscheint nie in deinem Questlog). Behalte den Applejack für {npc:955}: Trink ihn nicht.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Sich zusammenzutun wird empfohlen, such dir Leute dafür. {npc:248464} (Elite der Stufe 6) braucht eine Gruppe von 2. Überspring ihn, wenn du allein bist: Die Route lässt dich die EP wieder hereingrinden.",
		["Walk into the mine"] = "Geh in die Mine",
		["Walk through the mine"] = "Geh durch die Mine",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:11867} ({object:2096}, 10 Silber); ein Stab hat beim Leveln mehr Zauberwerte als eine Einhandwaffe.",
		["Wolves"] = "Wölfe",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Du beginnst vor der Abtei. {npc:823} steht am Fuß der Treppe, {npc:197} drinnen in der Halle, {npc:951} und {npc:247229} in der Bibliothek rechts, {npc:196} draußen an der Nordwestecke.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Junge Wölfe und Wilde Waldwölfe streifen über die Felder direkt um die Abtei.",
		["grind on {npc:1922}"] = "Grinde an {npc:1922}",
		["grind on {npc:40}"] = "Grinde an {npc:40}",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "sein Koboldaufspürer zeigt die Kobolde zum Anklicken auf der Straße nach {area:87}",
		["talk to the trainer"] = "Sprich mit dem Lehrer",
		["{area:18}: kill these as you meet them"] = "{area:18}: Töte sie, wenn du ihnen begegnest",
		["{area:34}: kill these as you meet them"] = "{area:34}: Töte sie, wenn du ihnen begegnest",
		["{area:54}: kill these as you meet them"] = "{area:54}: Töte diese, wenn sie dir begegnen",
		["{area:64}: kill these as you meet them"] = "{area:64}: Töte sie, wenn du ihnen begegnest",
		["{item:247824}, from the still"] = "{item:247824}, aus dem Brenner",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Steinhauereber",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} im Lager der Defias",
		["{item:981}; below ground"] = "{item:981}; unterirdisch",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} kniet verwundet an einem Baum am Westufer des {area:18}, zwischen den Fischfallen. Wirke {spell:613} (Rang 2) auf ihn, dann {spell:1243}: Rang 1 von {spell:613} zählt nicht. Sobald beides gewirkt ist, geht er weg und ist nach etwa 3 Minuten zurück.",
		["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} kocht in der Küche des Gasthauses. {npc:377} (Priester), {npc:328} (Magier) und {npc:917} (Schurken) stehen oben im Gasthaus: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430}: Camping 101 verlangt, dass du es lernst; unterirdisch",
		["{npc:1632} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1632} nimmt sie entgegen, sobald deine Fertigkeit in {skill:165} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, neben {npc:6306}",
		["{npc:1651} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1651} nimmt sie entgegen, sobald deine Fertigkeit in {skill:356} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: Zähme ihn mit {item:15908}",
		["{npc:197}, inside"] = "{npc:197}, drinnen",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, der Magierlehrer, in der Abtei",
		["{npc:2329} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2329} nimmt sie entgegen, sobald deine Fertigkeit in {skill:129} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, im Gasthaus „Zur Höhle des Löwen“",
		["{npc:240}, while William brews"] = "{npc:240}, während William braut",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, in der Bibliothek; drinnen",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} und {npc:248248} stehen am Fuß des Turms.",
		["{npc:248278} is a level 11 elite on the murloc shore south of the bridge: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back. Right-click the head for its quest."] = "{npc:248278} ist ein Elite der Stufe 11 am Murlocufer südlich der Brücke: Sich zusammenzutun wird empfohlen, such dir Leute dafür. {quest:91740} braucht eine Gruppe von 2. Überspring sie, wenn du allein bist: Die Route lässt dich die EP wieder hereingrinden. Klicke mit Rechtsklick auf den Kopf für seine Quest.",
		["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415} steht hinter der Abtei, bei den Ställen. {npc:198}, der Magierlehrer, steht oben in der Abtei: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, bei der Abtei",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} steht bei den Lehrern in {area:87}. Jede ihrer Quests gibt dir {item:15908}: Benutze ihn an dem Wildtier, das sie nennt, und bring den Stab dann zu ihr zurück. Steinhauteber und Junge Waldbären streifen durch die Hügel südlich von {area:64}, Graue Forstwölfe durch die Wälder östlich von {area:18}.",
		["{npc:253}, back in the inn"] = "{npc:253}, zurück im Gasthaus",
		["{npc:253}, inside"] = "{npc:253}, drinnen",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} in {zone:1426}; {area:87} hat keinen Schamanenlehrer",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, neben ihr: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} bewacht die Brücke an der Straße nach Osten; {npc:248265} steht direkt auf der anderen Seite.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} lagert nordöstlich des Gasthauses. Hast du einen Beruf erlernt, bietet er auch dessen „Camping 101“ an, das dessen Lehrer annimmt: Kürschnerei, Lederverarbeitung und Angeln am Seeufer, {skill:129} und Schmiedekunst in {area:87}.",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: für {npc:1632} am Seeufer",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: für {npc:1651} am Seeufer",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: für {npc:2329} im Gasthaus „Zur Höhle des Löwen“",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: für {npc:514} an der Schmiede in {area:87}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: für {npc:6306} am Seeufer",
		["{npc:278}, inside"] = "{npc:278}, drinnen",
		["{npc:295}, inside"] = "{npc:295}, drinnen",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: {npc:5497} in {zone:1453} nimmt sie an",
		["{npc:375}, the priest trainer"] = "{npc:375}, die Priesterlehrerin",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, die Priesterlehrerin: {npc:377} in {area:87} nimmt sie an",
		["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (Priester), {npc:328} (Magier) und {npc:917} (Schurken) stehen oben im Gasthaus: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:377}, upstairs"] = "{npc:377}, oben",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, oben: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: Heile {npc:12423} am {area:18}",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}: {npc:376} in {zone:1453} nimmt es an",
		["{npc:459}, outside the Abbey"] = "{npc:459}, vor der Abtei",
		["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476} läuft um {area:54} herum: Schau auf der Karte in den Kreis",
		["{npc:514} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:514} nimmt sie entgegen, sobald deine Fertigkeit in {skill:164} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, an der Schmiede auf der anderen Straßenseite",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: Zähme ihn mit {item:15908}",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} in {zone:1453}; {area:87} hat keinen Druidenlehrer",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: {npc:6122} in {zone:1453} nimmt sie an",
		["{npc:6306} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6306} nimmt sie entgegen, sobald deine Fertigkeit in {skill:393} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:6306}, inside"] = "{npc:6306}, drinnen",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, am Seeufer östlich des Ortes; drinnen",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} und {npc:1651} stehen am Ufer von {area:18} östlich des Ortes.",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}: nur für Kürschner, die Felle sind gehäutet; drinnen",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, bei den Ställen südlich der Abtei",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} graben in den Weinbergen nordöstlich der Abtei. Ab und zu lässt einer {quest:91741} fallen: Rechtsklicke es.",
		["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80} läuft um {area:34} umher: Schau in den Kreis auf der Karte",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: Zähme ihn mit {item:15908}",
		["{npc:823}, at the Abbey steps"] = "{npc:823}, an den Stufen der Abtei",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, zurück an der Treppe der Abtei",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} verkauft die Shiny Red Apples für {quest:91736}. Äpfel, die du von Kobolden und aus Kisten plünderst, zählen auch: Der Kauf hakt sich selbst ab, sobald du vier hast.",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, der Kriegerlehrer; drinnen",
		["{npc:915}, the rogue trainer"] = "{npc:915}, der Schurkenlehrer",
		["{npc:925}, the paladin trainer"] = "{npc:925}, der Paladinlehrer",
		["{npc:952}, upstairs"] = "{npc:952}, oben",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}: Er will dein {item:247824}; drinnen",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: für {npc:234} bei {area:108}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855} wächst auf den Feldern um die Weinberge und den Hof der Stonefields; Stonetusk Boars in der Nähe geben das Blut.\nStonetusk Boars grasen zwischen den Weinbergen und dem Hof.",
		["{quest:76}'s entrance"] = "Eingang von {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87} ist in {area:57}, nicht auf dem Hügel darüber: Geh am Eingang hinein und halte dich links bis zum hinteren Ende der Minensohle; nimm nicht die Treppe nach oben. Banditen der Defias rund um die Weinberge lassen ab und zu {item:1972} fallen: Rechtsklicke sie.\nVorsicht: {npc:248464} (6), ein Kobold tief in der Mine, ist eine Elite, und {npc:79} (10, Rare) läuft durch die Tunnel: Zieh die Kobolde einzeln.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} und {npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429}: Töte sie, wenn du ihnen begegnest",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sit an {npc:265811}s Lagerfeuer, bis du {spell:1229451} erhältst",
		["Back at {area:256}"] = "Zurück bei {area:256}",
		["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Zurück durch das Stadttor und die Straße nach Osten: {quest:1683} steht südlich davon, bei {area:736}. Bring sein Horn zu {quest:1684} zurück.",
		["Back to the moonwell."] = "Zurück zum Mondbrunnen.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Zurück nach oben auf {area:256}. Die {object:654846} liegt neben ihm.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Zurück nach oben zu {npc:3567}, mit erledigten Waldwebern und dem Moos von {npc:272116}.",
		["Befouled Webwoods"] = "Besudelte Waldweber",
		["Below ground"] = "Unter der Erde",
		["Bloodfeather harpies"] = "Harpyien der Blutfedern",
		["Cast {spell:18960}"] = "Wirke {spell:18960}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}; {quest:5929} sitzt im Wald im Nordwesten. Lerne die Flugroute von {area:493} bei {npc:10897} südlich des Sees, für spätere Reisen. Dann fliegt {npc:11800} in {area:2361} Druiden über ihr Gesprächsmenü direkt nach {area:702}: Bei ihr gibt es keine Flugroute zu lernen. {npc:11802} steht oben in seinem Gebäude: Geh drinnen hoch, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Crawler Legs: the Tide Crawlers"] = "Crawler Legs: die Tide Crawlers",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Jede Quest von Dazalar gibt dir eine {item:15908}: Benutze sie an dem Wildtier, das er nennt, und bring den Stab dann zu ihm nach {area:186} zurück. Waldweberlauerer schleichen um das Dorf, Pirschende Nachtsäbler und Strigidkreischer streifen durch die Wälder südlich davon.",
		["East along the road to {area:186}."] = "Nach Osten die Straße entlang nach {area:186}.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Eskortiere {npc:275744} aus dem Grabhügel; {npc:2081} in {area:186} nimmt den Bericht an.",
		["Fandral in {zone:1457} takes it"] = "Fandral in {zone:1457} nimmt sie an",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Fel Cones liegen unter den Bäumen rund um {area:186} und {npc:2150}: Sammle sie auf der Straße nach Osten ein und gib sie auf dem Weg zu {npc:7234} bei {npc:2150} ab.",
		["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Nur für Angler: {npc:10216} steht auf dem Pier. Sein {item:12238} wird direkt vom Pier aus geangelt.",
		["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Flieg mit {npc:3841} zurück nach {area:702}, gib {item:16263} am Dock bei {npc:10118} ab und flieg dann zurück nach {area:442}.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Flieg noch einmal nach {area:702} und nimm das Portal hinauf zu {npc:4217}, dann flieg zurück nach {area:442}.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Folge der Straße nach Südwesten aus {area:188} hinaus. {npc:2150} sitzt daneben gleich östlich von {area:186}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Wegelagerer der Knarzklauen verstecken sich entlang der Straße westlich des {area:258}.",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Gnarlpine Mystics und {npc:7234} lagern nordöstlich von {area:260}. {npc:7234} lässt {item:8049} fallen: Öffne es für den Edelstein.\nVorsicht: {npc:7234} wartet nahe dem Lagerfeuer, umgeben von Mystics, also ist es schwer, ihn ohne Adds zu pullen.",
		["Gnarlpine Shamans"] = "Schamanen der Knarzklauen",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Geh zurück hinab nach {area:702} und flieg nach {area:442}. Der {object:177525} steht in den Hügeln gleich östlich des Dorfs: Benutze dort den {item:15208}, besiege Mondklaue und sprich mit dem {npc:12144}.",
		["Grells"] = "Grells",
		["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "Grells (Stufe 2-3) tragen {item:3297} in den Wäldern westlich des Baums, bei den Totems. Die {npc:1989} weiter nördlich sind Stufe 3-4: Die Grells bei den Totems reichen.",
		["Heal and fortify {npc:12429}"] = "Heile und stärke {npc:12429}",
		["Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the Moon at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "Durch das Tor in die Stadt. {quest:922} steht gleich südlich von {area:1658} am Nordende, {npc:7316} im Westen, {npc:7313} und {npc:8396} im Tempel des Mondes am Südende. Benutze auf dem Rückweg Dalias {item:279378} an der Bank und am Stadttor; die anderen beiden Eulen warten auf deinen letzten Besuch.",
		["Lead {quest:938} to the moonwell"] = "Führ {quest:938} zum Mondbrunnen",
		["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Lerne die Flugroute bei {npc:3841}, wo du landest. {npc:4200}s Fischstand liegt direkt nördlich von ihr, bei den Docks.\nDas Boot legt westlich des Dorfes an. Der Flugmeister steht auf dem Hügel südlich des Gasthauses; die Questgeber verteilen sich entlang der Hauptstraße.",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Verlass {area:188} über den Pfad südöstlich von {area:256}: {npc:6780} steht daneben, wo er hinab zur Straße nach {area:186} führt.",
		["Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside {npc:11401}."] = "Zauber der Stufe 12, wenn du schon im Tempel des Mondes bist: Die Priesterlehrer stehen neben {npc:11401}.",
		["Level 12 spells while you're in the {area:1658}: the hunter, rogue and druid trainers all stand in it."] = "Zauber der Stufe 12, wenn du schon in {area:1658} bist: Die Lehrer für Jäger, Schurken und Druiden stehen alle dort.",
		["Level 12 spells while you're on the {area:1660}: the warrior trainers stand beside {quest:1684}."] = "Zauber der Stufe 12, wenn du schon auf {area:1660} bist: Die Kriegerlehrer stehen neben {quest:1684}.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Räudige Nachtsäbler und Distelkeiler streifen nördlich von {area:256} auf dem Weg zur Höhle umher. {npc:1994} sitzt tief im Inneren. {npc:8584} wartet in den Bäumen westlich des Höhleneingangs.",
		["Nightsabers"] = "Nachtsäbler",
		["North to {area:257}"] = "Nach Norden zur {area:257}",
		["North-east from Ursal's den, back to {area:186}. {npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "Von Ursals Höhle nach Nordosten zurück nach {area:186}. {npc:6094} nimmt {item:159} samt den Wedeln und der Phiole: Falls du deins getrunken hast, kauf vor der Abgabe ein neues bei {npc:6736} in diesem Gasthaus.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "Nordwestlich von Dolanaar, auf dem Weg zur {area:264}, kriechen Besudelte Waldweber durch die Wälder; {npc:272116} streift an ihrem Ostrand umher und trägt das {item:281023}.\n{npc:272116} ist ein Elite-Gegner (Stufe 12): Eine Gruppe wird empfohlen. Räum zuerst die Waldweber um ihn herum weg und zieh ihn allein.",
		["On the way back south to the glade: {npc:272046} (level 12) flies on the slopes north-west of the moonwell, among Bloodfeather Matriarchs (11). Pull the harpies around her first."] = "Auf dem Rückweg nach Süden zur Lichtung: {npc:272046} (Stufe 12) fliegt an den Hängen nordwestlich des Mondbrunnens, zwischen Matriarchinnen der Blutfedern (11). Zieh zuerst die Harpyien um sie herum weg.",
		["Portal to {quest:940}"] = "Portal nach {quest:940}",
		["Priest trainer"] = "Priesterlehrer",
		["Sentinel Arynia again"] = "Wieder zu Schildwache Arynia",
		["South from the glade to the road: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "Von der Lichtung nach Süden zur Straße: Shayla läuft die Straße westlich von {area:186} ab, von dort, wo der Pfad von der Lichtung herab auf sie trifft, nach Südwesten bis zur Biegung bei etwa 38,54 und zurück.",
		["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs.\nCareful: the Gnarlpine Avengers (9-10) and Augurs here stand close together and many players died at the Hold: pull them one at a time."] = "Südlich der Teiche. {object:6751} wächst beim Hold; die Furbolgs drumherum lassen den Rest der Reißzähne fallen.\nVorsicht: Die Rächer der Knarzklauen (9-10) und Auguren hier stehen dicht beieinander, und viele Spieler sind am Hold gestorben: Zieh sie einzeln.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Südöstlich von Dolanaar, zu {npc:2080}. Wildschlagsetzlinge wandern am Ufer um ihn herum.",
		["South-west from {area:259}, past the {area:478}: Ursal prowls the far south of the island.\nCareful: Gnarlpine of roughly level 9-11 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "Von {area:259} nach Südwesten, an {area:478} vorbei: Ursal streift ganz im Süden der Insel umher.\nVorsicht: Knarzklauen etwa der Stufen 9-11 drängen sich im Lager und stehen dicht beieinander, daher ist es leicht, mehrere auf einmal zu pullen. Nimm sie einzeln vor, bevor du dich Ursal stellst.",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Südwestlich von Starbreeze, südlich von {npc:2150}. {npc:2080} pflegt seine Setzlinge am Ufer; Lasher Sproutlings und Timberlings wandern um ihn herum, und die {quest:919} wachsen zwischen ihnen.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Südwestlich des Grabhügels. Der Mondbrunnen liegt bei den Teichen.",
		["Speak with the {quest:5929}"] = "Sprich mit dem {quest:5929}",
		["Take the antidote from {npc:8583} at the foot of {area:256} only now, on the way down: it lasts five minutes. {npc:8584} waits north-west, by the cave: go straight on to him."] = "Nimm das Gegengift von {npc:8583} am Fuß von {area:256} erst jetzt, auf dem Weg nach unten: Es wirkt fünf Minuten lang. {npc:8584} wartet im Nordwesten an der Höhle: Geh direkt zu ihm.",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Nimm das Portal hinunter nach {area:702}. {npc:10118} steht am Steg, {npc:3838} bei den Hippogryphen. Hast du {quest:6342}, sprich noch einmal mit {npc:3838} und wähle den Flug nach {area:442}: Er ist kostenlos und landet neben {npc:4200}. Öffnet sich stattdessen die Flugkarte, schließe sie und sprich noch einmal mit ihm, während du Umschalt gedrückt hältst.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Nimm wieder die Straße von {area:186} nach Nordwesten; sie liegt noch daneben, auf dem Weg nach {zone:1457}.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "Die Bloodfeather-Harpyien nisten an den Hängen westlich und nördlich der Lichtung. {quest:938}, eine verletzte Säbelzahnkatze, liegt an der Westmauer der Lichtung mitten unter ihnen: Führ sie zurück zu Schildwache Arynia am Mondbrunnen, bevor ihre Zeit abläuft.\nVorsicht: Die Harpyien stehen dicht gedrängt, deshalb mischen sich oft weitere in einen Kampf ein. Zwischen ihnen stehen Zauberwirker.",
		["The WANTED poster outside the inn"] = "Der Steckbrief vor dem Gasthaus",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs.\nCareful: the barrow's Gnarlpine Defenders, Augurs and Shamans (7-9) stand in threes in the narrow tunnels: pull each group back toward the entrance before you go deeper."] = "Der Hügel liegt südlich der Straße. {npc:275744} wird drinnen gefangen gehalten, {npc:7317} schläft in der Tiefe, und die vier Relikttruhen stehen in den unteren Räumen. Die Furbolgs dort lassen Shaylas Reißzähne fallen.\nVorsicht: Die Verteidiger, Auguren und Schamanen der Gnarlpine (7-9) im Hügel stehen zu dritt in den engen Tunneln: Zieh jede Gruppe zurück Richtung Eingang, bevor du tiefer gehst.",
		["The grells west of the tree"] = "Die Grells westlich des Baums",
		["The moonwell"] = "Der Mondbrunnen",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "Der Mondbrunnen liegt mitten auf der Lichtung. Die {object:6752} wächst an ihrem Nordende.",
		["The moonwell sits north of {area:256}."] = "Der Mondbrunnen liegt nördlich von {area:256}.",
		["The road to {zone:1457}"] = "Die Straße nach {zone:1457}",
		["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "Die Straße nach Westen zu {area:264} führt durch {area:186}: Gib {npc:3567} auf dem Weg den Edelstein.",
		["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Die Lehrer stehen oben in {area:256}, entlang der Rampe, die sich den Baum hinaufwindet: {npc:3593} und {npc:3594} auf der ersten Ebene, {npc:3595} darüber, {npc:3596} und {npc:3597} ganz oben. Der Pfeil kann die Ebenen nicht unterscheiden.",
		["The {area:265}"] = "{area:265}",
		["The {area:478}"] = "Die {area:478}",
		["The {object:177525}"] = "Der {object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "Die {object:4406} liegen hinten in der {area:257}: Nimm den mittleren Pfad, dann links an der Gabelung, hinauf zum hohen Felsvorsprung. Hyazinth-Pilze lassen Grells fallen, Mondblütenlilien wachsen an den Teichen nördlich von {area:256}.",
		["The {object:6752} grows at the glade's north end, on the way: then north along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "{object:6752} wächst am Nordende der Lichtung, auf dem Weg: Dann nach Norden, am Nordrand der Insel bei {area:266}, lauert {npc:7319}, eine Spinne der Stufe 12.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Gezeitenkriecher krabbeln unterhalb des Dorfes am Ufer entlang; {quest:983} steht am Strand gleich südlich der Anlegestelle. Dunkelküstendrescher schwimmen im seichten Wasser. {object:175207} liegt gleich südlich des Dorfes am Ufer.",
		["Upstairs"] = "Oben",
		["Use the {item:18152} at the moonwell"] = "Benutze die {item:18152} am Mondbrunnen",
		["Use the {item:5185} at the moonwell"] = "Benutze die {item:5185} am Mondbrunnen",
		["Use the {item:5619} at the moonwell"] = "Benutze die {item:5619} am Mondbrunnen",
		["Use the {item:5621} at the moonwell"] = "Benutze die {item:5621} am Mondbrunnen",
		["Walk Lynessa out and keep her alive"] = "Führ Lynessa hinaus und halte sie am Leben",
		["Warrior trainer"] = "Kriegerlehrer",
		["Webwood Lurkers"] = "Waldweberlauerer",
		["Webwood Spiders; below ground"] = "Netzwaldspinnen; unter der Erde",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Nach Westen die Straße entlang in Richtung Stadt. Shayla läuft diesen Straßenabschnitt ab, vom Pfeil nach Südwesten bis zur Biegung bei etwa 38,54 und zurück: Wenn sie nicht beim Pfeil ist, folge der Straße nach Südwesten. Jeder Furbolg der Knarzklauen lässt Fänge fallen: Die Wegelagerer an dieser Straße, die im Grabhügel und die in {area:261} zählen alle.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.\nCareful: {npc:272116}, a level 12 elite, prowls the east edge of the Befouled Webwoods north-west of {area:186}: if you are alone, keep clear of the webwoods and go round him."] = "Von den Waldwebern nach Westen zu {area:265}, dann an ihm entlang nach Norden zur Lichtung: Die Holzlinge an seinen Ufern lassen die Moosartigen Tumore fallen.\nVorsicht: {npc:272116}, ein Elite der Stufe 12, streift am Ostrand der Besudelten Waldweber nordwestlich von {area:186} umher: Wenn du allein bist, halte dich von den Waldwebern fern und geh um ihn herum.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:11866} ({area:1660}, 10 Silber); die Nahkampfwaffe eines Jägers besteht vor allem aus ihren Werten, und Zweihänder bieten die meisten.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:11866} ({area:1660}, 10 Silber); ein Stab bietet beim Leveln mehr Zauberwerte als eine Einhandwaffe.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "Hast du einen Beruf erlernt, bietet {npc:265811} auch dessen Camping 101 an, das sein Lehrer annimmt: Alchemie und Kräuterkunde neben {npc:6286}, {skill:129} bei {npc:6094} im Gasthaus, Kürschnerei und Lederverarbeitung im Lager der Mähnenweber an der Straße nach Westen.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Du beginnst am Fuß von {area:256}, dem großen Baum von {area:188}.",
		["Young Nightsabers and Young Thistle Boars (level 1-2) roam around {area:256}: start with them. The Gnarlpine Totems stand in the woods west of the tree, where the Grells (2-3) roam: take them once the beasts are done."] = "Junge Nachtsäbler und Junge Disteleber (Stufe 1-2) streifen um {area:256} herum: Fang mit ihnen an. Die Totems der Knarzklauen stehen in den Wäldern westlich des Baums, wo die Grells (2-3) umherstreifen: Hol sie dir, sobald die Wildtiere erledigt sind.",
		["talk to the trainer"] = "sprich mit dem Lehrer",
		["talk to {npc:3838} again: free with {quest:6342}"] = "sprich noch einmal mit {npc:3838}: kostenlos mit {quest:6342}",
		["the city gate"] = "das Stadttor",
		["the same {object:673378}: Fandral in {zone:1457} takes it"] = "dieselbe {object:673378}: Fandral in {zone:1457} nimmt sie an",
		["the tunnel mouth below {area:3425}, on the way south"] = "der Tunneleingang unterhalb von {area:3425}, auf dem Weg nach Süden",
		["{area:1658} trainers"] = "Lehrer in {area:1658}",
		["{area:186} again"] = "Wieder {area:186}",
		["{area:188}: kill these as you meet them"] = "{area:188}: Töte diese, sobald du ihnen begegnest",
		["{area:258}'s mouth"] = "Eingang des {area:258}",
		["{area:262}'s entrance"] = "Eingang von {area:262}",
		["{area:442} flight master"] = "Flugmeister von {area:442}",
		["{area:702} flight master"] = "Flugmeister von {area:702}",
		["{area:736}, outside the barrow"] = "{area:736}, außerhalb des Grabhügels",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} von {npc:6736}, für {npc:6094}",
		["{item:279378}: the bank, on the way out"] = "{item:279378}: die Bank, auf dem Weg nach draußen",
		["{item:279378}: the inn on the {area:1659}"] = "{item:279378}: das Gasthaus auf {area:1659}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} von {npc:3614}, neben {npc:6094}",
		["{item:5170}: timberlings"] = "{item:5170}: Timberlings",
		["{item:5220}: any Gnarlpine furbolg"] = "{item:5220}: jeder Gnarlpine-Furbolg",
		["{item:8049}, from {npc:7234}"] = "{item:8049}, von {npc:7234}",
		["{npc:10118} stands on the Rut'theran dock where you land. Then take the portal up to {npc:4217} in the {area:1658}."] = "{npc:10118} steht am Steg von Rut'theran, wo du landest. Nimm dann das Portal hinauf zu {npc:4217} in der {area:1658}.",
		["{npc:10216}, on the pier"] = "{npc:10216}, auf dem Pier",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, im Tempel des Mondes: Sternensplitter",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} kniet verwundet auf den Felsen am Nordrand des {area:259}, auf dem Rückweg nach {area:186}, ohne Questmarkierung über ihr. Wirke {spell:613} (Rang 2) auf sie, dann {spell:1243}: Rang 1 von {spell:613} zählt nicht. Sie läuft davon, sobald beide gewirkt sind, und ist nach etwa 5 Minuten zurück.",
		["{npc:1992}, south of the tree"] = "{npc:1992}, südlich des Baums",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: Zähme ihn mit der {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: Zähme ihn mit der {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} wartet in der Höhle, unten oder oben auf dem Felsvorsprung; halte dich rechts.",
		["{npc:2038}; below ground"] = "{npc:2038}; unter der Erde",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: Zähme ihn mit der {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, am Pfad",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: ein Siegel für {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: {quest:922} in {zone:1457} nimmt sie an",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, auf der Rampe des Baums",
		["{npc:2107} stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107} steht oben in einem Haus im Dorf, östlich des Mondbrunnens: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden. {object:126158} steht im Haus auf dem Hügel am Ostende des Dorfes.",
		["{npc:2150} sits by the road just east of {area:186}, between {area:186} and {area:260}."] = "{npc:2150} sitzt an der Straße knapp östlich von {area:186}, zwischen {area:186} und {area:260}.",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} patrouilliert auf der Straße westlich des Dorfs: Wenn sie nicht beim Pfeil ist, folge der Straße, bis du sie triffst.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}, an der Straße westlich des Dorfs",
		["{npc:265811}, by the campfire"] = "{npc:265811}, am Lagerfeuer",
		["{npc:265811}: for {npc:3603}, beside {npc:6286}"] = "{npc:265811}: für {npc:3603}, neben {npc:6286}",
		["{npc:265811}: for {npc:3604}, beside {npc:6286}"] = "{npc:265811}: für {npc:3604}, neben {npc:6286}",
		["{npc:265811}: for {npc:3605}, by the road west"] = "{npc:265811}: für {npc:3605}, an der Straße nach Westen",
		["{npc:265811}: for {npc:6094} in the inn"] = "{npc:265811}: für {npc:6094} im Gasthaus",
		["{npc:265811}: for {npc:6287}, by the road west"] = "{npc:265811}: für {npc:6287}, an der Straße nach Westen",
		["{npc:272034} and {npc:272044}"] = "{npc:272034} und {npc:272044}",
		["{npc:272034} and {npc:272044} (level 10) fly just west of the moonwell. {npc:272046} (12) waits further north for the walk back from {npc:7319}."] = "{npc:272034} und {npc:272044} (Stufe 10) fliegen gleich westlich des Mondbrunnens. {npc:272046} (12) heben wir uns weiter nördlich für den Rückweg von {npc:7319} auf.",
		["{npc:3514}, at the top of the tree"] = "{npc:3514}, oben im Baum",
		["{npc:3515}, south of the inn"] = "{npc:3515}, südlich des Gasthauses",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516}, im {area:1658}",
