		["{npc:4606}: take her {quest:5642} letter"] = "{npc:4606}: Nimm ihren Brief {quest:5642} an",
		["{npc:4606}: take her {quest:5652} letter"] = "{npc:4606}: Nimm ihren Brief {quest:5652} an",
