		["Leave {zone:1412} by the same pass and ride south through the {zone:1413} to the {area:485} down into {zone:1441}. {area:484} is a Horde town."] = "Verlasse {zone:1412} durch denselben Pass und reite durch die {zone:1413} nach Süden zum {area:485}, der hinab nach {zone:1441} führt. {area:484} ist eine Stadt der Horde.",
		["Leave {zone:1412} by the same pass, ride north through the {zone:1413} and west at {area:1702} into the {zone:1442}. {area:460} is the Horde town; {area:467} in the north is Alliance."] = "Verlasse {zone:1412} durch denselben Pass, reite durch die {zone:1413} nach Norden und bei {area:1702} nach Westen in das {zone:1442}. {area:460} ist die Stadt der Horde; {area:467} im Norden gehört zur Allianz.",
		["Take the boat from {area:442} to {area:702}. {zone:1438} is night elf country: {area:186} and {area:188} have guards, and {zone:1457} is reached only through the portal in {area:702}."] = "Nimm das Boot von {area:442} nach {area:702}. {zone:1438} ist Nachtelfengebiet: {area:186} und {area:188} haben Wachen, und {zone:1457} erreichst du nur durch das Portal in {area:702}.",
		["Take the boat from {area:702} to {area:442}."] = "Nimm das Boot von {area:702} nach {area:442}.",
		["The road east out of south-eastern Stonetalon comes down into the {zone:1413} at {area:1702}. {area:380} and {area:378} are Horde towns; {area:392} is a neutral port."] = "Die Straße nach Osten aus dem südöstlichen Steinkrallengebirge führt bei {area:1702} hinab in die {zone:1413}. {area:380} und {area:378} sind Städte der Horde; {area:392} ist ein neutraler Hafen.",
		["The road west from {area:378} climbs through the only pass into {zone:1412}."] = "Die Straße westlich von {area:378} führt durch den einzigen Pass nach {zone:1412}.",
		["The {area:363} opens onto {zone:1411}; {area:362} is north along the road."] = "Das Gebiet {area:363} öffnet sich nach {zone:1411}; {area:362} liegt nördlich an der Straße.",
		["The {zone:1442} border {zone:1440} to the south-west; {area:467} in the north is the Alliance flight point."] = "Das {zone:1442} grenzt im Südwesten an das {zone:1440}; der Ort ({area:467}) im Norden ist der Flugpunkt der Allianz.",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["level 35 area, well above this guide's range"] = "Gebiet der Stufe 35, weit über dem Bereich dieses Guides",
		["{area:1276} tunnel in eastern Stonetalon leads north into {zone:1440}. {area:431} and {area:2897} are Horde; {area:415} is Alliance."] = "Der Tunnel ({area:1276}) im Osten des Steinkrallengebirges führt nach Norden ins {zone:1440}. {area:431} und {area:2897} gehören der Horde; {area:415} der Allianz.",
		["{area:188} opens onto {zone:1438}; {area:186} is south along the road. {area:702}, at the foot of the tree, is reached through the portal in {zone:1457}."] = "{area:188} öffnet sich nach {zone:1438}; {area:186} liegt südlich an der Straße. {area:702} am Fuß des Baums erreichst du durch das Portal in {zone:1457}.",
} end)()
