t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "Erkundung: {zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "Himmelsgeborene starten hier. Alle anderen nehmen ein Himmelsboot, etwa alle fünf Minuten; jede Fraktion darf jedes nehmen.",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "Das Himmelsboot legt an den Klippen südlich des {area:17045} ab, nördlich von {zone:1456} (ein weiteres fliegt von {area:279}).",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "Das Himmelsboot legt an der Nordseite von {area:279} im {zone:1416} ab (ein weiteres fliegt nördlich von {zone:1456}).",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["{zone:2521} is the Skyborne starting island, a world of its own in {area:17221}; anyone may visit. 20 areas to discover here, levels 3-12."] = "{zone:2521} ist die Startinsel der Himmelsgeborenen, eine eigene Welt in {area:17221}; jeder darf sie besuchen. Hier gibt es 20 Gebiete zu entdecken, Stufe 3-12.",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Hilf {npc:261366}: Bleib bei ihm, wenn {npc:261367} und die Marinesoldaten von {area:21} den Kamm heraufkommen",
		["At the {area:2362}"] = "Am {area:2362}",
		["At the {object:147538}: summons {quest:882}"] = "Am toten Baum: beschwört {quest:882}",
		["Back down to {npc:11857}."] = "Zurück hinunter zu {npc:11857}.",
		["Back east over the bridge and up the trail to {npc:5900}'s shrine again. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Zurück nach Osten über die Brücke und den Pfad hinauf wieder zum Schrein von {npc:5900}. {npc:5900} stellt aus dem Teer und dem Beutel {item:6636} her. Benutze es am Kohlebecken neben ihm, um die {npc:5893} sichtbar zu machen, töte sie für die {item:6655} und lege die Glut dann ins Kohlebecken.",
		["Back north along the beach to {area:392}."] = "Den Strand entlang zurück nach Norden nach {area:392}.",
		["Back north into the Bristleback camps. Any Bristleback can drop a tusk for {npc:3432}, so collect them while you kill these for {npc:3430}. Keep one {item:5075}."] = "Zurück nach Norden in die Lager der Borstennacken. Jeder Borstennacken kann einen Hauer für {npc:3432} fallen lassen, also sammle sie, während du diese für {npc:3430} tötest. Behalte einen {item:5075}.",
		["Back north into {area:378} before the antennae fade: {npc:6394} is inside."] = "Zurück nach Norden nach {area:378}, bevor die Fühler verfallen: {npc:6394} ist drinnen.",
		["Back north into {area:378} on the way to the Crossroads: Jorn takes the thunderhawk wings."] = "Zurück nach Norden nach {area:378}, auf dem Weg zum Wegekreuz: Jorn nimmt die Donnerfalkenschwingen.",
		["Back out of the caverns and up to the cave above the entrance."] = "Aus den Höhlen hinaus und hinauf zur Höhle über dem Eingang.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them. Careful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438} and the supply crates, and {npc:267307} (20, elite) lies in the cave under {area:1699} beside them: pull {npc:3438} and the quilboar away from them one at a time, and leave the cave alone unless you are in a group."] = "Zurück zum Lager der Grimmhauer. Geomanten und Verteidiger halten die östliche Hälfte; {npc:3438} läuft zwischen ihnen herum. Vorsicht: Fleischfresser und Berserker der Grimmhauer (18-19) sind Elites im Nordosten des Lagers, nahe {npc:3438} und den Vorratskisten, und {npc:267307} (20, Elite) liegt in der Höhle unter {area:1699} neben ihnen: Zieh {npc:3438} und die Stacheleber einzeln von ihnen weg und lass die Höhle in Ruhe, außer du bist in einer Gruppe.",
		["Bristleback Geomancers"] = "Geomanten der Borstennacken",
		["Bristleback camps"] = "Lager der Borstennacken",
		["Cast {spell:18960}"] = "Wirke {spell:18960}",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}. {npc:11802} steht oben in seinem Gebäude in {area:2361}: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Crossroads flight master"] = "Flugmeister des Wegekreuzes",
		["Cure {npc:12296}"] = "Heile {npc:12296}",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran ist im Stacheleberlager westlich der Straße angekettet.",
		["Down the {area:458} to {area:378} again."] = "Die {area:458} wieder hinunter zum {area:378}.",
		["East along the road to {npc:4049} and {npc:11857}'s camp, on the way back out of Stonetalon."] = "Entlang der Straße nach Osten zum Lager von {npc:4049} und {npc:11857}, auf dem Rückweg aus dem Steinkrallengebirge.",
		["East from the keg toward {quest:881}: {npc:3682} camps below the hills, and his errands lie in the plains beside his camp."] = "Östlich vom Fass Richtung {quest:881}: {npc:3682} lagert unterhalb der Hügel, und seine Aufträge liegen auf den Ebenen neben seinem Lager.",
		["East from {npc:261366} toward the {area:382}: {npc:9316} stands at the camp on the road north of the Crossroads."] = "Von {npc:261366} nach Osten Richtung {area:382}: {npc:9316} steht im Lager an der Straße nördlich des Wegekreuzes.",
		["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints."] = "Östlich von Ziz rodet die Venture Company {area:461}; einer der Bediener trägt die Pläne.",
		["East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, and {npc:3467} (16) stands beside them."] = "Nach Osten zum Strand, am Südende des Piratenlagers: Die Kiste mit Stiefeln und die zerbrechliche Kiste mit der Linse stehen dort, und {npc:3467} (16) steht daneben.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Füll {item:7766} am Wasserloch der Stacheleber",
		["Finish the Plainstrider Beaks"] = "Schließe die Weideläufer-Schnäbel ab",
		["Finish the Raptor Heads"] = "Schließe die Raptorköpfe ab",
		["Fly from the Crossroads to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}. {spell:499} and {spell:526} follow in {zone:1450} on the same trip, then {npc:11798} flies you back here and on to {area:392}."] = "Flieg vom Wegekreuz nach {area:1638} und lerne deine Ränge für Stufe 20: {npc:3033} ist auf {area:1639}. {spell:499} und {spell:526} folgen auf derselben Reise in {zone:1450}, dann fliegt dich {npc:11798} hierher zurück und weiter nach {area:392}.",
		["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "Flieg von Crossroads nach {area:1638}. {quest:853} wartet in {area:2197}, der Höhle unter {area:1640}: Gib dort zuerst die Sporen ab, solange ihre Zeit läuft. Dann lässt dich {npc:3033} auf {area:1639} trainieren.",
		["Fly from {zone:1456} on to {area:392}."] = "Flieg von {zone:1456} weiter nach {area:392}.",
		["Fly from {zone:1456} straight on to {area:392}."] = "Flieg von {zone:1456} direkt weiter nach {area:392}.",
		["Fly on to {area:392} from Doras on the tower in the {object:172982}."] = "Flieg von Doras auf dem Turm im {object:172982} weiter nach {area:392}.",
		["Fly to Crossroads"] = "Flieg zum Wegekreuz",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Follow the road on west from {npc:4049} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "Folge der Straße von {npc:4049} weiter nach Westen ins Steinkrallengebirge. Das Trolldorf {area:2539} liegt am Eingang der Schlucht.",
		["Follow the {area:458} south to {area:378}."] = "Folge der {area:458} nach Süden zum {area:378}.",
		["For your {area:718} run: {npc:3446}'s next errand, {quest:1491}."] = "Für deinen Run durch {area:718}: der nächste Auftrag von {npc:3446}, {quest:1491}.",
		["For your {area:718} run: {npc:5767} and {npc:5768} stand in a hidden cave in the rocks above the entrance, at the north end of the oasis' west shore: climb up from the west side. Follow the arrow up."] = "Für deinen Run durch {area:718}: {npc:5767} und {npc:5768} stehen in einer versteckten Höhle in den Felsen über dem Eingang, am Nordende des Westufers der Oase: Klettere von der Westseite hinauf. Folge dem Pfeil nach oben.",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["He gives you the {item:15826}"] = "Er gibt dir {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Als Nächstes bietet er {quest:1838} an (1838, Stufe 30): Sie erfordert {area:1717} und schickt dich durch ganz Kalimdor und die Östlichen Königreiche. Der Kriegerklassen-Guide {quest:1838} deckt sie ab.",
		["Head north from the Crossroads to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the Crossroads. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "Geh nördlich vom Wegekreuz zum {area:384} und fülle den {item:15842} am {object:19464}, dann zurück zu {npc:3448} im Wegekreuz. Kein {skill:182}? {npc:3490} neben ihm verkauft {item:2449}, drei auf einmal, bis er neu auffüllt.",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "Durch das Nordtor hinein: zuerst {npc:3464}, {npc:3338} beim Gasthaus, dann hinauf zu {npc:3449} und {npc:3429} auf der Turmplattform, wo der Flugmeister steht.",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Im Lager halten Wassersucher und Dornenwirker die westliche Hälfte, Jäger die Mitte; die Vorratskisten stehen am östlichen Ende.\nEbenenschreiter hier zählen für die Schnäbel.\nVorsicht: Fleischfresser und Berserker der Grimmhauer (18-19) sind Elites; sie stehen im Nordosten des Lagers neben den Vorratskisten: Zieh die Stacheleber einzeln von ihnen weg.",
		["Inside"] = "Drinnen",
		["Keep it: the {object:107045} is beside {area:272}, on the {area:287} guide"] = "Behalte sie: Der {object:107045} ist neben {area:272}, im Guide {area:287}",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Behalte sie: {npc:12696} in {zone:1440}, nächster Guide",
		["Keep it: {npc:5875} in {zone:1454}, on the next guide's {zone:1454} stop"] = "Behalte sie: {npc:5875} in {zone:1454}, beim nächsten Halt in {zone:1454} im nächsten Guide",
		["Keep it: {quest:3923} is in {zone:1454}'s {object:172958}, on the {zone:1454} trip at 20"] = "Behalte sie: {quest:3923} ist im {object:172958} von {zone:1454}, auf der Reise nach {zone:1454} bei 20",
		["Keep {npc:3446}'s {quest:865} and {npc:3467} for the next {area:392} stop, at 18: Scytheclaws you meet on the plains before then drop the horns too."] = "Heb dir {quest:865} von {npc:3446} und {npc:3467} für den nächsten Halt in {area:392} auf, mit 18: Sensenklauen, die dir vorher in den Ebenen begegnen, lassen die Hörner auch fallen.",
		["Kolkar camp"] = "Lager der Kolkar",
		["Leave {zone:1454} by the main gate and follow the road south through {zone:1411}, then west over the {area:814} bridge: {npc:5810} stands at {area:379} just above it, on the road to the Crossroads."] = "Verlasse {zone:1454} durch das Haupttor und folge der Straße nach Süden durch {zone:1411}, dann westlich über die Brücke von {area:814}: {npc:5810} steht direkt darüber bei {area:379}, an der Straße zum Wegekreuz.",
		["Level 20"] = "Stufe 20",
		["Lost Barrens Kodos roam the plains around the Kolkar camp north-west of {npc:3389}; herbalists pick {item:2449} there too."] = "Verirrte Barrens-Kodos streifen durch die Ebenen um das Kolkar-Lager nordwestlich von {npc:3389}; Kräutersammler finden dort auch {item:2449}.",
		["North to the {area:383}: {quest:876} leads the Witchwing harpies in the hills to the west.\nCareful: The route in passes stealthed Harpy Ambushers and an elite harpy that patrols."] = "Nach Norden zur {area:383}: {quest:876} führt die Witchwing-Harpyien in den Hügeln im Westen.\nVorsicht: Der Weg hindurch kommt an getarnten Harpyien-Lauerern und einer Elite-Harpyie vorbei, die patrouilliert.",
		["North up the road from {area:2539}: {npc:11858} and his Grimtotem Brutes hold the bend in the road, and the Deepmoss Creepers and Venomspitters lurk in the webs on both sides of the path all the way up."] = "Die Straße nördlich von {area:2539} hinauf: {npc:11858} und seine Grimmtotem-Rohlinge halten die Biegung der Straße, und die Deepmoss-Schleicher und Giftspucker lauern in den Netzen zu beiden Seiten des Pfades, den ganzen Weg hinauf.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "Nach Norden die {area:458} hinauf nach Crossroads: {npc:3448} am Südtor, {npc:3432} beim Gasthaus, {npc:3428} westlich des Nordtors.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "Die {area:458} hinauf nach Norden zum Wegekreuz: {npc:3448} am Südtor, {npc:3432} beim Gasthaus, {npc:3428} westlich des Nordtors. Behalte {item:5075}: {npc:3430} nimmt ihn beim nächsten Halt im {area:378} entgegen.",
		["North-west to the {area:383}: the Witchwing Slayers hold their western end; they wear the rings.\nCareful: Some stealthed harpy ambushers wait in the area and stay hidden until you get close. A level 19 elite harpy also patrols there."] = "Nach Nordwesten zu den {area:383}: Die Witchwing-Schlächter halten ihr westliches Ende; sie tragen die Ringe.\nVorsicht: Einige getarnte Harpyien-Hinterhalter lauern in dem Gebiet und bleiben verborgen, bis du nah herankommst. Außerdem patrouilliert dort eine Elite-Harpyie der Stufe 19.",
		["On the top floor"] = "Im obersten Stockwerk",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "Auf dem Rückweg den {area:1076} hinunter wird {npc:11856} in der Hütte von {npc:11858} an der Straßenbiegung festgehalten. Sobald du ihre Quest annimmst, läuft sie ohne zu warten direkt nach Südosten zum {area:2538}, dem niedergebrannten Dorf: Bleib dicht bei ihr, sonst schlägt die Quest fehl.\nVorsicht: Drei Grimmtotem lauern ihr im niedergebrannten Dorf auf und greifen sie an, nicht dich: Zieh sie von ihr weg und töte schnell ihren Zauberwirker.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last Crossroads stop."] = "Auf dem Rückweg die {area:458} hinunter nach {area:378}: Die Klingenmähnen-Plünderer zwischen den Lagern der Borstennacken, auf beiden Seiten der Straße nördlich des Lagers, tragen {item:277277}. Gib sie bei deinem letzten Halt am Wegekreuz bei {npc:3432} ab.",
		["Plainstrider Beaks as you go"] = "Weideläufer-Schnäbel unterwegs",
		["Plainstriders roam the plains all over the {zone:1413}, and about one in four drops a beak: kill the ones you pass on the way."] = "Weideläufer streifen überall durch die Ebenen von {zone:1413}, und etwa einer von vier lässt einen Schnabel fallen: Töte die, an denen du vorbeikommst.",
		["Raptor Heads as you go"] = "Raptorköpfe unterwegs",
		["Raptor nests"] = "Raptornester",
		["Razormane camp"] = "Lager der Grimmhauer",
		["Razormane camp: {npc:3429}'s quilboar"] = "Lager der Klingenmähnen: die Stacheleber von {npc:3429}",
		["Savannah Patriarchs roam the plains east of {npc:3682}'s camp, and the Sprung Traps lie among them."] = "Savannen-Patriarchen streifen über die Ebenen östlich des Lagers von {npc:3682}, und die Springfallen liegen zwischen ihnen.",
		["Savannah lions"] = "Savannen-Löwen",
		["South along the beach past the pirate camp to {area:385}, on the coast. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier."] = "Nach Süden am Strand entlang, vorbei am Piratenlager, nach {area:385} an der Küste. Die Marinesoldaten und Bewahrer von Theramore (15-16) lassen die Medaillen fallen; {npc:3393} (20) und die zwei Kanoniere (19) stehen in der Festung und auf ihren Mauern.\nVorsicht: Jedes benannte Ziel ist mit einem Heiler und Wachen verbunden, und Hellstieg hat drei zusätzliche Marinesoldaten bei sich. Den Heiler zuerst zu töten macht den Kampf leichter.",
		["South down the road to the Crossroads: {npc:3449} stands on the tower platform, {npc:3448} at the south gate."] = "Die Straße nach Süden zum Wegekreuz: {npc:3449} steht auf der Turmplattform, {npc:3448} am Südtor.",
		["South-east on the way back to the Crossroads: {quest:881}, a white lion, prowls the plains north of the Razormane camp.\nCareful: Savannah Huntresses roam around the lair. They respawn quickly and often join the fight alongside {quest:881}, so clear them out before you blow the horn.\nSunscale raptors here count toward the heads."] = "Nach Südosten auf dem Rückweg zum Wegekreuz: {quest:881}, ein weißer Löwe, streift durch die Ebenen nördlich des Lagers der Klingenmähnen.\nVorsicht: Savannah jägerinnen streifen um die Höhle. Sie respawnen schnell und greifen oft zusammen mit {quest:881} an, also räume sie weg, bevor du das Horn bläst.\nSunscaleraptoren hier zählen für die Köpfe.",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "Von {area:392} nach Südwesten über die Ebenen zu {area:1697}: Die drei Nester liegen zusammen südwestlich der Oase; Bluthornsensenklauen bewachen sie. Jedes Nest braucht {item:5165}: Töte Raptoren der Bluthorn (die meisten lassen eine fallen), bis du drei hast, und benutze dann an jedem Nest eine Feder.",
		["Speak to {npc:3389} again to start the attack: the Kolkar charge the bunkers just west of him in waves. Fight beside the grunts until {npc:9456} (elite, 20) arrives with two bodyguards, usually from the south, then click the banner over his body."] = "Sprich noch einmal mit {npc:3389}, um den Angriff zu starten: Die Kolkar stürmen in Wellen die Bunker direkt westlich von ihm. Kämpfe neben den Grunts, bis {npc:9456} (Elite, 20) mit zwei Leibwächtern ankommt, meist aus dem Süden, und klicke dann das Banner über seiner Leiche an.",
		["Still short of seven? Plainstriders are thickest on the plains north of the Crossroads, along the road north."] = "Fehlen dir noch welche zu sieben? Weideläufer gibt es am dichtesten in den Ebenen nördlich des Wegekreuzes, entlang der Straße nach Norden.",
		["Still short of twelve? Sunscale Lashtails and Screechers roam the plains north-east of the Crossroads, on the way back south from {quest:881}'s lair."] = "Fehlen dir noch welche zu zwölf? Sunscale-Peitschenschwänze und -Kreischer streifen durch die Ebenen nordöstlich des Wegekreuzes, auf dem Rückweg nach Süden von der Höhle von {quest:881}.",
		["Sunscale Scytheclaws hunt the plains around the {area:1697}; they drop the horns. {npc:3446} takes them back in {area:392}; any still missing come with {npc:3682}'s hills later.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "Bluthornsensenklauen jagen in den Ebenen um {area:1697}; sie lassen die Hörner fallen. {npc:3446} nimmt sie in {area:392} entgegen; fehlende bekommst du später in den Hügeln von {npc:3682}.\nNach Südosten Richtung Küste: Das gestohlene Silber liegt in einem Raptornest nordwestlich von {area:385}.",
		["Sunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health."] = "Sunscaleraptoren streifen durch die Ebenen nördlich und östlich des Wegekreuzes, und etwa drei von vier lassen einen Kopf fallen: Töte die, an denen du vorbeikommst. Vorsicht: Sunscale-Kreischer rufen nahe Verbündete im Umkreis von 30 yd, sobald sie unter 30% Gesundheit fallen.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. Careful: the spirits are Territorial Terrans (level 60) that kill whoever they see: stay off their paths, and click the statue again before the stealth runs out."] = "Tauren: {npc:11957} wartet auf dem südlichen Hügel über der Brücke. Himmelsgeborene: {npc:272054} steht südlich der Zwillingsbrücken. Dann die Grabhügel östlich des Sees: Verlass deine Gestalt, klick die Statue am Eingang an für fünf Minuten Verstohlenheit, halte dich von den Geistern darin fern und nimm von jedem Relikt eins; {item:280680} liegt am Fuß der weißen Katzenstatue. Vorsicht: Die Geister sind Territorial Terrans (Stufe 60), die jeden töten, den sie sehen: Bleib von ihren Wegen fern und klick die Statue erneut an, bevor die Verstohlenheit ausläuft.",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. {npc:3432}'s wife lies at their north edge, on your way south. Leave the quilboar for now: {npc:3430} in {area:378} wants the same camps cleared. {quest:883}, a grey kodo (level 22), sometimes wanders here: his hoof starts a quest. Leave him alone below level 21."] = "Die Lager der Borstennacken-Stacheleber ziehen sich über die Ebenen nördlich von {area:378}, auf beiden Seiten der {area:458}. Die Frau von {npc:3432} liegt an ihrem Nordrand, auf deinem Weg nach Süden. Lass die Stacheleber vorerst in Ruhe: {npc:3430} in {area:378} will dieselben Lager geräumt haben. {quest:883}, ein grauer Kodo (Stufe 22), streift manchmal hier umher: Sein Huf startet eine Quest. Lass ihn unter Stufe 21 in Ruhe.",
		["The Grimtotem camp is just north of {npc:11857}, a short walk off the road: Ruffians and Mercenaries stand among the tents."] = "Das Lager der Grimmtotem liegt direkt nördlich von {npc:11857}, ein kurzer Fußweg von der Straße: Raufbolde und Söldner stehen zwischen den Zelten.",
		["The Razormane camp lies east of the Crossroads. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}.\nCareful: The chest stands next to a broken wagon, guarded by a pair of Razormanes, including hunters that can pull more quilboar into the fight."] = "Das Lager der Klingenmähnen liegt östlich des Wegekreuzes. Krieger: Die {object:58369} steht im Lager. Schamanen: Die Stacheleber lassen den {item:5026} fallen.\nVorsicht: Die Truhe steht neben einem kaputten Wagen und wird von zwei Klingenmähnen bewacht, darunter Jäger, die weitere Stacheleber in den Kampf ziehen können.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Die Vorarbeiter und Vollstrecker der Venture Co. an der Mine in der Nordostecke des Gebiets lassen {item:5097} fallen.",
		["The antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the Silithid Mounds in the {area:390}, south of {area:378}, until you have five, then take them straight to {npc:6394} in {area:378}, before the thunderhawks. Careful: Silithid Swarmers (level 21-22) cast {npc:4196} both in and out of combat, which brings several small adds; Silithid Creepers (level 20-21) periodically cast {npc:5781} in combat, which spawns extra adds. A {npc:3253} (24, rare) also wanders the mounds: leave it."] = "Die Fühler verschwinden fünfzehn Minuten, nachdem sie fallen: Töte Silithidschwärmer und Silithidkrabbler an den Silithid-Buckeln auf {area:390}, südlich von {area:378}, bis du fünf hast, und bring sie dann direkt zu {npc:6394} in {area:378}, noch vor den Donnerfalken. Vorsicht: Silithidschwärmer (Stufe 21-22) wirken {npc:4196} im und außerhalb des Kampfes, was mehrere kleine Adds herbeiholt; Silithidkrabbler (Stufe 20-21) wirken im Kampf regelmäßig {npc:5781}, was zusätzliche Adds hervorbringt. Ein {npc:3253} (24, Rare) wandert ebenfalls über die Buckel: Lass ihn in Ruhe.",
		["The next guide goes north-east across the {zone:1413} to the {area:1703} and {zone:1440}."] = "Der nächste Guide führt nach Nordosten über {zone:1413} zum {area:1703} und nach {zone:1440}.",
		["The pirates camp on the beach south of {area:392}: the piles of complicated parts lie in the sand among them. {npc:3467} (16) stands at the camp's southern end: leave him for the next {area:392} stop."] = "Die Piraten lagern am Strand südlich von {area:392}: Die Haufen komplizierter Teile liegen im Sand zwischen ihnen. {npc:3467} (16) steht am südlichen Ende des Lagers: Lass ihn für den nächsten Halt in {area:392}.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "Die Tümpel liegen direkt nördlich von {npc:3389}. Geh ins Wasser, um sie zu erkunden; die Beladenen Pilze für Helbrim wachsen um sie herum. Töte jeden Kolkar, an dem du vorbeikommst, für Armschienen. {npc:3394} steht im Lager der Kolkar westlich der Tümpel.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "Die Straße steigt als {area:1076} nach Norden an. {quest:1483} hat eine Hütte, wo die Straße nach Osten zum {area:461} abzweigt.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}."] = "Die Werkzeugeimer mit den Schnecken liegen um die Bohrstelle der Venture Co. im {area:382}.",
		["The {area:2363}"] = "Die {area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} ist die Schlucht unter dem {object:172982}.",
		["The {object:177794} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177794} liegt am Nordrand von {area:382}, beim Turm der Venture Co. Darin ist {item:15883} für {quest:30}.",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close."] = "Die {object:4141} steht an der Forschungsstätte der Venture Co. westlich der {area:382}. Schließe die drei Ventile um den Bohrer, benutze die Konsole noch einmal und nimm dann den {item:5089} von {npc:3471} daneben.\nVorsicht: Mehrere Wachen stehen in Aggro-Reichweite der Ventile, respawnen in unter etwa 3 Minuten und rennen bei niedriger Gesundheit los, um Hilfe zu holen; auch Mobs in der Nähe greifen ein, wenn du ein Ventil benutzt, während sie nah sind.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:209797} (level 20 elite) needs a group of 2. Skip it if you are alone."] = "Dies sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Leute dafür. {npc:209797} (Elite der Stufe 20) braucht eine Gruppe von 2. Überspringe ihn, wenn du allein bist.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:267307} (level 20 elite) needs a group of 3 and sits deep in the cave under {area:1699}, past the Razormane Flesheaters and Berserkers (18-19, elite). Skip it if you are alone."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Leute dafür. {npc:267307} (Elite der Stufe 20) braucht eine Gruppe aus 3 und sitzt tief in der Höhle unter {area:1699}, hinter den Razormane Flesheaters und Berserkers (18-19, Elite). Überspring ihn, wenn du allein bist.",
		["Thunderhawk Cloudscrapers circle over the plains south of the camp."] = "Donnerfalkenwolkenkitzler kreisen über den Ebenen südlich des Lagers.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard (level 24), roams among them: his Tailspike starts a quest. Leave him alone below level 23."] = "Donnerköpfe grasen auf den Ebenen gleich südlich von {area:378}. {quest:884}, eine blaue Donnerechse (Stufe 24), streift zwischen ihnen umher: Ihr Schwanzstachel startet eine Quest. Lass sie unter Stufe 23 in Ruhe.",
		["To {area:2539}"] = "Nach {area:2539}",
		["To {npc:3389}"] = "Zu {npc:3389}",
		["Train your level 20 ranks in {area:1637} now: fly from {npc:3615} on the Crossroads' tower."] = "Lerne jetzt deine Ränge für Stufe 20 in {area:1637}: Flieg von {npc:3615} auf dem Turm des Wegekreuzes ab.",
		["Train your level 20 ranks: {npc:246344} teaches Paladins in {area:1638}; {zone:1454} has no Paladin trainer. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "Lerne deine Ränge für Stufe 20: {npc:246344} lehrt Paladine in {area:1638}; {zone:1454} hat keinen Paladinlehrer. Du hast dort noch keinen Flugpunkt: Flieg nach {area:378}, geh nach Westen durch {zone:1412} und einen Aufzug hinauf und nimm den Flugpunkt bei {npc:2995} auf der mittleren Anhöhe.",
		["Twitching Antennae"] = "Zuckende Fühler",
		["Twitching Antennae from the silithid"] = "Zuckende Fühler von den Silithiden",
		["Underwater"] = "Unter Wasser",
		["Upstairs"] = "Oben",
		["Venture Co. Loggers, all over the clear-cut"] = "Holzfäller der Venture Co., überall im Kahlschlag",
		["Warriors: take {quest:1824} from {npc:6394} now: it runs for 30 minutes from the accept. The antennae come first, at the Silithid Mounds south of the camp, then straight back to {npc:6394}; the thunderhawks after."] = "Krieger: Nimm {quest:1824} jetzt bei {npc:6394} an: Sie läuft 30 Minuten ab dem Annehmen. Zuerst die Fühler, an den Silithid-Buckeln südlich des Lagers, dann direkt zurück zu {npc:6394}; die Donnerfalken danach.",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "Vom niedergebrannten Dorf nach Westen nach {area:2539}: {npc:12816} steht gleich davor, noch vor dem Dorf.",
		["West from the mine to {npc:9316}'s camp, then south down the road to the Crossroads."] = "Von der Mine nach Westen zum Lager von {npc:9316}, dann die Straße nach Süden zum Wegekreuz.",
		["West to the {area:383}. Any Witchwing harpy drops a talon: keep to the eastern slopes, where the Witchwing Harpies and Roguefeathers (14-15) nest; the Slayers and Windcallers (16-17) hold the western hills. Savannah Prowlers hunt the plains between {npc:3389} and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat."] = "Nach Westen zu den {area:383}. Jede Harpyie der Hexenschwingen kann eine Klaue fallen lassen: Bleib an den Osthängen, wo die Harpyien und Schurkenfedern der Hexenschwingen (14-15) nisten; die Schlächterinnen und Windruferinnen (16-17) halten die westlichen Hügel. Savannenstreuner jagen in den Ebenen zwischen {npc:3389} und den Hügeln: Nimm ihre Klauen auf dem Weg mit.\nVorsicht: Es gibt 2 Wegelagerinnen der Hexenschwingen (Stufe 17-18). Sie bleiben außerhalb des Kampfes mit Schleichen verborgen.",
		["West to {npc:3389}'s watch post on the Kolkar border."] = "Nach Westen zum Wachposten von {npc:3389} an der Grenze zu den Kolkar.",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Wenn du schon im Lager bist: die Wassersucher und Dornenwirker für {npc:3429} in der westlichen Hälfte, die Jäger in der Mitte, die Vorratskisten am östlichen Ende.\nVorsicht: Fleischfresser und Berserker der Grimmhauer (18-19) sind Elites; sie stehen im Nordosten des Lagers neben den Vorratskisten: Zieh die Stacheleber einzeln von ihnen weg.",
		["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}.\nCareful: The route leads west and climbs a ramp. Once you reach the top, two Venture Company mobs ambush you."] = "Wizzlecrank fährt seinen Schredder aus dem Lager: Bleib bei ihm und töte alles, was ihn angreift. {npc:3442} nimmt ihn in {area:392} an.\nVorsicht: Die Route führt nach Westen und eine Rampe hinauf. Sobald du oben bist, überfallen dich zwei Mobs der Venture Company.",
		["You arrive from {area:379}. {npc:3489} and {npc:3338} stand by the inn, Helbrim and {npc:3464} by the north gate; {npc:3615}, {npc:3429} and {npc:3449} on the tower platform."] = "Du kommst von {area:379}. {npc:3489} und {npc:3338} stehen beim Gasthaus, Helbrim und {npc:3464} am Nordtor; {npc:3615}, {npc:3429} und {npc:3449} auf der Turmplattform.",
		["Zhevra Runners graze along the road east toward {area:392}: take their hooves on the way out."] = "Zhevra-Läufer grasen entlang der Straße nach Osten Richtung {area:392}: Nimm ihre Hufe auf dem Weg hinaus mit.",
		["grind on {npc:3263}"] = "Grinde an {npc:3263}",
		["the Crossroads"] = "das Wegekreuz",
		["{area:1076}: kill these as you meet them"] = "{area:1076}: Töte diese, wenn sie dir begegnen",
		["{area:1697}: kill these as you meet them"] = "{area:1697}: Töte diese, wenn sie dir begegnen",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn: {npc:3338} by the inn, Helbrim and {npc:3464} by the north gate, then up the tower to {npc:3615}, the wind rider master, {npc:3429} and {npc:3449}, and {npc:3448} at the south gate on the way out."] = "{area:380} ist deine Basis für diesen Guide. Alle, die du brauchst, stehen nur wenige Schritte vom Gasthaus entfernt: {npc:3338} beim Gasthaus, Helbrim und {npc:3464} am Nordtor, dann den Turm hinauf zu {npc:3615}, dem Windreitermeister, {npc:3429} und {npc:3449}, und {npc:3448} am Südtor auf dem Weg hinaus.",
		["{area:385}: kill these as you meet them"] = "{area:385}: Töte diese, wenn sie dir begegnen",
		["{area:392} flight master"] = "Flugmeister in {area:392}",
		["{area:392}: {area:718} quests"] = "{area:392}: Quests für {area:718}",
		["{area:718} is a dungeon for a group of five, about levels 17 to 24, and a full run takes about an hour. Its mouth is just north of {npc:3396}'s shore, at the north end of {area:387}, under {npc:5767}'s cave.\nIn the caves before the portal: {npc:3655}, stealthed, with the {item:5334} (he moves between a few spots and comes back slowly: leave him if he's gone). Inside: the Deviates for {npc:5768}, and their hides for {npc:5767} (they drop rarely: one run may not be enough, so leave the rest for another run), {item:6464} from the Ectoplasms. After the four Fanglords, the {npc:3678} at the entrance leads you to Naralex: {npc:3654} drops the {item:10441}: its quest (someone in {area:392}, then {npc:8418} above the caverns) is not on this route; the Dungeons page's hand-in guide takes it."] = "{area:718} ist ein Dungeon für eine Gruppe aus fünf Spielern, etwa Stufe 17 bis 24; ein kompletter Run dauert etwa eine Stunde. Der Eingang liegt gleich nördlich des Ufers von {npc:3396}, am Nordende von {area:387}, unter der Höhle von {npc:5767}.\nIn den Höhlen vor dem Portal: {npc:3655}, getarnt, mit {item:5334} (er wechselt zwischen ein paar Stellen und kommt nur langsam zurück: Lass ihn aus, wenn er weg ist). Drinnen: die Deviates für {npc:5768} und ihre Häute für {npc:5767} (sie droppen selten: Ein Run reicht vielleicht nicht, also heb dir den Rest für einen weiteren Run auf), {item:6464} von den Ectoplasms. Nach den vier Fanglords führt dich {npc:3678} am Eingang zu Naralex: {npc:3654} lässt {item:10441} fallen: Die Quest dazu (jemand in {area:392}, dann {npc:8418} über den Höhlen) ist nicht Teil dieser Route; der Abgabe-Guide der Seite „Dungeons“ übernimmt sie.",
		["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338}, von jedem Zhevra; Zhevra-Stürmer grasen rund um den Baum",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, aus einem {object:177785} im See",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} von {npc:3490}; Kräuterkundige pflücken es auf den Ebenen",
		["{item:6464}: the Ectoplasms"] = "{item:6464}: die Ectoplasms",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, am Schrein: {area:2362}",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} steht oben in seinem Gebäude in {area:2361}: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}. {quest:28} runs on a timer: no teleport or Hearthstone until {npc:11799} has it."] = "{npc:11802} steht oben in seinem Gebäude in {area:2361}: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden. Die Schreinkugeln liegen auf dem Grund von {area:656} und vergehen nach wenigen Minuten: Schwimm mit einer direkt zum {area:2362} am Nordwestufer, benutze sie dort und sprich mit {npc:11799}. {quest:28} läuft auf Zeit: Kein Teleport und kein Ruhestein, bis {npc:11799} sie hat.",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: der Willkommensgruß von {npc:3033}",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, in der Hütte von {npc:11858}",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}: Behalte sie, {npc:11864} am {area:460} im Guide für {zone:1413} & Steinkrallengebirge",
		["{npc:11858} waits up the {area:1076}"] = "{npc:11858} wartet den {area:1076} hinauf",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the Crossroads"] = "{npc:12296}: Benutze das {item:15826} an ihnen; sie streifen überall um das Wegekreuz durch die Ebenen",
		["{npc:12816}: the spiders along the {area:1076}"] = "{npc:12816}: die Spinnen entlang des {area:1076}",
		["{npc:16227}, beside {npc:3442}"] = "{npc:16227}, neben {npc:3442}",
		["{npc:261366}, the hermit on the ridge behind {npc:3682}: on the next {area:383} visit, with {npc:3452}"] = "{npc:261366}, der Einsiedler auf dem Grat hinter {npc:3682}: bei deinem nächsten Besuch von {area:383}, mit {npc:3452}",
		["{npc:261366}, the hermit, stands on the ridge behind {npc:3682}'s camp."] = "{npc:261366}, der Einsiedler, steht auf dem Grat hinter dem Lager von {npc:3682}.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "{npc:262119} und seine Marinesoldaten halten die zerstörte Karawane südlich von {npc:261366}. Die Marinesoldaten sind verbunden: Pullst du einen, rufst du den Rest. Zieh vom Rand und lauf; sie lassen schnell ab, sodass du das Lager einzeln ausdünnen kannst, bevor du den Korporal angehst.",
		["{npc:267310} stands on the north-east side of the Crossroads. {quest:97003} is a group quest: {npc:267307} is a level 20 elite boar in the Razormane's {area:1699} cave, east of the town, where the route goes back for {npc:3438} later."] = "{npc:267310} steht auf der Nordostseite des Wegekreuzes. {quest:97003} ist eine Gruppenquest: {npc:267307} ist ein Elite-Eber der Stufe 20 in der Höhle der Klingenmähnen in {area:1699}, östlich der Stadt, wohin die Route später für {npc:3438} zurückkehrt.",
		["{npc:3338} by the inn first, then Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "Zuerst {npc:3338} beim Gasthaus, dann Helbrim beim Nordtor, {npc:3429} und {npc:3449} auf der Turmplattform, {npc:3432} beim Gasthaus und zuletzt {npc:3448} am Südtor. Sein Samentest wartet auf den Abstecher zu {npc:3395} bei {area:388}: Geh direkt weiter nach Nordwesten zu {area:383}. Nach den Sporen bietet Helbrim {quest:853} an, eine Lieferung nach {zone:1456} innerhalb von 45 Minuten: Diese Route geht nicht dorthin, also lass sie liegen (Druiden nehmen sie beim nächsten Halt in Crossroads an, direkt vor ihrem Flug nach {zone:1456}).",
		["{npc:3338}: the raptor nests south of the Crossroads"] = "{npc:3338}: die Raptornester südlich des Wegekreuzes",
		["{npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "{npc:3354} ist im {object:172958}, {npc:5892} im {object:172957}.",
		["{npc:3389}: {npc:3395} comes out when you kill the Kolkar at the {area:388}, later"] = "{npc:3389}: {npc:3395} erscheint später, wenn du die Kolkar an der {area:388} tötest",
		["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390}: 45 Minuten, für Zamah im nächsten Schritt in {zone:1456}",
		["{npc:3390}: {quest:1358}, from Zinge"] = "{npc:3390}: {quest:1358}, von Zinge",
		["{npc:3391} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:3391} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:3391}, upstairs"] = "{npc:3391}, oben",
		["{npc:3391}: the crates lie at the south end of the beach camp, on the next {area:392} stop at 18"] = "{npc:3391}: Die Kisten liegen am Südende des Strandlagers, beim nächsten Halt in {area:392} mit 18",
		["{npc:3395} doesn't wander on his own: he comes out when you kill the Kolkar centaurs at the {area:388}, south-east of the Crossroads. Keep killing them around the oasis until he appears. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395} wandert nicht von selbst umher: Er erscheint, wenn du die Kolkar-Zentauren an der {area:388} südöstlich vom Wegekreuz tötest. Töte sie weiter rund um die Oase, bis er auftaucht. Teste die Samen von {npc:3448} an der blubbernden Spalte am Ostufer der Oase, wenn du schon dort bist.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396} führt die Kolkar am Westufer von {area:387} an, südlich von {npc:3389}. Er läuft dieses Ufer ab, von etwa 46,36 im Norden bis 46,42 im Süden: Ist er nicht am Pfeil, folge dem Ufer, bis du ihn triffst. Gib seinen Kopf bei deinem letzten Halt in Crossroads bei {npc:3389} ab. Oasenschnappkiefer kriechen dort im Wasser der Oase: Ihre Panzer sind für {npc:3448}.",
		["{npc:3428}'s {quest:868} waits for this guide's last Crossroads stop: its eggs come on the next {zone:1413} guide's walk south, at about 25."] = "{quest:868} von {npc:3428} wartet auf den letzten Halt dieses Guides am Wegekreuz: Die Eier kommen auf dem Weg nach Süden im nächsten Guide für {zone:1413}, mit etwa 25.",
		["{npc:3428}, west of the north gate: keep {quest:868}, its eggs lie on the next {zone:1413} guide's walk south from {area:378}, at about 25"] = "{npc:3428}, westlich des Nordtors: Behalte {quest:868}, die Eier liegen auf dem Weg des nächsten Guides für {zone:1413} südlich von {area:378}, bei etwa 25",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, oben auf dem Turm",
		["{npc:3429}, on the tower, from level 17. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}, auf dem Turm, ab Stufe 17. Behalte es: Kadrak am {area:1703}, im nächsten Guide",
		["{npc:3430}, in the cage"] = "{npc:3430}, im Käfig",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} bietet {quest:95774} an, sobald {quest:4921} abgegeben ist",
		["{npc:3432}: his wife lies at the north edge of the Bristleback camps, later"] = "{npc:3432}: Seine Frau liegt später am Nordrand der Lager der Borstennacken",
		["{npc:3439} stands inside the Venture Co. camp in the {area:382}; {npc:3445} carries the key."] = "{npc:3439} steht im Lager der Venture Co. im {area:382}; {npc:3445} trägt den Schlüssel.",
		["{npc:3442} in {area:392}: on the next {area:392} stop"] = "{npc:3442} in {area:392}: beim nächsten Halt in {area:392}",
		["{npc:3442}: keep it, {quest:1483} is on the {area:1076} in Stonetalon, at the end of this guide"] = "{npc:3442}: Behalte sie, {quest:1483} liegt am {area:1076} im Steinkrallengebirge, am Ende dieses Guides",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: Die Konsole ist in {area:382}, später",
		["{npc:3442}: {npc:9316} stands on the road north of the Crossroads, on the way to the {area:382}"] = "{npc:3442}: {npc:9316} steht an der Straße nördlich des Wegekreuzes, auf dem Weg zum {area:382}",
		["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448}: die Oasenschnappkiefer bei {area:387}, mit {npc:3396} nach dem Ausflug nach {zone:1454}",
		["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448}: die blubbernde Spalte bei {area:388}, beim Abstecher zu {npc:3395}",
		["{npc:3449}, on the tower: {quest:876} leads the harpies in the {area:383}"] = "{npc:3449}, auf dem Turm: {quest:876} führt die Harpyien in den {area:383} an",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: Die Harpyien kommen später, in {area:383}",
		["{npc:3464}, by the Crossroads' north gate"] = "{npc:3464}, am Nordtor des Wegekreuzes",
		["{npc:3464}: the {quest:3281}, in a raptor nest north-west of {area:385}"] = "{npc:3464}: das {quest:3281}, in einem Raptornest nordwestlich von {area:385}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} ist in der Feste angekettet. Sprich mit ihm, um die Eskorte zu starten, und bleib dicht dran: Soldaten von Theramore greifen auf dem Weg hinaus an. Er führt dich zurück nach {area:392}.",
		["{npc:3615}, on the tower"] = "{npc:3615}, auf dem Turm",
		["{npc:4049} and {npc:11857} share the camp on the road west to Stonetalon."] = "{npc:4049} und {npc:11857} teilen sich das Lager an der Straße nach Westen ins Steinkrallengebirge.",
		["{npc:4049}'s camp"] = "Das Lager von {npc:4049}",
		["{npc:4049}: the Venture loggers at {area:461}"] = "{npc:4049}: die Holzfäller der Venture Co. bei {area:461}",
		["{npc:4049}: {quest:1063}, Magatha in {zone:1456}, on the next guide's way back from Zoram'gar"] = "{npc:4049}: {quest:1063}, Magatha in {zone:1456}, auf dem Rückweg des nächsten Guides von Zoram'gar",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} lebt in {area:2539}, dem Trolldorf gleich hinter der Grenze zum Steinkrallengebirge, am Ende der Straße westlich von {npc:3389}.",
		["{npc:4201}, inside"] = "{npc:4201}, drinnen",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}: für {npc:3442}, neben dem Flugmeister von {area:392}, am Ende des Guides für {zone:1413} & Steinkrallengebirge",
		["{npc:4276}'s defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\n{npc:4276} mines at the bottom of the {area:2160} on the east side of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails."] = "Die Verteidigung von {npc:4276} ist auf dieser Stufe allein schwer: Eine Gruppe wird empfohlen, such dir Leute dafür. Überspringe es, wenn du allein bist.\n{npc:4276} baut am Grund der {area:2160} auf der Ostseite der Schlucht ab, hinter ihren Kobolden (Stufe 19-23). Sprich mit ihm und halte ihn dann fünf Minuten am Leben, während er abbaut: Ein Dutzend oder mehr Kobolde greifen ihn in Wellen an, erst Nahkämpfer, dann Zauberer, und die Kobolde der Mine respawnen mitten im Kampf. Wenn er stirbt, schlägt die Quest fehl.",
		["{npc:4276}, below ground"] = "{npc:4276}, unter Tage",
		["{npc:5767} and {npc:5768}"] = "{npc:5767} und {npc:5768}",
		["{npc:5878} camps beside the road east of the Crossroads."] = "{npc:5878} lagert neben der Straße östlich des Wegekreuzes.",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} lagert an der Straße nach Osten Richtung {area:392}.",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}: fill the {item:7766} at the watering hole below it."] = "Die Hütte von {npc:5899} steht auf dem Kamm über der Tränke der Stacheleber, südlich von {area:378}: Fülle den {item:7766} an der Tränke darunter.",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} wartet auf dem Hügel südlich von {area:392}, auf deinem Weg nach Norden.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}, ein paar Schritte entfernt",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} steht im {object:172961} auf der Westseite der Stadt.",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} steht im {object:172961}, auf der Westseite der Stadt.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: {npc:4606} in {zone:1458}, zwei Guides weiter",
		["{npc:6394}, inside"] = "{npc:6394}, drinnen",
		["{quest:1483}, inside"] = "{quest:1483}, drinnen",
		["{quest:1492}, on the dock"] = "{quest:1492}, am Kai",
		["{quest:1492}: the emerald comes from the {area:381}, later"] = "{quest:1492}: Der Smaragd kommt später aus der {area:381}",
		["{quest:2458}: {npc:7233}, by the {area:382} on the next guide's walk north"] = "{quest:2458}: {npc:7233}, beim {area:382} auf dem Weg nach Norden im nächsten Guide",
		["{quest:30}, carried: one half pendant in the {area:382} in this guide, the other underwater off Silverpine on the way to {area:287} at 21; the pendant is handed in after {area:287}"] = "{quest:30}, mitgeführt: eine Anhängerhälfte im {area:382} in diesem Guide, die andere unter Wasser vor Silberwald auf dem Weg nach {area:287} bei 21; der Anhänger wird nach {area:287} abgegeben",
		["{quest:3923} stands by the {object:172958}'s water, east of the Drag."] = "{quest:3923} steht am Wasser des {object:172958}, östlich der Drag.",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, nächster Guide",
		["{quest:809}, beside {npc:3337}: from {npc:3216} in {zone:1454}"] = "{quest:809}, neben {npc:3337}: von {npc:3216} in {zone:1454}",
		["{quest:853}, in the {area:2197}"] = "{quest:853}, in {area:2197}",
		["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions below {npc:3682}'s camp"] = "{quest:865}, falls die Quest noch offen ist: Bluthornsensenklauen streunen zwischen den Löwen unterhalb des Lagers von {npc:3682}",
		["{quest:882}, a big Sunscale raptor, only comes to a fresh kill: loot a {item:10338} from a zhevra, then use it at the {object:147538} north-west of {area:392}, north of the road to the Crossroads, and be ready when he arrives."] = "{quest:882}, ein großer Sunscaleraptor, kommt nur zu einem frischen Kadaver: Plündere ein {item:10338} von einem Zhevra, benutze es dann am {object:147538} nordwestlich von {area:392}, nördlich der Straße zum Wegekreuz, und sei bereit, wenn er ankommt.",
		["{zone:1413}: kill these as you meet them"] = "{zone:1413}: Töte diese, wenn sie dir begegnen",
		["{zone:1454} class quests"] = "Klassenquests in {zone:1454}",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1454}'s level 20 class quests come right after the Crossroads, and they are offered only from 20. Still short of 20? The Bristleback Geomancers (19-20) hold {area:1700} around you: kill them until level 20. Or, with a group, run the {area:718} dungeon instead."] = "Die Klassenquests für Stufe 20 in {zone:1454} kommen direkt nach dem Wegekreuz und werden erst ab 20 angeboten. Noch nicht Stufe 20? Die Geomanten der Borstennacken (19-20) halten {area:1700} um dich herum: Töte sie bis Stufe 20. Oder lauf stattdessen mit einer Gruppe den Dungeon {area:718}.",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Allister's Ambermill Investigations is for the ride through Silverpine at 22; leave it."] = "Allisters Ermittlungen in Ambermühle sind für den Ritt durch Silberwald bei 22; lass sie liegen.",
		["Back down the road past the zeppelin towers and east to {npc:1495}'s camp: {npc:267009} stands beside her."] = "Zurück die Straße hinunter an den Zeppelintürmen vorbei und nach Osten zum Lager von {npc:1495}: {npc:267009} steht neben ihr.",
		["Back out through the portal: {npc:3216} stands beside it."] = "Durch das Portal zurück nach draußen: {npc:3216} steht daneben.",
		["Class trainer"] = "Klassenlehrer",
		["Follow the lake shore south from the murlocs: the {object:1593} lies at the ferry landing."] = "Folge dem Seeufer von den Murlocs nach Süden: Das {object:1593} liegt am Fähranleger.",
		["Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Folge dem Seeufer nach Südosten vom Haus der Yoricks: Die Schlitzer und Gezeitenjäger der Vile Fin am Ufer lassen die Murlocaugen fallen.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Folge der Straße nach Nordosten zum Haus der Yoricks bei {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood. Careful: Dalaran Apprentices (13) stand around the crate: pull them one at a time before you open it."] = "Folge der Straße nach Süden. Die {object:1627} steht daneben, nördlich von Pyrewood. Vorsicht: Lehrlinge von Dalaran (13) stehen um die Kiste herum: Zieh sie einzeln, bevor du sie öffnest.",
		["For your {area:2437} run: the {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end, next to the {area:2437} portal."] = "Für deinen Run durch {area:2437}: {object:172960} ist die Schlucht unter dem {object:172982}; {npc:3216} steht an ihrem hinteren Ende, neben dem Portal von {area:2437}.",
		["From the ferry back west up the road to the {area:228}."] = "Von der Fähre zurück nach Westen die Straße hinauf zu {area:228}.",
		["Inside"] = "Drinnen",
		["Mottled Worgs"] = "Scheckige Worgs",
		["Mottled Worgs prowl the hills around the house."] = "Scheckige Worgs streifen durch die Hügel um das Haus.",
		["North again to the Yoricks' house."] = "Wieder nach Norden zum Haus der Yoricks.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field. Careful: {npc:1983} (14) rises once you have killed rot hide gnolls in the field: fight her with full health."] = "Nördlich von {area:228}. {npc:1983} spukt auf dem {area:240}: Töte sie und geh dann über das Feld. Vorsicht: {npc:1983} (14) erscheint, sobald du Gnolle der Moderfelle auf dem Feld getötet hast: Kämpfe mit voller Gesundheit gegen sie.",
		["On the road north, the farmhouse at {area:227}: go upstairs, the {object:1571} lie on the floor in the back room. Looting them brings a {npc:1770}."] = "Auf der Straße nach Norden das Bauernhaus bei {area:227}: Geh nach oben, die {object:1571} liegen im hinteren Zimmer auf dem Boden. Sie zu plündern bringt einen {npc:1770}.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Sprich mit {npc:10181} im {object:36126}: {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "Sprich mit {npc:10540} in Grommash Hold",
		["Speak with {npc:3230}, in Grommash Hold"] = "Sprich mit {npc:3230} in Grommash Hold",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Nimm die Straße nach Norden Richtung {zone:1420}: Das Haus der Yoricks bei {area:238} liegt auf dem Weg. {quest:425} lauert ein kurzes Stück westlich davon.",
		["Talk to {npc:10181}"] = "Sprich mit {npc:10181}",
		["Talk to {npc:10540}"] = "Sprich mit {npc:10540}",
		["Talk to {npc:3230}"] = "Sprich mit {npc:3230}",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Rohrkolben und Speergras wachsen am Wasser im {object:172958}, östlich der Gasse.",
		["The cultists camp a short walk south-east of {npc:267009}. Dark Neophytes and Dark Enforcers drop the Necrotic Crystal Fragments; more fragments, black crystals, lie on the ground among the tents."] = "Die Kultisten lagern einen kurzen Fußweg südöstlich von {npc:267009}. Dunkle Neophyten und Dunkle Vollstrecker lassen die Nekrotischen Kristallfragmente fallen; weitere Fragmente, schwarze Kristalle, liegen zwischen den Zelten auf dem Boden.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960} ist die Schlucht unter dem {object:172982}; {quest:829} steht an ihrem hinteren Ende.",
		["Train while you are in the city: Druids and Paladins have no trainer here. Troll Priests: train with {npc:6018} in the {object:172961}, who takes {quest:5654}."] = "Lerne, solange du in der Stadt bist: Druiden und Paladine haben hier keinen Lehrer. Trollpriester: Lerne bei {npc:6018} im {object:172961}, der {quest:5654} annimmt.",
		["Vile Fin murlocs"] = "Murlocs der Finsterflossen",
		["Walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}; {npc:6929} keeps the inn below it, {npc:268701} stands by the bank. Bind here: the Hearthstone brings you back from {zone:1421} beside the zeppelin towers and the road to the {zone:1413}."] = "Geh durch das Haupttor hinein. {npc:3310}, der Windreitermeister, steht auf dem Turm im {object:172982}; {npc:6929} führt das Gasthaus darunter, {npc:268701} steht bei der Bank. Binde deinen Ruhestein hier: Er bringt dich aus {zone:1421} zurück neben die Zeppelintürme und die Straße ins {zone:1413}.",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "Geh durch das Haupttor hinein. {npc:268701} steht im {object:172982}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:2704} ({object:172958}, 10 Silber); die Nahkampfwaffe eines Jägers besteht hauptsächlich aus ihren Werten, und Zweihandwaffen haben die meisten.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:2704} ({object:172958}, 10 Silber); ein Stab hat beim Leveln mehr Zauberwerte als eine Einhandwaffe.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Paladin fastest."] = "Wenn du schon hier bist: Lerne {spell:197} bei {npc:11868} ({object:172958}, 10 Silber); Zweihandwaffen lassen einen Paladin am schnellsten leveln.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Warrior fastest."] = "Wenn du schon hier bist: Lerne {spell:197} bei {npc:11868} ({object:172958}, 10 Silber); Zweihandwaffen lassen einen Krieger am schnellsten leveln.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["{area:159} is a short walk north up the road from the zeppelin towers: {npc:1738} stands by the road into town, {npc:1518} in the apothecary's house on the west side of the square; Paladins: {npc:246152} trains you in town."] = "{area:159} liegt einen kurzen Fußweg nördlich die Straße hinauf von den Zeppelintürmen: {npc:1738} steht an der Straße in die Stadt, {npc:1518} im Haus des Apothekers an der Westseite des Platzes; Paladine: {npc:246152} bildet dich in der Stadt aus.",
		["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159} liegt einen kurzen Fußweg nördlich die Straße hinauf von den Zeppelintürmen; {npc:1499} ist im Rathaus.",
		["{area:227} farmhouse"] = "Bauernhaus von {area:227}",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} ist die Gruftstadt der Verlassenen mitten im Wald. Alle, die du brauchst, stehen um den Grufteingang; {npc:2226}, der Fledermausführer, steht gleich östlich davon.",
		["{npc:10181} holds court in the {object:36126}."] = "{npc:10181} hält Hof im {object:36126}.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, im Apothekarium",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, der Alchemielehrer, steht gleich neben {npc:3348}.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, der Verzauberkunstlehrer, arbeitet in der Gasse.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:1499} in {area:159}, on the way to the zeppelin at the end"] = "{npc:1499} in {area:159}, auf dem Weg zum Zeppelin am Ende",
		["{npc:1518}, inside"] = "{npc:1518}, drinnen",
		["{npc:1937}: Zinge in the {zone:1458}, on the way to the zeppelin at the end"] = "{npc:1937}: Zinge in der {zone:1458}, auf dem Weg zum Zeppelin am Ende",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: für Quinn, am Ende auf der Straße nach Norden",
		["{npc:1938}, just north of Allister"] = "{npc:1938}, direkt nördlich von Allister",
		["{npc:1938}: his books lie in the {area:227} farmhouse, on the walk north"] = "{npc:1938}: Seine Bücher liegen im Bauernhaus von {area:227}, auf dem Weg nach Norden",
		["{npc:1951}, inside"] = "{npc:1951}, drinnen",
		["{npc:1952}, below ground"] = "{npc:1952}, unter Tage",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} wartet nordöstlich des Hauses. Eskortiere ihn zurück zu {npc:1950}; unterwegs greifen Worgs an.",
		["{npc:1978}, inside"] = "{npc:1978}, drinnen",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}: {npc:4556} in {zone:1458}, am Ende dieses Guides; den Flug musst du nicht kaufen",
		["{npc:246152}, in {area:159}"] = "{npc:246152}, in {area:159}",
		["{npc:260093}, the {area:1497}'s paladin trainer"] = "{npc:260093}, der Paladinlehrer der {area:1497}",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them."] = "{npc:268684} und {npc:268682} sitzen hinter der Burg Grommash im {object:172957}; die Glatten Felsbrocken liegen um sie herum.",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, der Schneiderlehrer, ist im {object:172958}.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:3230}, in Grommash Hold"] = "{npc:3230}, in der Burg Grommash",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} und {npc:3347} führen den Alchemieladen in der Gasse; {npc:11046} ist nebenan.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, der Lederverarbeitungslehrer, arbeitet im {object:172958}.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, die Kräuterkundelehrerin, hat ihren Laden in der Gasse.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:4047}: {npc:4049}, on the road into Stonetalon in the next guide"] = "{npc:4047}: {npc:4049}, an der Straße ins Steinkrallengebirge im nächsten Guide",
		["{npc:4551}, the bat handler"] = "{npc:4551}, der Fledermausführer",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}: Behalte {item:16210}, Podrig nimmt sie beim nächsten Halt in {area:228} mit 22 entgegen",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, der Waffenhändler neben dem Fledermausführer",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, der Ingenieurskunstlehrer, arbeitet in {zone:1458}.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}: Camping 101, von {npc:265812}s Lagerfeuer in Tirisfal",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, der Bergbaulehrer, arbeitet in {zone:1458}.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}: Camping 101, von {npc:265812}s Lagerfeuer in Tirisfal",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, der Schmiedekunstlehrer, arbeitet in {zone:1458}.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}: Camping 101, von {npc:265812}s Lagerfeuer in Tirisfal",
		["{npc:4949} stands in Grommash Hold. He offers {quest:98024} and {quest:93739} once {quest:95350} is handed in."] = "{npc:4949} steht in der Burg Grommash. Er bietet {quest:98024} und {quest:93739} an, sobald {quest:95350} abgegeben ist.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, in Grommash Hold",
		["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949}: Behalte sie, Thork am Wegekreuz im Guide {zone:1413}",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, eine Tour zu den Anführern der Horde",
		["{npc:5204}, in the Apothecarium"] = "{npc:5204}, im Apothekarium",
		["{npc:5204}: Helbrim at the Crossroads, in the next guide"] = "{npc:5204}: Helbrim am Wegekreuz, im nächsten Guide",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, der Kürschnerlehrer, steht im {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{object:1571}; upstairs"] = "{object:1571}; oben",
		["{object:1661} lies under the {area:153}, beside the zeppelin towers. {npc:2050} stands at the inn by the way down; {npc:7683} on the way down to the Apothecarium, where {npc:11044} and {npc:5204} stand beside {npc:2055}."] = "{object:1661} liegt unter den {area:153}, neben den Zeppelintürmen. {npc:2050} steht im Gasthaus am Weg nach unten; {npc:7683} auf dem Weg hinunter zum Apothekarium, wo {npc:11044} und {npc:5204} neben {npc:2055} stehen.",
		["{object:173016} is a few steps north."] = "{object:173016} ist ein paar Schritte nördlich.",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} wird an {object:24776} abgegeben, einem Grab ein paar Schritte südlich des Grufteingangs, nicht bei einer Person.",
		["{quest:829}: {quest:809} stands at {area:379}, on the next guide's road to the Crossroads"] = "{quest:829}: {quest:809} steht bei {area:379}, an der Straße zum Wegekreuz im nächsten Guide",
		["{quest:829}: {quest:832}, from the {item:4903} in {zone:1411}"] = "{quest:829}: {quest:832}, aus {item:4903} in {zone:1411}",
		["{zone:1454}'s {object:172982}"] = "{object:172982} von {zone:1454}",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["A few steps east of {npc:14242}'s tree, a small camp: two Encroaching Soldiers and the {npc:268623} for Logmar. The {npc:268623} is elite: grouping up is advised."] = "Ein paar Schritte östlich vom Baum von {npc:14242} ein kleines Lager: zwei Eindringende Soldaten und der {npc:268623} für Logmar. Der {npc:268623} ist Elite: Eine Gruppe wird empfohlen.",
		["Back down the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Zurück den {area:1076} hinunter zur Hütte von {npc:4201}, dann nach Osten die Straße entlang Richtung {area:461}: {npc:4074} patrouilliert auf der Straße gleich östlich der Gabelung, {npc:4073} an den Hängen weiter nordöstlich unterhalb des Felsens. Beide sind einzelne Schredderroboter; sie wandern umher, also folge der Straße, bis du auf sie triffst.",
		["Back west to {npc:4201}' hut, on the way down to {area:2539}."] = "Zurück nach Westen zur Hütte von {npc:4201}, auf dem Weg hinunter nach {area:2539}.",
		["Bael'dun fortress"] = "Festung von Bael'dun",
		["Crossroads flight master"] = "Flugmeister des Wegekreuzes",
		["East along the road from {area:2539} to {npc:4049}'s camp."] = "Nach Osten die Straße entlang von {area:2539} zum Lager von {npc:4049}.",
		["Fly to Crossroads"] = "Flieg zum Wegekreuz",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:1638} (without its flight path the arrow goes by {area:378} and {zone:1412}): two of its elders give quests worked on this guide's and the next guide's walks, and {npc:3419} takes Lydon's toxin."] = "Flieg nach {area:1638} (ohne diese Flugroute führt der Pfeil über {area:378} und {zone:1412}): Zwei seiner Ältesten vergeben Quests, die auf den Wegen dieses und des nächsten Guides erledigt werden, und {npc:3419} nimmt Lydons Toxin an.",
		["Fly to {area:378}"] = "Flieg zum {area:378}",
		["Fly to {area:378}: {npc:2995} on {zone:1456}'s central rise, or the Crossroads' wind rider master if you start this guide there."] = "Flieg zum {area:378}: {npc:2995} auf der mittleren Anhöhe von {zone:1456} oder der Windreitermeister im Wegekreuz, wenn du diesen Guide dort beginnst.",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Folge der Straße nach Norden Richtung {area:467}. Gehörnte Renner grasen am Weg; die Blutsaftbestien, Mondlichtläufer und Siechdrachen streifen durch die Wälder unterhalb des Gipfels, und die Cenarischen Druiden halten den Hain dort.",
		["Follow the road on west past {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Folge der Straße weiter nach Westen am Lager von {npc:4049} vorbei ins Steinkrallengebirge: {npc:3995} wartet unter der Erde in {area:2539}, am Fuß des {area:1076}.",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Folge der Straße nach Westen an Regthars Bunkern vorbei: {npc:4049} lagert an ihrem Rand am Übergang zum Steinkrallengebirge.",
		["Gaea Dirt Mounds"] = "Gaeaerdhügel",
		["Gaea Seeds"] = "Gaeasamenkörner",
		["Keep {npc:4202} (27) and {npc:4049}'s robots: {area:461} comes in one trip on the way back down from Sun Rock."] = "Behalte {npc:4202} (27) und die Roboter von {npc:4049}: {area:461} kommt in einem Abstecher auf dem Rückweg von Sonnenfels hinunter.",
		["North up the road to {area:378}: your hearthstone takes you there if it is ready."] = "Nach Norden die Straße hinauf nach {area:378}: Dein Ruhestein bringt dich dorthin, wenn er bereit ist.",
		["On down the {area:1076} to {area:2539}."] = "Weiter den {area:1076} hinunter nach {area:2539}.",
		["On east to {area:461}, past where {npc:4073} roams: {quest:1096} (27) stands at the top of the Venture Co. tower. Clear the Venture Co. on the way up. His Mechanical Arm is for Ziz."] = "Weiter nach Osten zu {area:461}, vorbei an der Gegend von {npc:4073}: {quest:1096} (27) steht oben auf dem Turm der Venture Co. Räume die Venture Co. auf dem Weg nach oben. Sein mechanischer Arm ist für Ziz.",
		["On the way back east to {npc:3341}: Hecklefang Stalkers and {npc:3238} lizards roam the plain between the ridge and his camp. Careful: Qiraji Lieutenants (28, elite) sometimes stand on that plain: give them a wide berth."] = "Auf dem Rückweg nach Osten zu {npc:3341}: Hecklefang-Pirscher und {npc:3238}-Echsen streifen durch die Ebene zwischen dem Kamm und seinem Lager. Vorsicht: Auf dieser Ebene stehen manchmal Qiraji-Leutnants (28, Elite): Mach einen weiten Bogen um sie.",
		["On up the {area:1076} from {npc:4201}' hut to {area:460}."] = "Weiter von der Hütte von {npc:4201} den {area:1076} hinauf zum {area:460}.",
		["Place the {item:5638} on the {object:19594}"] = "Platziere den {item:5638} auf dem {object:19594}",
		["South of Camp Taurajo, on the road to {npc:3341}, the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit."] = "Südlich von Camp Taurajo, auf dem Weg zu {npc:3341}, verteilen sich die Silithid-Buckel über {area:390}; die Eier liegen darin, und Silithidschwärmer kommen heraus, um sie zu verteidigen.\nVorsicht: Silithidschwärmer setzen viele winzige Adds frei, die Zauber unterbrechen; Schadensschilde wie Dornen töten sie mit einem Treffer.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "Südlich von Gann graben die Zwerge von Bael'dun bei {area:359}. Ausgräber und Vorarbeiter arbeiten in der Grube; {npc:3392} (26) trägt das Tagebuch: Zieh ihn allein.\nVorsicht: Ausgräber (Stufe 21-22) und Vorarbeiter (Stufe 22-23) rennen bei 15% Gesundheit los, um Hilfe zu holen, sodass weitere Zwerge in den Kampf eingreifen können.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges."] = "Südwestlich vom Sonnenfels liegt das {area:465}. Pflanz die Gaeasamenkörner in die Erdhügel auf dem Talgrund; die Feuerelementare lassen {item:16312} fallen. Harpyien und Wegelagerinnen der Blutfurien nisten auf der Nordseite, Töterinnen und Wildfedern im Süden. Vorsicht: Die Brennenden Zerstörer, Versengten Basilisken und Sturmhexen der Blutfurien hier sind Stufe 27 und der Talgrund ist voll: Zieh sie einzeln und halte dich an seine Ränder.",
		["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them. {npc:3414} (30) and his Officers stand on the bottom floor: work the soldiers and riflemen on the upper levels and keep away from him.\nCareful: Riflemen (level 24-25) Shoot from 5-30 yd, so nearby ones can join a fight from range."] = "Die Soldaten, Gewehrschützen und Offiziere von Bael'dun bewachen die Festung auf der Ostseite der Grabung; alle drei Gegenstände fallen von ihnen. {npc:3414} (30) und seine Offiziere stehen im untersten Stockwerk: Kümmere dich um die Soldaten und Gewehrschützen auf den oberen Ebenen und halte dich von ihm fern.\nVorsicht: Gewehrschützen (Stufe 24-25) schießen aus 5-30 yd, sodass nahe stehende aus der Ferne in einen Kampf eingreifen können.",
		["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group."] = "Die Gaea-Samen liegen im Gras um das Südufer des {area:464}, nördlich des Sonnenfelsens.\nVorsicht: Pridewings um den See können als verbundene Gruppe aggro ziehen.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "Die Flugmaschine der Zwerge steht auf ihrer Plattform in der Grabungsstätte. Benutze {item:5021}, den dir {npc:3341} gegeben hat, an ihr.",
		["The flight lands at {area:378}'s wind rider master. {npc:3433} stands at the north edge of the camp, {npc:3387} and {npc:3430} (in the cage) in the middle."] = "Der Flug landet beim Windreitermeister von {area:378}. {npc:3433} steht am Nordrand des Lagers, {npc:3387} und {npc:3430} (im Käfig) in der Mitte.",
		["The flying machine"] = "Die Flugmaschine",
		["The next guide flies to {area:2897}: hearth to {area:378} if your hearthstone is ready, or walk on east to the Crossroads' flight master."] = "Der nächste Guide fliegt nach {area:2897}: Benutze deinen Ruhestein nach {area:378}, wenn er bereit ist, oder geh weiter nach Osten zum Flugmeister im Wegekreuz.",
		["The road west"] = "Die Straße nach Westen",
		["The road west past {npc:4049}'s camp"] = "Die Straße nach Westen am Lager von {npc:4049} vorbei",
		["The {object:19594} is the platform just south-east of {npc:4202}'s tower: place Zamah's {item:5638} on it. Zamah takes it back on the next guide's {zone:1456} stop."] = "Der {object:19594} ist die Plattform gleich südöstlich des Turms von {npc:4202}: Stell Zamahs {item:5638} darauf. Zamah nimmt ihn beim Halt des nächsten Guides in {zone:1456} wieder an.",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362} wächst auf dem Grund des {area:464}, vor demselben Südufer: Tauch zu den Pflanzen und den Haufen getrockneten Düsterkrauts; beide geben Schoten. Achte auf deinen Atem.",
		["To {area:378}"] = "Nach {area:378}",
		["Up the {area:1076} to {npc:4201}' hut, where the road forks east to {area:461}: {npc:3442}'s orders are for him."] = "Den {area:1076} hinauf zur Hütte von {npc:4201}, wo die Straße nach Osten Richtung {area:461} abzweigt: Die Befehle von {npc:3442} sind für ihn.",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "Westlich von Gann halten die Klingenmähnen {area:1701}. {npc:3436} ist auf der Ostseite, {npc:3434} im Süden, {npc:3435} am Westende. Lok (25) und die Kriegsrasenden (24-25) sind ein paar Stufen über dir; {npc:5859}, ein seltener Elite, läuft manchmal über den Kamm: Lass ihn in Ruhe. Pfadfinder und Pirscher lassen den Meuchler fallen, Seher den Zauberstab, Kriegsrasende den Kriegsschild. {quest:885}, eine seltene rote Windschlange, fliegt über den Kamm: Ihre Feder startet eine Quest.\nVorsicht: Klingenmähnen-Pirscher bewegen sich getarnt und treffen mit {spell:1752}, sodass sie ohne Vorwarnung in einen Kampf eingreifen können.",
		["{area:378} flight master"] = "Flugmeister von {area:378}",
		["{area:465}: kill these as you meet them"] = "{area:465}: Töte diese, wenn sie dir begegnen",
		["{area:718} quests still in your log: {npc:3446} stands beside the WANTED poster, Bigglefuzz on the dock by the flight master."] = "Quests für {area:718} noch in deinem Questlog: {npc:3446} steht neben dem Steckbrief, Bigglefuzz auf dem Steg beim Flugmeister.",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, von jeder Harpyie der Blutfurien",
		["{item:5736}, from {quest:1096}"] = "{item:5736}, von {quest:1096}",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: Glitzernde Sonnensteine von den Harpyien der Blutfurien",
		["{npc:11860}: Grish is at the {area:1718}, on the next guide's way into {zone:1441}"] = "{npc:11860}: Grish ist am {area:1718}, auf dem Weg des nächsten Guides nach {zone:1441}",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, neben {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, oben auf dem Felsvorsprung",
		["{npc:11862}: {npc:12736} at Zoram'gar, next guide"] = "{npc:11862}: {npc:12736} in Zoram'gar, nächster Guide",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} steht am Freudenfeuer im Sonnenfels: Makabas Nachricht, dass Kaya lebt, ist für sie bestimmt.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, oben im Baum gleich östlich von {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, der Windreitermeister, steht auf der mittleren Anhöhe: Hol dir seine Flugroute, falls du sie noch nicht hast. {npc:3024} und {npc:4721} stehen ein kurzes Stück östlich von ihm.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}: {object:667362} wächst im {area:464}, beim Sonnenfels",
		["{npc:3341} walks around {area:1701}: look inside the circle on the map"] = "{npc:3341} läuft um {area:1701} herum: Schau in den Kreis auf der Karte",
		["{npc:3341} walks the road south toward {area:359}, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. {npc:14242} sits up in the tree just east of the road at 47.9,77.5."] = "{npc:3341} läuft die Straße nach Süden Richtung {area:359} entlang, etwa zwischen 46,75 und 46,81: Wenn er nicht am Pfeil ist, folge der Straße, bis du ihn triffst. {npc:14242} sitzt oben im Baum direkt östlich der Straße bei 47,9 / 77,5.",
		["{npc:3375} walks around {area:359}: look inside the circle on the map"] = "{npc:3375} läuft um {area:359} herum: Schau in den Kreis auf der Karte",
		["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "{npc:3419} steht in {area:2197}, den Höhlen unter {area:1640}, westlich von {npc:2995}.",
		["{npc:3419}: the {item:5638} goes on the {object:19594} at {area:461}, on this guide's Windshear trip"] = "{npc:3419}: Der {item:5638} kommt auf den {object:19594} bei {area:461}, auf dem Abstecher dieses Guides zum Windschnittfelsen",
		["{npc:3428}, west of the north gate"] = "{npc:3428}, westlich des Nordtors",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, oben auf dem Turm",
		["{npc:3430}, in the cage"] = "{npc:3430}, im Käfig",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, am Nordrand des Lagers",
		["{npc:3442} stands beside the flight master you land at. His new orders go back to {npc:4201} on the {area:1076}, later in this guide."] = "{npc:3442} steht neben dem Flugmeister, bei dem du landest. Seine neuen Befehle gehen später in diesem Guide zurück an {npc:4201} auf dem {area:1076}.",
		["{npc:3442}: for {npc:4201}, on the way up the {area:1076}"] = "{npc:3442}: für {npc:4201}, auf dem Weg den {area:1076} hinauf",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {quest:1094}, von {npc:4201}",
		["{npc:3665}, on the dock"] = "{npc:3665}, am Steg",
		["{npc:3995}, below ground"] = "{npc:3995}, unter Tage",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way back down from Sun Rock"] = "{npc:4049}: {npc:4074} und {npc:4073} streifen östlich von {npc:4201} umher, auf dem Rückweg von Sonnenfels hinunter",
		["{npc:4128} walks around {area:1156}: look inside the circle on the map"] = "{npc:4128} läuft um {area:1156} herum: Schau in den Kreis auf der Karte",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}s nächste Quest, Ordanus, liegt auf der Allianzseite von {zone:1440}. Überspring sie.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, vor dem Tor",
		["{npc:4201}, inside"] = "{npc:4201}, drinnen",
		["{npc:4201}: {npc:4202}, at the top of the Venture Co. tower on {area:461}"] = "{npc:4201}: {npc:4202}, oben auf dem Turm der Venture Co. auf {area:461}",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: Die Phiole kommt aus dem {zone:1440}, nächster Guide",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "Die Hütte von {npc:5899} steht auf dem Grat über dem Wasserloch der Stacheleber, südlich von {area:378}, auf dem Weg nach {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: Der blaue Wasserschlauch wird im {zone:1440} gefüllt, nächster Guide",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: der rote Wasserschlauch aus {area:272}",
		["{npc:5911} stands by the flight master. His {npc:268623} (23) is elite: grouping up is advised; the two Encroaching Soldiers are not."] = "{npc:5911} steht beim Flugmeister. Sein {npc:268623} (23) ist Elite: Eine Gruppe wird empfohlen; die zwei Eindringenden Soldaten nicht.",
		["{npc:5911}, beside the flight master"] = "{npc:5911}, neben dem Flugmeister",
		["{npc:5911}: the soldiers and the pillager camp just east of {npc:3341}, on the way south"] = "{npc:5911}: Die Soldaten und der Plünderer lagern direkt östlich von {npc:3341}, auf dem Weg nach Süden",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, ein großer Dreschadon, schwimmt im seichten Wasser vor der Küste ({area:391}), östlich von {npc:3388} Skyseer.",
		["{quest:874} camps on the shore just north of {area:392}'s flight master."] = "{quest:874} lagert am Ufer direkt nördlich vom Flugmeister von {area:392}.",
		["{zone:1442}: kill these as you meet them"] = "{zone:1442}: Töte diese, wenn sie dir begegnen",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Zurück auf die Straße nach Süden. Wo sie nach Osten nach {area:287} abbiegt, wartet {npc:2214} am {area:285}.",
		["Back to the outpost."] = "Zurück zum Außenposten.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Zurück zu {npc:12867} im Holzfällerlager, an der Straße nach Norden zum Splintertreeposten.",
		["Back up to {npc:2995} on the central rise and fly to {area:1637}."] = "Zurück hinauf zu {npc:2995} auf der zentralen Anhöhe und flieg nach {area:1637}.",
		["Below ground"] = "Unter der Erde",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177844}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Die Straße durch den Silberwald hinunter zum {area:228}: von den Zeppelintürmen nach Süden durch Tirisfal; von {object:177844} nach Südosten von der Küste zur Straße. {npc:2121} und {npc:1937} stehen am Eingang der Gruft.",
		["Druid trainer"] = "Druidenlehrer",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Jeder Naga der Rächerflossen am Strand nördlich des Außenpostens lässt Köpfe fallen.",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:1637} from the {area:2897} flight master."] = "Flieg vom Flugmeister in {area:2897} nach {area:1637}.",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:378}"] = "Flieg nach {area:378}",
		["For your {area:153} run: the zeppelin lands beside the ruins. Walk into the {zone:1458} through them and down to the {object:36126}: {npc:266484} stands there, near {npc:10181}."] = "Für deinen Run durch {area:153}: Der Zeppelin landet neben den Ruinen. Geh durch sie hinein nach {zone:1458} und hinunter ins {object:36126}: {npc:266484} steht dort, in der Nähe von {npc:10181}.",
		["For your {area:236} run, at the end of the {area:287} guide: {npc:1952} stands below ground in the crypt."] = "Für deinen Run durch {area:236}, am Ende des Guides für {area:287}: {npc:1952} steht unter der Erde in der Gruft.",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "Geh von Seereths Lager nach Nordosten durch {zone:1413} zur Straße nördlich des Wegekreuzes; Schurken, die von Fizzules Turm kommen, gehen nach Westen dorthin. {npc:8582} steht auf dem Wachturm am {area:1703}, wo die Straße nach {zone:1440} führt.",
		["From the zeppelin towers, run south into Silverpine and west past the {area:240} to the coast: the {object:177844} lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the {item:15882} for Trial of the Sea Lion. Then on to the {area:228}."] = "Lauf von den Zeppelintürmen nach Süden nach Silberwald und westlich am {area:240} vorbei bis zur Küste: Die {object:177844} liegt dort am Grund sehr tiefen Wassers, neben einer Luftspalte, in der du atmen kannst. Achte auf deinen Atem auf dem Weg nach unten. Sie enthält die {item:15882} für Trial of the Sea Lion. Dann weiter zu {area:228}.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "Folge vom {area:378} der Straße nach Westen durch das Tor nach {zone:1412}, dann nach Norden an {area:222} vorbei nach {zone:1456}; ein Aufzug am Fuß der Klippen bringt dich hinauf.",
		["Head west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west: {npc:12719} and {npc:12717} stand around it, the {npc:12863} beside the flight master. Its other quests, Thistlefur's among them, are for the next visit, at 26."] = "Geh auf der Hauptstraße nach Westen durch {zone:1440}, an {area:415} vorbei (Allianz: Bleib auf der Straße), bis zur Küste. {area:2897} liegt am {area:414} im Nordwesten: {npc:12719} und {npc:12717} stehen darum, der {npc:12863} neben dem Flugmeister. Seine anderen Quests, darunter die von Distelfell, sind für den nächsten Besuch, bei 26.",
		["If you did {quest:2478} with a group, {npc:3401} in the {object:172960} takes it now."] = "Wenn du {quest:2478} mit einer Gruppe gemacht hast, nimmt {npc:3401} im {object:172960} sie jetzt an.",
		["Into {area:287}"] = "Nach {area:287}",
		["Into {zone:1440}"] = "Nach {zone:1440}",
		["Naga brazier"] = "Nagakohlenpfanne",
		["Naga heads"] = "Nagaköpfe",
		["On the roads around {area:233}, step into the town's outskirts: Protectors guard them and Mages the town; both drop pendants. Careful: each Mage (15) fights with a {npc:2540} (15) beside it: pull one Mage at a time from the outskirts. Stay out of the middle, where {npc:2120} (22) stands."] = "Geh auf den Straßen um {area:233} an den Stadtrand: Beschützer bewachen ihn und Magier die Stadt; beide lassen Anhänger fallen. Vorsicht: Jeder Magier (15) kämpft mit einer {npc:2540} (15) an seiner Seite: Pull vom Stadtrand aus immer nur einen Magier. Halte dich von der Mitte fern, wo {npc:2120} (22) steht.",
		["On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the {area:382}. Before you go near Fizzule, use {item:8051} to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first."] = "Auf dem Weg nach Norden vom Lager von Seereth halte dich östlich der Straße zum Turm der Venture Co. nördlich des {area:382}. Bevor du in die Nähe von Fizzule kommst, benutze {item:8051}, um zwei Leuchtraketen abzufeuern, wähle ihn dann als Ziel und /salute: Er greift jeden an, der ohne Signal hereinkommt.",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "Auf dem Weg nach Westen steckt {npc:267214} in einer Schlucht südlich der Hauptstraße fest, südöstlich von {area:415}. Schattenhornhirsche und Ashenvalebären streifen rundherum durch die Wälder.",
		["Out of the ruins, take the road south through Tirisfal into {zone:1421} and on to the {area:228}."] = "Nimm aus den Ruinen die Straße nach Süden durch Tirisfal in den {zone:1421} und weiter zum {area:228}.",
		["South down the road past Pyrewood: Dalaran Watchers and Wizards patrol the roads around {area:233}, and south-west of the town the Ravenclaw Drudgers and Guardians haunt the ruins of {quest:516} in the south-east of the forest. Careful: High Order Mages (30) walk the same roads among the Watchers and Wizards: leave them."] = "Südlich die Straße hinunter an Pyrewood vorbei: Dalaran-Wächter und -Zauberer patrouillieren auf den Straßen um {area:233}, und südwestlich der Stadt suchen die Ravenclaw-Knechte und -Wächter von Ravenclaw die Ruinen von {quest:516} im Südosten des Waldes heim. Vorsicht: Magier des Hohen Ordens (30) laufen zwischen den Wächtern und Zauberern dieselben Straßen ab: Lass sie in Ruhe.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Steuere {npc:267214}s {npc:271181} innerhalb von vier Minuten aus der Schlucht zur Hauptstraße; bricht die Kanalisierung ab, frag {npc:267214} erneut.",
		["The Ravenclaw undead haunt the ruins of {quest:516}, east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}.\nAn elite spirit (20) often stands beside the {object:645153}: pull the Ravenclaws away from the stone before you fight them."] = "Die Untoten von Ravenclaw suchen die Ruinen von {quest:516} heim, östlich der Straße im Südosten des Waldes; ein {npc:1973} lässt das {item:271343} fallen, das zum {object:645153} führt.\nEin Elite-Geist (20) steht oft neben dem {object:645153}: Zieh die Ravenclawn vom Stein weg, bevor du sie bekämpfst.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "{quest:6503} (23-24), Nachtelfen, pirschen durch die Wälder südlich und südöstlich des Holzfällerlagers; sie sind getarnt, also halte nach ihnen Ausschau.",
		["The quest hands you a {item:210713}: use it beside the {object:645153} to offer your blood, then kill the elite spirit that answers.\n{quest:95883} is elite: grouping up is advised."] = "Die Quest gibt dir einen {item:210713}: Benutze ihn neben dem {object:645153}, um dein Blut zu opfern, und töte dann den Elite-Geist, der antwortet.\n{quest:95883} ist Elite: Eine Gruppe wird empfohlen.",
		["The road east to {area:285}"] = "Die Straße nach Osten zu {area:285}",
		["The road north to {area:431}"] = "Die Straße nach Norden zu {area:431}",
		["The {area:153} is a dungeon for a group of five, about levels 15 to 22, in the ruined city above the {zone:1458}: its portal is in the ruins you walked through.\nInside: every undead can drop {item:268580} for {npc:266484}, so clear as you go. {npc:250660} can drop an {item:280438}, which starts a quest for {npc:2055}, and a {npc:256102} found inside starts one for {npc:7825}: both are in the {zone:1458}, on this route's next stop there."] = "{area:153} ist ein Dungeon für eine Gruppe aus fünf Spielern, etwa Stufe 15 bis 22, in der zerstörten Stadt über {zone:1458}: Das Portal liegt in den Ruinen, durch die du gegangen bist.\nDrinnen: Jeder Untote kann {item:268580} für {npc:266484} fallen lassen, also räum auf dem Weg alles ab. {npc:250660} kann {item:280438} fallen lassen; damit beginnt eine Quest für {npc:2055}, und mit {npc:256102} (drinnen zu finden) eine für {npc:7825}: Beide sind in {zone:1458}, beim nächsten Halt dieser Route dort.",
		["To {zone:1456}"] = "Nach {zone:1456}",
		["Warsong lumber camp"] = "Holzfällerlager der Warsong",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["the {object:645153} offers {quest:95883} once the {item:271343} is in; below ground"] = "der {object:645153} bietet {quest:95883} an, sobald das {item:271343} abgegeben ist; unter Tage",
		["{area:2897} flight master"] = "Flugmeister von {area:2897}",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers {quest:6503}: leave it for the next {zone:1440} visit, at 26."] = "{area:431} liegt gleich nördlich der Straße. Kommst du von Süden, kommen zuerst der Flugmeister und die Jagdtafel von {npc:12696} bei {area:428}, dann die Händler. {npc:12867} am Holzfällerlager bietet {quest:6503} an: Lass sie für deinen nächsten Besuch in {zone:1440} mit 26.",
		["{item:15882}, from the {object:177844}"] = "{item:15882}, aus {object:177844}",
		["{item:210713}, beside the {object:645153}: summons the elite spirit"] = "{item:210713}, neben dem {object:645153}: beschwört den Elite-Geist",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, von einem {npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "{item:271350}, von den Gequälten Seelen zwischen den Ruinen; unter Tage",
		["{npc:12696}'s hunt targets Ursangous and Shadumbra are for the next {zone:1440} visit, at 26; Sharptalon (31) only from level 30."] = "Die Jagdziele von {npc:12696}, Ursangus und Schattumbra, sind für den nächsten Besuch in {zone:1440}, bei 26; Scharfkralle (31) erst ab Stufe 30.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads {npc:12719} wants."] = "{npc:12717} läuft die Küste nach Norden zu einem Nagabecken. Lösche das Becken, dann bewache ihn durch die Nagawellen, bis Vorsha tot ist; die Naga der Wrathtail lassen die Köpfe fallen, die {npc:12719} will.",
		["{npc:12717}: take it last, his escort starts at once"] = "{npc:12717}: Nimm sie zuletzt an, seine Eskorte startet sofort",
		["{npc:1937}: Lydon in {area:272}, next guide"] = "{npc:1937}: Lydon in {area:272}, nächster Guide",
		["{npc:1952}, below ground"] = "{npc:1952}, unter der Erde",
		["{npc:2121}: {area:233}'s pendants, on the same roads"] = "{npc:2121}: die Anhänger aus {area:233}, auf denselben Straßen",
		["{npc:2121}: {quest:516}, south-east of {area:233}"] = "{npc:2121}: {quest:516}, südöstlich von {area:233}",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Darthalia in {area:272}",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391} in {area:272} lehrt Gifte: behalte sie",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} bildet in {area:159} Paladine aus, ein kurzer Weg die Straße hinauf nach Norden von den Zeppelintürmen. Für den Silberwald kommst du dieselbe Straße zurück.",
		["{npc:271181}, on the road"] = "{npc:271181}, auf der Straße",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:4046} stands on {area:1639} to the east; {npc:3419} in the {area:2197}, the caves under {area:1640} to the west."] = "{npc:2995}, der Windreitermeister, steht auf der zentralen Anhöhe: Hol dir seine Flugroute, falls du sie noch nicht hast. {npc:4046} steht auf der {area:1639} im Osten; {npc:3419} in den {area:2197}, den Höhlen unter der {area:1640} im Westen.",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} in {zone:1412}; {zone:1454} hat keinen Druidenlehrer",
		["{npc:3419}: her note is for {npc:2216} in {area:272}, next guide"] = "{npc:3419}: Ihre Notiz ist für {npc:2216} in {area:272}, nächster Guide",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} steht in {object:172960}. Benutze dort {item:6626} am Beschwörungskreis und besiege die Sukkubus, um sie zu binden.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389} steht gleich westlich des Eingangs der Gruft: Übergib ihm {item:16210} aus {zone:1458}.",
		["{quest:1063} first: fly to {area:1638} from the {area:2897} flight master. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {area:1638}'s flight path takes you on to {zone:1454}."] = "Zuerst {quest:1063}: Flieg vom Flugmeister in {area:2897} nach {area:1638}. {npc:4046} und {npc:3419} schicken dich zu {npc:2216} in {area:272}, dem Stützpunkt des nächsten Guides, und die Flugroute von {area:1638} bringt dich weiter nach {zone:1454}.",
		["{quest:1063} first: fly to {area:378} from the {area:2897} flight master and walk on to {zone:1456}. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {zone:1456}'s flight path takes you on to {zone:1454}."] = "Zuerst {quest:1063}: Flieg vom Flugmeister in {area:2897} nach {area:378} und lauf weiter nach {zone:1456}. {npc:4046} und {npc:3419} schicken dich zu {npc:2216} in {area:272}, dem Stützpunkt des nächsten Guides, und die Flugroute von {zone:1456} bringt dich weiter nach {zone:1454}.",
		["{quest:2478} is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)."] = "{quest:2478} ist für Stufe 23 oder höher: Die Drohnen des Turms sind 25 und Gallywix ein Elite der Stufe 23. Mach sie, wenn du kannst, mit einer Gruppe, aus dem Klassen-Guide Gifte (Horde).",
		["{quest:92421}: the {item:268580}, inside"] = "{quest:92421}: {item:268580}, drinnen",
		["{zone:1421}: kill these as you meet them"] = "{zone:1421}: Töte diese, wenn sie dir begegnen",
		["{zone:1456}'s central rise"] = "Mittlere Anhöhe von {zone:1456}",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Hast du „Mission: Possible But Not Probable“ bei Shenthul abgegeben, bring {quest:2479} zu {npc:2391} in {area:272}. Bleib neben ihm, bis das Brauziel abgeschlossen ist, und gib dann die Folgequest ab, um Gifte zu lernen. Schließe sie auch dann ab, wenn das Zanzilgift schon entfernt wurde; das Entfernen des Debuffs allein lehrt die Fertigkeit nicht.",
		["Back north up the road to the {area:228}: {npc:1938} stands just north of Allister."] = "Zurück nach Norden die Straße hinauf zum {area:228}: {npc:1938} steht gleich nördlich von Allister.",
		["Back to the Crossroads"] = "Zurück zum Wegekreuz",
		["Bears, creepers and lions"] = "Bären, Krabbler und Löwen",
		["Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight."] = "Vorsicht: Wenn ein Löwe angegriffen wird, eilen nahe Löwen ihm zu Hilfe, und die Bösartigen Schwarzbären, die sich diese Felder teilen, können ebenfalls in den Kampf eingreifen.",
		["Cast {spell:18960}. Join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}. Füge die beiden Anhängerhälften am {area:2362} am Nordwestufer des Sees zusammen, bevor du {npc:11802} in {area:2361} aufsuchst. {npc:11802} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues, Watchmen and Shadow Mages hold the camps along the way; the Shadow Mages carry Lydon's Vials of Innocent Blood."] = "Drull und {npc:2238} sind in Gebäuden im Hof der {area:275} angekettet. Für ihre Schlösser brauchst du Schlüssel: {npc:2427} trägt den {item:3467} und {npc:2428} den {item:3499}, beide in der Burg. Töte sie und öffne dann beide Schlösser.\nGeh von {area:272} nach Südosten in die Hügel auf dem Weg zur {area:275}. Schurken, Wachmänner und Schattenmagier des Syndikats halten die Lager unterwegs; die Schattenmagier tragen Lydons Phiolen mit unschuldigem Blut.",
		["Drull's ball and chain"] = "Drulls Kugel und Kette",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Füll den {item:7768} am {object:107045} neben dem Gasthaus",
		["Fly on from {npc:2226}, the bat handler just east of the crypt, to the {area:1497}."] = "Flieg von {npc:2226}, dem Fledermausführer direkt östlich der Krypta, weiter zur {area:1497}.",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["For your {area:236} run: {npc:1952} stands below ground in the crypt, {npc:1938} just north of Allister."] = "Für deinen Run durch {area:236}: {npc:1952} steht unter der Erde in der Gruft, {npc:1938} gleich nördlich von Allister.",
		["From {area:272} fly to the {area:228}: {npc:2121} stands by the crypt entrance."] = "Flieg von {area:272} zu {area:228}: {npc:2121} steht am Eingang der Krypta.",
		["Hadrec and {npc:1938}"] = "Hadrec und {npc:1938}",
		["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "Giftreihe unvollendet? Setze deine aktuelle Stufe im Klassen-Guide Gifte (Horde) fort; abgeschlossene Quests müssen nicht neu begonnen werden. Organisiere eine Gruppe für Gallywix, schließe die Folgequest von Hinott ab und kehre dann zu diesem Leveling-Guide zurück.",
		["Take {quest:31} from {npc:11802}, who stands upstairs in his building. Then {npc:11798} in {area:2361} flies druids to {area:1638}: {npc:3033} is on {area:1639}."] = "Nimm {quest:31} von {npc:11802} an, der oben in seinem Gebäude steht. Dann fliegt {npc:11798} in {area:2361} Druiden nach {area:1638}: {npc:3033} ist auf {area:1639}.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms. Careful: Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields."] = "Die Höfe östlich des Orts {area:287}. {npc:232} bestellt das Feld beim nördlichen Bauernhaus, {npc:2403} das weiter südöstlich; Landarbeiter und Bauern von Hillsbrad sind überall. {npc:2451} pflegt das Feld südlich der Höfe. Vorsicht: Wachen der Kirin Tor (55) stehen nördlich der Höfe, an der Straße hinauf Richtung Alterac: Bleib auf den Feldern.",
		["The {item:280438} from the {area:153}: Faranell takes it here."] = "{item:280438} aus {area:153}: Faranell nimmt den Kopf hier entgegen.",
		["The {quest:95204} from your {area:153} run: {npc:7825} takes it."] = "{quest:95204} aus deinem Run durch {area:153}: {npc:7825} nimmt das Wappen entgegen.",
		["Train and restock in the {zone:1458} before the zeppelin."] = "Lerne und füll deine Vorräte in {zone:1458} auf, bevor du den Zeppelin nimmst.",
		["Train before you fly on: the next guide flies from here."] = "Lerne, bevor du weiterfliegst: Der nächste Guide fliegt von hier los.",
		["Train with {npc:3033}. {npc:3419}, in the {area:2197} under {area:1640}, takes Lydon's toxin if you carry it. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Trainiere bei {npc:3033}. {npc:3419}, in den {area:2197} unter der {area:1640}, nimmt Lydons Toxin, wenn du es dabeihast. Bevor du weiterfliegst, geben dir {npc:3024} und {npc:4721}, ein kurzes Stück östlich des Windreitermeisters, zwei Quests, die auf den Wegen der nächsten Guides erledigt werden; flieg dann weiter zum Wegekreuz, wo der nächste Guide beginnt.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "Westlich von Tarrens Mühle streifen Graubären, Waldmooskrabbler und Verhungernde Berglöwen auf dem Weg hinunter zu den Höfen durch die Hügel. Die Krabbler droppen {item:3477} selten; du brauchst nur eins.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Wenn du schon hier bist: Lerne Stangenwaffen bei {npc:11870} ({object:36070}, 1 Gold); die Nahkampfwaffe eines Jägers besteht hauptsächlich aus ihren Werten, und Zweihandwaffen haben die meisten.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); two-handers level a Warrior fastest."] = "Wenn du schon hier bist: Lerne Stangenwaffen bei {npc:11870} ({object:36070}, 1 Gold); Zweihandwaffen lassen einen Krieger am schnellsten leveln.",
		["While you're here: learn Swords from {npc:11870} ({object:36070}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Wenn du schon hier bist: Lerne Schwerter bei {npc:11870} ({object:36070}, 10 Silber); ein Schwert in der Haupthand lässt einen Schurken stetig leveln.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Paladin fastest."] = "Wenn du schon hier bist: Lerne {spell:202} bei {npc:11870} ({object:36070}, 10 Silber); Zweihandwaffen lassen einen Paladin am schnellsten leveln.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Warrior fastest."] = "Wenn du schon hier bist: Lerne {spell:202} bei {npc:11870} ({object:36070}, 10 Silber); Zweihandwaffen lassen einen Krieger am schnellsten leveln.",
		["Your {area:153} limbs: {npc:266484} stands in the {object:36126}, just past the Apothecarium."] = "Deine Gliedmaßen aus {area:153}: {npc:266484} steht im {object:36126}, gleich hinter dem Apothekarium.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{area:236} is a dungeon for a group of five, about levels 20 to 30, and a full run takes about an hour. Follow the road south from the {area:228}: the keep stands on the hill above {area:204}, its gate at the top of the path.\nInside: Rethilgore first; the Deathstalker freed from the cells after him opens the courtyard door, and {npc:4444} lies just inside the courtyard, to the right: hand {quest:1098} in to him there. Then {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} and {npc:3927}; {npc:4275} at the top drops his head for {npc:1938}."] = "{area:236} ist ein Dungeon für eine Gruppe aus fünf Spielern, etwa Stufe 20 bis 30; ein kompletter Run dauert etwa eine Stunde. Folge der Straße vom {area:228} nach Süden: Die Burg steht auf dem Hügel über {area:204}, ihr Tor oben am Pfad.\nDrinnen: Zuerst Rethilgore; der Todespirscher, den du danach aus den Zellen befreist, öffnet die Tür zum Hof, und {npc:4444} liegt gleich innerhalb des Hofs, rechts: Gib {quest:1098} dort bei ihm ab. Dann {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} und {npc:3927}; {npc:4275} ganz oben lässt seinen Kopf für {npc:1938} fallen.",
		["{area:272} flight master"] = "Flugmeister von {area:272}",
		["{area:272} is your base for this guide: you come back here between each loop. Everyone stands around the town square."] = "{area:272} ist dein Stützpunkt für diesen Guide: Zwischen den Runden kommst du jedes Mal hierher zurück. Alle stehen rund um den Dorfplatz.",
		["{area:275}: kill these as you meet them"] = "{area:275}: Töte diese, wenn sie dir begegnen",
		["{area:286}: kill these as you meet them"] = "{area:286}: Töte diese, wenn sie dir begegnen",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: Benutze eine Hälfte beim {area:2362}",
		["{item:5620}, from the Syndicate Shadow Mages"] = "{item:5620}, von den Schattenmagiern des Syndikats",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin",
		["{npc:1952}, below ground"] = "{npc:1952}, unter der Erde",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, im Apothekarium",
		["{npc:2121}: {area:233}'s pendants"] = "{npc:2121}: die Anhänger aus {area:233}",
		["{npc:2216}, inside"] = "{npc:2216}, drinnen",
		["{npc:2216}: Zamah's note"] = "{npc:2216}: Zamahs Notiz",
		["{npc:2216}: his toxin is for {npc:3419}, on the {zone:1413} & Stonetalon guide's {zone:1456} stop"] = "{npc:2216}: Sein Toxin ist für {npc:3419}, beim Halt in {zone:1456} im Guide für {zone:1413} & Steinkrallengebirge",
		["{npc:2216}: the vials come from the Syndicate Shadow Mages on the way to Durnholde"] = "{npc:2216}: Die Phiolen bekommst du von den Schattenmagiern des Syndikats auf dem Weg nach Durnholde",
		["{npc:2229}, inside"] = "{npc:2229}, drinnen",
		["{npc:2230}, next to Lydon; inside"] = "{npc:2230}, neben Lydon; drinnen",
		["{npc:2238}'s ball and chain"] = "Kugel und Kette von {npc:2238}",
		["{npc:2261} walks around here: look inside the circle on the map"] = "{npc:2261} läuft hier umher: Schau in den Kreis auf der Karte",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} ist der Hund von {npc:232}, beim nördlichen Bauernhaus im Gebiet {area:286}.",
		["{npc:2391}: Poisons"] = "{npc:2391}: Gifte",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, das Dunkelkraut am {area:464} beim Sonnenfels",
		["{npc:3419}: the {item:5638}, for {area:461} in the next guide"] = "{npc:3419}: der {item:5638}, für {area:461} im nächsten Guide",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} steht im {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, die Phiole von den Lachenden Schwestern im {zone:1440}",
		["{quest:1014}: the {item:5442}"] = "{quest:1014}: {item:5442}",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "Ein kurzes Stück nördlich der Lager der Galak führt die Höhle von {area:1557} hinab in ihre tiefste Kammer, wo die {object:20807} brennt. Benutze die {item:5868} daran und plündere dann sofort den {item:5869}: Die Flamme bleibt nur kurz aus, und wenn sie wieder auflodert, ist die Phiole verloren. Dann nach Osten zum Tafelberg von {npc:2986}.\nVorsicht: Zwei Flammenwachen der Galak (30) stehen bei der Kohlenpfanne und eine Zentaurenwache läuft durch die Höhle: Zieh sie einzeln weg, bevor du die Flamme löschst.",
		["Back east to {area:484}."] = "Zurück nach Osten zum {area:484}.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Zurück nach Süden zum Lager, dann hinauf nach {zone:1456} für den Flug nach {area:378}.",
		["Back south-west to {area:421}. {npc:12759}, a corrupted water elemental, drifts around the lake's island and under the water. She drops the {item:16408} only once you have {quest:25} from {npc:12737}; it starts a quest for Splintertree."] = "Zurück nach Südwesten zum {area:421}. {npc:12759}, ein verderbtes Wasserelementar, treibt um die Insel des Sees und unter Wasser. Sie lässt die {item:16408} nur fallen, wenn du {quest:25} von {npc:12737} hast; sie startet eine Quest für Splintertree.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Zurück zu {npc:12867} im Holzfällerlager, an der Straße nach Norden zum Splintertreeposten.",
		["Back west to Zoram'gar from Thistlefur before heading east for good."] = "Von Distelfell zurück nach Westen nach Zoram'gar, bevor es endgültig nach Osten geht.",
		["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Besudelte Wasserelementare treiben um die Ufer des Sees; der Pavillon steht auf der Insel, mit Blick auf den Außenposten der Allianz.",
		["Below ground"] = "Unter der Erde",
		["Class trainer"] = "Klassenlehrer",
		["Crossroads flight master"] = "Flugmeister im Wegekreuz",
		["East along the road from Seereth's camp to the Crossroads' wind rider master, and fly to {area:2897}. If your hearthstone is ready, hearth to {area:378} and fly from there instead."] = "Nach Osten die Straße entlang von Seereths Lager zum Windreitermeister im Wegekreuz, und flieg nach {area:2897}. Ist dein Ruhestein bereit, kehr stattdessen nach {area:378} zurück und flieg von dort.",
		["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "Östlich von Zoram'gar füllen die Furbolgs von Thistlefur das Dorf und die Hügel um ihre Feste.\nVorsicht: Ein Schamane mit 15% Gesundheit oder weniger rennt los, um Hilfe zu holen, was zusätzliche Furbolgs heranziehen kann.",
		["Felmusk satyrs"] = "Satyrn der Teufelshufe",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Flieg von Zoram'gar nach {area:1638}. Wenn du die Flugroute nicht kennst, flieg stattdessen nach {area:378} und geh nach Norden durch {zone:1412}.",
		["Fly to {area:2897}"] = "Flieg nach {area:2897}",
		["Fly to {area:378}"] = "Flieg nach {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Folge der Hauptstraße nach Osten an {area:415} vorbei (Allianz: bleib auf der Straße). {npc:12678}, ein großer Grizzly, streift durch die Ruinen ({area:418}) südlich der Straße, westlich von {area:421}. Seine Pranke startet die nächste Jagdquest.",
		["For your {area:2797} run, in the same tunnels as the Sapphires: {npc:12736}'s ruins errand. Look for a group now if you have none yet."] = "Für deinen Run durch {area:2797}, in denselben Tunneln wie die Saphire: der Auftrag von {npc:12736} in den Ruinen. Such dir jetzt eine Gruppe, falls du noch keine hast.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "Geh von {area:2360} nach Nordosten zum Holzfällerlager der Warsong an der Straße: {npc:12867} steht dort.",
		["Galak centaurs"] = "Zentauren der Galak",
		["Gazebo"] = "Pavillon",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Toxinproben der Düsteranhöhe, von den Angenagten Leichnamen",
		["Grimtotem camps below {area:2097}"] = "Lager der Grimmtotem unterhalb von {area:2097}",
		["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where {npc:3987} roams."] = "In der Feste liegen Trollkisten entlang der Tunnel. {npc:12818} wird tief im Inneren festgehalten: Befreie ihn und beschütze ihn den ganzen Weg hinaus, dann rennt er heim nach {area:428}.\nVorsicht: Es gibt zwei geskriptete Hinterhalte, jeder aus drei Thistlefur (einem Schamanen, einem Pfadfinder und einem Rächer, Ursa oder Höhlenwächter): der erste, wenn du zur Gabelung des Tunnels in der Höhle zurückkommst, der zweite direkt hinter dem Tor, wo {npc:3987} umherzieht.",
		["Into {area:1638} by a lift: {npc:2995}, the wind rider master, stands on the central rise. Take his flight path if you don't know it yet."] = "Mit einem Aufzug nach {area:1638}: {npc:2995}, der Windreitermeister, steht auf der mittleren Anhöhe. Nimm seine Flugroute mit, wenn du sie noch nicht kennst.",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Bleib auf der Straße nach Osten. {npc:12858} wartet südwestlich vom Holzfällerlager der Warsong. Er und seine Grunzer stürmen den {area:2360}: Lass sie die Aggro ziehen und bleib bei {npc:12858}, bis {npc:12860} tot ist.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Töte den {npc:10720}, der für {npc:10638} kommt",
		["Laughing Sisters"] = "Lachende Schwestern",
		["Level 28"] = "Stufe 28",
		["North of Thunder Bluff"] = "Nördlich von Donnerfels",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} (30, elite) sits at the north end: leave her unless you do {quest:96261} with a group; her {item:273658} starts {quest:96294}."] = "Nördlich des Lagers überrennen Spinnen die Grabstätte {area:17044}. Benutze den {item:273015} von {npc:264074} an den Angenagten Leichnamen; die Spinner lassen {item:273181} fallen. {npc:264082} (30, Elite) sitzt am Nordende: Lass sie in Ruhe, außer du machst {quest:96261} mit einer Gruppe; ihr {item:273658} startet {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns. Careful: Felmusk Rogues and Shadowstalkers move in stealth and join fights without warning."] = "Nordwestlich vom Splintertreeposten lagern die Satyrn der Teufelshufe im Wald. Jeder Satyr kann Hörner fallen lassen. Vorsicht: Schurken und Schattenpirscher der Teufelshufe bewegen sich verstohlen und greifen ohne Vorwarnung in Kämpfe ein.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest. Careful: {npc:12676} is a level 31 nightsaber and hits hard: pull her alone, away from the Outrunners."] = "Auf dem Rückweg nach Nordosten zum Splintertreeposten: {npc:12676} streift durch die Wälder südöstlich des Holzfällerlagers der Kriegshymnen. Ihre Klaue startet die nächste Jagdquest. Vorsicht: {npc:12676} ist ein Nachtsäbler der Stufe 31 und schlägt hart zu: Zieh sie allein, weg von den Läufern.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Nur wenn {npc:10617} dir seinen Plan hinterlassen hat: {npc:10638} steht bei {area:2237}.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Fahr mit dem Aufzug hinunter und folge dann der Straße nach Osten durch die Schluchten zum {area:484}, einem Taurendorf oben auf den Tafelbergen. Sein Aufzug ist auf der Nordseite.",
		["Sapphires of Aku'Mai"] = "Saphire von Aku'Mai",
		["Short of 28? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to {npc:10646}. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon instead."] = "Noch nicht Stufe 28? Die Grimmtotem um diese Lager (25-28) haben die richtige Stufe: Töte noch ein paar, bevor du zu {npc:10646} hinaufsteigst. Danach überspringt sich dieser Schritt. Oder lauf mit einer Gruppe stattdessen den Dungeon {area:2797}.",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "Südlich von Raynewood liegt der Mondbrunnen in einer Senke westlich des Flusses, von der Straße aus schwer zu sehen; {area:421} liegt westlich davon. Benutze die {item:5867} am Mondbrunnen, um sie zu füllen.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Sprich mit {npc:3057} in {area:1638}: {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Fahr mit dem Aufzug hinunter. Das Ei liegt in einem Nest am Schluchtboden an einer von drei Stellen: südöstlich der Tafelberge (52.3,55.2), östlich (56.4,50.4) oder südwestlich (37.6,56.1).",
		["Talk to {npc:3057}"] = "Sprich mit {npc:3057}",
		["The Earthen Ring"] = "Der Irdene Ring",
		["The Earthen Ring camp and its three quests stand up on {area:17045}, north of {zone:1456}. Fly to {zone:1456} if you know its flight path and take a lift down, else fly to {area:378} and walk north through {zone:1412}; the arrow then leads round to the plateau's north end and up onto it."] = "Das Lager des Irdenen Rings und seine drei Quests stehen oben auf {area:17045}, nördlich von {zone:1456}. Flieg nach {zone:1456}, wenn du die Flugroute kennst, und nimm einen Aufzug hinunter, sonst flieg nach {area:378} und geh nach Norden durch {zone:1412}; der Pfeil führt dich dann zum Nordende der Hochebene und hinauf.",
		["The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}. From {zone:1456}, take a lift down; coming on foot from {area:378}, keep north past the bluffs."] = "Das Lager des Irdenen Rings steht nördlich der Felsen: {npc:264074}, {npc:264072} und {npc:259118}. Von {zone:1456} nimm einen Aufzug hinunter; wenn du zu Fuß von {area:378} kommst, halte dich nördlich an den Felsen vorbei.",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Die Furbolgs der Fäulnisklauen halten die Wälder östlich von {area:421}, südlich der Straße. Stell {item:16972} auf den {object:178206} und bewache es: Die Furbolgs kommen, um es niederzureißen. {npc:12918} kommt zuletzt; sein Totem fällt in den Korb.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him. Careful: storm elementals roam the canyon floor around the camps: Stormheart (30), the Ravaging Tempests (40) and {npc:216463} (38), all elite. Keep clear of them."] = "Die Lager der Galak füllen die Schlucht nördlich vom Freiwindposten; Späher, Zänker und Windhetzerinnen der Galak teilen sich jedes Lager. Ein einzelner {npc:10617} läuft einen langen Weg zwischen den Lagern: Triffst du ihn, töte ihn, seine Notiz startet eine Quest für den {area:2237}. Warte nicht auf ihn. Vorsicht: Sturmelementare streifen über den Schluchtboden um die Lager: Stormheart (30), die Ravaging Tempests (40) und {npc:216463} (38), alle Elite. Halte dich von ihnen fern.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "Die Kichernden Schwestern, Dryaden, wandern durch {area:426} um die Wälder von {npc:12677}; eine von ihnen lässt die {item:5867} von {npc:4721} fallen, was mehrere Kills dauern kann.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Die Saphire sind blaue Kristalle an den Wänden der Tunnel zum Portal der {area:2797}, unterirdisch und außerhalb der Instanz: Schwimm aus der Grube hinab, unter der Mauer hindurch, in die Höhle. Die Satyrn und Naga in den Tunneln sind Elite: Eine Gruppe wird empfohlen. Die Kristalle erscheinen schnell wieder, du musst also nicht tief hinein.",
		["The Wanted poster beside {npc:10537}"] = "Der Steckbrief neben {npc:10537}",
		["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "Der Brunnen steht in der Mitte der {area:418}, wo {npc:12678} umherzieht: Benutze dort den {item:7767}.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "{quest:6503} (23-24), Nachtelfen, pirschen durch die Wälder südlich und südöstlich des Holzfällerlagers; sie sind getarnt, also halte nach ihnen Ausschau.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "Der Weg zu den Saphiren führt durch die versunkenen Ruinen am Nordende des Strands: Geh die Treppe hinunter in die Grube.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone."] = "Dies sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Leute dafür. {npc:10992} ist ein Elite der Stufe 30: Die meisten Klassen schaffen ihn solo auf Stufe 32, aber vielleicht brauchst du Hilfe. Überspringe ihn, wenn du allein bist.",
		["Thistlefur Hold"] = "Höhle der Distelfelle",
		["Underwater"] = "Unter Wasser",
		["Warsong lumber camp"] = "Holzfällerlager der Warsong",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "Westlich vom Freiwindposten liegen die Lager der Grimmtotem unterhalb vom {area:2097}. Die Geheimnotizen liegen in Dokumententruhen im südöstlichen, südwestlichen und nordwestlichen Lager.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "Westlich vom Mystralsee streift {npc:12678}, ein großer Grizzly, durch die Ruinen ({area:418}): Seine Pranke fällt jetzt für dich.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom. Highperch Patriarchs (30-31) and the rare Heartrazor (32) nest here too: pull around them."] = "Westlich vom Weißgipfelposten nisten die Flügeldrachen auf den Klippen ({area:482}); die Eier liegen in den Nestern. {npc:10427} wartet auf der Ostseite der Nistplätze: Befreie ihn und halte ihn auf dem Rückweg zum {area:2237} am Leben.\nVorsicht: Flügeldrachen der Stufe 28-29 fliegen über dir und können ohne Vorwarnung gezogen werden. Eine Gruppe aus drei Flügeldrachen kann dich überfallen, sobald du die erste Säule unten passierst. Steilhangpatriarchen (30-31) und der Rare Herzschlitzer (32) nisten hier ebenfalls: Zieh um sie herum.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Wenn du schon hier bist: Lerne {spell:199} bei {npc:11869} (10 Silber); Zweihandwaffen lassen einen Krieger am schnellsten leveln.",
		["for {npc:5901}, south of {area:392}: next guide"] = "für {npc:5901}, südlich von {area:392}: nächster Guide",
		["grind on {npc:10759}"] = "grinde an {npc:10759}",
		["the end of the planks"] = "Das Ende der Planken",
		["{area:17044}: kill these as you meet them"] = "{area:17044}: Töte diese, wenn sie dir begegnen",
		["{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. Its portal is a little further along the tunnels you are in, past the Sapphires.\nInside: the {object:177964} lies under the water of the Moonshrine Ruins' pool, beneath the walkway (clear the crabs first): open it for the {item:16762}, and {quest:6922} comes; open the {item:16782} he drops for a quest for {npc:12736}. The Tide Priestesses sometimes drop a {item:16790}: open it for another quest for {npc:12736}. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, offers Blackfathom Villainy ({npc:4832}' head, for {npc:9087} on {zone:1456}'s {area:1639})."] = "{area:2797} ist ein Dungeon für eine Gruppe aus fünf Spielern, etwa Stufe 22 bis 30; ein kompletter Run dauert etwa eine Stunde. Das Portal liegt ein Stück weiter in den Tunneln, in denen du bist, hinter den Saphiren.\nDrinnen: {object:177964} liegt unter dem Wasser des Beckens der Moonshrine Ruins, unter dem Steg (räum zuerst die Krabben weg): Öffne ihn für {item:16762}, und {quest:6922} erscheint; öffne {item:16782}, die er fallen lässt, für eine Quest für {npc:12736}. Die Tide Priestesses lassen manchmal {item:16790} fallen: Öffne sie für eine weitere Quest für {npc:12736}. {npc:4787} bietet an einem Lagerfeuer in einem Unterwasser-Nebenraum von Ghamoo-ras Raum Blackfathom Villainy an (den Kopf von {npc:4832}, für {npc:9087} auf der {area:1639} in {zone:1456}).",
		["{area:2797} ruins"] = "Ruinen: {area:2797}",
		["{area:2897} flight master"] = "Flugmeister von {area:2897}",
		["{area:418} fountain"] = "Brunnen: {area:418}",
		["{area:484} flight master"] = "Flugmeister von {area:484}",
		["{area:484}'s lift"] = "Der Aufzug von {area:484}",
		["{area:485} detour warning: the arrow may miss the path up {area:2097}. If you are on the canyon floor, follow the path and rope bridges up {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Warnung zum Umweg über {area:485}: Der Pfeil verfehlt eventuell den Pfad hinauf zum {area:2097}. Bist du unten in der Schlucht, folge dem Pfad und den Seilbrücken hinauf zum {area:2097}. {npc:10646} wird neben {npc:10896} (29) gefangen gehalten: Besiege zuerst die Wachen und {npc:10896}, befreie sie dann und beschütze sie auf dem Weg hinunter; unterwegs greifen dich Grimmtotem aus dem Hinterhalt an.",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, von Spinnern der Düsteranhöhe",
		["{item:273658}, from {npc:264082}: it does not drop for everyone"] = "{item:273658}, von {npc:264082}: Es fällt nicht für jeden",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, am {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, von einer {npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}, an der {object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}, von der {object:20807}",
		["{npc:10079}, at the top of the lift: {npc:10537} at {area:484}"] = "{npc:10079}, oben am Aufzug: {npc:10537} am {area:484}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, beim Windreitermeister",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} von {npc:10617}, falls du ihm begegnest",
		["{npc:10645}, inside"] = "{npc:10645}, drinnen",
		["{npc:11116}, beside {npc:4877}"] = "{npc:11116}, neben {npc:4877}",
		["{npc:12576} and {npc:10079} wait at the top of the {area:485}: Maggran's letter is for {npc:12576}, and Moonhorn's message goes down to {area:484} with you."] = "{npc:12576} und {npc:10079} warten oben am {area:485}: Maggrans Brief ist für {npc:12576}, und Moonhorns Nachricht nimmst du mit hinunter zum {area:484}.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, ein Schattenpanther, pirscht durch die Wälder um {area:426}, westlich vom Lager der Teufelshufe. Ihr Kopf startet die nächste Jagdquest.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} betreut das Jagdbrett in {area:428}, beim Flugmeister: Nimm {quest:6383} an und gib sie sofort wieder ab. {npc:12678}, {npc:12676} und {npc:12677} lassen ihre Trophäen erst danach fallen.",
		["{npc:12696}: {quest:247}, once {quest:2} is in"] = "{npc:12696}: {quest:247}, sobald {quest:2} abgegeben ist",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: nur, wenn du die Handbuchseiten dabeihast",
		["{npc:12721}: the troll charms are in Thistlefur Hold, east of the outpost"] = "{npc:12721}: Die Trollamulette sind in der Feste Thistlefur, östlich des Außenpostens",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} bietet als Nächstes eine Quest für die {area:2797} an; lass sie aus, außer du hast eine Gruppe.",
		["{npc:12736} then offers the next part, {quest:6564}: it is for a second run, so leave it."] = "{npc:12736} bietet dann den nächsten Teil an, {quest:6564}: Er ist für einen zweiten Run gedacht, also lass ihn aus.",
		["{npc:12736}, {npc:12757} and {npc:12721} stand in the outpost."] = "{npc:12736}, {npc:12757} und {npc:12721} stehen im Außenposten.",
		["{npc:12757}: a banner defence in the Foulweald, east of {area:421}: furbolg waves, then {npc:12918}"] = "{npc:12757}: eine Bannerverteidigung im Foulweald, östlich von {area:421}: Wellen von Furbolgs, dann {npc:12918}",
		["{npc:12818}, below ground"] = "{npc:12818}, unter Tage",
		["{npc:12837}, inside the inn"] = "{npc:12837}, im Gasthaus",
		["{npc:259118} offers {quest:96261} only once {quest:96259} is handed in."] = "{npc:259118} bietet {quest:96261} erst an, wenn {quest:96259} abgegeben ist.",
		["{npc:259118}: {quest:96261} comes once this is handed in"] = "{npc:259118}: {quest:96261} kommt, sobald dies abgegeben ist",
		["{npc:264082} sits at the north end of {area:17044}; her {item:273658} starts {quest:96294}. {npc:264082} is elite: grouping up is advised."] = "{npc:264082} sitzt am Nordende von {area:17044}; ihr {item:273658} startet {quest:96294}. {npc:264082} ist Elite: Eine Gruppe wird empfohlen.",
		["{npc:2986} stands on a mesa top east of the Galak camps. Taking his {quest:1149} puts you on a high cliff far to the west: follow the stone path to the end of the wooden planks and step off there, and you land safely. Jump from anywhere else and you fall to your death."] = "{npc:2986} steht auf einem Mesatop östlich der Galak-Lager. {quest:1149} zu nehmen bringt dich auf eine hohe Klippe weit im Westen: Folge dem Steinpfad bis zum Ende der Holzplanken und spring dort ab, und du landest sicher. Springst du von irgendwoanders, stürzt du in den Tod.",
		["{npc:2986}, below ground"] = "{npc:2986}, unter Tage",
		["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986}: {npc:4490}, im Harpyienbau westlich des Postens",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} steht neben {npc:4721}, östlich von {npc:2995}.",
		["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "{npc:3419} steht in {area:2197}, den Höhlen unter {area:1640}, westlich von {npc:2995}.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} steht ein kurzes Stück östlich von {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: {npc:4722} am {area:484}, später in diesem Guide",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} steht am {area:484}: Die gefüllte Phiole von {npc:4721} ist für ihn.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}: die {object:20807} in {area:1557}, zwischen den Lagern der Galak",
		["{npc:4877}, inside the inn"] = "{npc:4877}, im Gasthaus",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole south of {area:378}, on the road to the {area:485}."] = "Die Hütte von {npc:5899} steht auf dem Kamm über der Tränke der Stacheleber südlich von {area:378}, an der Straße zum {area:485}.",
		["{object:176344}, north-west camp"] = "{object:176344}, nordwestliches Lager",
		["{object:176344}, south-east camp"] = "{object:176344}, südöstliches Lager",
		["{object:176344}, south-west camp"] = "{object:176344}, südwestliches Lager",
		["{quest:1150} ({npc:4490}, 31) waits for the next Freewind visit, at about 30: keep it."] = "{quest:1150} ({npc:4490}, 31) wartet auf den nächsten Besuch in Freiwindposten, etwa auf Stufe 30: Behalte sie.",
		["{quest:6921}: the {item:16762}, from the {object:177964}"] = "{quest:6921}: {item:16762}, aus {object:177964}",
		["{quest:98069}, on the ground around the den"] = "{quest:98069}, auf dem Boden um die Höhle",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
		["{zone:1456}'s central rise"] = "Mittlere Anhöhe von {zone:1456}",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back east to {area:272}."] = "Zurück nach Osten nach {area:272}.",
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "Zurück zu den Feldern: Die Arbeiter von Hillsbrad schuften südlich der Bauernhäuser. Vorsicht: Ein fliehender Arbeiter, der das Rathaus erreicht, kann Verstärkung mitbringen; Verlangsamungen oder Wurzeln halten sie von der Flucht ab.",
		["Back to {area:272}."] = "Zurück nach {area:272}.",
		["City of Dalaran"] = "City of Dalaran",
		["Clear {area:290} from the gate in; the dwarves run for help at 30% health."] = "Räume {area:290} vom Tor an aus; die Zwerge rennen bei 30% Gesundheit los, um Hilfe zu holen.",
		["Crossroads flight master"] = "Flugmeister des Wegekreuzes",
		["Darthalia's last battle is at {area:290}, the dwarven keep south-east of {area:271}: every dwarf there is elite (28-32), {npc:2304} too. Great XP if you have a group for it."] = "Darthalias letzte Schlacht findet bei {area:290} statt, der Zwergenfestung südöstlich von {area:271}: Jeder Zwerg dort ist Elite (28-32), {npc:2304} auch. Tolle EP, wenn du eine Gruppe dafür hast.",
		["Drull's ball and chain"] = "Drulls Kugel und Kette",
		["Faranell's next {quest:513} needs a {item:3388} ({skill:171}) and the {area:287} coast: leave it."] = "Faranells nächste Quest {quest:513} braucht ein {item:3388} ({skill:171}) und die Küste von {area:287}: Lass sie aus.",
		["Finish the {item:3712}"] = "{item:3712} fertig sammeln",
		["Fly to the Crossroads"] = "Flieg zum Wegekreuz",
		["Fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "Flieg nach {area:228}. Das {object:113791} steht auf dem Hügel direkt südwestlich davon: Besiege die Verderbte Manifestation des Wassers daneben, lege ihre Armschienen ins Kohlebecken, sprich mit der {npc:5895} und behalte den {item:7813} für {npc:5901}. Flieg von {area:228} weiter nach {area:272}.",
		["Fly to {area:1497}"] = "Flieg zur {area:1497}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["For characters of 29 to 31: the {quest:527}, {area:272}'s errands and the gnolls of the foothills, all at or under your level."] = "Für Charaktere der Stufen 29 bis 31: {quest:527}, die Aufträge in {area:272} und die Gnolle des Vorgebirges, alle auf oder unter deiner Stufe.",
		["For your City of Dalaran run, later in this guide: {npc:2278} stands in {area:272}, a short walk east of {npc:2410}."] = "Für deinen Run durch die City of Dalaran, später in diesem Guide: {npc:2278} steht in {area:272}, ein kurzes Stück östlich von {npc:2410}.",
		["From the blossoms, back north along the river and then west to {area:287} town, well north of {area:271} (its guards are 55)."] = "Von den Blüten zurück nach Norden den Fluss entlang und dann nach Westen zum Ort {area:287}, ein gutes Stück nördlich von {area:271} (die Wachen dort sind 55).",
		["Hillsbrad Peasants"] = "Arbeiter von Hillsbrad",
		["Inside"] = "Drinnen",
		["Inside {area:288}"] = "In der {area:288}",
		["Keep Infiltration in your log: its Syndicate (32-35) are over you now, and the 38-39 guide (Alterac and Arathi) works it on its first {area:272} loop."] = "Behalte Infiltration im Questlog: Das Syndikat (32-35) liegt jetzt über dir, und der Guide 38-39 (Alterac und Arathi) erledigt sie auf seiner ersten Runde in {area:272}.",
		["Keep these in your log: their camps are two to four levels over you now, and the 38-39 guide works them on its first {area:272} loop and in {area:321}."] = "Behalte diese im Questlog: Ihre Lager liegen jetzt zwei bis vier Stufen über dir, und der Guide 38-39 erledigt sie auf seiner ersten Runde in {area:272} und in {area:321}.",
		["Level 30"] = "Stufe 30",
		["North of Southshore"] = "Nördlich von Süderstade",
		["North-east back to {area:272}, passing well north of {area:271} (its guards are 55)."] = "Nach Nordosten zurück nach {area:272}, mit großem Abstand nördlich an {area:271} vorbei (die Wachen dort sind 55).",
		["Snapjaws"] = "Schnappkiefer",
		["South of the river's bend, the Mudsnout gnolls (26-28) camp in the hills above {area:290}; the blossoms grow among their tents. The Shamans heal and call their friends: pull them first."] = "Südlich der Flussbiegung lagern die Gnolle der Schlammschnauzen (26-28) in den Hügeln oberhalb von {area:290}; die Blüten wachsen zwischen ihren Zelten. Die Schamanen heilen und rufen Verstärkung: Zieh sie zuerst.",
		["Thaivand's next errand, the flames, sends you among the Mountain and Giant Yetis (32-34) and to Helcular's grave inside {area:271}: leave it."] = "Thaivands nächster Auftrag, die Flammen, schickt dich zu den Berg- und Riesenyetis (32-34) und zu Helculars Grab mitten in {area:271}: Lass ihn aus.",
		["The City of Dalaran is a dungeon for a group of five, about levels 28 to 33, under the violet dome. Without the {item:277507}, go in through the sewer pipe north-west of the crater: the arrow leads there.\nInside: {npc:247126} is {npc:2278}'s. {npc:268743}, in the sewer, gives Opportunistic Education and takes it back there."] = "Die City of Dalaran ist ein Dungeon für eine Gruppe aus fünf Spielern, etwa Stufe 28 bis 33, unter der violetten Kuppel. Ohne {item:277507} gehst du durch das Abwasserrohr nordwestlich des Kraters hinein: Der Pfeil führt dorthin.\nDrinnen: {npc:247126} ist für {npc:2278}. {npc:268743} in der Kanalisation gibt Opportunistic Education und nimmt die Quest dort auch wieder entgegen.",
		["The river south of {area:272}: kill these as you meet them"] = "Der Fluss südlich von {area:272}: Töte diese, wenn sie dir begegnen",
		["The smithy"] = "Die Schmiede",
		["The {quest:567} poster hangs by the inn; {npc:2216} stands inside it. {npc:2393}, the cook by the inn, wants turtle meat and sells the spices for it."] = "Der Steckbrief {quest:567} hängt beim Gasthaus; {npc:2216} steht darin. {npc:2393}, der Koch beim Gasthaus, will Schildkrötenfleisch und verkauft die Gewürze dafür.",
		["Town hall"] = "Rathaus",
		["Train"] = "Trainieren",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Trainiere, solange du in {zone:1458} bist: Die Lehrer stehen im {object:36070}, im {object:36073} und im {object:36082} (Paladine: {npc:260093}).",
		["Train your new spells."] = "Lerne deine neuen Zauber.",
		["Voidglare, Bel'varil and {npc:2770}"] = "Voidglare, Bel'varil und {npc:2770}",
		["West across the foothills to {area:287} town: the smithy stands in the middle of it. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the west side of the town; {npc:2451} works the field south-east of the town."] = "Westwärts über die Ausläufer zur Stadt {area:287}: die Schmiede steht in ihrer Mitte. {npc:2404} und seine Lehrlinge arbeiten in der Schmiede; das {object:1736} liegt daneben gestapelt. {npc:2449} geht die Westseite der Stadt entlang; {npc:2451} arbeitet auf dem Feld südöstlich der Stadt.",
		["West of Tarren Mill, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but they hit hard and come in pairs."] = "Westlich von Tarrens Mühle füllen die Höhlenyetis und Wilden Yetis (30-32) {area:277} in den Hügeln; etwa jeder sechzehnte trägt die Rute. Bleib in diesen Höhlen: Die Berg- und Riesenyetis (32-34) der Höhle weiter nördlich tragen sie auch, aber sie schlagen hart zu und kommen zu zweit.",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere.\nCareful: Kirin Tor Guards (55) patrol {area:287}'s fields and roads and attack the Horde: keep an eye out for them and stay out of their way."] = "Nach Westen an den Hügeln vorbei zu den Höfen östlich des Orts {area:287}. {npc:232} bestellt das Feld beim nördlichen Bauernhaus, {npc:2403} das weiter südöstlich; Landarbeiter und Bauern sind überall.\nVorsicht: Wachen der Kirin Tor (55) patrouillieren auf den Feldern und Straßen von {area:287} und greifen die Horde an: Halte nach ihnen Ausschau und geh ihnen aus dem Weg.",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["for {npc:2055}, on the {zone:1458} stop at the end of this guide"] = "für {npc:2055}, beim Halt in {zone:1458} am Ende dieses Guides",
		["for {npc:2425} in the {zone:1458}, at the end of this guide"] = "für {npc:2425} in der {zone:1458}, am Ende dieses Guides",
		["for {npc:4483} in the {area:439}, next guide"] = "für {npc:4483} in den {area:439}, nächster Guide",
		["for {npc:5901}, next guide"] = "für {npc:5901}, nächster Guide",
		["{area:228} flight master"] = "Flugmeister von {area:228}",
		["{area:272} flight master"] = "Flugmeister von {area:272}",
		["{area:378} flight master"] = "Flugmeister von {area:378}",
		["{area:392} flight master"] = "Flugmeister in {area:392}",
		["{item:3712}, from the Snapjaws"] = "{item:3712}, von den Schnappkiefern",
		["{item:3713}, from {npc:2393}"] = "{item:3713}, von {npc:2393}",
		["{item:6637}: drink it by the standing stone to see the elemental"] = "{item:6637}: Trink es am Menhir, um das Elementar zu sehen",
		["{npc:2055} stands in the Apothecarium, in the {object:36126}."] = "{npc:2055} steht im Apothekarium, im {object:36126}.",
		["{npc:2215}: her next {quest:539}, and {npc:2419}'s sword, are elite group quests at {area:290}: take them only with a group"] = "{npc:2215}: Ihr nächster Teil von {quest:539} und das Schwert von {npc:2419} sind Elite-Gruppenquests bei {area:290}: Nimm sie nur mit einer Gruppe an",
		["{npc:2216}, inside"] = "{npc:2216}, drinnen",
		["{npc:2229} wants his two scouts freed from {area:275}."] = "{npc:2229} will, dass du seine zwei Späher aus {area:275} befreist.",
		["{npc:2229}, inside"] = "{npc:2229}, drinnen",
		["{npc:2229}, inside: Infiltration, worked on the 38-39 visit (its Syndicate are 32-35)"] = "{npc:2229} drinnen: Infiltration, erledigt beim Besuch mit 38-39 (das Syndikat dort ist 32-35)",
		["{npc:2238}'s ball and chain"] = "Kugel und Kette von {npc:2238}",
		["{npc:2393}: {quest:7321}, the Snapjaws of the river south of town"] = "{npc:2393}: {quest:7321}, die Schnappkiefer am Fluss südlich des Orts",
		["{npc:2410} and {npc:2437} are inside the inn, {npc:2770} just outside it. Their quests are offered from level 30; below it, the 38-39 guide's first {area:272} stop takes them."] = "{npc:2410} und {npc:2437} sind im Gasthaus, {npc:2770} gleich davor. Ihre Quests gibt es ab Stufe 30; darunter nimmt sie der erste Halt in {area:272} im Guide 38-39 an.",
		["{npc:2410}, inside: {quest:544}, for the 38-39 visit (the {area:279} crater's traitors are 33-35)"] = "{npc:2410} drinnen: {quest:544}, für den Besuch mit 38-39 (die Verräter im Krater von {area:279} sind 33-35)",
		["{npc:2410}: {quest:93680}, with {quest:544} on the 38-39 visit"] = "{npc:2410}: {quest:93680}, zusammen mit {quest:544} beim Besuch mit 38-39",
		["{npc:2419}'s sword drops from the same {area:290} dwarves (about one in twelve)."] = "Das Schwert von {npc:2419} fällt von denselben Zwergen von {area:290} (etwa eines von zwölf).",
		["{npc:2425} stands beside Sylvanas in the {object:36126}."] = "{npc:2425} steht neben Sylvanas im {object:36126}.",
		["{npc:2425}: Darthalia's commendation"] = "{npc:2425}: Darthalias Belobigung",
		["{npc:2429}, in the town: {item:3708}, from the yetis on the way to the town hall"] = "{npc:2429} im Ort: {item:3708}, von den Yetis auf dem Weg zum Rathaus",
		["{npc:2437}, inside: {quest:556}, with the crater on the 38-39 visit"] = "{npc:2437} drinnen: {quest:556}, zusammen mit dem Krater beim Besuch mit 38-39",
		["{npc:2449}, on the west side of the town"] = "{npc:2449}, auf der Westseite der Stadt",
		["{npc:260093} trains Paladins in the {zone:1458}."] = "{npc:260093} bildet Paladine in der {zone:1458} aus.",
		["{npc:270038} stands in the Apothecarium. His {quest:97985} is for Stormheart, a level 30 elite who walks the canyon east of {area:484}, on the next guide's way to the {area:439}."] = "{npc:270038} steht im Apothekarium. Seine Quest {quest:97985} gilt Stormheart, einem Elite der Stufe 30, der durch die Schlucht östlich vom {area:484} läuft, auf dem Weg zur {area:439} im nächsten Guide.",
		["{npc:270038}: back to him on the next {zone:1458} stop, at about 38"] = "{npc:270038}: zurück zu ihm beim nächsten Halt in {zone:1458}, bei etwa Stufe 38",
		["{npc:2770}, outside the inn: the Boulderfist ogres (32-34) on the 38-39 Arathi visit"] = "{npc:2770} vor dem Gasthaus: die Oger der Felsfäuste (32-34) beim Besuch im Arathihochland mit 38-39",
		["{npc:3428}: for {npc:4485} in {zone:1454}"] = "{npc:3428}: für {npc:4485} in {zone:1454}",
		["{npc:4485} stands in the {object:172958}, on the way out to the main gate."] = "{npc:4485} steht im {object:172958}, auf dem Weg hinaus zum Haupttor.",
		["{npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:4949} wartet in der Burg Grommash, im {object:172957}.",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Grommash Hold, falls du sie dabeihast",
		["{npc:5901}: your {item:6637}, for the brazier"] = "{npc:5901}: dein {item:6637}, für das Kohlebecken",
		["{object:1761}, inside"] = "{object:1761}, drinnen",
		["{quest:539} with a group"] = "{quest:539} mit einer Gruppe",
		["{quest:547} with a group"] = "{quest:547} mit einer Gruppe",
		["{quest:567}, the poster by the inn"] = "{quest:567}, der Steckbrief beim Gasthaus",
		["{quest:96986} from your City of Dalaran run: {npc:2278}, a short walk east of {npc:2410}."] = "{quest:96986} aus deinem Run durch die City of Dalaran: {npc:2278}, ein kurzes Stück östlich von {npc:2410}.",
		["{zone:1458} flight master"] = "Flugmeister der {zone:1458}",
		["{zone:1458} trainers"] = "Lehrer in {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back across to {npc:2986}'s mesa north-east of the post, then take the lift down to the canyon floor. {npc:2986}'s next test, {npc:4499}, is an elite: leave it."] = "Zurück hinüber zum Tafelberg von {npc:2986} nordöstlich des Postens, dann nimm den Aufzug hinunter auf den Schluchtboden. Die nächste Prüfung von {npc:2986}, {npc:4499}, ist ein Elite: Lass ihn aus.",
		["Back east to {area:484}."] = "Zurück nach Osten zum {area:484}.",
		["Back to {area:1637}"] = "Zurück nach {area:1637}",
		["Clam beds"] = "Muschelbänke",
		["Crossroads flight master"] = "Flugmeister am Wegekreuz",
		["East to the raceway, on the way south to {area:976}."] = "Nach Osten zur Rennstrecke, auf dem Weg nach Süden nach {area:976}.",
		["Fly from {zone:1454} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {area:484} from there."] = "Flieg von {zone:1454} nach {area:1638} und lerne bei {npc:3033} auf {area:1639}; flieg von dort weiter nach {area:484}.",
		["Fly from {zone:1454} to {area:392}. {npc:5901} camps on the coast a short walk south of the town; fly on to {area:484} from {area:392}."] = "Flieg von {zone:1454} nach {area:392}. {npc:5901} lagert an der Küste einen kurzen Fußweg südlich der Stadt; flieg von {area:392} weiter nach {area:484}.",
		["Fly to the Crossroads"] = "Flieg zum Wegekreuz",
		["Fly to {area:460}"] = "Flieg nach {area:460}",
		["Fly to {area:484}"] = "Flieg zum {area:484}",
		["Giant Softshell Clams, on the sea floor"] = "Riesige Weichschalenmuscheln, auf dem Meeresgrund",
		["Head east to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. The {npc:13019} stands on the fortress's top floor with the Sceptre. The cultists also drop a {item:20310} now and then (1-5%); if one drops, read it. Leave the red {object:176581} for now: its {npc:11876} is 37, and the second {zone:1443} visit comes back for it."] = "Geh nach Osten zur {area:599}. Prügle einen Kultisten der Brennenden Klinge nieder und benutze dann den {item:6436} an ihm, bevor er stirbt, um einen {item:6435} zu füllen. Der {npc:13019} steht im obersten Stockwerk der Festung mit dem Zepter. Die Kultisten lassen hin und wieder auch eine {item:20310} fallen (1-5%); wenn eine fällt, lies sie. Lass den roten {object:176581} vorerst in Ruhe: Sein {npc:11876} ist Stufe 37, und der zweite Besuch in {zone:1443} kommt dafür zurück.",
		["Head south out of Stonetalon into {zone:1443} and follow the road south to {npc:11596}'s camp."] = "Geh südlich aus dem Steinkrallengebirge hinaus nach {zone:1443} und folge der Straße nach Süden zum Lager von {npc:11596}.",
		["Keep killing silithid at the dig site for the heart, the talons and the carapaces."] = "Töte weiter Silithiden an der Grabungsstätte für das Herz, die Klauen und die Panzer.",
		["Level 32"] = "Stufe 32",
		["North from the dig to {npc:4483}'s camp on the western edge of the flats."] = "Nördlich von der Grabung zum Lager von {npc:4483} am Westrand der Ebenen.",
		["North-east of the raceway onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it, and the Sparkleshell Tortoises (30-31) wander among them on the western flats; the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low. The Sparkleshell Snappers (34-35) crowd round a half-buried ship in the north-east and are over you here: the Tortoises of the western flats drop the shells just as often, so stay with them. Take the venom from the Reavers (31-32) of the north half and leave the Scorpid Terrors (33-34) further south."] = "Nordöstlich der Rennstrecke auf die Ebenen. Die Salzsteinbasilisken (30-31) sonnen sich nordwestlich davon, und die Spiegelpanzerschildkröten (30-31) wandern zwischen ihnen auf den westlichen Ebenen; die Salzwüstenaasfresser und Geier kreisen über den östlichen Ebenen. Jeder Geier droppt einen Knochen, etwa jede dritte Schildkröte einen Panzer.\nVorsicht: Aasfresser und Geier nutzen Hinrichten, wenn deine Gesundheit niedrig ist. Die Spiegelpanzerschnapper (34-35) drängen sich im Nordosten um ein halb vergrabenes Schiff und sind hier über dir: Die Schildkröten der westlichen Ebenen droppen die Panzer genauso oft, also bleib bei ihnen. Hol dir das Gift von den Häschern (31-32) der nördlichen Hälfte und lass die Skorpidschrecker (33-34) weiter südlich in Ruhe.",
		["On the top floor"] = "Im obersten Stockwerk",
		["Scorpid Reavers"] = "Skorpidhäscher",
		["South from the raceway over the {zone:1446} border to {area:976}, the walled goblin town: learn its flight path and fly back to {area:484} from there, which is quicker than the walk west across the flats, and the next guides fly straight to {area:976}."] = "Von der Rennstrecke nach Süden über die Grenze nach {zone:1446} bis {area:976}, der ummauerten Goblinstadt: Lerne dort die Flugroute und flieg von dort zurück zum {area:484}; das ist schneller als der Weg nach Westen über die Ebene, und die nächsten Guides fliegen direkt nach {area:976}.",
		["South of the raceway, the Saltstone Crystalhides (32-33) and Gazers (34-35) roam the far end of the flats.\nCareful: the level 35 Gazers can still be two over you: pull them one at a time from the camp's edge, never two together."] = "Südlich der Rennstrecke streifen die Salzsteinkristallhäute (32-33) und Gaffer (34-35) durch das Ende der Ebenen.\nVorsicht: Die Gaffer der Stufe 35 können noch zwei Stufen über dir sein: Pull sie einzeln vom Rand des Lagers, nie zwei zusammen.",
		["South-west back to the raceway."] = "Nach Südwesten zurück zur Rennstrecke.",
		["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "Schwimm hinaus nach {area:2406} vor der äußersten Nordspitze: {object:177786} steht am Ufer neben der {object:177673}. Öffne sie mit beiden Schlüsseln; lass die Statue in Ruhe.",
		["Take the lift down and follow the canyon east. {npc:4483} camps on the north-western edge of the salt flats."] = "Nimm den Aufzug nach unten und folge der Schlucht nach Osten. {npc:4483} lagert am nordwestlichen Rand der Salzebenen.",
		["The flats' south and the silithid dig are 32-35, {zone:1443}'s quests 32-38. Still below 32 after the raceway's hand-ins? Back north on the flats, the Scorpid Reavers (31-32) roam among the basilisks and tortoises: kill them until level 32; leave the Sparkleshell Snappers (34-35) and the Scorpid Terrors (33-34) alone. Or, with a group, run the {area:1717} dungeon instead."] = "Der Süden der Ebenen und die Silithidengrabung sind 32-35, die Quests in {zone:1443} 32-38. Nach den Abgaben an der Rennstrecke noch unter 32? Zurück nach Norden auf die Ebenen, dort streifen die Skorpidhäscher (31-32) zwischen Basilisken und Schildkröten umher: Töte sie bis Stufe 32; lass die Spiegelpanzerschnapper (34-35) und die Skorpidschrecker (33-34) in Ruhe. Oder lauf mit einer Gruppe stattdessen den Dungeon {area:1717}.",
		["The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Die Goblins und Gnome von {area:2240} sind neutral und geben Quests an beide Fraktionen.",
		["The southern flats"] = "Die südlichen Ebenen",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "Der Zeppelin landet am Turm vor dem Haupttor von {zone:1454}. {npc:5639} läuft durch die Gasse: Wenn er nicht am Pfeil ist, such ihn in ihren Straßen im Südwesten. {npc:5640} steht im {object:172961} auf der Westseite der Stadt.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:270094} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:270094} walks the canyon road east of {area:484}'s lift, on the way to the salt flats: kill him for his heart."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Leute dafür. {npc:270094} ist ein Elite der Stufe 30: Die meisten Klassen schaffen ihn auf Stufe 32 allein, aber du brauchst eventuell Hilfe. Überspring ihn, wenn du allein bist: Die Route lässt dich die EP wieder ergrinden.\n{npc:270094} läuft die Schluchtstraße östlich des Aufzugs vom {area:484} entlang, auf dem Weg zu den Salzebenen: Töte ihn für sein Herz.",
		["Train while you are in the city."] = "Lerne, solange du in der Stadt bist.",
		["Underwater"] = "Unter Wasser",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: leave the kodo skulls on the ground alone: opening one raises a {npc:11521} (37-38) that hits hard."] = "Benutze {item:13892} von {npc:11596} an einem Alten, Sterbenden oder {npc:4702} auf dem Friedhof und führe den gezähmten Kodo zurück zu {npc:11596}. Sprich an seinem Lager mit dem Kodo: Das zählt ihn und lässt dich den nächsten zähmen. Fünf Kodos, einen nach dem anderen. Vorsicht: Lass die Kodoschädel am Boden in Ruhe: Wenn du einen öffnest, erscheint eine {npc:11521} (37-38), die hart zuschlägt.",
		["West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a {item:5877}: open it.\nCareful: Hive Drones call for help when they fall to 20% health, and the {npc:4132} (37, rare) walks the dig: take the Searchers and Drones (32-34) outside first, then pull the Invaders (34-35) one at a time from the cave mouth."] = "Westlich von ihnen befallen die Silithiden die Grabungsstätte. Sucher und Stockdrohnen laufen zwischen den Hügeln umher; die Eindringlinge (34-35) bleiben in der Stockhöhle. Der erste Silithid, den du tötest, lässt einen {item:5877} fallen: Öffne ihn.\nVorsicht: Stockdrohnen rufen um Hilfe, wenn sie auf 20% Gesundheit fallen, und der {npc:4132} (37, Rare) läuft durch die Grabung: Erledige zuerst draußen die Sucher und Drohnen (32-34) und zieh dann die Eindringlinge (34-35) einzeln vom Höhleneingang.",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "Geh nach Westen zum Ufer. Riesen-Weichpanzermuscheln liegen im Flachwasser, und die Wütenden Riffkriecher laufen am Strand: Jede Muschel, die du am Meeresgrund öffnest, und manche Kriecher geben eine {item:15874}. Öffne jede davon in deinen Taschen für ihr Fleisch.\nDie Trockenschnappkriecher und -zwicker am selben Strand tragen {item:15878}, etwa jeder siebte.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\n{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges.\nFor the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "Das hast du beim früheren Besuch der Route hier verpasst: Es kommt jetzt zuerst. Es geht schnell und öffnet die Quests danach.\n{npc:2986} wartet auf dem Tafelberg knapp nordöstlich vom {area:484}, über die Seilbrücken.\nFür {quest:1149} geh über das Ende der Planken neben ihm hinaus: Du landest sicher.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["for {npc:4483} in the {area:439}, later in this guide"] = "für {npc:4483} in den {area:439}, später in diesem Guide",
		["for {npc:5641} in {zone:1443}, later in this guide"] = "für {npc:5641} in {zone:1443}, später in diesem Guide",
		["grind on {npc:4140}"] = "grinde an {npc:4140}",
		["on an Aged, Dying or {npc:4702} in the graveyard; don't kill it"] = "an einem Aged Kodo, Dying Kodo oder {npc:4702} auf dem Friedhof; töte es nicht",
		["the tamed kodo, at {npc:11596}'s camp: talk to it, five times"] = "das gezähmte Kodo, im Lager von {npc:11596}: sprich fünfmal mit ihm",
		["{area:392} flight master"] = "Flugmeister in {area:392}",
		["{area:439}: kill these as you meet them"] = "{area:439}: Töte diese, wenn sie dir begegnen",
		["{area:483}: kill these as you meet them"] = "{area:483}: Töte diese, wenn sie dir begegnen",
		["{area:484} flight master"] = "Flugmeister von {area:484}",
		["{item:15874}: open it in your bags"] = "{item:15874}: Öffne sie in deinen Taschen",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, von den Trockenschnappkrabben",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, von den Schlangenschuppen-Naga",
		["{item:279186}, from {npc:270094}"] = "{item:279186}, von {npc:270094}",
		["{item:5795}, from the Sparkleshell Tortoises of the western flats"] = "{item:5795}, von den Spiegelpanzerschildkröten der westlichen Ebenen",
		["{item:5843}, from {npc:4490}"] = "{item:5843}, von {npc:4490}",
		["{npc:10537} stands in the middle of the post, on the way to the flight master."] = "{npc:10537} steht in der Mitte des Postens, auf dem Weg zum Flugmeister.",
		["{npc:10537}: for {npc:11259} in {zone:1443}, next"] = "{npc:10537}: für {npc:11259} in {zone:1443}, als Nächstes",
		["{npc:11259}, up on the rise"] = "{npc:11259}, oben auf der Anhöhe",
		["{npc:11863}'s next errand, the {item:15803}, needs {npc:12369} (38) out on {area:2406}: leave it, he is over your level."] = "Der nächste Auftrag von {npc:11863}, das {item:15803}, braucht {npc:12369} (38) draußen auf {area:2406}: Lass es, er ist über deiner Stufe.",
		["{npc:11877}: for {quest:5762} in Stranglethorn, next guide"] = "{npc:11877}: für {quest:5762} im Schlingendorntal, nächster Guide",
		["{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges."] = "{npc:2986} wartet auf dem Tafelberg knapp nordöstlich vom {area:484}, über die Seilbrücken.",
		["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986}: {npc:4490}, im Harpyienbau westlich des Postens",
		["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} steht neben dem Flugmeister des Wegekreuzes.",
		["{npc:3428}'s {quest:1145} needed level 29 on the last guide's Crossroads stop: take it now, on a short flight to the Crossroads and back."] = "{quest:1145} von {npc:3428} brauchte beim Halt am Wegekreuz im letzten Guide Stufe 29: Nimm sie jetzt an, mit einem kurzen Flug zum Wegekreuz und zurück.",
		["{npc:3428}: for {npc:4485} in {zone:1454}"] = "{npc:3428}: für {npc:4485} in {zone:1454}",
		["{npc:4452}'s crate for {quest:5762} in Stranglethorn, later on the route"] = "Die Kiste von {npc:4452} für {quest:5762} im Schlingendorntal, später auf der Route",
		["{npc:4452}: his parts order goes to {quest:1111} in {area:392}, later on the route"] = "{npc:4452}: Seine Teilebestellung geht später auf der Route an {quest:1111} in {area:392}",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, at 39"] = "{npc:4454}: Sein Brief geht an Martek in den {zone:1418}, bei 39",
		["{npc:4485} stands in the {object:172958}."] = "{npc:4485} steht im {object:172958}.",
		["{npc:4630}: for Gazlowe in {area:392}, later on the route"] = "{npc:4630}: für Gazlowe in {area:392}, später auf der Route",
		["{npc:4877}, inside the inn"] = "{npc:4877}, im Gasthaus",
		["{npc:4877}: her stolen supplies lie in the same harpy den"] = "{npc:4877}: Ihre gestohlenen Vorräte liegen in derselben Harpyienhöhle",
		["{npc:4877}: the Screeching harpies of {area:487}"] = "{npc:4877}: die Kreischenden Harpyien vom {area:487}",
		["{npc:5395} stands in the post, {npc:11259} up on its rise; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395} steht im Posten, {npc:11259} oben auf seiner Anhöhe; {npc:5641} und {npc:4498} warten auf der Anhöhe westlich davon, über dem {area:596}.",
		["{npc:5639}: offered from level 30"] = "{npc:5639}: wird ab Stufe 30 angeboten",
		["{npc:5641} and {npc:4498}"] = "{npc:5641} und {npc:4498}",
		["{npc:5641}: for {npc:5640} in {zone:1454}, next guide"] = "{npc:5641}: für {npc:5640} in {zone:1454}, nächster Guide",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} steht im {object:172957}.",
		["{npc:5892}: for {npc:5905} by {area:484}, later in this guide"] = "{npc:5892}: für {npc:5905} bei {area:484}, später in diesem Guide",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} und dein {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} startet auch Elementare Hilfe ({area:1717}), die Kette (33-40) zu The Tempest's Weapons: forever/class/shaman/call-of-air-horde.",
		["{npc:5905} hides in a small cave in the canyon wall north-east of the post, on the way east."] = "{npc:5905} versteckt sich in einer kleinen Höhle in der Schluchtwand nordöstlich des Postens, auf dem Weg nach Osten.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: dein {item:5178}",
		["{npc:6726}, at the village's south-west end"] = "{npc:6726}, am südwestlichen Ende des Dorfes",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} liegt knapp südwestlich von {npc:11863}s Turm auf dem Boden, auf dem Weg hinunter zum Ufer: Lies es. Seine beiden Schlüssel droppen nur, solange du die Quest hast.",
		["{object:19868}, all over the northern flats: pick it on the western flats, away from the Snappers"] = "{object:19868}, überall auf den nördlichen Ebenen: Sammle sie auf den westlichen Ebenen, weg von den Schnappern",
		["{quest:1104}, from the Scorpid Reavers of the north half"] = "{quest:1104}, von den Skorpiden-Räubern der Nordhälfte",
		["{quest:98069}, on the ground around the den"] = "{quest:98069}, auf dem Boden um die Höhle",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1454} trainers"] = "Lehrer in {zone:1454}",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Zurück nach Norden zum Lager.",
		["Back to {area:1637}"] = "Zurück nach {area:1637}",
		["Back to {object:3202}."] = "Zurück nach {object:3202}.",
		["Boat to {area:35}"] = "Schiff nach {area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Dizzywigs Teile gehen zurück zu Kravel in {area:439}, abseits der Route: Lass sie liegen.",
		["East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them; the 38s can be two over you: pull them one at a time and leave the Elders alone."] = "Östlich der Mosh'Ogg-Hügel pirschen Schattentatzenpanther (37-38) durch den Dschungel Richtung See; die Schlingendorntigerinnen streifen über dasselbe Gelände und lassen hin und wieder einen makellosen Fang fallen. Schnappkieferkrokilisken säumen den Fluss direkt westlich des Dschungels; behalte ihre Häute für {npc:2495}. Vorsicht: Schattentatzenpanther (Stufe 37-38) und Alte Schattentatzenpanther (Stufe 42-43) benutzen Schleichen außerhalb des Kampfes, sodass sie verborgen bleiben, bis du nah herankommst; die 38er können zwei Stufen über dir sein: Zieh sie einzeln und lass die Alten in Ruhe.",
		["Elder Stranglethorn Tigers"] = "Ältere Schlingendorn-Tiger",
		["Escort {npc:268992} out of the ruins and keep him alive: Lozgil takes the news once he is safe."] = "Eskortiere {npc:268992} aus den Ruinen und halte ihn am Leben: Lozgil nimmt die Nachricht entgegen, sobald er in Sicherheit ist.",
		["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Flieg von {area:2408} nach {area:1638} und lerne bei {npc:3033} auf {area:1639}; flieg von dort weiter nach {zone:1454}.",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of The {item:2755} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Folge der Straße von {object:3202} nach Norden; Nesingwarys Jagdlager liegt auf dem Hügel nordöstlich des Flusses. {npc:773} will, dass es untersucht wird: Geh zwischen den Zelten umher. Ab hier behältst du jede Seite von {item:2755}, die du erbeutest: {npc:716} nimmt sie bei deinem nächsten Besuch im Schlingendorntal.",
		["Lashtail Raptors"] = "Lashtail-Raptoren",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Verlass {area:35} durch den Tunnel und folge der Straße nach Norden nach {object:3202}, dem Orclager auf der Westseite des Tals. Bleib auf der Straße: Der Dschungel daneben liegt über deiner Stufe.",
		["Level 35"] = "Stufe 35",
		["Level 36"] = "Stufe 36",
		["Mosh'Ogg camp"] = "Lager der Mosh'Ogg",
		["Nesingwary's camp"] = "Lager von Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Nordwestlich von Grom'gol liegt {area:104} unter Wasser vor der Küste. Die {item:4094} liegt auf dem Meeresgrund bei den versunkenen Ruinen; achte auf deinen Atem und die Murlocs.",
		["On the walk west from Nesingwary's camp, a pile of {object:661516} lies by the path: it starts {quest:97328}, whose Stolen Shipments lie in the {area:102} on the coast ahead."] = "Auf dem Weg nach Westen von Nesingwarys Lager liegen {object:661516} am Pfad: Sie starten {quest:97328}, deren Gestohlene Lieferungen in den {area:102} an der Küste vor dir liegen.",
		["On your way back south to {object:3202}, the Lashtail Raptors (35-36) hunt the jungle between the camp and {object:3202}: they count for Hemet and for {npc:2464}. Careful: the 36s can be two over you: pull them one at a time. Carnivorous Weeds (36-38) are rooted in the jungle south of the raptors: walk around them."] = "Auf deinem Rückweg nach Süden zu {object:3202} jagen die Schmetterschwänze (35-36) im Dschungel zwischen dem Lager und {object:3202}: Sie zählen für Hemet und für {npc:2464}. Vorsicht: Die 36er können zwei Stufen über dir sein: Zieh sie einzeln. Fleischfressendes Unkraut (36-38) wurzelt im Dschungel südlich der Raptoren: Geh drumherum.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Flusskrokilisken liegen am Fluss unterhalb des Lagers. Junge Schlingendorntiger streifen westlich des Lagers umher, junge Panther östlich davon. Geh westlich am Lager vorbei. Schlingendornraptoren (33-34) jagen auf den Lichtungen, und die Trolle der Blutskalpe halten die Ruinen an der Küste: Jeder Blutskalp kann einen Hauer droppen. Ein {item:4614} ist ein sehr seltener Drop von ihnen: Falls einer droppt, lies ihn. Vorsicht: In den Trolllagern patrouillieren viele Mobs, daher greifen oft weitere Trolle in einen Kampf ein.",
		["Snapjaw Crocolisks"] = "Schnappkieferkrokilisken",
		["Stolen Shipments, in the ruins"] = "Gestohlene Lieferungen, in den Ruinen",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads. Careful: the 37s can be two over you: pull them one at a time from the village's edge, never into the middle with the Witch Doctors.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of The {item:2755}."] = "Die Kopfjäger der Bloodscalp (36-37) im Dorf an der Küste tragen die Schrumpfköpfe. Vorsicht: Die 37er können zwei Stufen über dir sein: Zieh sie einzeln vom Dorfrand, nie in die Mitte zu den Hexendoktoren.\nDie Bloodscalp-Trolle halten die Ruinen die Küste hinauf nördlich des Riffs und das Dorf dahinter; jeder kann eine {item:3915} fallen lassen. Plündere weiter Seiten von {item:2755}.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp. Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly."] = "Die Älteren Schlingendorn-Tiger (34-35) streifen durch die Hügel südwestlich des Lagers. Vorsicht: Trolllager sind nah am Tigergebiet, und Trolle können in einen Kampf eingreifen, wenn du unvorsichtig ziehst.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time. Careful: the 37s can be two over you: take them from the camp's western edge, never two together."] = "Die Mosh'Ogg-Oger lagern in den Hügeln direkt östlich von {object:3202}, auf deinem Rückweg. Töte 10 Rohlinge und 5 Hexendoktoren (36-37); zieh sie einzeln. Vorsicht: Die 37er können zwei Stufen über dir sein: Nimm sie vom Westrand des Lagers aus, nie zwei zusammen.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Die Schattentatzenpanther kommen viel später, bei {object:3202}",
		["Train while you are in the city."] = "Lerne, solange du in der Stadt bist.",
		["Tumbled Crystals, from the geologists of the eastern camps"] = "Gerommelte Kristalle, von den Geologen der östlichen Lager",
		["Underwater"] = "Unter Wasser",
		["grind on {npc:1085}"] = "Grinde an {npc:1085}",
		["grind on {npc:1152}"] = "Grinde an {npc:1152}",
		["{area:100}: kill these as you meet them"] = "{area:100}: Töte diese, wenn sie dir begegnen",
		["{area:102}: kill these as you meet them"] = "{area:102}: Töte diese, wenn sie dir begegnen",
		["{area:2408} flight master"] = "Flugmeister: {area:2408}",
		["{area:301}: kill these as you meet them"] = "{area:301}: Töte diese, sobald sie dir begegnen",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "Zuerst {area:35}: Das Schiff der Goblins fährt von {area:392} dorthin, und alle Quests aus {area:35} führen in den Norden des Tals, in den du dann hinaufläufst.",
		["{area:35} flight master"] = "Flugmeister von {area:35}",
		["{item:277957}, from the Bloodscalp Scouts, Hunters and Mystics"] = "{item:277957}, von den Spähern, Jägern und Mystikern der Bloodscalp",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464} steht mitten in {object:3202}, {npc:2497} beim Zeppelinturm, {npc:2465} neben dem Flugmeister.",
		["{npc:2465}: the Shadowmaw claws and the tigress fang come at the end of this guide"] = "{npc:2465}: Die Klauen der Shadowmaw und der Fang der Tigerin kommen am Ende dieses Guides",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master. {npc:4631} stands on the pier."] = "Der Laden von {npc:2495} ist im Gebäude östlich des Gasthauses; {npc:2498} ist im Erdgeschoss des Gasthauses, {npc:2496}, {npc:737} und {npc:773} oben neben dem Flugmeister. {npc:4631} steht auf dem Pier.",
		["{npc:2495}, inside"] = "{npc:2495}, drinnen",
		["{npc:2496}, upstairs"] = "{npc:2496}, oben",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: für das Arathihochland, später auf der Route",
		["{npc:2498}, inside"] = "{npc:2498}, drinnen",
		["{npc:2498}, inside, on the bottom floor"] = "{npc:2498}, drinnen, auf dem untersten Stockwerk",
		["{npc:268992} is held at the east edge of the {area:102}; the Stolen Shipments lie among the ruins around him. The Bloodscalp Scouts, Hunters and Mystics (34-35) there carry his {item:277957}. Then lead him out of the ruins: {npc:4631} in {area:35} takes the news and the shipments.\nCareful: Bloodscalp Berserkers and Headhunters (36-37) and Witch Doctors (37, casters) hold the ruins north and west of {npc:268992}, close to the northern shipments (around 24.9,9.6): pick the shipments in the southern ruins by {npc:268992} first, and pull one at a time if you go north."] = "{npc:268992} wird am Ostrand der {area:102} festgehalten; die Gestohlenen Lieferungen liegen in den Ruinen um ihn herum. Die Späher, Jäger und Mystiker der Bloodscalp (34-35) dort tragen seinen {item:277957}. Führe ihn dann aus den Ruinen: {npc:4631} in {area:35} nimmt die Nachricht und die Lieferungen entgegen.\nVorsicht: Berserker und Kopfjäger der Bloodscalp (36-37) und Hexendoktoren (37, Zauberwirker) halten die Ruinen nördlich und westlich von {npc:268992}, nahe den nördlichen Lieferungen (um 24.9,9.6): Sammle zuerst die Lieferungen in den südlichen Ruinen bei {npc:268992} und zieh einzeln, wenn du nach Norden gehst.",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} wartet oben im Haus beim Flugmeister; {quest:1111} steht auf den Docks neben dem Schiff.",
		["{npc:3391}, upstairs"] = "{npc:3391}, oben",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: für {npc:4631} in {area:35}, wohin das Schiff fährt",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} steht auf dem Pier, an dem das Schiff anlegt. {npc:2495}s Laden ist im Gebäude östlich des Gasthauses; {npc:2498} ist im Erdgeschoss des Gasthauses, {npc:2496}, {npc:737} und {npc:773} oben, {npc:2858}, der Flugmeister, auf dem oberen Deck.",
		["{npc:4631}, on the pier"] = "{npc:4631}, auf dem Pier",
		["{npc:4631}, on the pier: the Stolen Shipments"] = "{npc:4631}, auf dem Pier: die Gestohlenen Lieferungen",
		["{npc:4631}: {npc:268992} is safe"] = "{npc:4631}: {npc:268992} ist in Sicherheit",
		["{npc:5640} stands in the {object:172961} on the west side of the city."] = "{npc:5640} steht im {object:172961} auf der Westseite der Stadt.",
		["{npc:737}, upstairs"] = "{npc:737}, oben",
		["{npc:773}, upstairs"] = "{npc:773}, oben",
		["{object:3202} flight master"] = "Flugmeister von {object:3202}",
		["{quest:1111}, on the docks"] = "{quest:1111}, auf den Docks",
		["{quest:629}'s and Zul'Kunda's quests are next, with Bloodscalp Headhunters of 36-37. Still below 35 after {area:35}'s hand-ins? The Elder Stranglethorn Tigers (34-35) roam the hills north of {object:3202}, below Nesingwary's camp: kill them until level 35. The Lashtail Raptors (35-36) beside them are a level higher."] = "Als Nächstes kommen die Quests für {quest:629} und Zul'Kunda, mit Kopfjägern der Bloodscalp der Stufe 36-37. Nach den Abgaben in {area:35} noch unter Stufe 35? Die Alten Schlingendorntiger (34-35) streifen durch die Hügel nördlich von {object:3202}, unterhalb von Nesingwarys Lager: Töte sie bis Stufe 35. Die Schmetterschwänze (35-36) daneben sind eine Stufe höher.",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434}: Töte diese, sobald sie dir begegnen",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1454} trainers"] = "Lehrer in {zone:1454}",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Back north along the coast to {area:392}'s flight master."] = "Zurück an der Küste nach Norden zum Flugmeister in {area:392}.",
		["Back to {area:1637}"] = "Zurück nach {area:1637}",
		["Crossroads flight master"] = "Flugmeister des Wegekreuzes",
		["Drywallow Crocolisks"] = "Staubsuhlerkrokilisken",
		["East along the road to {area:597}; {npc:5412} stands beside {npc:5395}."] = "Geh die Straße entlang nach Osten zum {area:597}; {npc:5412} steht neben {npc:5395}.",
		["Every Darkfang spider drops them: Lurkers, Spiders, Venomspitters and the Giant Darkfang Spiders"] = "Jede Dunkelfang-Spinne lässt sie fallen: Lurker, Spinnen, Giftspucker und die Riesen-Dunkelfang-Spinnen",
		["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Flieg von {area:2408} nach {area:1638} und lerne bei {npc:3033} auf {area:1639}; flieg von dort weiter nach {zone:1454}.",
		["Fly to the Crossroads"] = "Flieg zum Wegekreuz",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:2408}"] = "Flieg nach {area:2408}",
		["Fly to {area:2408} from the flight master you are next to: {area:392}'s, or Brackenwall's if you had no errand in {area:392}."] = "Flieg nach {area:2408} vom Flugmeister, bei dem du gerade bist: dem in {area:392} oder dem in Brackenwall, falls du in {area:392} nichts zu erledigen hattest.",
		["Fly to {area:378}"] = "Flieg nach {area:378}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} and {npc:4926} in the village."] = "Geh mit dem Kopf zurück nach Westen nach Brackenwall: {npc:4503} steht am Südrand des Dorfes, wo die Straße hereinkommt, {npc:4791} und {npc:4926} im Dorf.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Geh von {area:378} entlang der Straße nach Osten in den Sumpf. Das ausgebrannte {area:403} steht direkt hinter der Grenze neben ihr; der Schild, das Abzeichen und die Hufspuren sind in und neben der Ruine.",
		["Head east to {area:602}. With the {quest:5381} from {npc:11624} in your bags, open a demon portal's ring: a {npc:11937} (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake."] = "Geh nach Osten zum {area:602}. Mit der {quest:5381} von {npc:11624} in deinen Taschen öffne den Ring eines Dämonenportals: Ein {npc:11937} (38-39) kommt heraus; töte ihn, um das Portal zu schließen. Sechs Portale. Vorsicht: Höllenbestien, Verdammniswachen und Beschwörer der Brennenden Klinge laufen nahe an vielen Portalen umher und können eingreifen; töte nahe Mobs zuerst oder zieh den Wächter weg, zum Beispiel Richtung des zentralen Sees des Zirkels.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Geh nach Norden zum {area:502}. Stinki steht am Fuß des Hügels; eskortiere ihn, während er Sumpfbohnenblätter direkt südlich davon sammelt.",
		["Head south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Geh von {area:392} an der Küste nach Süden zu {area:720}. {npc:6236} steht an der Arena: Betritt das Gitter, um den Kampf zu beginnen; die Herausforderer kommen einzeln, dann {npc:6238} (33).",
		["Head west back across the marsh. The Darkfang Lurkers (36-37) and Venomspitters (37-38) on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes. Work its outer edge, where the Spiders and Recluses (35-37) stand: the Lurkers and Silkspinners (37-39) deeper in are two or three over you.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Geh nach Westen zurück über den Sumpf. Die Dunkelzahnlauerer (36-37) und Giftspucker (37-38) auf den Kämmen nördlich von Brackenwall lassen die Giftbeutel fallen. Spitzel von Theramore (35-36) schleichen durch dieselben Wälder: Sie sind getarnt, also sieh genau hin.\nDie Graunebelspinnen schwärmen am Höhleneingang nordwestlich von Brackenwall; jede Art lässt Augen fallen. Arbeite dich am äußeren Rand entlang, wo die Spinnen und Einsiedler (35-37) stehen: Die Lauerer und Seidenspinner (37-39) weiter drinnen sind zwei oder drei Stufen über dir.\nVorsicht: Dunkelzahnlauerer (Stufe 36-37) benutzen Schleichen, um außerhalb des Kampfes getarnt zu bleiben, und wirken im Kampf Gift.\nVorsicht: Getarnte Spinnen im selben Gebiet greifen dich auf Sicht an.\nVorsicht: Graunebellauerer bewegen sich getarnt und benutzen im Kampf Gift. Die Spinnen stehen dicht beieinander, daher sind Adds häufig; einzelne Ziele vom äußeren Rand zu ziehen verringert sie.",
		["Hearth to Shadowprey: your hearthstone is still bound there."] = "Benutze deinen Ruhestein nach Schattenflucht: Er ist noch dort gebunden.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Jarl wohnt im {area:497} südöstlich vom {area:502}.",
		["Level 36"] = "Stufe 36",
		["Mirefin murlocs"] = "Murlocs der Schlammflossen",
		["North up the road to {area:599}. Clear the middle of the largest building, then use the {item:14523} on the red {object:176581} there. A {npc:11876} (37) comes out: kill it for the {item:13542}. The Burning Blade around it are well under you now."] = "Geh die Straße nach Norden hinauf zur {area:599}. Räum die Mitte des größten Gebäudes, dann benutze die {item:14523} am roten {object:176581} dort. Ein {npc:11876} (37) kommt heraus: Töte ihn für den {item:13542}. Die Brennende Klinge drumherum ist jetzt deutlich unter deiner Stufe.",
		["North-west to the goblin camp on the west side of the {area:596}, back past {area:602}: keep west of the Magram's village."] = "Geh nach Nordwesten zum Goblinlager auf der Westseite des Friedhofs ({area:596}), zurück am {area:602} vorbei: Bleib westlich des Dorfs der Magram.",
		["On east to the {area:497}."] = "Weiter nach Osten zum {area:497}.",
		["On the way east, {npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out: {npc:5045} and Theramore Skirmishers (36) join it."] = "Auf dem Weg nach Osten wartet {npc:4983} im Morast ({area:2302}) östlich des Dorfs. Folge ihm zu Reethe und halte ihn im ausbrechenden Kampf am Leben: {npc:5045} und Scharmützler von Theramore (36) greifen ein.",
		["Shadowprey"] = "Shadowprey",
		["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57, and a death here is a long run back from the spirit healer. Young Murk Threshers (40-41) circle in the water around the docks: grab the footlocker and swim straight out."] = "Vom Gutshaus nach Südosten zu {area:513}: {object:20925} liegt auf dem Meeresgrund vor den Docks an der Ostseite der Insel. Schwimm hinein und wieder hinaus und halte dich von den Piers und der Stadt fern: Die Wachen von Theramore sind Stufe 53-57, und ein Tod hier bedeutet einen langen Weg zurück vom Geistheiler. Junge Düsterdrescher (40-41) kreisen im Wasser um die Docks: Schnapp dir die Kiste und schwimm direkt wieder hinaus.",
		["South-east of the coven, the bone fields of the {area:2657}, where Undead Ravagers roam, at {zone:1443}'s southern edge: keep south of the Magram's village on the way. Use the {item:15848} at the arrow to draw the Magrami Spectres (38-39): they come in numbers, so fight them with your back to the valley's edge. They drop the ghost-o-plasm.\nCareful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields just west of the arrow, well above you: use the crate at the arrow, on the valley's eastern side, and pull the spectres away from them."] = "Südöstlich des Zirkels liegen die Knochenfelder des {area:2657}, wo Untote Verheerer umherstreifen, am Südrand von {zone:1443}: Bleib unterwegs südlich des Dorfs der Magram. Benutze die {item:15848} am Pfeil, um die Magrami-Gespenster (38-39) anzulocken: Sie kommen in Scharen, also kämpf mit dem Rücken zum Rand des Tals. Sie lassen das Ghost-o-Plasma fallen.\nVorsicht: Nekrokhane und Leichenfresser der Magram (45, Elite) laufen über die Knochenfelder direkt westlich des Pfeils, weit über deiner Stufe: Benutze die Kiste am Pfeil, auf der Ostseite des Tals, und zieh die Gespenster von ihnen weg.",
		["Stinky Ignatz"] = "Stinki Ignatz",
		["Swamp Eye Jarl"] = "Sumpfauge Jarl",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "Nimm an der Gabelung die Straße nach Norden zum Ogerdorf Brackenwall.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Die Murlocs der Schlammflossen drängen sich an der Küste östlich und nordöstlich vom {area:502}; jede Art lässt Köpfe fallen.",
		["The middle of {zone:1454}"] = "Die Mitte von {zone:1454}",
		["The next guide takes the {zone:1458} zeppelin from the tower outside the main gate."] = "Der nächste Guide nimmt den Zeppelin der {zone:1458} vom Turm vor dem Haupttor.",
		["The {area:2657}"] = "Das {area:2657}",
		["Train while you are in the city; everyone else trains in the {zone:1458}, next."] = "Lerne, solange du in der Stadt bist; alle anderen lernen als Nächstes in der {zone:1458}.",
		["Underwater"] = "Unter Wasser",
		["West of the post, the Maraudine centaurs hold the {area:607}; every Maraudine can drop a {item:254432} and an ear for {npc:5395}'s {quest:1366}. Stay with the Scouts and Wranglers (36-38) at the valley's eastern edge; the Maulers and Windchasers (38-39) a little further in are up to two over you at 37: pull them one at a time.\nCareful: {npc:5402} and the Rock Worms (41-42, elite) hold the valley's north-western end with the Khan Guards and Marauders (39-40), and the Magram's village in the south-east has Necromancers (42-43): keep east of the arrow."] = "Westlich des Postens halten die Zentauren der Maraudine das {area:607}; jeder Maraudine kann ein {item:254432} und ein Ohr für {quest:1366} von {npc:5395} fallen lassen. Bleib bei den Spähern und Treibern (36-38) am Ostrand des Tals; die Zerfleischer und Windjäger (38-39) etwas weiter drinnen sind mit Stufe 37 bis zu zwei Stufen über dir: Zieh sie einzeln.\nVorsicht: {npc:5402} und die Felswürmer (41-42, Elite) halten das nordwestliche Ende des Tals mit den Khanwachen und Plünderern (39-40), und das Dorf der Magram im Südosten hat Nekromanten (42-43): Bleib östlich des Pfeils.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["for {npc:4485} in {zone:1454}, at the end of this guide"] = "für {npc:4485} in {zone:1454}, am Ende dieses Guides",
		["grind on {npc:4341}"] = "grinde an {npc:4341}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "nur, wenn du ein {item:3853} dabeihast ({skill:164} oder Auktionshaus)",
		["{area:2408} flight master"] = "Flugmeister: {area:2408}",
		["{area:392} flight master"] = "Flugmeister in {area:392}",
		["{area:496} flight master"] = "Flugmeister von {area:496}",
		["{area:496}: kill these as you meet them"] = "{area:496}: Töte diese, wenn sie dir begegnen",
		["{item:14523}, on the {object:176581}"] = "{item:14523}, am {object:176581}",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, für Sumpfauge Jarl",
		["{npc:11624} and {npc:12340} stand in the village."] = "{npc:11624} und {npc:12340} stehen im Dorf.",
		["{npc:11624}: the {quest:5381}, at {area:599} later on this visit"] = "{npc:11624}: {quest:5381}, später bei diesem Besuch in {area:599}",
		["{npc:12277} is held in the Maraudine camp at the valley's western end; free her and escort her out east of the valley.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} wird im Lager der Maraudine am westlichen Ende des Tals festgehalten; befreie sie und eskortiere sie östlich aus dem Tal.\nVorsicht: Die gescripteten Gruppen sind verbunden und erscheinen nur während der Eskorte, also kannst du sie nicht im Voraus räumen oder einzeln ziehen. Die normalen Zentauren auf dem Weg vor dem Start zu räumen hilft aber.",
		["{npc:12340}: the Slitherblade of Sar'theris Strand, on the way back from {area:599}"] = "{npc:12340}: die Naga der Zackenkämme am Strand von Sar'theris, auf dem Rückweg von {area:599}",
		["{npc:3354}, {object:172958}: for {area:720}, later in this guide (offered from level 30)"] = "{npc:3354}, {object:172958}: für {area:720}, später in diesem Guide (wird ab Stufe 30 angeboten)",
		["{npc:3412}'s workshop is in the {object:172958} beside {npc:4485}: hand in {quest:2841} if you ran {area:133}."] = "Die Werkstatt von {npc:3412} ist im {object:172958} neben {npc:4485}: Gib {quest:2841} ab, wenn du {area:133} gemacht hast.",
		["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} steht neben dem Flugmeister des Wegekreuzes.",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} steht unterhalb von Gazlowes Haus beim Flugmeister, in Richtung der Docks.",
		["{npc:4485} stands in the {object:172958}."] = "{npc:4485} steht im {object:172958}.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, am Südrand des Dorfs, wo die Straße hereinkommt",
		["{npc:5395}: his {quest:1366}, from the same Maraudine as Gurda's totems"] = "{npc:5395}: {quest:1366}, von denselben Maraudine wie Gurdas Totems",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} wartet im Goblinlager auf der Westseite des Friedhofs ({area:596}).",
		["{npc:6019}: the ghost-o-plasm, after {area:602} at the end of this visit"] = "{npc:6019}: das Ghost-o-Plasma, nach dem {area:602} am Ende dieses Besuchs",
		["{object:20985}, beside the manor"] = "{object:20985}, neben dem Anwesen",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, jetzt wo {npc:4791} den Bericht gelesen hat",
		["{quest:1218}, if you did not buy them in {zone:1454}"] = "{quest:1218}, wenn du sie nicht in {zone:1454} gekauft hast",
		["{zone:1443}'s last quests are 36-39. Still below 36 after Brackenwall's hand-ins? The Drywallow Crocolisks (35-36) along the river east of the village are the closest at your level: kill them until level 36."] = "Die letzten Quests in {zone:1443} sind Stufe 36-39. Nach den Abgaben in Brackenwall noch unter Stufe 36? Die Staubsuhlerkrokilisken (35-36) am Fluss östlich des Dorfs sind die nächsten Gegner deiner Stufe: Töte sie bis Stufe 36.",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1454} trainers"] = "Lehrer in {zone:1454}",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back east along the foothills to {area:272}: everything from the first loop is handed in inside the inn."] = "Geh an den Ausläufern entlang zurück nach Osten nach {area:272}: Alles aus der ersten Runde wird im Gasthaus abgegeben.",
		["Back north to {area:321}: the doctor stands at the south gate."] = "Zurück nach Norden nach {area:321}: Der Doktor steht am Südtor.",
		["Back north-east to {area:321}."] = "Zurück nach Nordosten nach {area:321}.",
		["Back to {area:272}"] = "Zurück nach {area:272}",
		["Back to {area:321}"] = "Zurück nach {area:321}",
		["Below ground"] = "Unter der Erde",
		["Boulderfist camp"] = "Lager der Felsfäuste",
		["Boulderfist quests for a group"] = "Boulderfist-Quests für eine Gruppe",
		["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Jeder {object:180105} ist ein Ring aus Menhiren; der Schlüssel liegt auf dem Stein in seiner Mitte. Der östliche Kreis liegt auf den Hügeln nordwestlich von {area:321}.\nVorsicht: Jeder mittlere Stein wird von etwa drei Elementaren nahe Stufe 39 bewacht, die gemeinsam angreifen, wenn du den Stein anklickst, ohne sie geräumt zu haben: Brennende Verbannte im Westen, Donnernde Verbannte im Äußeren, Brandende Verbannte im Osten.",
		["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Eskortiere den Professor den Hügel hinauf zur Höhle über der Bucht und beschütze ihn, während er arbeitet. Zwei Wasserelementare der Stufe 40 greifen ihn dort aus dem Hinterhalt an, und sie sind immun gegen Frost. Halt sie am Höhleneingang fest, weg von ihm: Findet der Kampf in der Höhle statt, mischt er sich ein, statt zu arbeiten, und es kommen immer mehr Elementare nach.",
		["Find where {quest:503} is held, on the top floor"] = "Finde heraus, wo {quest:503} festgehalten wird, im obersten Stockwerk",
		["Fleshstalker raptors"] = "Hochlandfleischpirscher",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Follow the road east. The violet shards glow just off the road a short way west of {area:321}."] = "Folge der Straße nach Osten. Die violetten Splitter leuchten direkt neben der Straße, ein kurzes Stück westlich von {area:321}.",
		["Follow the road north out of {area:272} into the Alterac foothills: {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "Folge der Straße aus {area:272} nach Norden in die Ausläufer des Alteracgebirges: {quest:535} wartet beim Lager des Syndikats. Er bietet seinen Auftrag nur an, solange du Infiltration von {npc:2229} hast: Gib ihm sofort das Starkbier, und seine Belohnung ist das Syndikatsschreiben, das Krusk will. Ein Schreiben vom Syndikat hier tut dasselbe: Hast du eins in den Taschen, überspringt der Guide {quest:535}.",
		["From the south, walk up into the camp below the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together in the camp, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens: the ones on the camp's west side are furthest from the Guard's road.\nCareful: Kirin Tor Guards (55) attack the Horde on sight, and one of them patrols the road that comes down into the camp from the north-east and walks right up to the traitors: he has killed many players here. Watch for him, let him walk back up the road, then pull the traitors. Many of the camp's guards stand in linked pairs and others patrol alone. Arcane Sentries (55, elite) and Kirin Tor Enforcers (55) stand around the violet dome itself: keep to the camp below the rim."] = "Geh von Süden hinauf ins Lager unter der violetten Kuppel von {area:279}. {npc:2411}, {npc:2412} und {npc:2413} (33-34) stehen zusammen im Lager, {npc:2414} (35) etwas westlich von ihnen; jeder trägt ein Blutsteinstück. Die Schildwachen und Theurgen (31-33) um sie herum lassen die Abgenutzten Steinmarken fallen: Die auf der Westseite des Lagers sind am weitesten von der Straße der Wache entfernt.\nVorsicht: Wachen der Kirin Tor (55) greifen die Horde sofort an, und eine davon patrouilliert die Straße, die von Nordosten ins Lager herunterkommt, und läuft direkt bis zu den Verrätern: Sie hat hier schon viele Spieler getötet. Achte auf sie, lass sie die Straße wieder hinauflaufen, dann zieh die Verräter. Viele Wachen des Lagers stehen in verbundenen Paaren, andere patrouillieren allein. Arkane Wächter (55, Elite) und Vollstrecker der Kirin Tor (55) stehen um die violette Kuppel selbst: Bleib im Lager unterhalb des Rands.",
		["From {area:280} follow the road south-west to {area:1357} and on west to the ruins north of the {area:279} crater, along the lake shore. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves. Careful: Arcane Sentries (55, elite) and Kirin Tor Guards (55) guard the dome itself and attack the Horde: work the ruins' outer edge and don't go up to the dome."] = "Folge von {area:280} der Straße nach Südwesten bis {area:1357} und weiter nach Westen zu den Ruinen nördlich des Kraters von {area:279}, am Seeufer entlang. Die Beschwörer von Dalaran führen Elementarsklaven an; die Armschienen fallen von den Sklaven. Vorsicht: Arkane Wächter (55, Elite) und Wachen der Kirin Tor (55) bewachen die Kuppel selbst und greifen die Horde an: Arbeite dich am Außenrand der Ruinen entlang und geh nicht zur Kuppel hinauf.",
		["Go'shek Farm"] = "Gehöft Go'shek",
		["Head east out of {area:272} through {area:1057} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south of {area:313}; the Enforcers stay in the cave there."] = "Verlasse {area:272} nach Osten durch {area:1057} und folge der Straße nach Osten. Die Boulderfist-Oger und -Vollstrecker (32-34) lagern südlich der Straße, südlich von {area:313}; die Vollstrecker bleiben in der Höhle dort.",
		["Head north up the road past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam {area:280}, and the buildings hold many Syndicate mobs, mages among them."] = "Geh die Straße nach Norden hinauf am Lager von {quest:535} vorbei nach {area:280}, dem vom Syndikat gehaltenen Dorf (35-37). {npc:2431} trägt den {item:3704}; {quest:503} sitzt in einem Käfig im Haus an der Nordseite.\nVorsicht: Getarnte Syndikat-Spione streifen durch {area:280}, und die Gebäude beherbergen viele Syndikat-Mobs, darunter Magier.",
		["Head south to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Geh nach Süden zur Bucht der Goblins an der Südküste. {npc:2766} hält auf der Klippe darüber Wache.",
		["Head west; the outer circle stands in the middle of the highlands."] = "Geh nach Westen; der äußere Kreis steht in der Mitte des Hochlands.",
		["Hearth back to {area:272} (your hearthstone is bound there), or walk back south-east along the road out of Alterac."] = "Nimm den Ruhestein zurück nach {area:272} (dein Ruhestein ist dort gebunden) oder lauf die Straße aus Alterac nach Südosten zurück.",
		["Hearth back to {area:272}: your hearthstone is bound there."] = "Nimm den Ruhestein zurück nach {area:272}: Dein Ruhestein ist dort gebunden.",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Hochlandfleischpirscher (36-37) jagen im südlichen Hochland, ein Rudel nördlich von {area:316} und ein weiteres auf der Ebene westlich davon. Zieh sie einzeln.",
		["Highland raptors and Plains Creepers"] = "Hochland-Raptoren und Plains Creepers",
		["Inside"] = "Drinnen",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Nordöstlich von Hammerfall bauen die Drywhisker-Kobolde in der Schlucht ab; die Kobolde am Eingang und die Gräber und Landvermesser weiter drinnen lassen alle die Myzrael-Splitter fallen.\nVorsicht: Jede Koboldart rennt bei niedriger Gesundheit los, um Hilfe zu holen (Kobolde bei 30%, Landvermesser und Gräber bei 15%), was weitere von ihnen heranziehen kann.",
		["On the way back north, Highland Striders roam the hills all around {area:321} and drop the eyes, and south of it the Plains Creepers (32-33) spin their webs in the grass; they carry the spidersilk."] = "Auf dem Rückweg nach Norden streifen Highland Striders durch die Hügel rund um {area:321} und lassen die Augen fallen, und südlich davon spinnen die Plains Creepers (32-33) ihre Netze im Gras; sie tragen die Spinnenseide.",
		["Only if you ran Stromgarde with a group: back to {area:321} for its hand-ins, then on to the {area:880}."] = "Nur wenn du Stromgarde mit einer Gruppe gemacht hast: zurück nach {area:321} für die Abgaben, dann weiter zur {area:880}.",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one."] = "Nur, wenn du das Schreiben von {quest:535} nicht bekommen hast: Die Schleicher und Diebe des Syndikats (32-34) um die Lager westlich der Straße tragen auch Schreiben; etwa jeder dritte lässt eins fallen.",
		["South of Hammerfall, the Witherbark trolls hold the village in the hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village. Careful: All three troll types flee for help at 15% health, which can pull more trolls from the nearby camps."] = "Südlich von Hammerfall halten die Witherbark-Trolle das Dorf in den Hügeln. Axtwerfer bewachen die äußeren Hütten; die Hexendoktoren und Kopfjäger halten das Herz des Dorfes. Vorsicht: Alle drei Trollarten fliehen bei 15% Gesundheit, um Hilfe zu holen, was weitere Trolle aus den nahen Lagern heranziehen kann.",
		["South of the {area:279} crater's camp"] = "Südlich des Lagers im Krater von {area:279}",
		["Stromgarde"] = "Stromgarde",
		["Stromgarde quests for a group"] = "Stromgarde-Quests für eine Gruppe",
		["Syndicate missives"] = "Schreiben des Syndikats",
		["The Boulderfist Brutes camp outside the ogres' hall, far south-west of {area:321}; the Magus stand among them. Pull them one at a time."] = "Die Boulderfist-Rohlinge lagern vor der Halle der Oger, weit südwestlich von {area:321}; die Magi stehen unter ihnen. Zieh sie einzeln.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Der innere Kreis liegt südlich des westlichen Kreises, östlich von Stromgarde.",
		["The magus offers a dungeon errand next: leave it."] = "Der Magus bietet als Nächstes einen Dungeon-Auftrag an: Lass ihn liegen.",
		["The next guide crosses the {area:880} into the {zone:1437} and heads for the {zone:1418}."] = "Der nächste Guide überquert die {area:880} ins {zone:1437} und hält auf die {zone:1418} zu.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate.\n{npc:15126} offers the {quest:8263} only once you are Friendly with the Defilers ({zone:1461}): skip it if he doesn't offer it."] = "Die Orc-Festung am östlichen Ende der Straße. {npc:2851}, der Windreitermeister, steht am Tor.\n{npc:15126} bietet das {quest:8263} erst an, wenn du bei den Entweihten ({zone:1461}) Freundlich bist: Überspringe es, wenn er es nicht anbietet.",
		["The road east through {area:1057}"] = "Die Straße nach Osten durch {area:1057}",
		["The stone's next task needs Fozruk, a level 42 elite who roams west of {area:321}: leave it."] = "Die nächste Aufgabe des Steins braucht Fozruk, einen Elite der Stufe 42, der westlich von {area:321} umherzieht: Lass sie liegen.",
		["The western circle is near {area:1057}, north-west of the outer one."] = "Der westliche Kreis ist nahe {area:1057}, nordwestlich des äußeren.",
		["The {area:279} crater"] = "Der Krater von {area:279}",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} liegen am hinteren Ende der Schlucht.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Trainiere, solange du in {zone:1458} bist: Die Lehrer stehen im {object:36070}, im {object:36073} und im {object:36082} (Paladine: {npc:260093}).",
		["Underwater"] = "Unter Wasser",
		["West along the foot of the hills, south of the road: a {npc:246848} (55) walks that road from the north-east down into the traitors' camp."] = "Geh am Fuß der Hügel nach Westen, südlich der Straße: Eine {npc:246848} (55) läuft diese Straße von Nordosten hinunter ins Lager der Verräter.",
		["West of the inner circle, Stromgarde's ruins: the Syndicate hold the east half (the Sigil drops from their Conjurors, Prowlers and Magi), the Boulderfist the west half by the {area:325} ({npc:2773} waits in one of the roofless houses beside it)."] = "Westlich des inneren Kreises die Ruinen von Stromgarde: Das Syndikat hält die Osthälfte (das Siegel fällt von ihren Beschwörern, Pirschern und Magi), die Boulderfist die Westhälfte beim {area:325} ({npc:2773} wartet in einem der dachlosen Häuser daneben).",
		["Worn Stone Tokens, from the Shield Guards and Theurgists on the camp's west side"] = "Abgenutzte Steinmarken, von den Schildwachen und Theurgen auf der Westseite des Lagers",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["for {npc:2487} in {area:35}, around level 41"] = "für {npc:2487} in {area:35}, bei etwa Stufe 41",
		["{area:17707}: kill these as you meet them"] = "{area:17707}: Töte diese, wenn sie dir begegnen",
		["{area:328}: kill these as you meet them"] = "{area:328}: Töte diese, sobald sie dir begegnen",
		["{item:278225}, from Plains Creepers"] = "{item:278225}, von Plains Creepersn",
		["{item:279469}: an object to loot, by the traitors"] = "{item:279469}: ein Objekt zum Plündern, bei den Verrätern",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, für {npc:2333}",
		["{npc:12920}, at the south gate"] = "{npc:12920}, am Südtor",
		["{npc:12920}, at the south gate. If he won't take the silk, another player may be running Triage: wait a few minutes and talk to him again."] = "{npc:12920}, am Südtor. Wenn er die Seide nicht annimmt, macht vielleicht gerade ein anderer Spieler Triage: Warte ein paar Minuten und sprich ihn erneut an.",
		["{npc:12920}, at the south gate. If {npc:12920} offers nothing, another player may be running his {skill:129} quest Triage: he can be busy for a few minutes. Wait, then talk to him again."] = "{npc:12920}, am Südtor. Wenn {npc:12920} nichts anbietet, macht vielleicht gerade ein anderer Spieler seine {skill:129}-Quest Triage: Er kann ein paar Minuten beschäftigt sein. Warte und sprich ihn dann erneut an.",
		["{npc:2229} will offer {npc:2423} (41, in his manor far up {area:1339}) for this: leave it, he is over your level."] = "{npc:2229} bietet dafür {npc:2423} an (41, in seinem Herrenhaus weit oben am {area:1339}): Lass es liegen, er liegt über deiner Stufe.",
		["{npc:2229}, inside"] = "{npc:2229}, drinnen",
		["{npc:2229}, {npc:2410} and {npc:2437} are inside the inn; {npc:2770} stands outside it."] = "{npc:2229}, {npc:2410} und {npc:2437} sind im Gasthaus; {npc:2770} steht draußen davor.",
		["{npc:2410}, inside"] = "{npc:2410}, drinnen",
		["{npc:2410}: {quest:93680}, the {item:279469} is by the traitors"] = "{npc:2410}: {quest:93680}, der {item:279469} ist bei den Verrätern",
		["{npc:2437}, inside"] = "{npc:2437}, drinnen",
		["{npc:270038} stands in the Apothecarium."] = "{npc:270038} steht im Apothekarium.",
		["{npc:270038}: Stormheart's heart from {zone:1441}"] = "{npc:270038}: Stormhearts Herz aus {zone:1441}",
		["{npc:2703}'s {quest:639} drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle."] = "{quest:639} von {npc:2703} fällt von den Elite-Syndikatsleuten (35-38) in den Ruinen von Stromgarde, im Westen des Hochlands. Tolle EP, wenn du eine Gruppe dafür hast: Die Route kommt auf dem Weg zum inneren Kreis an Stromgarde vorbei.",
		["{npc:2733}'s lab shack stands at Go'shek Farm, north-east of the raptors' plain on the way back to {area:321}; the case of {item:278462} is inside."] = "Die Laborhütte von {npc:2733} steht auf dem Gehöft Go'shek, nordöstlich der Raptorenebene auf dem Rückweg nach {area:321}; die Kiste mit {item:278462} ist drinnen.",
		["{npc:2770}: for {npc:2771} in {area:321}, later in this guide"] = "{npc:2770}: für {npc:2771} in {area:321}, später in diesem Guide",
		["{npc:2771}'s next {quest:678} and {npc:2772}'s {quest:680} are the elite ogres (38-40) in Stromgarde's ogre quarter, on the same group trip as the Sigil."] = "Die nächste {quest:678} von {npc:2771} und {quest:680} von {npc:2772} sind die Elite-Oger (38-40) im Ogerviertel von Stromgarde, auf demselben Gruppenausflug wie das Siegel.",
		["{npc:2772}, beside him"] = "{npc:2772}, neben ihm",
		["{npc:2792}, by the gate"] = "{npc:2792}, am Tor",
		["{quest:503}, on the top floor"] = "{quest:503}, im obersten Stockwerk",
		["{zone:1458} flight master"] = "Flugmeister der {zone:1458}",
		["{zone:1458} trainers"] = "Lehrer in {zone:1458}",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "Unter der Erde",
		["Head back south down the road, past the {area:1877}."] = "Geh die Straße zurück nach Süden, am {area:1877} vorbei.",
		["Head for the {object:2673}, the great bridge at Arathi's southern edge, cross it and follow the road south through the {zone:1437} to the {object:1668} tunnel into {zone:1432}. {area:144}, the dwarf town on the road in the middle of {zone:1432}, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves {zone:1432} to the south into the {zone:1418}; follow it to the goblin camp in the {area:1877}."] = "Halte auf die {object:2673} zu, die große Brücke am Südrand von Arathi, überquere sie und folge der Straße nach Süden durch das {zone:1437} zum Tunnel {object:1668} nach {zone:1432}. {area:144}, die Zwergenstadt an der Straße mitten in {zone:1432}, hat Wachen, die die Horde angreifen: Verlasse die Straße davor und umgehe die Stadt auf den Hügeln westlich davon. Die Straße verlässt {zone:1432} nach Süden in die {zone:1418}; folge ihr zum Goblinlager im {area:1877}.",
		["Head west along the road towards {area:340}; {npc:2921}'s camp sits in the {area:1878} halfway there."] = "Geh auf der Straße nach Westen Richtung {area:340}; das Lager von {npc:2921} liegt auf halbem Weg im {area:1878}.",
		["Head west back to {area:340}. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "Geh nach Westen zurück nach {area:340}. {npc:5394} steht auf der oberen Ebene von {area:340}, hoch über dem Flugmeister: Nimm die Rampen nach oben, der Pfeil kann die Ebenen nicht unterscheiden.",
		["Into the {zone:1418}"] = "Ins {zone:1418}",
		["Keep north on the road to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "Bleib auf der Straße nach Norden zum Eingang von {area:1517} im Norden von {zone:1418}: Die Truhe liegt gleich hinter dem Höhleneingang. {npc:2932} und die Obsidian Golems (38) stehen daneben, und Shadowforge Diggers (35-36) arbeiten im Tunnel, alle Elite: Halte deine Gruppe zusammen.",
		["Lesser Rock Elementals"] = "Kleine Felselementare",
		["North-west across the basin to {npc:2921}'s camp. Short of Jarkal's shards? The Lesser Rock Elementals (37) on the flats west of the camp drop them about one kill in five."] = "Nach Nordwesten durch das Becken zum Lager von {npc:2921}. Fehlen dir noch Jarkals Splitter? Die Geringeren Felselementare (37) auf den Ebenen westlich des Lagers lassen sie bei etwa jedem fünften Kill fallen.",
		["Rock Elementals"] = "Felselementare",
		["South-east across the basin, the bigger Rock Elementals (39) stand on the slopes west of {area:345}; each one drops a slab. Every rock elemental can drop {npc:6868}'s Rock Elemental Shards. Careful: Malevolent Mirages (42, elite) drift across these slopes too."] = "Südöstlich durch das Becken stehen die größeren Felselementare (39) an den Hängen westlich von {area:345}; jedes lässt eine Platte fallen. Jedes Felselementar kann die Felselementar-Splitter von {npc:6868} fallen lassen. Vorsicht: Auch Bösartige Trugbilder (42, Elite) treiben über diese Hänge.",
		["Stonevault troggs"] = "Steingrufttroggs",
		["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way north from {area:345}; the Bonesnappers and Shamans drop the flakes. The Buzzards for {npc:2817}'s wings circle the hills between the {area:1877} and {area:345}."] = "Die Stonevault-Troggs graben um die Höhleneingänge südlich des {area:1877}, auf dem Weg nach Norden von {area:345}; die Knochenschnapper und Schamanen lassen die Flocken fallen. Die Bussarde für die Flügel von {npc:2817} kreisen über den Hügeln zwischen dem {area:1877} und {area:345}.",
		["The road north to {area:1517} runs through the {area:1877}: {npc:2817} and {npc:4618} take the wings and the flakes on the way."] = "Die Straße nach Norden nach {area:1517} führt durch das {area:1877}: {npc:2817} und {npc:4618} nehmen die Flügel und die Flocken auf dem Weg an.",
		["The small elementals drift across the flats between {area:340} and {npc:2921}'s camp, on the road back east. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards."] = "Die kleinen Elementare treiben über die Ebenen zwischen {area:340} und dem Lager von {npc:2921}, auf dem Rückweg nach Osten. Jedes Felselementar im Gebiet kann die Felselementar-Splitter von {npc:6868} fallen lassen.",
		["Theldurin sits among the dwarven ruins at {area:345}, just east of the elementals. His tablet lies just inside {area:1517}'s cave mouth, beside level 38 elites: a quest for a group."] = "Theldurin sitzt zwischen den Zwergenruinen bei {area:345}, direkt östlich der Elementare. Seine Tafel liegt direkt im Höhleneingang von {area:1517}, neben Elites der Stufe 38: eine Quest für eine Gruppe.",
		["for Fizzle at the {area:2240}, on the way from {area:484} to {zone:1446} around level 43"] = "für Fizzle an der {area:2240}, auf dem Weg von {area:484} nach {zone:1446} bei etwa Stufe 43",
		["for Helgrum in {area:75}, around level 42"] = "für Helgrum in {area:75}, etwa ab Stufe 42",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge. {quest:1418} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "{area:340} ist die Festung der Horde, die in die Klippen am westlichen Rand des Gebiets gebaut ist. {quest:1418} steht auf der oberen Ebene von {area:340}, hoch über dem Flugmeister: Nimm die Rampen nach oben, der Pfeil kann die Ebenen nicht unterscheiden.",
		["{npc:2921}'s next study wants bracers from the Greater Rock Elementals (42-44) in the south-western gulches, well above you: leave it."] = "Die nächste Studie von {npc:2921} will Armschienen von den Größeren Felselementaren (42-44) in den südwestlichen Schluchten, weit über dir: Lass sie liegen.",
		["{npc:6868}, inside"] = "{npc:6868}, drinnen",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: Fizzles Brief aus {area:439}",
		["{zone:1418}: kill these as you meet them"] = "{zone:1418}: Töte diese, wenn sie dir begegnen",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "„Sea Wolf“ MacKinley, im obersten Stockwerk",
		["Draenethyst crystals"] = "Draenethystkristalle",
		["Felsteed: Zevrost in {zone:1454}, then {npc:6251} in {area:392}, on the {zone:1444} guide's {zone:1454} stop."] = "Teufelsross: Zevrost in {zone:1454}, dann {npc:6251} in {area:392}, beim Halt in {zone:1454} im Guide für {zone:1444}.",
		["Fly back to {object:3202}: Zul'Mamwe's Skullsplitters are just east of it."] = "Flieg zurück nach {object:3202}: Die Schädelspalter von Zul'Mamwe sind gleich östlich davon.",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the road east from {zone:1431} through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp just off the road where it comes in from {zone:1430}."] = "Folge der Straße von {zone:1431} durch {zone:1430} nach Osten in den Sumpf. {npc:1776} wartet bei {area:657}, dem Draenei-Lager direkt an der Straße, dort wo sie aus {zone:1430} kommt.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Weiter nördlich graben die Goblins der Venture Co. in der Mine östlich der Straße; Minenarbeiter, Vorarbeiter, Landvermesser und Tüftler lassen alle die Kristalle fallen.\nVorsicht: Getarnte Shadowmaw Panthers und Stranglethorn Tigresses streifen um das Lager.",
		["Gringer, the flight master, waits on {area:35}'s upper deck. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Gringer, der Flugmeister, wartet auf dem Oberdeck von {area:35}. Die Questgeber stehen auf den Stegen rund um den Hafen und im Gasthaus.",
		["Head east to {area:75}, in the reeds south of the road."] = "Geh nach Osten nach {area:75}, im Schilf südlich der Straße.",
		["Head north up the road to the hunters' camp."] = "Geh die Straße nach Norden hinauf zum Lager der Jäger.",
		["Head north up the road; the hunters camp on the hill above the river."] = "Geh die Straße nach Norden hinauf; die Jäger lagern auf dem Hügel über dem Fluss.",
		["Head north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Geh nach Nordosten zum {area:76}. Die Kristalle stehen am Weg hinauf zum Käfig von {npc:5391}.",
		["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "Geh nach Süden nach {area:35}. Shaky Phillipe wartet an den Docks.",
		["Head west to {object:3202}."] = "Geh nach Westen nach {object:3202}.",
		["His strongbox waits at his old camp north of {area:75}, on the way back west."] = "Seine Truhe steht in seinem alten Lager nördlich von {area:75}, auf dem Rückweg nach Westen.",
		["Inside"] = "Drinnen",
		["Into the {zone:1435}"] = "In die {zone:1435}",
		["Jungle Stalkers"] = "Dschungelpirscher",
		["Jungle stalkers"] = "Dschungelpirscher",
		["Keep {quest:571}, {quest:621} and {npc:737}'s tusks: the Skullsplitter chief, Zanzil's camps, the naga coast and {area:35} come on your Stranglethorn stop at about 45, after the {zone:2548}."] = "Behalte {quest:571}, {quest:621} und die Hauer für {npc:737}: Der Häuptling der Schädelspalter, Zanzils Lager, die Naga-Küste und {area:35} kommen bei deinem Halt im Schlingendorntal mit etwa 45, nach {zone:2548}.",
		["Lashtail Raptors"] = "Lashtail-Raptoren",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Verlass den Ort durch den Tunnel; die Notiz liegt in der Piratenbucht gleich nördlich von {area:35}.",
		["MacKinley: keep it, the ghost pirates (43-44) wait for your Stranglethorn stop at about 45"] = "MacKinley: Behalte sie, die Geisterpiraten (43-44) warten auf deinen Halt im Schlingendorntal mit etwa 45",
		["Mistvale gorillas"] = "Nebeltalgorillas",
		["Nesingwary's camp"] = "Lager von Nesingwary",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Noboru wandert über die Lichtung südwestlich vom {area:76}; sein Knüppel startet eine Quest.",
		["Riding at 40"] = "Reiten mit 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a Galestrider, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454} and fly to {zone:1456}: the skyboat to {zone:2521} leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes, and {npc:265756} teaches Skyborne at the {area:17684} in {area:16638}. Then back to {zone:1454} for the {object:3202} zeppelin. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen bekommst du einen Sturmschreiter, und {zone:2548} nach Stranglethorn sind ohne einen ein langer Fußmarsch. Nimm den Zeppelin vom Turm bei {object:3202} nach {zone:1454} und flieg nach {zone:1456}: Das Himmelsboot nach {zone:2521} legt etwa alle fünf Minuten an den Klippen südlich von {area:17045} ab, nördlich von {zone:1456}, und {npc:265756} lehrt Himmelsgeborene in {area:17684} in {area:16638}. Dann zurück nach {zone:1454} zum Zeppelin nach {object:3202}. Zu wenig Gold? Überspringe diesen Schritt: Der Guide für {zone:1444} kommt mit etwa 45 wieder durch {zone:1454}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454} and go south down the {zone:1411} road to {area:367}: {npc:7953} teaches Trolls there, with Zjolnir's raptors (20 gold each). Then back to the zeppelin for {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen bekommst du ein Reittier, und {zone:2548} nach Stranglethorn sind ohne eins ein langer Fußmarsch. Nimm den Zeppelin vom Turm bei {object:3202} nach {zone:1454} und geh die Straße durch {zone:1411} nach Süden bis {area:367}: {npc:7953} lehrt dort Trolle, bei Zjolnirs Raptoren (je 20 Gold). Dann zurück zum Zeppelin nach {object:3202}. Zu wenig Gold? Überspringe diesen Schritt: Der Guide für {zone:1444} kommt mit etwa 45 wieder durch {zone:1454}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}, fly to {zone:1456} and ride down to {area:222}: {npc:3690} teaches Tauren there, with {npc:3685}'s kodos (20 gold each). Then fly back to {zone:1454} for the {object:3202} zeppelin. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1456} again at about 45."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen bekommst du ein Reittier, und {zone:2548} nach Stranglethorn sind ohne eins ein langer Fußmarsch. Nimm den Zeppelin vom Turm bei {object:3202} nach {zone:1454}, flieg nach {zone:1456} und reite hinunter nach {area:222}: {npc:3690} lehrt dort Tauren, bei den Kodos von {npc:3685} (je 20 Gold). Dann flieg zurück nach {zone:1454} zum Zeppelin nach {object:3202}. Zu wenig Gold? Überspringe diesen Schritt: Der Guide für {zone:1444} kommt mit etwa 45 wieder durch {zone:1456}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}: {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel (wolves 20 gold each). Then the zeppelin back to {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen bekommst du ein Reittier, und {zone:2548} nach Stranglethorn sind ohne eins ein langer Fußmarsch. Nimm den Zeppelin vom Turm bei {object:3202} nach {zone:1454}: {npc:4752} lehrt Orcs im {object:172958}, beim Zwinger von {npc:3362} (Wölfe je 20 Gold). Dann mit dem Zeppelin zurück nach {object:3202}. Zu wenig Gold? Überspringe diesen Schritt: Der Guide für {zone:1444} kommt mit etwa 45 wieder durch {zone:1454}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, a short ride north of the zeppelin towers, with {npc:4731}'s skeletal horses (20 gold each) beside her. Ride back to the towers for the {object:3202} zeppelin."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen bekommst du ein Reittier. Jedes Volk lernt es beim Lehrer des eigenen Volkes: Bei dir ist es {npc:4773} in {area:159}, ein kurzer Ritt nördlich der Zeppelintürme, mit den Skelettpferden von {npc:4731} (je 20 Gold) neben ihr. Reite zurück zu den Türmen für den Zeppelin nach {object:3202}.",
		["Sawtooth crocolisks"] = "Sägezahnkrokilisken",
		["Sawtooth snappers"] = "Sägezahnschnapper",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Skelettpferde: {npc:4731}, neben {npc:4773} in {area:159}.",
		["The Bloodsail ships"] = "Die Schiffe der Blutsegelbukaniere",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights.\nCareful: {npc:730}, a level 43 elite raptor, roams among the stalkers: leave him for {quest:195}'s group step."] = "Die Dschungelpirscher (40-41) jagen an der Küste südlich von {object:3202}. Sie liegen weit über dir: Zieh sie einzeln und ruh dich zwischen den Kämpfen aus.\nVorsicht: {npc:730}, ein Elite-Raptor der Stufe 43, streift zwischen den Pirschern umher: Lass ihn für den Gruppenschritt von {quest:195} liegen.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Die Krokilisken suhlen sich in den Tümpeln um {npc:5391}s Lager und südlich Richtung {area:75}; etwa jeder vierte lässt eine Flanke fallen.",
		["The naga explorers on the coast south of here (43-44) are for Bloads and Mok'thardin: keep both quests for your Stranglethorn stop at about 45."] = "Die Naga-Forscher an der Küste südlich von hier (43-44) sind für Bloads und Mok'thardin: Behalte beide Quests für deinen Halt im Schlingendorntal mit etwa 45.",
		["The scroll, {quest:624}, lies on the decks of the three ships off the {area:43}, crewed by pirates of 42-45 who come in pairs, with captains of 45-48: take it with a group. Its chain runs on through the {zone:1435}, {zone:1445} and the {zone:1425}."] = "Die Schriftrolle, {quest:624}, liegt auf den Decks der drei Schiffe vor {area:43}, bemannt von Piraten der Stufen 42-45, die paarweise auftreten, mit Kapitänen der Stufen 45-48: Mach das in einer Gruppe. Ihre Questreihe führt weiter durch {zone:1435}, {zone:1445} und {zone:1425}.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast.\nCareful: the Jungle Stalkers (40-41) are thick here: pull one at a time and rest between fights."] = "Die Pirscher-Raptoren jagen im Dschungel südlich von {object:3202}, hinaus Richtung Westküste.\nVorsicht: Die Dschungelpirscher (40-41) stehen hier dicht: Zieh sie einzeln und ruh dich zwischen den Kämpfen aus.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:728} ist ein Elite der Stufe 40: Die meisten Klassen schaffen ihn allein auf Stufe 42, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:730} ist ein Elite der Stufe 43: Die meisten Klassen schaffen ihn allein auf Stufe 45, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:731} ist ein Elite der Stufe 43: Die meisten Klassen schaffen ihn allein auf Stufe 45, aber du brauchst vielleicht Hilfe. Überspring ihn, wenn du allein bist.\nVorsicht: Tiger und getarnte Schattenschlundpanther streifen in seiner Nähe umher. Räum sie, bevor du ihn ziehst. Wenn er gezogen wird, ruft {npc:731} Kreaturen im Umkreis von 20 Metern zu Hilfe.",
		["Venture Co. mine"] = "Mine der Venture Co.",
		["Warlocks don't buy riding: your mount is the Felsteed, from your class quest. Zevrost in {zone:1454}'s {object:172960} starts it and {npc:6251} in {area:392} teaches it, both on the {zone:1444} guide's {zone:1454} stop at about 45."] = "Hexenmeister kaufen kein Reiten: Dein Reittier ist das Teufelsross aus deiner Klassenquest. Zevrost in {zone:1454}, {object:172960}, startet sie und {npc:6251} in {area:392} lehrt es, beides beim Halt in {zone:1454} im Guide für {zone:1444} mit etwa 45.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "Westlich der Expedition stehen die Häuptlinge der Bloodscalp, {npc:1061} und {npc:1062}, zusammen in den Ruinen von Zul'Kunda. Räum zuerst ihre Wachen weg und zieh dann die beiden.\nAn der Küste zwischen Zul'Kunda und {object:3202} teilt sich ein {npc:2635} (Stufe 38, Elite) die Spawnpunkte mit den gewöhnlichen Krokilisken: Töte ihn, wenn er da ist, und nimm seine Haut für {npc:2495} mit.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Das hast du beim früheren Besuch der Route hier verpasst: Es kommt jetzt zuerst. Es geht schnell und öffnet die Quests danach.",
		["Your level 40 training is in the {area:1497}: fly there from {area:340}, train, and take the zeppelin from the towers outside the city to {object:3202}."] = "Dein Training für Stufe 40 ist in {area:1497}: Flieg von {area:340} dorthin, trainiere und nimm an den Türmen vor der Stadt den Zeppelin nach {object:3202}.",
		["Your mount at 40"] = "Dein Reittier mit 40",
		["Zeppelin to {object:3202}"] = "Zeppelin nach {object:3202}",
		["Zul'Kunda"] = "Ruinen von Zul'Kunda",
		["Zul'Mamwe"] = "Ruinen von Zul'Mamwe",
		["for a later stop in the {zone:1435}"] = "für einen späteren Halt in den {zone:1435}",
		["from the {object:52}, in the ruins"] = "vom {object:52}, in den Ruinen",
		["the {area:16550}'s entrance, underwater"] = "der Eingang von {area:16550}, unter Wasser",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}, neben {npc:2497}",
		["{area:340} flight master"] = "Flugmeister in {area:340}",
		["{area:35} flight master"] = "Flugmeister von {area:35}",
		["{npc:1442}, upstairs"] = "{npc:1442}, oben",
		["{npc:1443}, on the top floor"] = "{npc:1443}, im obersten Stock",
		["{npc:2464}: for {npc:256418} in {area:16743}, the {zone:2548}' Horde fort, in the next guide"] = "{npc:2464}: für {npc:256418} in {area:16743}, dem Hordefort in {zone:2548}, im nächsten Guide",
		["{npc:2487}: keep it for the {area:43} at about 45"] = "{npc:2487}: Behalte sie für {area:43} mit etwa 45",
		["{npc:2488}, on the top floor: keep it for the {area:43} at about 45"] = "{npc:2488}, im obersten Stock: Behalte sie für {area:43} mit etwa 45",
		["{npc:2491}, in the inn: his bottles wash up on the {zone:1425} coast, around level 48"] = "{npc:2491}, im Gasthaus: Seine Flaschen werden an der Küste von {zone:1425} angespült, ungefähr auf Stufe 48",
		["{npc:2493}: keep it for the {area:43} at about 45"] = "{npc:2493}: Behalte sie für {area:43} mit etwa 45",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}, drinnen: {item:4105}",
		["{npc:2495}: the Snapjaw skins gathered earlier; inside"] = "{npc:2495}: die zuvor gesammelten Snapjaw-Häute; drinnen",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495}: {npc:2635} sonnt sich an der Küste zwischen Zul'Kunda und {object:3202}, später auf dieser Runde",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}, auf dem Balkon neben MacKinley",
		["{npc:2519}: the cavern entrance under the {area:104}, west of the camp"] = "{npc:2519}: der Höhleneingang unter dem {area:104}, westlich des Lagers",
		["{npc:2519}: the legend lies in Zul'Kunda, where this guide goes for {npc:1061}"] = "{npc:2519}: die Legende liegt in Zul'Kunda, wohin dieser Guide für {npc:1061} geht",
		["{npc:265756}, riding trainer, at the {area:17684} in {area:16638}"] = "{npc:265756}, Reitlehrer, in {area:17684} in {area:16638}",
		["{npc:3690}, riding trainer"] = "{npc:3690}, Reitlehrer",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, an den Docks: Gazlowes Brief, falls du ihn dabeihast",
		["{npc:4631}: {quest:97332}, after Zimmix's rescue; the package goes to {npc:259961} at {area:16727}, in the {zone:2548} guide"] = "{npc:4631}: {quest:97332}, nach Zimmix' Rettung; das Paket geht an {npc:259961} in {area:16727}, im Guide für {zone:2548}",
		["{npc:4752}, riding trainer"] = "{npc:4752}, Reitlehrer",
		["{npc:4773}, riding trainer"] = "{npc:4773}, Reitlehrerin",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} wird im {area:76} im Nordosten des Sumpfs gefangen gehalten. Befrei ihn und folge ihm hinaus; wehr die Sumpfkreaturen ab, die ihn verfolgen.",
		["{npc:5591}, inside"] = "{npc:5591}, drinnen",
		["{npc:716} collects the pages of {quest:338}: the trolls of the vale drop them now and then. Take his quest; each chapter he takes once you have all its pages."] = "{npc:716} sammelt die Seiten von {quest:338}: Die Trolle des Tals lassen sie ab und zu fallen. Nimm seine Quest an; jedes Kapitel nimmt er entgegen, sobald du alle seine Seiten hast.",
		["{npc:716}: every page of chapter I is in your bags"] = "{npc:716}: Alle Seiten von Kapitel I sind in deinen Taschen",
		["{npc:716}: every page of chapter II is in your bags"] = "{npc:716}: Alle Seiten von Kapitel II sind in deinen Taschen",
		["{npc:716}: every page of chapter III is in your bags"] = "{npc:716}: Alle Seiten von Kapitel III sind in deinen Taschen",
		["{npc:716}: every page of chapter IV is in your bags"] = "{npc:716}: Alle Seiten von Kapitel IV sind in deinen Taschen",
		["{npc:716}: the four chapters"] = "{npc:716}: die vier Kapitel",
		["{npc:729}, the tiger {npc:717} sent you after on your last visit, prowls the hilltop just south-west of the camp."] = "{npc:729}, der Tiger, auf den dich {npc:717} bei deinem letzten Besuch angesetzt hat, streift über die Hügelkuppe direkt südwestlich des Lagers.",
		["{npc:737}, upstairs"] = "{npc:737}, oben",
		["{npc:737}, upstairs, has his next errand now: the Skullsplitter tusks come from the trolls of Zul'Mamwe, later on this loop."] = "{npc:737}, oben, hat jetzt seinen nächsten Auftrag: Die Skullsplitter-Hauer stammen von den Trollen in Zul'Mamwe, später auf dieser Runde.",
		["{npc:737}, upstairs: the tusks come from the Skullsplitters, later on this loop"] = "{npc:737}, oben: Die Stoßzähne stammen von den Skullsplitters, später auf dieser Runde",
		["{npc:7953}, riding trainer"] = "{npc:7953}, Reitlehrer",
		["{object:3202} flight master"] = "Flugmeister von {object:3202}",
		["{quest:95770}: west of {object:3202}, swim out over the {area:104} and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast."] = "{quest:95770}: Schwimm westlich von {object:3202} hinaus über das {area:104} und tauch zum Höhleneingang im Riff; die Quest wird abgeschlossen, sobald du ihn findest. Lass die Höhle vorerst links liegen: Die Dschungelpirscher sind südlich an der Küste.",
		["{zone:1458} trainers"] = "Lehrer in {zone:1458}",
} end)()
t.guides["forever/horde/40-50/01b-riverglades"] = (function() return {
		["About 70 quests in Forever's new zone, from the fort of {area:16743}."] = "Etwa 70 Quests im neuen Gebiet von Forever, von der Festung {area:16743} aus.",
		["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "Durch das {area:3} nach {area:340}, der in die Klippen gebauten Festung der Horde am Westrand des Gebiets: Der Flugmeister steht am Fuß der Festung.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Zurück nach Norden am Ufer entlang: Gib die Murlocs und die Haut auf dem Weg zu den Krabblern an den Docks ab.",
		["Back through the port"] = "Zurück durch den Hafen",
		["Back to the port, from the north pier west through the docks."] = "Zurück zum Hafen, vom Nordpier nach Westen durch die Docks.",
		["Back to the port."] = "Zurück zum Hafen.",
		["Back to {area:16743}, where your Hearthstone is set: {npc:263190} on the fort's west side first, then {npc:256418}, {npc:256655} by the cook fire, {npc:256657} and {npc:258031} on your way east through the fort."] = "Zurück nach {area:16743}, wo dein Ruhestein gesetzt ist: zuerst {npc:263190} auf der Westseite der Festung, dann {npc:256418}, {npc:256655} am Kochfeuer, {npc:256657} und {npc:258031} auf deinem Weg nach Osten durch die Festung.",
		["Back to {npc:255829} on his hill. {npc:257062} runs the {quest:94668} just below it."] = "Zurück zu {npc:255829} auf seinem Hügel. {npc:257062} leitet direkt darunter {quest:94668}.",
		["Boat to {area:16727}"] = "Boot nach {area:16727}",
		["Bonegnaw"] = "Bonegnaw",
		["Down to the port."] = "Hinunter zum Hafen.",
		["Each bout is a fight in the ring below {npc:255829}'s hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) and {npc:257059} (45). Come in rested, with full health and mana; if a bout goes wrong, {npc:257062} offers it again."] = "Jeder Kampf findet im Ring unterhalb von {npc:255829}s Hügel gegen einen Elite statt: Buzzbeak (41), Kronk und Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) und {npc:257059} (45). Komm ausgeruht, mit voller Gesundheit und Mana; geht ein Kampf schief, bietet {npc:257062} ihn erneut an.",
		["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Nach Osten die Klippen entlang zum hinteren Ende des Piratenlagers: {npc:260390} wartet am Wasser, {npc:260391} neben ihm.",
		["East back to {area:16743}."] = "Zurück nach Osten nach {area:16743}.",
		["East back to {area:16743}: {npc:260931}'s word goes to {npc:256710}, and {npc:256710}'s to {npc:255829}, the ogres' chieftain."] = "Zurück nach Osten nach {area:16743}: {npc:260931}s Nachricht geht an {npc:256710} und {npc:256710}s an {npc:255829}, den Häuptling der Oger.",
		["East of Rog'mar, on the hill above the road to {area:16727}: {npc:263367} has his workshop there. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "Östlich von Rog'mar, auf dem Hügel über der Straße nach {area:16727}: Dort hat {npc:263367} seine Werkstatt. Die Gasschlote sind im Marschland südwestlich davon, bei deiner ersten Jagd für {npc:258031}.",
		["East to {area:16735}, the Alliance farm by the river: the farmhands work the fields and the feed satchels lie by the barns. {area:16744}, the Alliance outpost on the road, has guards: pass south of it.\nCareful: {npc:263380}, an elite (level 42), hunts along the river by the farm: keep an eye on the riverbank."] = "Nach Osten nach {area:16735}, dem Allianzhof am Fluss: Die Feldarbeiter arbeiten auf den Feldern und die Futtersäcke liegen bei den Scheunen. {area:16744}, der Allianzaußenposten an der Straße, hat Wachen: Geh südlich daran vorbei.\nVorsicht: {npc:263380}, ein Elite (Stufe 42), jagt am Fluss beim Hof: Behalte das Flussufer im Auge.",
		["Finish the {item:268632}"] = "Sammle die restlichen {item:268632}",
		["Fly to {area:340}"] = "Flieg nach {area:340}",
		["Fly to {area:484}"] = "Flieg zum {area:484}",
		["Frazzlespark's crate from the port goes to {npc:256418}, in the middle of the fort."] = "Frazzlesparks Kiste vom Hafen geht an {npc:256418} in der Mitte der Festung.",
		["Into the {area:16591}"] = "Hinein nach {area:16591}",
		["Kronk"] = "Kronk",
		["Learn {area:976}'s flight path: it saves the ride next time."] = "Lerne die Flugroute von {area:976}: Das spart beim nächsten Mal den Ritt.",
		["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42) wanders the shore and {npc:263380} (elite, 42) the river: take your beasts away from them."] = "Die meisten Bestien im {zone:2548} droppen {item:268632} für {npc:260231}: die Uferkriecher an dieser Küste und die Eber auf dem Kamm westlich der Piraten.\nVorsicht: {npc:257001} (Elite, 42) streift am Ufer umher und {npc:263380} (Elite, 42) am Fluss: Zieh deine Bestien von ihnen weg.",
		["New in Forever: if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\n{npc:255897} keeps a stall at the west end of the docks. The port's other jobs are for later in this guide: this crate goes to the Horde's fort."] = "Neu in Forever: Wenn ein Schritt falsch ist, sag es uns auf Polestars Discord oder GitHub und nenne den Schritt.\n{npc:255897} hat einen Stand am Westende der Docks. Die übrigen Aufträge des Hafens kommen später in diesem Guide: Diese Kiste geht an die Festung der Horde.",
		["New in Forever: this guide follows what players did in the {area:16591}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nFrom {area:340}, ride south-east across the {area:3} to the zone's southern edge: the pass of {area:16685} leads down into the {area:16591}. {area:16743}, the Horde's fort, stands in the middle of the zone, east along the valley."] = "Neu in Forever: Dieser Guide folgt dem, was Spieler in {area:16591} gemacht haben. Wenn ein Schritt falsch ist, sag es uns auf Polestars Discord oder GitHub und nenne den Schritt.\nReite von {area:340} nach Südosten durch {area:3} zum Südrand des Gebiets: Der Pass von {area:16685} führt hinab nach {area:16591}. {area:16743}, die Festung der Horde, liegt in der Mitte des Gebiets, östlich das Tal entlang.",
		["New in Forever: this guide follows what players did in the {zone:2548}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nThe {zone:2548} lie across the sea from {zone:1446}: a goblin boat sails from {area:977}, north-east of {area:976}, to {area:16727}. Fly to {area:484} in {zone:1441} and head south-east through the {area:439} to {area:976}. (If you already know {area:340} in the {area:3}, the way in through {area:16685} works too.)"] = "Neu in Forever: Dieser Guide folgt dem, was Spieler in {zone:2548} gemacht haben. Wenn ein Schritt falsch ist, sag es uns auf Polestars Discord oder GitHub und nenne den Schritt.\n{zone:2548} liegt jenseits des Meeres von {zone:1446}: Ein Goblinboot fährt von {area:977}, nordöstlich von {area:976}, nach {area:16727}. Flieg nach {area:484} in {zone:1441} und reise nach Südosten durch {area:439} nach {area:976}. (Wenn du {area:340} in {area:3} schon kennst, geht auch der Weg über {area:16685}.)",
		["North along the beach from the docks: the crawlers drop the meat for {npc:259962}, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "Von den Docks nach Norden den Strand entlang: Die Kriecher droppen das Fleisch für {npc:259962}, und ihre Innereien zählen für {npc:260231}. {npc:260235}, eine große Krabbe, krabbelt über die Felsen östlich der Docks. {npc:259758}, ein Rare-Elite der Stufe 49, streift von den Docks bis zum Piratenlager an dieser Küste umher: Wenn du ihn siehst, halte großen Abstand.",
		["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. Watch for {npc:259758} on these cliffs.\nCareful: the Eastsea Raiders are level 44-45, a level or two over you here: pull them one at a time from the edge of the slopes and keep clear of the camp behind them."] = "Vom Hafen nach Norden die Küste entlang: Die Plünderer und Bombardiere der Ostsee haben sich an den Hängen westlich des Freibeuterlagers zwischen ihren Pulverfässern verschanzt. Achte auf diesen Klippen auf {npc:259758}.\nVorsicht: Die Plünderer der Ostsee sind Stufe 44-45, hier ein oder zwei Stufen über dir: Zieh sie einzeln vom Rand der Hänge und halte dich vom Lager dahinter fern.",
		["North of the camps the cult works ogre miners in a mine: talk five of them into rising up against their masters.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in."] = "Nördlich der Lager lässt der Kult Ogerminenarbeiter in einer Mine schuften: Überrede fünf von ihnen, sich gegen ihre Herren zu erheben.\nVorsicht: Twilight-Vollstrecker (Elite, Stufe 45) laufen auf ihrem Weg durch die Lager am Mineneingang vorbei. Warte, bis einer vorbei ist, bevor du hineingehst.",
		["North of the fort the Rog'mar Trainees drill: use {npc:256655}'s {item:265066} on them.\nCareful: {npc:263380}, an elite (level 42), can come up from the river south of the fort: let him pass."] = "Nördlich der Festung exerzieren die Lehrlinge von Rog'mar: Benutze {npc:256655}s {item:265066} an ihnen.\nVorsicht: {npc:263380}, ein Elite (Stufe 42), kann vom Fluss südlich der Festung heraufkommen: Lass ihn vorbeiziehen.",
		["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "Nach Nordosten die Küste entlang zum Lager der Piraten auf den Klippen. Die Freibeuter und Musketiere tragen die Schmuggelware. Auch {npc:259758} streift durch das Lager: Halte nach ihm Ausschau.",
		["North-east from {area:16743} up into the hills: {npc:256728} watches the Paletusk boars from his camp."] = "Von {area:16743} nach Nordosten hinauf in die Hügel: {npc:256728} beobachtet von seinem Lager aus die Bleichhauer-Eber.",
		["North-east to the workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "Nach Nordosten zur Werkstatt. Der Belastungstest von {npc:263367} ist ein Kampf gegen seinen G45-B4G neben der Werkstatt: Gib die Quest ab, sobald er besiegt ist.",
		["North-west to {area:16726}, the ogres' town. {npc:255829}, its chieftain, sits on the hill. The ogres are friendly while you leave them alone."] = "Nach Nordwesten nach {area:16726}, der Stadt der Oger. {npc:255829}, ihr Häuptling, sitzt auf dem Hügel. Die Oger sind freundlich, solange du sie in Ruhe lässt.",
		["Rotflesh Mushrooms"] = "Faulfleischpilze",
		["Snufflesnout (44)"] = "Schnüffelschnauze (44)",
		["South down the hills, round the west side of the Alliance scouts' camp: tap the Young Paletusks with {npc:256728}'s staff to send them home; the Mature Paletusks around the hills drop the boar meat."] = "Nach Süden die Hügel hinab, an der Westseite des Späherlagers der Allianz vorbei: Tippe die Jungen Bleichhauer mit {npc:256728}s Stab an, um sie nach Hause zu schicken; die Ausgewachsenen Bleichhauer in den Hügeln droppen das Eberfleisch.",
		["South-east back towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "Nach Südosten zurück zum Hafen: Die Uferkriecher am Strand nördlich der Docks liefern die Innereien am schnellsten. {npc:259758} kommt auch an diesen Strand herunter.",
		["South-east down out of the hills to {area:16727}, the goblins' harbour on the coast. {npc:255897} keeps a stall at the west end of the docks, {npc:259962} cooks by the inn, and {npc:259961} works the north pier."] = "Nach Südosten aus den Hügeln hinab nach {area:16727}, dem Hafen der Goblins an der Küste. {npc:255897} hat einen Stand am Westende der Docks, {npc:259962} kocht beim Gasthaus und {npc:259961} arbeitet am Nordpier.",
		["South-east of Rog'mar the plains run down to {area:16729}. The Low Plains Buzzards circle everywhere; a picked carcass lies in the grass (its skull starts {quest:96103}), and the marsh vents are just past it."] = "Südöstlich von Rog'mar fallen die Ebenen bis zu {area:16729} ab. Überall kreisen Tiefebenenbussarde; im Gras liegt ein abgenagter Kadaver (sein Schädel startet {quest:96103}), und die Schlote im Marschland liegen gleich dahinter.",
		["South-east out of the hills: {npc:262399}, a prospector who deals with both sides, has camped by the Cinderscale dragonkin's hollow."] = "Nach Südosten aus den Hügeln: {npc:262399}, eine Prospektorin, die mit beiden Seiten handelt, lagert bei der Senke der Aschenschuppen-Drachkin.",
		["South-west across the river to the Alliance lumber camp. The lumberjacks carry the axes. Loot Wood Bundles from the Peasant Woodpiles around the camp and use them to fletch Makeshift Stickin' Spears. {npc:263380}, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass."] = "Nach Südwesten über den Fluss zum Holzfällerlager der Allianz. Die Holzfäller tragen die Äxte. Plündere Holzbündel aus den Holzstapeln der Bauern rund um das Lager und fertige daraus Behelfsmäßige Stechspeere. {npc:263380}, ein Elite (Stufe 42), streift am Fluss beim Lager umher: Wenn er in deine Richtung kommt, zieh dich zurück und lass ihn vorbei.",
		["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "Vom Hafen nach Südwesten am Ufer entlang: Die Salzwassermurlocs lagern an den Stränden. Unterwegs ist neben dem Pfad eine bemalte Haut aufgespannt: Sie startet {quest:95260} für {npc:260231} an den Docks.",
		["South-west of Rog'mar the river runs between the farms: impale the Freshwater Crocolisks with {npc:263190}'s spears. The Alliance trains its scouts and priests at a camp on the far bank. {npc:257079}, the Alliance elite, rides the road just east of the camp: pull the scouts and priests away from it.\nCareful: {npc:263380}, an elite (level 42), hunts along this river: if he comes your way, back off and let him pass."] = "Südwestlich von Rog'mar fließt der Fluss zwischen den Höfen: Spieße die Süßwasserkrokilisken mit {npc:263190}s Speeren auf. Die Allianz bildet in einem Lager am anderen Ufer ihre Späher und Priester aus. {npc:257079}, der Allianz-Elite, reitet die Straße direkt östlich des Lagers ab: Zieh die Späher und Priester von ihr weg.\nVorsicht: {npc:263380}, ein Elite (Stufe 42), jagt entlang dieses Flusses: Wenn er in deine Richtung kommt, zieh dich zurück und lass ihn vorbeiziehen.",
		["The Cinderscale hollow"] = "Die Senke der Glutschuppen",
		["The Eastsea pirates"] = "Die Ostmeerpiraten",
		["The Glade Vipers hide in the long grass south-east of town; the Roving Tallstriders graze beside them. {npc:257079}, an Alliance elite (level 45), rides the road from {area:16729} to {area:16725} along the grass's south-west edge: keep clear of him."] = "Die Lichtungsvipern verstecken sich im hohen Gras südöstlich der Stadt; die Umherstreifenden Weitschreiter grasen daneben. {npc:257079}, ein Elite der Allianz (Stufe 45), reitet die Straße von {area:16729} nach {area:16725} entlang des Südwestrands der Wiese: Halte dich von ihm fern.",
		["The Twilight Maulers and Firecallers camp on the ridge east of {npc:256728}. {npc:260973}, who carries the {item:269257}, stands among them. Just south of the ogres, {npc:260211} (an Alliance elite, level 42) and his Farholde Ambushers hold the scouts' camp: keep north of it unless you came with a group for him."] = "Die Schattenhammerzerfleischer und Feuerrufer lagern auf dem Grat östlich von {npc:256728}. {npc:260973}, der {item:269257} trägt, steht zwischen ihnen. Direkt südlich der Oger halten {npc:260211} (ein Allianz-Elite, Stufe 42) und seine Hinterhältigen von Farholde das Lager der Späher: Bleib nördlich davon, außer du bist mit einer Gruppe für ihn gekommen.",
		["The Twilight camps"] = "Die Lager des Schattenhammers",
		["The Twilight ogres' camp"] = "Das Lager der Schattenhammeroger",
		["The Wildplains lions roam the plains just south of {area:16743}.\nCareful: {npc:263315}, an elite lion (level 41), prowls the same plains around 59.6,53.2: keep an eye out for him and pull the lions away from where he walks."] = "Die Löwen der Wildebenen streifen durch die Ebenen gleich südlich von {area:16743}.\nVorsicht: {npc:263315}, ein Elite-Löwe (Stufe 41), streift durch dieselben Ebenen um 59.6,53.2: Halte nach ihm Ausschau und zieh die Löwen von seinem Weg weg.",
		["The crawlers and {npc:260235}"] = "Die Krabbler und {npc:260235}",
		["The cultists fill the streets and fields; the Shadowmancers on the town's northern side carry the missives. The finger bones drop from all of them.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass."] = "Die Kultisten füllen Straßen und Felder; die Schattenbeschwörer auf der Nordseite des Dorfs tragen die Schreiben. Die Fingerknochen lassen alle fallen.\nVorsicht: {npc:256899}, ein Elite-Oger (Stufe 41), läuft durch die westlichen Straßen von {area:16723}, um 44-47,47-52. Zieh die Kultisten zu dir heraus und lass ihn vorbeiziehen.",
		["The lions"] = "Die Löwen",
		["The murlocs, south-west"] = "Die Murlocs im Südwesten",
		["The ogre mine"] = "Die Ogermine",
		["The paletusks"] = "Die Bleichhauer",
		["The pirates' second wave"] = "Die zweite Welle der Piraten",
		["The pirates' ships"] = "Die Schiffe der Piraten",
		["The plains and the marsh"] = "Die Ebenen und das Marschland",
		["The ritual grounds"] = "Die Ritualstätte",
		["The ritualists and their empowered brutes gather at the ritual circles in the middle of {area:16723}: wreck five of the circles.\nCareful: {npc:256899}, the elite ogre (level 41), walks through here from the western streets: watch for him before each pull."] = "Die Ritualisten und ihre verstärkten Schläger versammeln sich an den Ritualkreisen mitten in {area:16723}: Zerstöre fünf der Kreise.\nVorsicht: {npc:256899}, der Elite-Oger (Stufe 41), kommt von den westlichen Straßen hier durch: Achte vor jedem Pull auf ihn.",
		["The river and the Farholde camp"] = "Der Fluss und das Lager von Farholde",
		["The training grounds"] = "Der Übungsplatz",
		["The vipers and the tallstriders"] = "Die Vipern und die Weitschreiter",
		["The whelps nest all over the hollow; the warriors guard its back, by the {item:271611}. The warriors are level 41-42: pull them one at a time. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."] = "Die Welpen nisten überall in der Senke; die Krieger bewachen ihren hinteren Teil bei {item:271611}. Die Krieger sind Stufe 41-42: Zieh sie einzeln. Scaldaron, ein Rare-Elite-Drache, kann auch hier oben sein: Lass ihn in Ruhe, außer du hast eine Gruppe.",
		["The {area:16737}"] = "{area:16737}",
		["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "{npc:260244} streift durch das seichte Wasser südwestlich des Hafens, unterhalb der Strände der Murlocs. {npc:257001}, ein Elite, läuft ganz in der Nähe am Ufer entlang: Halte Abstand zu ihm.",
		["The {object:628948} poster by the inn"] = "Das Plakat {object:628948} beim Gasthaus",
		["The {object:628948} poster by the inn: {npc:260235}"] = "Das Plakat {object:628948} beim Gasthaus: {npc:260235}",
		["The {quest:94670}: Buzzbeak"] = "{quest:94670}: Buzzbeak",
		["The {quest:94670}: Kronk and Bonegnaw"] = "{quest:94670}: Kronk und Bonegnaw",
		["The {quest:94962}: {npc:258626}"] = "{quest:94962}: {npc:258626}",
		["West back to {area:16743}'s east side."] = "Nach Westen zurück zur Ostseite von {area:16743}.",
		["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "Westlich vom nördlichen Schiff den Grat hinauf: Die Faulfleischpilze wachsen zwischen den Felsen, nahe dem Lager der Oger des Schattenhammers. Die Ausgewachsenen Bleichhauer auf dem Grat geben ebenfalls Innereien.",
		["West from {area:16743} through {area:16723} and on up the valley towards {area:16685}: {npc:258570}, {npc:256418}'s wayward warrior, keeps a camp in the hills below the Twilight cult's fortress."] = "Von {area:16743} nach Westen durch {area:16723} und weiter das Tal hinauf Richtung {area:16685}: {npc:258570}, {npc:256418}s abtrünniger Krieger, hat ein Lager in den Hügeln unterhalb der Festung des Schattenhammerkults.",
		["West into the {area:16737}: the Redridge gnolls camp along the slopes and carry the stolen ore. Work south-west through their camps.\nCareful: {npc:255906}, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."] = "Nach Westen in {area:16737}: Die Gnolle des Rotkammgebirges lagern an den Hängen und tragen das gestohlene Erz. Arbeite dich nach Südwesten durch ihre Lager.\nVorsicht: {npc:255906}, ein Elite-Gnoll (Stufe 40), streift durch die südwestlichen Lager: Zieh die Gnolle von ihm weg.",
		["West to {area:16723} again: {npc:260931}, a Twilight miner who wants out, waits at the town's eastern edge. Talk him round, then hand {npc:256710}'s quest in; one of the missing ogres stands a few steps west."] = "Wieder nach Westen nach {area:16723}: {npc:260931}, ein Schattenhammer-Bergarbeiter, der aussteigen will, wartet am Ostrand des Dorfs. Überrede ihn, dann gib {npc:256710}s Quest ab; einer der vermissten Oger steht ein paar Schritte westlich.",
		["West to {area:16743}, the Horde's fort in the middle of the zone. {npc:258031} stands on its east side, {npc:256657} and {npc:256418} in the middle with {npc:255993}, the wind rider master; {npc:256675} and {npc:263190} on the west side."] = "Nach Westen nach {area:16743}, der Festung der Horde in der Mitte des Gebiets. {npc:258031} steht auf der Ostseite, {npc:256657} und {npc:256418} in der Mitte bei {npc:255993}, der Windreitermeisterin; {npc:256675} und {npc:263190} auf der Westseite.",
		["West up the road from the port: {npc:263367} has his workshop on the hill. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "Vom Hafen die Straße nach Westen hinauf: {npc:263367} hat seine Werkstatt auf dem Hügel. Die Gasschlote sind im Marschland südwestlich davon, bei deiner ersten Jagd für {npc:258031}.",
		["beat Buzzbeak"] = "besiege Buzzbeak",
		["destroy 5 Twilight Ritual Circles"] = "5 Ritualkreise des Schattenhammers zerstören",
		["free five captive Rog'mar Scouts"] = "Befreie fünf gefangene Späher der Rog'mar",
		["help {npc:258048} reach {area:16726}"] = "hilf {npc:258048}, {area:16726} zu erreichen",
		["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "Führ {npc:259158} aus {area:16723} hinaus zu seinem Schatz westlich der Stadt",
		["recruit five Ogre Miners"] = "Rekrutiere fünf Ogerminenarbeiter",
		["talk {npc:260931} round"] = "{npc:260931} überreden",
		["the middle ship"] = "das mittlere Schiff",
		["the northern ship"] = "das nördliche Schiff",
		["the stress test: beat G45-B4G beside the workshop"] = "der Belastungstest: Besiege G45-B4G neben der Werkstatt",
		["the {object:645164} poster"] = "das Plakat {object:645164}",
		["{area:75} flight master"] = "Flugmeister in {area:75}",
		["{area:977} is on the coast north-east of {area:976}: wait on the pier for the goblin boat to {area:16727}."] = "{area:977} liegt an der Küste nordöstlich von {area:976}: Warte auf dem Pier auf das Goblinboot nach {area:16727}.",
		["{item:268505}, the southern ship"] = "{item:268505}, das südliche Schiff",
		["{item:268521}, on the Young Paletusks"] = "{item:268521}, an den Jungen Bleichhauern",
		["{item:268632} as you go"] = "{item:268632} nebenbei",
		["{item:269257}, from {npc:260973}"] = "{item:269257}, von {npc:260973}",
		["{item:271629}, from the Peasant Woodpiles"] = "{item:271629}, aus den Holzstapeln der Bauern",
		["{item:271629}: fletch it into Makeshift Stickin' Spears"] = "{item:271629}: fertige daraus Behelfsmäßige Stechspeere",
		["{item:769}, from the Mature Paletusks"] = "{item:769}, von den Ausgewachsenen Bleichhauern",
		["{npc:255829}, on the hill"] = "{npc:255829}, auf dem Hügel",
		["{npc:255897}: {quest:95296}, for {npc:260405} at {area:977} in the {zone:1444} & {zone:1446} guide"] = "{npc:255897}: {quest:95296}, für {npc:260405} in {area:977} im Guide {zone:1444} & {zone:1446}",
		["{npc:255906} is an elite gnoll (level 40) who roams the south-western camps of the {area:16737}: grouping up is advised."] = "{npc:255906} ist ein Elite-Gnoll (Stufe 40), der durch die südwestlichen Lager von {area:16737} streift: Eine Gruppe wird empfohlen.",
		["{npc:255993}, in the middle of the fort"] = "{npc:255993}, in der Mitte der Festung",
		["{npc:256418}: Aggro'gosh's report from {object:3202}, if you carry it"] = "{npc:256418}: Aggro'goshs Bericht aus {object:3202}, falls du ihn dabeihast",
		["{npc:256655}, by the cook fire"] = "{npc:256655}, am Kochfeuer",
		["{npc:256710} stands beside {npc:256418} in the middle of {area:16743}: now that the Farholde camp has had its lesson, he has work in {area:16723}."] = "{npc:256710} steht neben {npc:256418} mitten in {area:16743}: Jetzt, da das Lager von Farholde seine Lektion bekommen hat, hat er Arbeit in {area:16723}.",
		["{npc:256728}'s camp"] = "{npc:256728}s Lager",
		["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881} ist ein Elite (Stufe 46) in der Festung am Ende des Tals, umgeben von den Vollstreckern: Eine Gruppe wird empfohlen.",
		["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001} ist ein Elite (Stufe 42) am Südufer: Eine Gruppe ist ratsam.",
		["{npc:258031}'s elites"] = "Die Elites von {npc:258031}",
		["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158} will raus aus {area:16723}: Führ ihn nach Westen zu seinem Schatz am Stadtrand und halte die Kultisten von ihm fern.",
		["{npc:259961} on the north pier takes Lozgil's {item:277974}."] = "{npc:259961} am Nordpier nimmt Lozgils {item:277974} entgegen.",
		["{npc:260211} is an elite (level 42) at the Alliance scouts' camp in the hills south-east of {npc:256728}, where you go next: grouping up is advised. The poster hangs in the middle of the fort; {npc:258031} takes the eye, later in this guide."] = "{npc:260211} ist ein Elite (Stufe 42) im Lager der Allianz-Späher in den Hügeln südöstlich von {npc:256728}, wo du als Nächstes hingehst: Eine Gruppe wird empfohlen. Der Steckbrief hängt mitten in der Festung; {npc:258031} nimmt das Auge später in diesem Guide entgegen.",
		["{npc:260993}, a {area:16726} ogre, hides in the cave west of {npc:258570}'s camp."] = "{npc:260993}, ein Oger der {area:16726}, versteckt sich in der Höhle westlich des Lagers von {npc:258570}.",
		["{npc:261208}, a few steps west"] = "{npc:261208}, ein paar Schritte westlich",
		["{npc:263190}: {quest:95033}, for {npc:8115} at {area:1099} in the {zone:1444} guide"] = "{npc:263190}: {quest:95033}, für {npc:8115} in {area:1099} im Guide für {zone:1444}",
		["{npc:263315}, an elite lion (level 41), prowls the plains south of {area:16743}, where the lions are: grouping up is advised."] = "{npc:263315}, ein Elite-Löwe (Stufe 41), streift durch die Ebenen südlich von {area:16743}, wo die Löwen sind: Eine Gruppe wird empfohlen.",
		["{npc:263367}'s workshop"] = "Werkstatt von {npc:263367}",
		["{npc:263380} is an elite (level 42) who hunts along the river south-west of {area:16743}, by the Farholde camp you go to next: grouping up is advised. The poster hangs in the middle of the fort."] = "{npc:263380} ist ein Elite (Stufe 42), der am Fluss südwestlich von {area:16743} jagt, beim Lager von Farholde, zu dem du als Nächstes gehst: Eine Gruppe wird empfohlen. Das Plakat hängt in der Mitte der Festung.",
		["{quest:93976}: for {npc:255897} in {area:16727}, keep it"] = "{quest:93976}: für {npc:255897} in {area:16727}, behalte sie",
		["{quest:94669}: the Ring's bouts, one-on-one fights with elites (41-45); a deposit first"] = "{quest:94669}: die Kämpfe des Rings, Einzelkämpfe gegen Elites (41-45); zuerst eine Anzahlung",
		["{quest:94670}: Buzzbeak"] = "{quest:94670}: Buzzbeak",
		["{quest:94727}: for {npc:260931} in {area:16723}"] = "{quest:94727}: für {npc:260931} in {area:16723}",
		["{quest:94744}: for {npc:258570}, west of {area:16723}"] = "{quest:94744}: für {npc:258570}, westlich von {area:16723}",
		["{quest:95062}: for {npc:256418} in {area:16743}"] = "{quest:95062}: für {npc:256418} in {area:16743}",
		["{quest:95261}: the beasts' entrails come as you go; the mushrooms grow on the ridge west of the pirates"] = "{quest:95261}: Die Innereien der Bestien kommen nebenbei; die Pilze wachsen auf dem Kamm westlich der Piraten",
		["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267}: ein großes Ungeheuer im seichten Wasser südwestlich des Hafens, nahe {npc:257001}, dem Elite",
		["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293}: für {npc:260390} im Lager der Piraten",
		["{quest:95418}: for {npc:256710} in {area:16743}"] = "{quest:95418}: für {npc:256710} in {area:16743}",
		["{quest:95420}: for {npc:255829} in {area:16726}"] = "{quest:95420}: für {npc:255829} in {area:16726}",
		["{quest:95428}: for {npc:256418} in {area:16743}, later in this guide"] = "{quest:95428}: für {npc:256418} in {area:16743}, später in diesem Guide",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "„Sea Wolf“ MacKinley, im obersten Stockwerk",
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "Zurück nach Osten an {area:75} vorbei: Die Artefakte der Atal'ai liegen im Wasser und an den Ufern des {quest:1424}.",
		["Back west to {object:3202}."] = "Zurück nach Westen nach {object:3202}.",
		["Below ground"] = "Unter der Erde",
		["Coming from the {zone:2548}: {area:340}'s flight master stands at the foot of the fortress."] = "Aus {zone:2548} kommend: Der Flugmeister von {area:340} steht am Fuß der Festung.",
		["Flown in to {area:976}: the raceway is a short ride north over the {zone:1446} border.\nThe road from {area:484} to {zone:1446} runs past the {area:2240} on the {area:439}: {npc:4454} is in the gnomes' camp beside the track, {npc:4630} and {npc:4709} by the goblins' camp. {npc:4630} first, then {npc:4709}, who runs off to keep Rizzle busy; then take Rizzle's plans from the gnomes' camp and bring them back to {npc:4630}."] = "Mit dem Flug in {area:976} angekommen: Die Rennstrecke liegt einen kurzen Ritt nördlich, gleich hinter der Grenze zu {zone:1446}.\nDie Straße von {area:484} nach {zone:1446} führt an {area:2240} auf {area:439} vorbei: {npc:4454} ist im Lager der Gnome neben der Piste, {npc:4630} und {npc:4709} beim Lager der Goblins. Erst {npc:4630}, dann {npc:4709}, der losrennt, um Rizzle zu beschäftigen; dann nimm Rizzles Pläne aus dem Lager der Gnome und bring sie zu {npc:4630} zurück.",
		["Flown in: {area:976}'s quests first, by the flight master, then the {area:2240} is a short ride north over the {zone:1446} border."] = "Eingeflogen: Zuerst die Quests von {area:976} beim Flugmeister, dann ist {area:2240} ein kurzer Ritt nach Norden über die Grenze von {zone:1446}.",
		["Fly from {zone:1454} to {area:392}; {npc:6251} stands on the hill above the docks."] = "Flieg von {zone:1454} nach {area:392}; {npc:6251} steht auf dem Hügel über den Docks.",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:484}"] = "Flieg zum {area:484}",
		["Fly to {area:75}"] = "Flieg nach {area:75}",
		["Fly to {area:976}"] = "Flieg nach {area:976}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["For your {area:978} run, in the next guide: {quest:2864} wants scarab shells, and {npc:7804}, a short walk from the flight master, {quest:3042} from the Sandfury trolls."] = "Für deinen Run durch {area:978} im nächsten Guide: {quest:2864} will Skarabäuspanzer, und {npc:7804}, ein kurzes Stück vom Flugmeister entfernt, {quest:3042} von den Trollen der Sandfury.",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["Ironjaw Basilisks"] = "Eisenkieferbasilisken",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Kodos: {npc:3685}, neben {npc:3690} in {area:222}.",
		["Murlocs of the Misty Reed"] = "Murlocs am Nebelschilf",
		["North-west of the ruins, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "Nordwestlich der Ruinen hausen die Yetis in {area:1105}; jeder Yeti dort kann ein dickes Fell fallen lassen.",
		["Only with the distress beacon: any beast, gnoll or ogre in {zone:1444} can drop it, about one kill in a hundred; use it to start the quest. The robot sits in a small cave on the north side of {area:1105}, just north-west of the ruins. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock."] = "Nur mit dem Notsignal: Jedes Tier, jeder Gnoll und jeder Oger in {zone:1444} kann es fallen lassen, ungefähr bei jedem hundertsten Kill; benutze es, um die Quest zu starten. Der Roboter sitzt in einer kleinen Höhle an der Nordseite von {area:1105}, direkt nordwestlich der Ruinen. Eskortiere ihn zum Dock an der {area:1108}; Yetis und Gorillas überfallen dich unterwegs. Seine Belohnung wartet in {area:35} auf einen späteren Besuch.\nVorsicht: Während der Eskorte tauchen drei Hinterhalte auf, und der Roboter warnt dich vor jedem. Der erste sind 3 Yetis, direkt nachdem der Roboter die Höhle verlässt und zur Straße hinaufklettert. Der zweite sind 3 Gorillas, auf dem Pfad entlang der Klippe. Der dritte sind etwa 4 Gnolle, einer davon ein Zauberwirker, dort wo die Route zum Dock abbiegt.",
		["Pirate ghosts and Zanzil's camps"] = "Piratengeister und Zanzils Lager",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Raptoren: Zjolnir, neben {npc:7953} in {area:367}.",
		["Ride east to the Skullsplitter ruins east of the Venture Co. mine. The headhunters, berserkers and hunters roam the ruins.\n{npc:1059} (45) carries the Broken Armor for {quest:586}: he walks the south-western ruins with two guards and sometimes stands in a small cave there. Pull the guards first.\nCareful: {npc:1060}, an elite troll (level 44), stands in the southern ruins around 47.7,44.3: pull the headhunters and berserkers away from him."] = "Reite nach Osten zu den Ruinen der Skullsplitter östlich der Mine der Venture Co. Die Kopfjäger, Berserker und Jäger streifen durch die Ruinen.\n{npc:1059} (45) trägt die Zerbrochene Rüstung für {quest:586}: Er läuft mit zwei Wachen durch die südwestlichen Ruinen und steht manchmal in einer kleinen Höhle dort. Zieh zuerst die Wachen.\nVorsicht: {npc:1060}, ein Elite-Troll (Stufe 44), steht in den südlichen Ruinen bei 47.7,44.3: Zieh die Kopfjäger und Berserker von ihm weg.",
		["Ride north-east back to the port: {npc:7881}, the {npc:15165} and the Security Chief take what {area:1336} gave you. {area:976} is west of it."] = "Reite nach Nordosten zurück zum Hafen: {npc:7881}, {npc:15165} und der Sicherheitschef nehmen, was {area:1336} dir gegeben hat. {area:976} liegt westlich davon.",
		["Ride north-east to the goblin harbour on the coast."] = "Reite nach Nordosten zum Goblinhafen an der Küste.",
		["Ride south along the road towards {area:35}; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Reite auf der Straße nach Süden Richtung {area:35}; die Basilisken sonnen sich mitten im Dschungel auf den Felsen östlich davon. Ihre Splitter droppen oft.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Reite auf der Straße nach Westen; die Schriftrolle liegt am Wasser im äußersten Westen des Sumpfs.",
		["Ride west from the hive to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.\nCareful: the Mage-Lords (45-46) and the Shamans cast from range and the ruins are packed: pull one at a time from the edge."] = "Reite vom Bau nach Westen zu den Ogerruinen unterhalb von {area:1105}. Schamanen, Hexenmeister und Raufer füllen sie; die Magierfürsten am Südende tragen die Kugel.\nVorsicht: Die Magierfürsten (45-46) und die Schamanen zaubern aus der Ferne, und die Ruinen sind dicht besetzt: Zieh sie einzeln vom Rand aus.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Reiten und Galestrider: {npc:265756}, in den {area:17684} in {area:16638} auf Zephras Isle.",
		["Riding at 40"] = "Reiten mit 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Ride back up to {zone:1456}'s flight master afterwards."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; wenn du es lernst, bekommst du ein Reittier. Jede Rasse lernt es bei ihrem eigenen Rassenlehrer: deiner ist {npc:3690} in {area:222}, mit den Kodos von {npc:3685} (je 20 Gold) neben ihm. Reite danach zurück zum Flugmeister von {zone:1456}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:7953} in {area:367}, a short ride south of {zone:1454} down the {zone:1411} road, with Zjolnir's raptors (20 gold each) beside him. Ride back to {zone:1454}'s flight master afterwards."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; wenn du es lernst, bekommst du ein Reittier. Jede Rasse lernt es bei ihrem eigenen Rassenlehrer: deiner ist {npc:7953} in {area:367}, ein kurzes Stück südlich von {zone:1454} die Straße von {zone:1411} entlang, mit den Raptoren von Zjolnir (je 20 Gold) neben ihm. Reite danach zurück zum Flugmeister von {zone:1454}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; wenn du es lernst, bekommst du ein Reittier. {npc:4752} unterrichtet Orcs im {object:172958}, beim Zwinger von {npc:3362}. Himmelsgeborene lernen es bei {npc:265756} in {area:17684} in {area:16638} auf Zephras Isle, mit einem Galestrider: Das Himmelsboot zur Insel legt an den Klippen südlich von {area:17045}, nördlich von {zone:1456}, ungefähr alle fünf Minuten ab. Die anderen Reittiere deiner Rasse kosten je 20 Gold: Sammelobjekte, Reittiere · Stufe 40 hat für jedes einen Guide.",
		["Rogue Vale screechers"] = "Kreischer",
		["Sawtooth crocolisks"] = "Sägezahnkrokilisken",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Skelettpferde: {npc:4731}, neben {npc:4773} in {area:159}.",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns.\nCareful: {npc:222286} (level 43, elite) stands in the camp: pull the raiders and shamans away from her."] = "Die Tauren der Grimmtotem lagern neben dem Hain der Grimmlingflitzer; Räuber, Naturalisten und Schamanen tragen alle Hörner.\nVorsicht: {npc:222286} (Stufe 43, Elite) steht im Lager: Zieh die Räuber und Schamanen von ihr weg.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Die Marschenmurlocs leben am Strand südlich des Postens; die Marschentintenspucker sind am Ufer östlich davon und die Marschenfleischfresser weiter westlich, um die Hütten am Westufer.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "Die Woodpaw-Gnolle lagern in den Hügeln direkt nordwestlich von Mojache; jeder von ihnen kann eine Mähne fallen lassen.\nVorsicht: Jeder Woodpaw-Gnoll außer dem Alpha rennt bei 15% Gesundheit los, um Hilfe zu holen, wodurch weitere Gnolle in den Kampf gezogen werden können.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber.\nCareful: {quest:7731} is level 47: clear the hive around him and pull him alone at full health."] = "Der Bau der Zukk'ash gräbt sich in die Hügel südöstlich des Lagers; {quest:7731} wartet in seiner tiefsten Kammer.\nVorsicht: {quest:7731} ist Stufe 47: Räum den Bau um ihn herum und zieh ihn allein mit voller Gesundheit.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Der Schlachtplan liegt im Lager der Waldpfoten südlich von Mojache.",
		["The crocolisks wallow in the pools around Galen's old camp, just north of {area:75}, on the way back east; about one in four drops a flank."] = "Die Krokolisken suhlen sich in den Tümpeln rund um Galens altes Lager, direkt nördlich von {area:75}, auf dem Rückweg nach Osten; etwa jede vierte lässt eine Flanke fallen.",
		["The middle of {zone:1454}"] = "Die Mitte von {zone:1454}",
		["The same murloc shore again: Inkspewers east of the post, Flesheaters around the western huts, and the Oracles among both."] = "Dieselbe Murloc-Küste noch einmal: Inkspewers östlich des Postens, Flesheaters rund um die westlichen Hütten und die Oracles unter beiden.",
		["The shadow mages, rogues and assassins camp south-east of {area:976}.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Die Schattenmagier, Schurken und Assassinen lagern südöstlich von {area:976}.\nSüdöstlich von Gadgetzan lagern die Banditen der Wastewander in den Dünen; {npc:7847} steht im östlichen Lager.\nVorsicht: Wastewander Rogues bleiben außerhalb des Kampfes in Verstohlenheit, sodass versteckte Schurken in einen Kampf eingreifen können, den du an einem Lager beginnst.\nVorsicht: Zwei getarnte Wastewander Rogues begleiten ihn, wohin er auch geht. An seinem Spawn-Lager sind zwei Schattenmagier und ihre Diener nah genug, um in den Kampf mit ihm einzugreifen. Draußen bei den Türmen kannst du ihn ohne sie bekämpfen.",
		["The snappers line the strand south of the post.\nThe Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see, the ones on the ride down from the pool too.\nCareful: a {npc:272377} (level 60) walks the south-east strand: give it a wide berth."] = "Die Snapper säumen den Strand südlich des Postens.\nDie Monstrous Crawlers laufen an den Stränden der Ostküste, nur vereinzelt: Töte jeden, den du siehst, auch die auf dem Ritt hinab vom Teich.\nVorsicht: Am südöstlichen Strand läuft {npc:272377} (Stufe 60) umher: Mach einen weiten Bogen darum.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "Die Sprite Darters schwirren über den Hain direkt westlich von Mojache; fast jeder lässt einen Flügel fallen. Die Woodpaw Alphas führen die Lager südwestlich davon an: Töte sie innerhalb einer Stunde.\nVorsicht: Die meisten Alphas sitzen in kleinen Zeltlagern mit 2-4 anderen Gnollen, die in den Kampf eingreifen, und zwischen den Lagern patrouillieren weitere Gnolle.",
		["The {area:43}"] = "{area:43}",
		["To {area:75}"] = "Nach {area:75}",
		["To {area:976}"] = "Nach {area:976}",
		["Underwater"] = "Unter Wasser",
		["Upstairs"] = "Oben",
		["West into Mistvale: {npc:1449} sits among the gorillas. Any gorilla can drop a fang: hand him ten and stay by him, he calls three waves of gorillas, then {npc:1514}.\nCareful: three waves of gorillas come one after another with little rest between, then {npc:1514}. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy."] = "Nach Westen ins Nebeltal: {npc:1449} sitzt zwischen den Gorillas. Jeder Gorilla kann einen Reißzahn droppen: Gib ihm zehn und bleib bei ihm, er ruft drei Wellen Gorillas herbei, dann {npc:1514}.\nVorsicht: Drei Wellen Gorillas kommen kurz hintereinander, dann {npc:1514}. Starte mit voller Gesundheit und vollem Mana und bleib in Unbagwas Nähe. Manche Klassen tun sich allein schwer: Mit einem Freund ist es leicht.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Wölfe: {npc:3362}, neben {npc:4752}.",
		["Woodpaw battle map"] = "Schlachtplan der Waldpfoten",
		["Woodpaw north camp"] = "Nördliches Lager der Waldpfoten",
		["Your trainer is in {zone:1456}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins)."] = "Dein Lehrer ist in {zone:1456}: {npc:3033} (Druiden) auf {area:1639}, {npc:246344} (Paladine).",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["Zul'Mamwe"] = "Ruinen von Zul'Mamwe",
		["for {area:35}, around level 51 (40-50/06)"] = "für {area:35}, etwa um Stufe 51 (40-50/06)",
		["for {zone:1454}, after {zone:2652}"] = "für {zone:1454}, nach {zone:2652}",
		["the Rage Scar yetis, on the next visit to {zone:1444}"] = "die Rage Scar Yetis, beim nächsten Besuch in {zone:1444}",
		["the {item:8523} from these errands: keep it, Tanaris Field Sampling hands it back in {area:976}"] = "{item:8523} von diesen Aufträgen: behalte es, Tanaris Field Sampling gibt es in {area:976} zurück",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076} again: Yenniku's fate"] = "noch einmal {object:2076}: Yennikus Schicksal",
		["the {object:2076}: {quest:586}"] = "{object:2076}: {quest:586}",
		["{area:1105} yetis"] = "Yetis in {area:1105}",
		["{area:1336}: kill these as you meet them"] = "{area:1336}: Töte diese, sobald sie dir begegnen",
