		["{npc:669} walks around here: look inside the circle on the map"] = "{npc:669} läuft hier herum: schau in den Kreis auf der Karte",
		["{npc:737}, upstairs"] = "{npc:737}, oben",
		["{npc:773}, upstairs: for {quest:2864} in {area:976}, later in this guide"] = "{npc:773}, oben: für {quest:2864} in {area:976}, später in diesem Guide",
		["{npc:7777} walks around {area:1099}: look inside the circle on the map"] = "{npc:7777} läuft um {area:1099} herum: schau in den Kreis auf der Karte",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
		["{npc:7854}, inside"] = "{npc:7854}, drinnen",
		["{npc:7875}: for {npc:7010} in {zone:1454}"] = "{npc:7875}: für {npc:7010} in {zone:1454}",
		["{npc:7881}, inside"] = "{npc:7881}, drinnen",
		["{npc:7882}, inside"] = "{npc:7882}, drinnen",
		["{npc:7953}, riding trainer"] = "{npc:7953}, Reitlehrer",
		["{npc:8115}: {npc:263190}'s errand from the {zone:2548}, if you carry it"] = "{npc:8115}: Auftrag von {npc:263190} aus {zone:2548}, falls du ihn dabeihast",
		["{object:3202} flight master"] = "Flugmeister von {object:3202}",
		["{quest:2863}: one hour from now"] = "{quest:2863}: eine Stunde ab jetzt",
		["{zone:1444}: kill these as you meet them"] = "{zone:1444}: töte diese, wenn du sie triffst",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
		["{zone:2652} is next, a ride north from {area:1099} into {zone:1443}: keep your {zone:1454} hand-ins (Neeru, Zilzibin, {npc:4485}, {npc:7311}) for the flight there after it."] = "Als Nächstes kommt {zone:2652}, ein Ritt nach Norden von {area:1099} nach {zone:1443}: Behalte deine Abgaben für {zone:1454} (Neeru, Zilzibin, {npc:4485}, {npc:7311}) für den Flug dorthin danach.",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Below ground"] = "Unter der Erde",
		["East through the {area:511}: the Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Weiter östlich durch {area:511}: Die Firemane-Späher und Aschenschwänze streifen mit den Searing-Jungtieren und Welpen am Nordrand umher; die Scalebane bewachen die Drachenhöhlen weiter südöstlich. Mok'Morokks Schnupftabak, Grog und Truhe liegen in den Lagern der Drachkin.",
		["Fly to {area:1099}"] = "Flieg zum {area:1099}",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:496}"] = "Flieg nach {area:496}",
		["From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "Vom Flugmeister: {object:172960}, dann die Gasse, dann {object:172958}.",
		["Inside {area:498}"] = "In {area:498}",
		["Level 45.37"] = "Stufe 45.37",
		["Onyxia's eggs"] = "Onyxias Eier",
		["Ride back north to Brackenwall."] = "Reite zurück nach Norden nach Brackenwall.",
		["Ride south-west to the {object:2555}."] = "Reite nach Südwesten zu {object:2555}.",
		["Stays on the main route"] = "Bleibt auf der Hauptroute",
		["Takes you to level 47"] = "Bringt dich auf Stufe 47",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Die Eier von Onyxia liegen in den Drachenhöhlen im Südosten von {area:511}, bewacht von den Bannschuppen; zerschlag fünf.",
		["The {object:2555}"] = "{object:2555}",
		["Then on to {zone:1446}"] = "Dann weiter nach {zone:1446}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:1173} needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\n{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "Das sind Elite-Mobs: Sich zu gruppieren ist empfohlen, such dir Leute dafür. {quest:1173} braucht eine Gruppe von 3. Überspring sie, wenn du allein bist: Die Route lässt dich die EP wieder erarbeiten.\n{npc:4500} ist Elite: Gruppe empfohlen. Prügle ihn nieder, bis er aufgibt, und melde dich dann bei {npc:4501}.",
		["grind on {npc:4329}"] = "grinde {npc:4329}",
		["the {object:2555}"] = "{object:2555}",
		["{area:1099} flight master"] = "Flugmeister in {area:1099}",
		["{area:510}: kill these as you meet them"] = "{area:510}: töte diese, wenn du sie triffst",
		["{npc:4329} walks around {area:510}: look inside the circle on the map"] = "{npc:4329} läuft um {area:510} herum: schau in den Kreis auf der Karte",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon instead."] = "Die Herausforderung von {npc:4500}, zurück in Brackenwall, braucht eine Dreiergruppe. Allein grindest du hier am Nordrand von {area:511} die Späher der Feuermähnen bis Stufe 45.37, bevor du zurück nach Norden reitest, damit du dafür nicht noch einmal herunterkommen musst. Oder lauf mit einer Gruppe stattdessen den Dungeon {area:978}.",
		["{npc:4500}, {npc:4502} and {npc:4501} (below ground) are in the village; their quests are for the {area:511} on this trip."] = "{npc:4500}, {npc:4502} und {npc:4501} (unterirdisch) sind im Dorf; ihre Quests sind für {area:511} bei diesem Besuch.",
		["{npc:4501}, below ground"] = "{npc:4501}, unterirdisch",
		["{npc:6986}, the Drag"] = "{npc:6986}, die Gasse",
		["{npc:7010}, the Drag"] = "{npc:7010}, die Gasse",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Back east to Fizzledowser on the west side of {area:976}; {npc:7771} is south from there."] = "Zurück nach Osten zu Fizzledowser auf der Westseite von {area:976}; {npc:7771} liegt von dort südlich.",
		["Below ground"] = "Unter der Erde",
		["Below ground: the plans, on the {area:1443}'s upper ledge"] = "Unter der Erde: die Pläne, auf dem oberen Sims von {area:1443}",
		["Boat to {area:16727}"] = "Boot nach {area:16727}",
		["Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and {spell:686}. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."] = "Vorsicht: Shadow Mages (Stufe 42-43) rufen außerhalb des Kampfes einen Leerwandler und greifen mit Feuerbrand und {spell:686} an. Diebe können dich entwaffnen, Schurken bewegen sich im Schleichen, und Assassinen setzen Hinrichten ein, sobald du bei 20% Gesundheit oder darunter bist.",
		["Dark Iron Lookouts"] = "Ausgucke der Dunkeleisenzwerge",
		["Fly to {area:976}"] = "Flieg nach {area:976}",
		["For your {area:978} run, after {area:979}: {npc:7407}, by the water tower, wants his {quest:2768} back; {quest:2864} his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet."] = "Für deinen Run durch {area:978}, nach {area:979}: {npc:7407} beim Wasserturm will seinen {quest:2768} zurück; {quest:2864} seine Skarabäuspanzer und Trenton Lighthammer Troll Temper, falls du diese Quests noch nicht angenommen hast.",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Weiter südlich liegt die Ausrüstung von Junior Surveyor Scrimshank am Eingang eines Centipaar-Baus.\nVorsicht: Ein Käfer bewacht die Ausrüstung. Viele Käfer patrouillieren in den Tunneln, einige davon Stufe 50, sodass Kämpfe oft zusätzliche Adds ziehen.",
		["Heavy War Golems patrol the Cauldron below {npc:8479} and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it.\nThe Searing Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\n{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee. The biggest Incendosaurs and Lava Spiders are 49: pull them one at a time."] = "Schwere Kriegsgolems patrouillieren im Kessel unterhalb von {npc:8479} und lassen das Öl fallen; die Magma- und Lodernden Elementare, die zwischen ihnen umhertreiben, lassen die Herzen fallen. Die Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge treiben die Sklaven auf den Pfaden an; ein Sklavenhändler kann {item:11818} fallen lassen: Behalte ihn.\nDie Großen Lavaspinnen streifen über die Plateaus und Lavatümpel im Südwesten der Schlucht.\n{area:1443} öffnet sich im Norden des Kessels. Incendosaurier schwimmen in seinen Lavatümpeln: Zieh sie an den Rand. Die geheimen Pläne liegen auf dem oberen Sims der Grube.\nVorsicht: Sklavenhändler der Dunkeleisenzwerge (Stufe 45-46) rufen beim Pullen Verbündete im Umkreis von 15 yd zu Hilfe, wirken Netz aus bis zu 15 yd und benutzen Zerreißen im Nahkampf. Die größten Incendosaurier und Lavaspinnen sind 49: Zieh sie einzeln.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Seine nächste Bitte braucht das {item:10552} von Elitekultisten: Lass sie aus.",
		["Into {zone:1427}"] = "Hinein nach {zone:1427}",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "Behalte die Model 4711-FTZ-Energiequelle, die Bilgewhizzle dir gegeben hat: Sie startet {quest:654} mit einem Zwei-Stunden-Timer, also benutze sie erst auf dem Rückweg nach Norden von Scrimshanks Bau.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."] = "Nur mit dem Notsignal: OOX-17/TN sitzt südöstlich von Scrimshanks Bau. Eskortiere ihn nach Norden zu {area:977}; seine Belohnung wartet bei Oglethorpe in {area:35}.\nVorsicht: Die Eskorte hat zwei Hinterhalte. Drei Skorpide der Stufe 47 greifen nahe dem Anfang an. Gegen Ende, am Strand, greifen drei Menschen der Wastewander an: ein Magier und zwei Assassinen, ungefähr Stufe 44.",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Nur mit dem {item:11818}: zurück nach Osten zum {object:173265} an der Grabungsstätte.",
		["Ride back north to {area:1446}, just past {npc:8479}."] = "Reite zurück nach Norden zu {area:1446}, direkt hinter {npc:8479}.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Reite nach Nordwesten durch die Schlucht; {area:1446} ist das Lager mit den Gerüsten im Nordwesten.",
		["Ride south from {area:1446} into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below {npc:8479}. Careful: the biggest golems are 49: pull them one at a time."] = "Reite von {area:1446} nach Süden in den Kessel: Die Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge treiben die Sklaven auf den Pfaden an, und die Schweren Kriegsgolems patrouillieren am Boden unterhalb von {npc:8479}. Vorsicht: Die größten Golems sind 49: Zieh sie einzeln.",
		["Scrimshank's gear"] = "Scrimshanks Ausrüstung",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Die Ausgucke der Dunkeleisenzwerge stehen auf den Kämmen um die Wachtürme südlich des Kessels; etwa jeder zehnte trägt {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Die Dampfschmiede der Dunkeleisenzwerge arbeiten an den Öfen mitten im Kessel; die Hälfte trägt {item:10551}, jeder zehnte {item:18959}. Sklaven, Sklavenhändler und Zuchtmeister tragen auch Dolche.",
		["The Steamsmiths' furnaces"] = "Die Öfen der Dampfschmiede",
		["The flight lands beside {npc:7876}. Take the town's quests before riding west to {area:979}."] = "Der Flug landet neben {npc:7876}. Nimm die Quests der Stadt an, bevor du nach Westen zu {area:979} reitest.",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "Das Brett {object:179827}",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}: {npc:7407}, beim Wasserturm.",
		["The {quest:3042}: {npc:7804}, a short walk from the flight master."] = "{quest:3042}: {npc:7804}, ein kurzes Stück vom Flugmeister entfernt.",
		["Use the {item:8524}"] = "Benutze die {item:8524}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "Nach Westen entlang der Straße nach Süden; {npc:7771} lagert bei den Ruinen an der {area:1938}. Leg seinen {item:9978} an: Er zeigt die vergrabenen Ornamente, hier und rund um das {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Benutze westlich von Gadgetzan das {item:8584} neben dem Wasserloch im Trolllager.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers."] = "Im Westen schwärmen die Centipaar-Insekten um ihre Bauten; jedes von ihnen lässt die Teile fallen.\nVorsicht: Schwärmer der Centipaar wirken {npc:4196} im und außerhalb des Kampfes, was kleine Adds bringt, die dich unterbrechen. Die Sandplünderer sind 49-50: Nimm die Arbeiter und Tunnelgräber.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Das hast du beim früheren Besuch der Route hier verpasst: Es kommt jetzt zuerst. Es geht schnell und öffnet die Quests danach.",
		["Your {area:978} scarab shells: {npc:7876}, beside the wind rider master."] = "Deine Skarabäuspanzer aus {area:978}: {npc:7876}, neben dem Windreitermeister.",
		["for {npc:5204} in the {zone:1458}, around level 52"] = "für {npc:5204} in {zone:1458}, ungefähr auf Stufe 52",
		["for {npc:7010} in {zone:1454}, around level 50"] = "für {npc:7010} in {zone:1454}, etwa auf Stufe 50",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526} wächst im {zone:1425}, etwa auf Stufe 48",
		["the {object:173265}"] = "das {object:173265}",
		["{area:1099} flight master"] = "Flugmeister in {area:1099}",
		["{area:246}'s slavers and golems"] = "die Sklavenhalter und Golems von {area:246}",
		["{area:496} flight master"] = "Flugmeister von {area:496}",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the troll camp's water hole.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978} ist ein Dungeon für eine Gruppe aus fünf Spielern; seine Quests hier sind Stufe 45 bis 47. Das Tor liegt etwa 400 Meter nördlich des Wasserlochs im Trolllager.\nDrinnen: Die Skarabäen lassen die Panzer fallen, jeder Troll der Sandfury kann {quest:3042} fallen lassen, und {npc:7604} trägt {quest:2768} bei sich.",
		["{item:11818}, a rare drop"] = "{item:11818}, seltene Beute",
		["{item:8623}, a rare drop"] = "{item:8623}, seltene Beute",
		["{npc:5594}, inside"] = "{npc:5594}, drinnen",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} wartet im Tal. Bring ihn den ganzen Weg zu seiner Frau {npc:6015} in {area:977}, nach Nordosten durch die Wüste: Bleib nah bei ihm, geh langsam für ihn und wehr ab, was ihn angreift. Steig nicht auf und nutz keinen Ruhestein außerhalb seiner Reichweite. {npc:8579} steht auch im Hafen.",
		["{npc:5955}'s escort"] = "Eskorte: {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, neben dem Windreitermeister",
		["{npc:8479} stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "{npc:8479} steht allein südlich von {area:1446}, am Rand des Kessels. Hör dir seine Geschichte an.",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, drinnen",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: die Skarabäen, drinnen",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: die Trolle der Sandfury, drinnen",
		["{quest:3161} ornaments"] = "Ornamente für {quest:3161}",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362}: Töte diese, sobald sie dir begegnen",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427}: Töte diese, sobald sie dir begegnen",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Zurück nach Westen zur {area:350}; Waldläuferinnen und Schützen bleiben nahe der Jagdhütte, Späher und Kundschafterinnen an den Hängen südlich davon.",
		["Careful: Stealthed wolves and griffons roam the {area:1883} area."] = "Vorsicht: Getarnte Wölfe und Greifen streifen durch die Gegend von {area:1883}.",
		["East of the village, the violet flower grows in the hills."] = "Östlich des Dorfs wächst der Violette Tragan in den Hügeln.",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Fly to {area:75}"] = "Flieg nach {area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Folge den Straßen nach Osten durch das {zone:1425} zum Trolldorf an der Ostküste.",
		["Highvale"] = "Hochtal",
		["His next request, going on to the {area:355}, is for a group."] = "Seine nächste Bitte, weiter zu {area:355}, ist etwas für eine Gruppe.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. The trolls inside are elite: stay with your group and keep to the paths."] = "Huntsman Malkhors Schädel liegt auf einem Haufen unterhalb der Ruinen der Vilebranch, seine Knochen auf einem Haufen am Fuß von {area:354}. Die Vessels of Tainted Blood stehen auf den unteren Terrassen, und {npc:14757} wird oben festgehalten. Die Trolle darin sind Elite: Bleib bei deiner Gruppe und halte dich an die Pfade.",
		["If you skipped {quest:7816} or the {area:354} group quests, grind here to level 49.02 to stay on the route's plan."] = "Wenn du {quest:7816} oder die Gruppenquests von {area:354} übersprungen hast, grinde hier bis Stufe 49,02, um im Plan der Route zu bleiben.",
		["Level 49.02"] = "Stufe 49,02",
		["No flight path to {area:75} yet: the arrow takes the quickest way there (by the {object:3202} flight and the road through {zone:1431} and {zone:1430}). Learn {area:75}'s flight path when you arrive."] = "Noch keine Flugroute nach {area:75}: Der Pfeil nimmt den schnellsten Weg dorthin (mit dem Flug nach {object:3202} und der Straße durch {zone:1431} und {zone:1430}). Lerne die Flugroute von {area:75}, wenn du ankommst.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Nördlich an der Küste steht der Picknickkorb von {npc:14731} auf der kleinen Insel; ein {npc:14748} bewacht ihn.",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the top floor"] = "Im obersten Stockwerk",
		["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand."] = "Nur mit dem Notsignal: Der Roboter sitzt am Quellfluss westlich von {area:351}. Eskortiere ihn nach Osten zum Ufer hinter {area:307}; seine Belohnung wartet bei Oglethorpe in {area:35}.\nVorsicht: Während der Eskorte tauchen zwei Hinterhalte auf: erst drei Wildkin-Owlbeasts, dann drei Trolle. Vor jedem hält der Roboter an und meldet, dass er Gefahr spürt. Schlicke, getarnte Wölfe und eine große Schildkröte entlang des Wegs können in Kämpfe eingreifen, und sie respawnen auch, wenn du sie vorher erledigt hast.",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Reite ganz nach Westen zur Stadt der Wildhammer, {area:348}, und leg die Nachricht beim Brunnen in ihrer Mitte ab. Die Stadt ist voller Wachen der Allianz: Rein, ablegen, raus.",
		["Ride back north through the canyon to {area:75}."] = "Reite zurück nach Norden durch die Schlucht nach {area:75}.",
		["Ride back north to the bloodmages."] = "Reite zurück nach Norden zu den Blutmagiern.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Reite von {area:272} nach Nordosten ins {zone:1425} und auf der Straße nach Osten; {npc:7801} lagert auf dem Hügel südlich der {area:350} der Elfen.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Reite nach Westen aus {area:75} und nach Süden durch die Schlucht in die {zone:1419}; die beiden Blutmagier stehen gleich dahinter an der Straße.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Südlich der Jagdhütte halten die Trolle der Witherbark ihre Dörfer. Jeder von ihnen trägt einen Schädel: Mit zwanzig benutzt du {item:15002}, um Nimboyas geladene Pike zu machen, und pflanzt sie dann im Dorf auf.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "Wieder nach Südwesten: Der Verbannte versteckt sich bei den Ruinen von {area:353}.",
		["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "Südwestlich des Sees halten die Vilebranch Soothsayers {area:355}, den Tempel der Trolle südlich der zentralen Hügel. Qiaga und {npc:8636} (Elite, 50) stehen an seiner Spitze: Nimm dir die Soothsayers auf den unteren Stufen vor.\nSüdwestlich streifen die Silvermane Howlers durch die Hügel östlich der Dörfer der Witherbark.",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "Die Highvale-Elfen lagern rund um {area:350}. Verbrenne den Bericht, die Notizen und die Aufzeichnungen in ihren Lagern. {npc:7780} wird in der Lodge festgehalten: Führe ihn hinaus und wehre den Hinterhalt unterwegs ab.\nVorsicht: Gruppen von etwa drei Elfen überfallen die Eskorte, meistens zweimal.",
		["The big turtles crawl along the beaches north of the village, and {npc:2491}'s bottles of port lie on the same beaches, from the village up to the {area:307}: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.\nCareful: the biggest Saltwater Snapjaws are 50: pull them one at a time."] = "Die großen Schildkröten kriechen an den Stränden nördlich des Dorfes entlang, und die Portflaschen von {npc:2491} liegen an denselben Stränden, vom Dorf bis hinauf zu {area:307}: Sammle sie im Vorbeigehen ein. Ein Schnappkiefer kann OOX-09/HLs Notsignal fallen lassen, selten: Behalte es.\nVorsicht: Die größten Salzwasserschnappkiefer sind 50: Zieh sie einzeln.",
		["The bloodmages"] = "Die Blutmagier",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Die Kisten mit {item:8684} liegen um das verlassene Hordelager am {area:351}, zwischen den Schlammen.",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers (50-51) use {spell:5416}; {npc:8301} adds Knockdown. Pull the Stingers one at a time."] = "Die fünf Quests brauchen dieselben Teile: Sammle sie alle in einem Durchgang. Westlich der Straße teilen sich {npc:5982}-Geier, Verhungernde Kicherfänge, Skorpokstecher und Todesaugen-Basilisken die Hügel.\nÖstlich der Straße wühlen die Aschenmähnen-Eber und Grunzer an den Hängen neben den Rotstein-Basilisken. Halte dich von den Höllenebern der Stufe 52 weiter südlich fern.\nVorsicht: Skorpokstecher (50-51) benutzen {spell:5416}; {npc:8301} setzt zusätzlich Niederschlagen ein. Zieh die Stecher einzeln.",
		["The ghostly orc stands by the road where the swamp meets the canyon into the {zone:1419}. Listen to his story."] = "Der Geister-Ork steht an der Straße, wo der Sumpf auf die Schlucht in die {zone:1419} trifft. Hör dir seine Geschichte an.",
		["The secret lies on the {area:307}, above the beach."] = "Das Geheimnis liegt auf den {area:307}, über dem Strand.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Ihre Folgequests wollen dieselben Teile noch einmal für einen Buffgegenstand und geben keine Erfahrung: Lass sie liegen.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Das sind Elitegegner: Eine Gruppe ist empfehlenswert, such dir Leute dafür. {npc:7977} ist eine Elite der Stufe 48: Die meisten Klassen schaffen sie auf Stufe 50 allein, aber vielleicht brauchst du Hilfe. Lass sie aus, wenn du allein bist: Die Route lässt dich die Erfahrung wieder hereingrinden.\n{npc:7977} läuft am Ufer unterhalb der {area:307} entlang, vom Pfeil nach Süden bis etwa 75,66 und nach Norden bis etwa 82,52: Wenn sie nicht am Pfeil ist, folge dem Ufer.",
		["To {area:75}"] = "Nach {area:75}",
		["Underwater"] = "Unter Wasser",
		["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use {spell:7367}. When a {npc:2925} falls to 50% health or lower, it calls for help from anything within 25 yd."] = "Westlich der Insel halten die Vilebranch Scalpers die Tempel von {area:1884} und {area:1917}. Slagtrees Werkzeuge liegen bei einem der Tempel.\nDie Silvermane Stalkers, Savage Owlbeasts und Razorbeak Skylords teilen sich die Hügel zwischen den Tempeln und {area:351}. Benutze {item:9618} an den Owlbeasts, die du tötest. Die Skylords lassen auch Long Elegant Feathers fallen: Behalte zehn für {npc:14738}s zweite Botschaft.\nVorsicht: Silvermane Stalkers sind Stufe 47-48 und bleiben außerhalb des Kampfes getarnt. Aus der Nähe benutzen sie {spell:7367}. Wenn ein {npc:2925} auf 50% Gesundheit oder weniger fällt, ruft er alles im Umkreis von 25 yd zu Hilfe.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "für {npc:6986} in {zone:1454}, etwa ab Stufe 50",
		["for {npc:7623} in {area:75}, after the {zone:1419}"] = "für {npc:7623} in {area:75}, nach {zone:1419}",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "für {npc:7825} in {zone:1458}, etwa ab Stufe 50",
		["grind on {npc:2505}"] = "grinde {npc:2505}",
		["{area:1440}: kill these as you meet them"] = "{area:1440}: töte diese, wenn du sie triffst",
		["{area:1446} flight master"] = "Flugmeister von {area:1446}",
		["{area:1917}: kill these as you meet them"] = "{area:1917}: töte diese, wenn du sie triffst",
		["{area:307}: kill these as you meet them"] = "{area:307}: töte diese, wenn du sie triffst",
		["{area:3317} flight master"] = "Flugmeister in {area:3317}",
		["{area:348} well"] = "Brunnen von {area:348}",
		["{area:355}: kill these as you meet them"] = "{area:355}: töte diese, wenn du sie triffst",
		["{item:8704}, a rare drop"] = "{item:8704}, eine seltene Beute",
		["{npc:14731}'s lunch"] = "Mittagessen von {npc:14731}",
		["{npc:14731}, inside"] = "{npc:14731}, drinnen",
		["{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{npc:14736} steht oben auf dem Gasthaus, über {npc:14731}: Geh hinauf, der Pfeil kann die Ebenen nicht unterscheiden.",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, oben in {area:354}",
		["{npc:7643}'s The {npc:950} is a level 55 quest: leave it."] = "{npc:950} von {npc:7643} ist eine Quest für Stufe 55: Lass sie liegen.",
		["{npc:7801}'s camp"] = "{npc:7801}s Lager",
		["{object:2068}, on the beaches"] = "{object:2068}, an den Stränden",
		["{quest:7849}, {quest:7845} and {quest:7850} are group quests: they send you into {area:354}, whose trolls are elite (46-50). Take them with a group of three or more; skip them if you are alone, the route has you grind the experience back.\n{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{quest:7849}, {quest:7845} und {quest:7850} sind Gruppenquests: Sie schicken dich nach {area:354}, dessen Trolle Elite sind (46-50). Nimm sie mit einer Gruppe von drei oder mehr an; überspring sie, wenn du allein bist, die Route lässt dich die Erfahrung wieder erarbeiten.\n{npc:14736} steht oben auf dem Gasthaus, über {npc:14731}: Geh hinauf, der Pfeil kann die Ebenen nicht unterscheiden.",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor: Stoley's shipment from {zone:1446}"] = "„Sea Wolf“ MacKinley, im obersten Stock: Stoleys Lieferung aus {zone:1446}",
		["Back to {area:1099}"] = "Zurück nach {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Zurück zu {npc:11548} am Schrein; bleib westlich der Wachen an der {area:3137}.",
		["Back to {object:3202}"] = "Zurück nach {object:3202}",
		["Below ground"] = "Unter der Erde",
		["Fly to {area:1099}"] = "Flieg zum {area:1099}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {area:976}"] = "Flieg nach {area:976}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and Magatha are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "Flieg nach {zone:1456}; es liegt auf dem Weg nach {area:1099}. Noch keine Flugroute dort? Flieg nach {area:378} und reite nach Westen durch {zone:1412}. Hamuul und Magatha sind im Gebiet {area:1639}; Druiden und Paladine trainieren hier ({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "Folge der Straße nach Norden nach {area:1237}, dem Lager der Horde.",
		["Frayfeather Hippogryphs"] = "Fransenfederhippogryphen",
		["Hippogryph nests"] = "Hippogryphennester",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Behalte {quest:3444}: {npc:7771}s Truhe wird bei einem späteren Besuch geöffnet.",
		["Northspring harpies"] = "Harpyien der Nordschwingen",
		["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}."] = "Geh auf dem Weg durch {zone:1454} zum Flugmeister in die Gasse: {npc:7010} nimmt den Insektenbericht aus {zone:1446} an.",
		["Pestlezugg's samples come from {zone:1449}."] = "Pestlezuggs Proben stammen aus {zone:1449}.",
		["Rage Scar yetis"] = "Wutschrammyetis",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Reite auf der Straße vom Splintertreeposten aus nach Osten. {npc:11548} wartet am {area:1235} gleich neben der Straße, ein paar Schritte westlich der {area:3137} der Allianz: Komm von Westen und halte dich von den Azshara-Schildwachen und Jarrodenus (Elite) fern.",
		["Ride into {zone:1447}"] = "Reite nach {zone:1447}",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Reite auf der Straße nach Süden zur {area:1938}; {npc:7771} lagert daneben. Von hier führt die Straße nach Westen hinab in {zone:1449}, wo der nächste Guide beginnt.",
		["South of Booty Bay, three Bloodsail ships lie off the {area:43}: {npc:2550}, {npc:2548} and {npc:2546} each stand on a deck with their crews. Swim out and work from ship to ship."] = "Südlich von Booty Bay liegen drei Schiffe der Bloodsail vor {area:43}: {npc:2550}, {npc:2548} und {npc:2546} stehen jeweils mit ihrer Besatzung auf einem Deck. Schwimm hinaus und arbeite dich von Schiff zu Schiff.",
		["Sprite Darters"] = "Grimmlingflitzer",
		["The Bloodsail ships"] = "Die Schiffe der Blutsegelbukaniere",
		["The Droffers' shop is a few steps further into the Drag."] = "Der Laden der Droffers ist ein paar Schritte weiter in der Gasse.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Die Geister der Hochgeborenen spuken in den Ruinen gleich nördlich des Schreins; die Satyrn der Haldarr lagern etwas weiter nördlich.",
		["The Northspring harpies nest on the ridges in the far north-west, past the giants' hills. The Windcallers heal, so kill them first and pull one at a time."] = "Die Harpyien der Northspring nisten auf den Graten ganz im Nordwesten, hinter den Hügeln der Riesen. Die Windrufer heilen, also töte sie zuerst und zieh sie einzeln.",
		["The flight from {area:75} lands on {area:35}'s upper deck. {npc:7406} has his workshop on the upper ring of the bay."] = "Der Flug von {area:75} landet auf dem Oberdeck von {area:35}. {npc:7406} hat seine Werkstatt auf dem oberen Ring der Bucht.",
		["The flight lands at {area:117}; {npc:2497} stands by the {object:2076}."] = "Der Flug landet bei {area:117}; {npc:2497} steht bei {object:2076}.",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "Die Hippogryphennester liegen auf den Hügeln im Süden, rund um {area:2522}; jedes enthält ein Ei für den {object:142071}.",
		["The {object:142071}"] = "Der {object:142071}",
		["The {object:142071}, in the middle of town"] = "Der {object:142071}, mitten im Ort",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:818} (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with {npc:818} and join the fight together with him."] = "Das sind Elite-Mobs: Sich zu gruppieren ist empfohlen, such dir Leute dafür. {npc:818} (Elite, Stufe 47) braucht eine Gruppe von 2. Überspring ihn, wenn du allein bist: Die Route lässt dich die EP wieder erarbeiten.\nVorsicht: Zwei Elite-Zauberwirker-Wachen, ungefähr Stufe 45, stehen bei {npc:818} und greifen gemeinsam mit ihm in den Kampf ein.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Das sind Elite-Mobs: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {quest:8552} braucht eine Gruppe von 2. Überspring sie, wenn du allein bist: Die Route lässt dich die Erfahrung wieder erfarmen.",
		["Wandering Forest Walkers"] = "Wandernde Waldgänger",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{area:1099} flight master"] = "Flugmeister in {area:1099}",
		["{area:1236}: kill these as you meet them"] = "{area:1236}: töte diese, wenn du sie triffst",
		["{area:1237} flight master"] = "Flugmeister in {area:1237}",
		["{area:35} flight master"] = "Flugmeister von {area:35}",
		["{area:75} flight master"] = "Flugmeister in {area:75}",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904}, auf die Wellen- und Tiefenschreiter im Wasser",
		["{item:18958}, from the Sea Sprays"] = "{item:18958}, von den Meeresschauern",
		["{npc:2487}, on the balcony of the same building"] = "{npc:2487}, auf dem Balkon desselben Gebäudes",
		["{npc:2491}, in the inn"] = "{npc:2491}, im Gasthaus",
		["{npc:5594}, inside"] = "{npc:5594}, drinnen",
		["{npc:5769}, on the {area:1639}"] = "{npc:5769}, auf der {area:1639}",
		["{npc:6117} walks around {area:1235}: look inside the circle on the map"] = "{npc:6117} läuft um {area:1235} herum: schau in den Kreis auf der Karte",
		["{npc:6746}, at the inn: for Hamuul"] = "{npc:6746}, im Gasthaus: für Hamuul",
		["{npc:6986}, the Drag"] = "{npc:6986}, die Gasse",
		["{npc:7010}, the Drag"] = "{npc:7010}, die Gasse",
		["{npc:7406}, inside"] = "{npc:7406}, drinnen",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: Die Bären sind im {zone:1448}",
		["{npc:7854}, inside"] = "{npc:7854}, drinnen",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, neben dem Windreitermeister",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide."] = "{quest:3761} wird im nächsten Guide gesammelt.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, eine seltene Beute",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "Ein paar Schritte zurück nach Westen zum Hof der Felsteins, dem ersten Hof an der Straße; {npc:10778} wartet im Haus.",
		["Back north-east to {area:251}."] = "Zurück nach Nordosten zum {area:251}.",
		["Back to {area:976}"] = "Zurück nach {area:976}",
		["Below ground"] = "Unter der Erde",
		["Boat to {area:16727}"] = "Boot nach {area:16727}",
		["Bridge into {area:254}"] = "Brücke in den Berg ({area:254})",
		["Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast {spell:8137} and Tunnelers and the Hive Guard use {spell:14120}."] = "Vorsicht: Gorishi Workers rufen unter 45% Gesundheit möglicherweise Verbündete im Umkreis von 25 yd zu Hilfe; Silithiden wirken {spell:8137}, und die Tunnelers und die Hive Guards benutzen {spell:14120}.",
		["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd. The Hive Guards (54) and the Queen stand inside the hive: work the Workers and Wasps outside it."] = "Vorsicht: Arbeiter der Gorishi, die unter 45% Gesundheit fallen, rufen mit 50% Wahrscheinlichkeit Verbündete im Umkreis von 25 yd zu Hilfe. Die Stockwachen (54) und die Königin stehen im Stock: Kümmere dich um die Arbeiter und Wespen draußen.",
		["Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time."] = "Vorsicht: Hier streifen viele Ravasaurier umher, du ziehst also leicht mehrere gleichzeitig.",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Durchquere den Süden des Kraters zum Pylon auf den westlichen Klippen.",
		["Eastern Pylon"] = "Östlicher Kristallpylon",
		["Escort {npc:9999}"] = "Eskortiere {npc:9999}",
		["Fly to {area:1497}"] = "Flieg zur {area:1497}",
		["Fly to {area:1637} and train before the boat to {area:16727}: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "Flieg nach {area:1637} und lerne bei den Lehrern, bevor du das Boot nach {area:16727} nimmst: Der Halt in {zone:1458} später in diesem Guide hat keinen Jäger- oder Schamanenlehrer.",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Folge den Klippen nach Süden zum {quest:3821}, dem Hügel der Oger der Feuermägen. Die Überreste von {npc:9136} liegen an seinem Fuß.",
		["From here on pick up every {npc:271301} (blue, green, red, yellow) and every {quest:3761} pile you pass: 20 for Hamuul, and 5 more for Pestlezugg if you carry {quest:4496}."] = "Sammle ab jetzt jeden {npc:271301} (blau, grün, rot, gelb) und jeden Haufen {quest:3761} auf deinem Weg ein: 20 für Hamuul und 5 weitere für Pestlezugg, falls du {quest:4496} hast.",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "Folge vom {area:152} aus der Straße nach Osten in die {zone:1422}. Die Zelte des Scharlachroten Kreuzzugs stehen gleich hinter dem Hof der Felsteins, zwischen {area:199} und {area:200}. Zünde das Kommandozelt mit {object:176092} an und pflanz das Banner der Geißel auf. Vorsicht: Die Scharlachroten um die Zelte sind bis Stufe 54 und die Beschwörer wirken Zauber: Komm von der Seite, die dem Kommandozelt am nächsten ist, und lass die anderen in Ruhe.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "Reite von der {area:1938} nach Westen zur langen Rampe, die sich in den {zone:1449} hinabwindet, und folge dann der Nordwand des Kraters nach {area:541}, einem Lager in den Klippenhöhlen. Alle hier sind neutral.",
		["Gorillas"] = "Gorillas",
		["Into the {zone:1427}"] = "In die {zone:1427}",
		["Into {zone:1449}"] = "Hinab in den {zone:1449}",
		["Keep the parcel: {npc:10781} is in the {zone:1458}. The next guide starts with {npc:10739} by the {area:202}, south-east of here."] = "Behalte das Paket: {npc:10781} ist in {zone:1458}. Der nächste Guide beginnt mit {npc:10739} beim {area:202}, südöstlich von hier.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Behalte {npc:10267}s Brief: {quest:4808} ist in {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Behalte {quest:4147} von {npc:9118} und den Brief von {npc:8737} für spätere Guides.",
		["Lar'korwi Mates"] = "Lar'korwi-Weibchen",
		["Lashers and Threshers"] = "Peitscher und Drescher",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "Verlass {zone:1458} und reite auf der Straße nach Osten durch {zone:1420} zum {area:152}, der Festung der Verlassenen an der Grenze.",
		["Leave {zone:2548} on foot to the north-west, north of {area:16685}, into the {zone:1418}."] = "Verlasse {zone:2548} zu Fuß nach Nordwesten, nördlich von {area:16685}, in {zone:1418}.",
		["Listen to {npc:8479}'s story once more."] = "Hör dir die Geschichte von {npc:8479} noch einmal an.",
		["North of Torwa, a dead Threshadon lies by the water. The {item:280417} lies on the ground a short ride west of {npc:9619}'s camp."] = "Nördlich von Torwa liegt ein toter Threshadon am Wasser. Der {item:280417} liegt einen kurzen Ritt westlich des Lagers von {npc:9619} am Boden.",
		["Northern Pylon"] = "Nördlicher Kristallpylon",
		["Only from level 53: her next errand is {quest:3822} (54), who walks the caves of {quest:3821} among ogres of 50-53."] = "Erst ab Stufe 53: Ihr nächster Auftrag ist {quest:3822} (54), der durch die Höhlen des {quest:3821} zwischen Ogern der Stufe 50-53 streift.",
		["Out of the refuge"] = "Raus aus der Zuflucht",
		["Power Crystals and soil"] = "Machtkristalle und Erde",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Reite die Ostseite des Kraters hinab zum Pylon auf den östlichen Klippen.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Reite an der Ostseite nach Norden. Blutblütenpeitscher und -drescher füllen den Dschungel.",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.\nSouth of the hot springs, Dinosaur Bones lie on the ground among the Stegodons and drop from the Diemetradons nearby, which also carry the scales {npc:9998} wants. Careful: the Stegodons are elites (52-53): pick the bones up around them, don't pull them; the Elder Diemetradons are 53-55, take the smaller ones. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.\nRide south-west along the western cliffs. Bloodpetal Trappers grow in the jungle there. Careful: the biggest Trappers are 53: pull them one at a time."] = "Reite nach Südwesten zu {area:537}, dem Vulkan in der Mitte des Kraters. Blutblütenschinder wachsen rund um seinen Fuß.\nSüdlich der heißen Quellen liegen Dinosaurierknochen zwischen den Stegodons am Boden und fallen von den Dimetrodons in der Nähe, die auch die Schuppen für {npc:9998} tragen. Vorsicht: Die Stegodons sind Elite (52-53): Sammle die Knochen um sie herum, zieh sie nicht; die Alten Dimetrodons sind 53-55, nimm die kleineren. Ravasaurier jagen im Südwesten in Rudeln: Ihre Klauen sind für {npc:8659}, und hin und wieder trägt einer ein Zerfleddertes Tagebuch (ein seltener Drop: Nimm die Quest nur an, wenn du eines bekommst). Meide Gruff, einen Stegodon der Stufe 57.\nReite nach Südwesten entlang der westlichen Klippen. Dort im Dschungel wachsen Blutblütenfallen. Vorsicht: Die größten Fallen sind Stufe 53: Zieh sie einzeln.",
		["Scarlet forward camp"] = "Vorgeschobenes Lager des Scharlachroten Kreuzzugs",
		["Sentry Braziers"] = "Wachkohlenbecken",
		["Stegodons and ravasaurs"] = "Stegodons und Ravasaurier",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "Nimm einen {object:176092} aus der Kiste neben Derrington für {quest:5096}, die du auf dem Rückweg erledigst. Leg die {quest:5405} an: Geißelsteine fallen nur, solange du sie trägst.",
		["The Anvilrage dwarves of your {area:1584} run: {npc:9077}, in {area:340}."] = "Die Anvilrage-Zwerge aus deinem Run durch {area:1584}: {npc:9077}, in {area:340}.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Die Lar'korwi-Weibchen streifen durch den Dschungel nordwestlich von {npc:9619}.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Die Kristallgruppen stehen überall im Krater, viele rund um den Ort {area:537}. Nimm von jeder Farbe ein paar mehr für die Pylonen mit.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "Die Kiste der Expedition steht in einem verlassenen Lager im östlichen Dschungel.",
		["The expedition's lost equipment lies in the south-west jungle."] = "Die verlorene Ausrüstung der Expedition liegt im südwestlichen Dschungel.",
		["The gorillas live on the north-east plateau: {npc:9619} wants two pelts of each kind, and the Thunderers (52-53) are the biggest. Stay out of the deepest cave: {npc:9622} lives there."] = "Die Gorillas leben auf dem nordöstlichen Plateau: {npc:9619} will je zwei Felle jeder Art, und die Donnerer (52-53) sind die größten. Halte dich von der hintersten Höhle fern: Dort lebt {npc:9622}.",
		["The hearth lands in {area:976}: {npc:11758} takes the {area:983} and Tran'rek Thistleshrub Valley, both done on the way into the crater."] = "Der Ruhestein bringt dich nach {area:976}: {npc:11758} nimmt {area:983} und das Tal von Tran'rek Distelstrauch an, beides auf dem Weg in den Krater erledigt.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "Der Berg lässt dich neben der {area:252} hinaus, voller Orcs der Stufe 55-57. Folge der Straße an den nördlichen Klippen nach Osten zum Lager der Horde am {area:251}.",
		["The pylon stands on the slope east of the refuge."] = "Der Pylon steht am Hang östlich der Zuflucht.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Das Floß liegt am Ufer des südöstlichen Sees; das kleine Bündel liegt daneben im Wasser.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}. Careful: the Lurkers reach 54 and the Tar Lords stand among them: take the Tar Beasts (50-51) and Creepers (51-52)."] = "Die Teergruben liegen gleich südlich der Zuflucht. Teerbestien, Teerlauerer und Teerkriecher lassen {item:11834} fallen. Vorsicht: Die Lauerer erreichen Stufe 54 und die Teerfürsten stehen zwischen ihnen: Nimm die Teerbestien (50-51) und Kriecher (51-52).",
		["The {npc:9167} fly over the western cliffs around the pylon. Careful: the biggest are 54: pull them one at a time."] = "Die Exemplare von {npc:9167} fliegen über den westlichen Klippen rund um den Pylon. Vorsicht: Die größten sind Stufe 54: Zieh sie einzeln.",
		["To {area:976}"] = "Nach {area:976}",
		["Underwater"] = "Unter Wasser",
		["Upstairs"] = "Oben",
		["Use the Mangled Journal to start it"] = "Benutze Ein zerfleddertes Tagebuch, um sie zu starten",
		["Use the scale to start {quest:87494}, for {npc:9619}"] = "Benutze die Schuppe, um {quest:87494} für {npc:9619} zu starten",
		["Western Pylon"] = "Westlicher Kristallpylon",
		["the wooden sign beside {npc:9997}, by the flight master: the {npc:9167} (51-54) come on the pylon loop"] = "das Holzschild neben {npc:9997}, beim Flugmeister: Die {npc:9167} (51-54) kommen auf der Pylonenrunde",
		["{area:1584} is a dungeon for a group of five from about level 48, the biggest in the mountain: its Anvilrage dwarves are this quest's, and you need not go further in than they are. Its portal is deep inside the mountain, down the chain walkways from the bridge.\nInside: the Anvilrage Guardsmen, Wardens and Footmen. Then back out of the portal and on through the mountain's southern exit to the {zone:1428}."] = "{area:1584} ist ein Dungeon für eine Gruppe aus fünf Spielern ab etwa Stufe 48, der größte im Berg: Seine Anvilrage-Zwerge sind die dieser Quest, und du musst nicht weiter hinein als bis zu ihnen. Das Portal liegt tief im Berg, über die Kettenstege von der Brücke hinab.\nDrinnen: die Anvilrage Guardsmen, Wardens und Footmen. Dann zurück aus dem Portal und weiter durch den Südausgang des Bergs in die {zone:1428}.",
		["{area:250}: kill these as you meet them"] = "{area:250}: Töte sie, wenn du ihnen begegnest",
		["{area:340} flight master"] = "Flugmeister in {area:340}",
		["{area:340} is built into the cliffs on the {zone:1418}' west edge."] = "{area:340} ist in die Klippen am Westrand von {zone:1418} gebaut.",
		["{area:538}: kill these as you meet them"] = "{area:538}: Töte sie, wenn du ihnen begegnest",
		["{item:10575}, from the hoard"] = "{item:10575}, aus dem Hort",
		["{item:11116}, a rare drop"] = "{item:11116}, seltene Beute",
		["{item:280459}, a rare drop from the ravasaurs and Diemetradons"] = "{item:280459}, ein seltener Drop von den Ravasauriern und Dimetrodons",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} schickt dich zu {npc:9298} in {zone:1452}: Behalte es.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "Der Goblin {npc:10302} sitzt am Ort {area:543}, gleich östlich des Pylons.",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, neben dem Fledermausführer",
		["{npc:5204}, near Cuely in the Apothecarium"] = "{npc:5204}, in der Nähe von Cuely im Apothecarium",
		["{npc:5594}, inside"] = "{npc:5594}, drinnen",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} steht im {object:36082}.",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, im Apothekarium: Die Phiolen füllst du später in {zone:1447}",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, hinten in der Höhle; unter der Erde",
		["{npc:9117}, below ground"] = "{npc:9117}, unter der Erde",
		["{npc:9166} (50-52) fly over the east of the crater, from the slopes below the refuge southward; their webbed scales are for {npc:9998}, and {npc:9997}'s sign wants ten of them. Leave the {npc:9167} over the west for the pylon loop."] = "{npc:9166} (50-52) fliegen über den Osten des Kraters, von den Hängen unterhalb der Zuflucht nach Süden; ihre Schwimmhautschuppen sind für {npc:9998}, und das Schild von {npc:9997} will zehn davon. Lass die {npc:9167} im Westen für die Pylonenrunde.",
		["{npc:9167}: kill these as you meet them"] = "{npc:9167}: Töte sie, wenn du ihnen begegnest",
		["{npc:9618}, just outside"] = "{npc:9618}, gleich draußen",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} lagert in der Südostecke des Kraters.",
		["{npc:9619}'s camp is in the south-east corner, a short ride from the {area:1942}."] = "Das Lager von {npc:9619} liegt in der Südostecke, ein kurzer Ritt von {area:1942} entfernt.",
		["{npc:9619}: {quest:4289}, the gorillas of the north-east plateau on the pylon loop"] = "{npc:9619}: {quest:4289}, die Gorillas auf dem nordöstlichen Plateau auf der Pylonenrunde",
		["{npc:9619}: {quest:87492}, a short ride west of his camp"] = "{npc:9619}: {quest:87492}, ein kurzer Ritt westlich seines Lagers",
		["{npc:9619}: {quest:87494}, if the scale dropped"] = "{npc:9619}: {quest:87494}, falls die Schuppe gedroppt ist",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623} will dann ein {item:10561}, einen Gegenstand aus {skill:202}. Überspringe das, außer du hast eins.",
		["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}, der Roboter auf dem Plateau; unterirdisch",
		["{npc:9706}, by the dock: for {quest:4324} at {area:251}, later in this guide"] = "{npc:9706}, am Dock: für {quest:4324} in {area:251}, später in diesem Guide",
		["{npc:9997}, beside the flight master"] = "{npc:9997}, neben dem Flugmeister",
		["{npc:9998}, at the entrance"] = "{npc:9998}, am Eingang",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, am Eingang der Zuflucht",
		["{object:175894}, beside the house; inside"] = "{object:175894}, neben dem Haus; drinnen",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} liegt zu Füßen von {npc:8479} auf dem Boden; {quest:3462} steht neben ihm.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} durchstreift die Höhlen und Minenstollen des {quest:3821}; ist er nicht da, räum die Oger an den Eingängen weg, bis er zurückkommt.",
		["{quest:4081}: the Anvilrage dwarves, inside"] = "{quest:4081}: die Anvilrage-Zwerge, drinnen",
		["{zone:1449}: kill these as you meet them"] = "{zone:1449}: Töte sie, wenn du ihnen begegnest",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "Zurück nach Norden nach {area:1763}. Füll Gretas Feldflasche am verderbten Mondbrunnen mitten im südlichen Lager.",
		["Back north to {npc:8420} with the rune, then south-west along the road."] = "Mit der Rune zurück nach Norden zu {npc:8420}, dann die Straße nach Südwesten.",
		["Back north-west to {npc:8420}."] = "Zurück nach Nordwesten zu {npc:8420}.",
		["Below ground"] = "Unter der Erde",
		["Class trainer"] = "Klassenlehrer",
		["Derrington's watchtowers and Vandis' cauldron are done on a later visit: keep them."] = "Derringtons Wachtürme und Vandis' Kessel erledigst du bei einem späteren Besuch: Behalte sie.",
		["Diseased Wolves"] = "Kranke Wölfe",
		["Druid trainer"] = "Druidenlehrer",
		["Each of the camp's three officers (53) carries a seal: {npc:247006} in the middle of the camp, {npc:247013} at its eastern end, and {npc:246991}, who walks its western half: take him on the east side of his walk, where the arrow points.\nCareful: the {npc:250023}, a level 55-57 elite, stands at the camp's western edge, close to the far end of Hawkhelm's walk: wait for Hawkhelm to come back east."] = "Jeder der drei Offiziere des Lagers (53) trägt ein Siegel: {npc:247006} in der Mitte des Lagers, {npc:247013} an seinem Ostende und {npc:246991}, der die Westhälfte abläuft: Greif ihn auf der Ostseite seines Wegs an, wo der Pfeil hinzeigt.\nVorsicht: {npc:250023}, ein Elite der Stufe 55-57, steht am Westrand des Lagers, nahe dem anderen Ende von Hawkhelms Weg: Warte, bis Hawkhelm wieder nach Osten kommt.",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Östlich vom Blutgiftposten liegt das kraterübersäte Tal, wo die Entropischen Bestien und Schrecken umherstreifen. Töte je zwei davon und geh dann zu jedem der drei Krater mit Teufelswasser.",
		["Fly to {area:1237}"] = "Flieg nach {area:1237}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:431}"] = "Flieg nach {area:431}",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "Folge vom {area:152} aus der Straße nach Osten in die {zone:1422}. Die Zelte des Scharlachroten Kreuzzugs stehen gleich hinter dem Hof der Felsteins, zwischen {area:199} und {area:200}. Zünde das Kommandozelt mit {object:176092} an und pflanz das Banner der Geißel auf. Vorsicht: Die Scharlachroten um die Zelte sind bis Stufe 54 und die Beschwörer wirken Zauber: Komm von der Seite, die dem Kommandozelt am nächsten ist, und lass die anderen in Ruhe.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Er lagert beim {area:202}, südöstlich von {area:200}.",
		["Inside"] = "Drinnen",
		["Keep {quest:8465} for {zone:1452}."] = "Behalte {quest:8465} für {zone:1452}.",
		["Makrinni Burrowers"] = "Makrinni-Wühler",
		["Northern crater"] = "Nördlicher Krater",
		["On north-east across the middle of {zone:1447}: {npc:235903} camps by the road."] = "Weiter nach Nordosten durch die Mitte von {zone:1447}: {npc:235903} lagert an der Straße.",
		["Paladin trainer"] = "Paladinlehrer",
		["Ride back west to {area:1237}."] = "Reite zurück nach Westen nach {area:1237}.",
		["Ride east to the ruins on the coast. The four tablets lie among the ruins, guarded by Spitelash naga (52-55): pull them one at a time."] = "Reite nach Osten zu den Ruinen an der Küste. Die vier Tafeln liegen zwischen den Ruinen, bewacht von Naga der Grollflossen (52-55): Zieh sie einzeln.",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}, just north of the blood elves."] = "Reite nach Nordosten zum Lager des Goblins auf den Klippen über der {area:1227}, gleich nördlich der Blutelfen.",
		["Ride south to the northern edge of the {area:1221}. The Spitelash Sirens and Myrmidons (50-52) there carry {npc:8420}'s rune; it doesn't drop often, so work your way along the edge until it does."] = "Reite nach Süden zum Nordrand von {area:1221}. Die Sirenen und Myrmidonen der Grollflossen (50-52) dort tragen die Rune von {npc:8420}; sie droppt selten, also arbeite dich am Rand entlang, bis sie fällt.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Reite nach Südwesten am Teufelssteinhof vorbei und folge der Straße nach Westen zurück zum {area:152}.",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there: on Forever the Sin'dorei Tome beside it then asks for the seals of the camp's three officers."] = "Rimtoris Lager ist am Ostende des Stützpunkts. Lies dort {object:151286}: Auf Forever verlangt der Sin'dorei-Foliant daneben dann die Siegel der drei Offiziere des Lagers.",
		["Scarlet forward camp"] = "Vorgeschobenes Lager des Scharlachroten Kreuzzugs",
		["South-west along the road: {npc:235903} takes the satyrs."] = "Die Straße nach Südwesten: {npc:235903} nimmt die Satyrn.",
		["Southern crater"] = "Südlicher Krater",
		["Southern {area:1763}"] = "Südliches {area:1763}",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "Das Furbolgdorf der Totenwaldfelle liegt gleich südlich des Refugiums. Jeder getötete Totenwaldfell erhöht auch deinen Ruf bei der {area:1769}; behalte die Kopfputzfedern.",
		["The Horde camp just north of {area:1763}."] = "Das Hordelager gleich nördlich von {area:1763}.",
		["The Legashi satyrs"] = "Die Satyrn der Legashi",
		["The Makrinni Burrowers (50-51) dig in the sands just east of the ruins, on the way north-east; they and the buried caches there give up the Highborne Treasure Fragments."] = "Die Makrinni-Wühler (50-51) graben im Sand gleich östlich der Ruinen, auf dem Weg nach Nordosten; sie und die vergrabenen Verstecke dort liefern die Fragmente eines Hochgeborenenschatzes.",
		["The apprentice at the top of the tower sends you back down."] = "Der Lehrling oben im Turm schickt dich wieder nach unten.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}. {npc:8420}'s four pieces of equipment lie in the crates around the camp; the Blood Elf Arcanists carry {npc:247473}'s wand.\nCareful: a {npc:250023}, a level 55-57 elite, stands at the west edge of the camp: work the blood elves from its east side."] = "Die Blutelfen lagern auf den Klippen im Nordosten, an der {area:1227}. Die vier Ausrüstungsteile von {npc:8420} liegen in den Kisten rund ums Lager; die Arkanisten der Blutelfen tragen den Zauberstab für {npc:247473}.\nVorsicht: Am Westrand des Lagers steht {npc:250023}, ein Elite der Stufe 55-57: Arbeite dich von der Ostseite an die Blutelfen heran.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Das Tagebuch liegt im Bauernhaus, der Schrank steht drinnen und der Abort dahinter. Ein {npc:10816} trägt den Schlüssel zum Abort; {npc:10836} kommt heraus, wenn du den Abort öffnest, und trägt den Schlüssel zum Schrank.",
		["The druids' camp is just past the border."] = "Das Lager der Druiden liegt gleich hinter der Grenze.",
		["The middle of {zone:1454}"] = "Die Mitte von {zone:1454}",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "Die Straße endet bei {npc:15395}, vor dem Tunnel der {area:1769} im äußersten Nordosten.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east. Careful: the biggest are 54: pull them one at a time."] = "Die Wölfe streifen über die Felder zwischen Andorhal, {area:200} und {area:202}. Erledige sie auf dem Rückritt nach Osten. Vorsicht: Die größten sind Stufe 54: Zieh sie einzeln.",
		["The {area:1763} moonwell"] = "Der Mondbrunnen von {area:1763}",
		["The {object:661778} stands just south of the vale, by the road north: its bauble starts a quest for {npc:9996} at {area:1997}."] = "Die Statue von Malorne ({object:661778}) steht gleich südlich des Tals an der Straße nach Norden: Ihr Schmuckstück startet eine Quest für {npc:9996} am {area:1997}.",
		["Western crater"] = "Westlicher Krater",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\nTake a {object:176092} from the crate next to Derrington for {quest:5096}."] = "Das hast du beim früheren Besuch der Route hier verpasst: Es kommt jetzt zuerst. Es geht schnell und öffnet die Quests danach.\nNimm einen {object:176092} aus der Kiste neben Derrington für {quest:5096}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{area:1221}: kill these as you meet them"] = "{area:1221}: töte diese, wenn du sie triffst",
		["{area:1237} flight master"] = "Flugmeister in {area:1237}",
		["{area:200} farmhouse"] = "Bauernhaus von {area:200}",
		["{item:246680}, from the Blood Elf Arcanists"] = "{item:246680}, von den Arkanisten der Blutelfen",
		["{item:246721}, from {npc:246991}"] = "{item:246721}, von {npc:246991}",
		["{item:246722}, from {npc:247013}"] = "{item:246722}, von {npc:247013}",
		["{item:246725}, from {npc:247006}"] = "{item:246725}, von {npc:247006}",
		["{item:277958}, from the Angerclaw bears"] = "{item:277958}, von den Zornklauenbären",
		["{item:277959}, from the Felpaw wolves"] = "{item:277959}, von den Teufelspfotenwölfen",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: Die Eulenbestien sind in {zone:1452}",
		["{npc:10920}, beside {npc:10921}: {quest:86577}, the organs of {zone:1448}'s bears and wolves"] = "{npc:10920}, neben {npc:10921}: {quest:86577}, die Organe der Bären und Wölfe in {zone:1448}",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, am Südrand des Lagers",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} läuft hier herum: schau in den Kreis auf der Karte",
		["{npc:235903}: {quest:86746}, the satyrs north of the blood elves' camp"] = "{npc:235903}: {quest:86746}, die Satyrn nördlich des Blutelfenlagers",
		["{npc:246152} in {zone:1420}; {zone:1454} has no paladin trainer"] = "{npc:246152} in {zone:1420}; in {zone:1454} gibt es keinen Paladin-Lehrer",
		["{npc:247473}: {quest:91569}, a wand from the blood elves' arcanists"] = "{npc:247473}: {quest:91569}, ein Zauberstab von den Arkanisten der Blutelfen",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} in {zone:1412}; {zone:1454} hat keinen Druidenlehrer",
		["{npc:3326}, the {object:172960}"] = "{npc:3326}, {object:172960}",
		["{npc:8576}: {quest:91531}, for {npc:4485} in {zone:1454}"] = "{npc:8576}: {quest:91531}, für {npc:4485} in {zone:1454}",
		["{npc:8578}'s camp"] = "Lager von {npc:8578}",
		["{npc:8587}: the tome goes to {npc:3326} in {zone:1454}"] = "{npc:8587}: Der Foliant geht an {npc:3326} in {zone:1454}",
		["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659} nimmt die Ravasaurusklauen aus Un'Goro an; er steht in {object:172960}, ein kurzer Weg von der Stadtmitte.",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{npc:9529}, on the west side of the camp"] = "{npc:9529}, auf der Westseite des Lagers",
		["{quest:91538}: for {npc:8587} in {area:1237}"] = "{quest:91538}: für {npc:8587} in {area:1237}",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "Zurück nach Süden zu {npc:7775}. Behalte das Elixier und trink es noch nicht: Es tötet dich, und so triffst du später Gaeriyan bei {area:976}.",
		["Chillwind chimaeras"] = "Eiswindschimären",
		["Fly to {area:1099}"] = "Flieg zum {area:1099}",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:431}"] = "Flieg nach {area:431}",
		["Gregor's quests lead to other zones: keep them."] = "Gregors Quests führen in andere Gebiete: Behalte sie.",
		["Ice Thistle yetis"] = "Eisdistelyetis",
		["Into {zone:1452}"] = "Nach {zone:1452}",
		["Linken's letter"] = "Linkens Brief",
		["Raging Owlbeasts"] = "Tobende Eulenbestien",
		["Ride south from the tunnel: {npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "Reite südlich vom Tunnel: {npc:9298} lagert zwischen den dampfenden Becken von {area:2246}, im Westen des Tals.",
		["The Jadefire moonwell"] = "Der Mondbrunnen der Jadefeuersatyrn",
		["The Matriarchs and Patriarchs that carry Umi's horns are 56-58: leave them for that later stop."] = "Die Matriarchinnen und Patriarchen mit Umis Hörnern sind Stufe 56-58: Heb sie dir für diesen späteren Halt auf.",
		["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "Die {item:11242} wächst in einem zerfallenen Gebäude nördlich von {npc:7775}s Lager, östlich von {area:1114} der Harpyien: Kletter durch das zerbrochene Stück der Wand hinein.",
		["{area:2246}: kill these as you meet them"] = "{area:2246}: Töte sie, wenn du ihnen begegnest",
		["{area:2255} flight master"] = "Flugmeister in {area:2255}",
		["{area:2255} is the goblin town on the east side of the valley, past the owlbeast hills."] = "{area:2255} ist die Goblin-Stadt auf der Ostseite des Tals, hinter den Hügeln der Owlbeasts.",
		["{area:2408} flight master"] = "Flugmeister: {area:2408}",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}, die Belohnung von {npc:7775}",
		["{item:12565}, at the Jadefire moonwell"] = "{item:12565}, am Mondbrunnen der Jadefeuersatyrn",
		["{item:12771}: about one Winterfall furbolg in ten carries one; keep killing them until it drops"] = "{item:12771}: Etwa jeder zehnte Winterquell-Furbolg trägt einen; töte sie weiter, bis einer fallen gelassen wird",
		["{npc:10431}, inside"] = "{npc:10431}, drinnen",
		["{npc:10881} and {npc:14728} stand on {area:1641}. Each of Rumstag's donations takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "{npc:10881} und {npc:14728} stehen auf {area:1641}. Jede von Rumstags Spenden nimmt sechzig Wolle, Seide oder Magiestoff aus deinen Taschen: Gib ab, was du dabeihast, den Rest überspringe.",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} steht direkt am Ausgang des Tunnels von {area:1769} nach {zone:1452}, wo du herauskommst.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} auf der {area:1639}; {npc:246344}",
		["{npc:9087} buys {item:11040} grown from your {quest:3761}. {quest:3782} wants ten, and the {item:11020} gives one try every ten minutes: take it only if you already have the grain."] = "{npc:9087} kauft {item:11040}, das aus deinem {quest:3761} gewachsen ist. {quest:3782} will zehn, und {item:11020} gibt alle zehn Minuten einen Versuch: Nimm es nur mit, wenn du das Getreide schon hast.",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, auf der Westseite des Refugiums",
		["{npc:9996}'s kitten"] = "{npc:9996}s Kätzchen",
		["{npc:9996}: the {quest:86612}"] = "{npc:9996}: {quest:86612}",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} wartet in {zone:1450}: Behalte sie für später.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} wird bei {object:176091} im {zone:1448} abgegeben, auf einer späteren Reise.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, eine seltene Beute der Winterfell-Furbolgs",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Both {item:14047} donations are handed in later in the route: save sixty {item:14047} for each if you want them."] = "Beide Spenden von {item:14047} gibst du später auf der Route ab: Spar dir sechzig {item:14047} für jede, wenn du sie willst.",
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "Das gereinigte Wasser geht zum {area:2479} im {zone:1448}: Behalte es für später.",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {zone:1454} and train."] = "Flieg nach {zone:1454} und lerne bei den Lehrern.",
		["In the {object:172958}."] = "Im {object:172958}.",
		["In the {object:172961}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "Im {object:172961}. Jede Spende nimmt sechzig Wolle, Seide oder Magiestoff aus deinen Taschen: Gib ab, was du dabeihast, den Rest überspringe.",
		["Inside"] = "Drinnen",
		["Into {zone:1411}"] = "Nach {zone:1411}",
		["Lady Sylvanas holds the {object:36126}."] = "Fürstin Sylvanas ist im {object:36126}.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "Livs Werkstatt ist am Nordende der Docks von {area:392}; {object:149036} steht darin.",
		["Only with {quest:79095} from {area:159}'s alchemy shop in your bags (the Library Books guide)"] = "Nur mit {quest:79095} aus dem Alchemieladen von {area:159} in deinen Taschen (der Guide Bibliotheksbücher)",
		["Paladin trainer"] = "Paladinlehrer",
		["Ride east out of the {zone:1458} along the road; the {area:152} guards the way into the {zone:1422}."] = "Reite von {zone:1458} die Straße nach Osten; {area:152} bewacht den Weg nach {zone:1422}.",
		["Upstairs"] = "Oben",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["{area:392} flight master"] = "Flugmeister in {area:392}",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field.\nCareful: One or two undead usually fight alongside him, and more cauldron lords can attack after you use the cauldron."] = "Die Farm von {npc:10778} ist die erste östlich von {area:152}. Jabbering Ghouls auf der Farm tragen die andere Hälfte ihres Amuletts; {npc:11075} bewacht den Kessel auf dem Feld.\nVorsicht: Ein oder zwei Untote kämpfen meist an seiner Seite, und nachdem du den Kessel benutzt hast, können weitere Cauldron Lords angreifen.",
		["{npc:11615}: the termites are in {area:2627}, on the next guide"] = "{npc:11615}: Die Termiten sind in {area:2627}, im nächsten Guide",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957}: Behalte sie für {zone:1451}",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} in {zone:1456}; in {zone:1454} gibt es keinen Paladin-Lehrer",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901} lagert am Ufer gleich nördlich von {area:392}.",
		["{npc:6522} stands in the {object:36073}."] = "{npc:6522} steht im {object:36073}.",
		["{npc:7010} works in the Drag."] = "{npc:7010} arbeitet in der Gasse.",
		["{npc:8390} and {npc:8393} work in the Apothecarium."] = "{npc:8390} und {npc:8393} arbeiten im Apothecarium.",
		["{npc:8393}, beside him"] = "{npc:8393}, neben ihm",
		["{npc:8403}, nearby"] = "{npc:8403}, in der Nähe",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} geht zurück zu {npc:10778} in den {zone:1422}: Behalte sie.",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["A {item:13140} dropped: the Jaedenar Enforcers, Darkweavers, Warlocks and Legionnaires of Shadow Hold carry one now and then. Use it to start the quest, then free {npc:11018} from her cage in the cave's south end on your way out."] = "Ein {item:13140} ist gedroppt: Die Vollstrecker von Jaedenar, Darkweavers, Hexenmeister und Legionäre der Schattenfeste tragen ab und zu einen. Benutze ihn, um die Quest zu starten, und befreie dann auf dem Rückweg {npc:11018} aus ihrem Käfig im Südende der Höhle.",
		["Andorhal watchtowers and silos"] = "Wachtürme und Silos von Andorhal",
		["Back south to the Sanctuary, a short ride."] = "Zurück nach Süden zum Refugium, ein kurzer Ritt.",
		["Back to {area:2268}"] = "Zurück zur {area:2268}",
		["Below ground"] = "Unter der Erde",
		["Both quests lead to {zone:1451}: keep them."] = "Beide Quests führen nach {zone:1451}: Behalte sie.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Vorsicht: {npc:10411} wird außerhalb des Kampfes unsichtbar und ruft Felsschwingengargoyles herbei, sobald ein Kampf beginnt. Es gibt nur 3, und sie erscheinen alle 15 Min. neu.",
		["Class trainer"] = "Klassenlehrer",
		["Diseased Grizzlies"] = "Kranke Grizzlys",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:2268}"] = "Flieg zur {area:2268}",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Fly to {area:431}"] = "Flieg nach {area:431}",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "Folge der Straße von den {zone:1422} nach Osten, über den Fluss und quer durch die gesamten {zone:1423}, bis zur Kapelle der {object:92525} im äußersten Osten.",
		["Free Darrowshire Spirits: talk to them"] = "Befreie Geister von Darrowehr: Sprich mit ihnen",
		["From the tunnel's {zone:1452} exit, ride south to {area:2246}."] = "Reite vom Tunnelausgang nach {zone:1452} nach Süden zu {area:2246}.",
		["Inside"] = "Drinnen",
		["Into {zone:1423}"] = "Nach {zone:1423}",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "Behalte {quest:5152}: {npc:10927} wohnt am {area:197} in den {zone:1422}.",
		["Mark {npc:10902} with the {item:12815}"] = "Markiere {npc:10902} mit der {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Markiere {npc:10903} mit der {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Markiere {npc:10904} mit der {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Markiere {npc:10905} mit der {item:12815}",
		["Moontouched Owlbeasts"] = "Mondbestrahlte Eulenbestien",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Kleine Seuchenhunde und Seuchenfledermäuse streifen durch die Hügel nördlich von {area:2260}, Aaslarven kriechen zwischen ihnen; arbeite dich nach Norden Richtung {area:2627} vor.",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel; Plaguebats and Carrion Grubs share the ground. Careful: the biggest Plaguehounds are 56, pull them one at a time.\nThe shattered sword lies on the ground north-west of the lake."] = "Seuchenhunde und ihre kleinen Artgenossen streifen an den Ufern des Sees südwestlich der Kapelle umher; Seuchenfledermäuse und Aaslarven teilen sich das Gelände. Vorsicht: Die größten Seuchenhunde sind Stufe 56, zieh sie einzeln.\nDas zerbrochene Schwert liegt am Boden nordwestlich des Sees.",
		["Pristine Yeti Horns"] = "Makellose Yetihörner",
		["Radley and Durgen"] = "Radley und Durgen",
		["Ride back south to {area:272} and fly to {area:2268}."] = "Reite zurück nach Süden nach {area:272} und flieg zur {area:2268}.",
		["Ride east along the road into the {zone:1423}. {npc:1855} lives in a small house by the {area:2619}, just north of the road at the border; his three hunts are on this guide's ground."] = "Reite auf der Straße nach Osten in die {zone:1423}. {npc:1855} wohnt in einem kleinen Haus am {area:2619}, direkt nördlich der Straße an der Grenze; seine drei Jagdaufträge liegen im Gebiet dieses Guides.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Careful: they are 57-58: pull them one at a time.\nCareful: Hailspite, level 60 elites, gather in the snowfields south-east of {area:2255}, where a few Moontouched Owlbeasts roam too: stay on the slopes north of town."] = "Reite nach Osten nach {area:2255} und von dort nach Norden; die Mondbestrahlten Eulenbestien streifen durch die Hügel an den Südhängen von {area:2241}. Vorsicht: Sie sind Stufe 57-58: Zieh sie einzeln.\nVorsicht: Hailspite, Elites der Stufe 60, sammeln sich in den Schneefeldern südöstlich von {area:2255}, wo auch ein paar Mondbestrahlte Eulenbestien umherstreifen: Bleib an den Hängen nördlich der Stadt.",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Reite von {area:272} die Straße nach Norden hinauf. Das Haus von {npc:10927} steht an der Straße am {area:197}, und das Denkmal von {npc:10936} ist auf dem Friedhof dahinter.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Reite nach Nordwesten nach Andorhal. {npc:10667} wartet im zerstörten Gasthaus auf der Westseite der Stadt; die Skelette darin sind Stufe 54-57, also halte dich an die Ränder.",
		["Ride south to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Reite auf der Straße nach Süden zu {area:2264}. {item:15447} verdirbt binnen zehn Minuten: Töte die Geißel des Orts zügig und zerreibe die sieben Stücke sofort mit {item:15454}.\nVorsicht: Ungesehene Diener rufen im Umkreis von 25 Metern um Hilfe, sobald sie auf 40 % Gesundheit fallen. Außerhalb des Kampfes werden sie außerdem mit {spell:10228} unsichtbar. Wenn innerhalb des Orts um Hilfe gerufen wird, können sich sehr viele Gegner dem Kampf anschließen. Am Ortsrand zu kämpfen senkt dieses Risiko.\nMit {quest:5211} in deinem Questlog (von {npc:11063} zu Beginn dieses Guides) hinterlässt die Geißel rund um den Ort Geister von Darrowshire: Sprich jeden an, um ihn zu befreien. Befreie sie, bevor du mit {item:15447} anfängst.",
		["Scarlet Crusade"] = "Scharlachroter Kreuzzug",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one.\nCareful: a {npc:10996}, a level 58-59 elite, can stand in Andorhal, as at many other spots of the {zone:1422}: give it room."] = "Die Annalen liegen zwischen den Modrigen Folianten im Rathaus von Andorhal; öffne sie, bis du den richtigen findest.\nVorsicht: Ein {npc:10996}, ein Elite der Stufe 58-59, kann in Andorhal stehen, wie an vielen anderen Stellen der {zone:1422}: Halte Abstand.",
		["The book lies in the ruined inn of {area:2627}; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass.\nCareful: Ziggurat Protectors (58, elite) stand by the ziggurats east and north-east of the town: take the mounds nearer the town and stay clear of them."] = "Das Buch liegt im zerstörten Gasthaus von {area:2627}; die Untoten im Ort sind Stufe 54-56, also zieh sie einzeln.\nDie Großen Termitenhügel stehen überall in den Hügeln östlich von {area:2627}. Benutze {item:15042} an jedem Hügel, an dem du vorbeikommst.\nVorsicht: Zigguratbeschützer (58, Elite) stehen bei den Zikkuraten östlich und nordöstlich des Orts: Nimm die Hügel näher am Ort und halte dich von ihnen fern.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "Der Kopf der Puppe und ihre beiden Hälften liegen in den Häusern rund um {npc:10926}; füge sie aus deinen Taschen zusammen.",
		["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "Der Schädel liegt in {area:2622}, zwischen Verseuchten Schrecken und Seuchenmonstern.",
		["The {area:2479}"] = "{area:2479}",
		["To {area:197}"] = "Zum {area:197}",
		["Umi's horns, carried from your last {area:2255} stop: the yeti hills start just south-east of {area:2255}. Only Matriarchs and Patriarchs drop horns, and the Patriarchs reach 58: pull them one at a time."] = "Umis Hörner, mitgebracht von deinem letzten Halt in {area:2255}: Die Yetihügel beginnen direkt südöstlich von {area:2255}. Nur Matriarchen und Patriarchen lassen Hörner fallen, und die Patriarchen erreichen Stufe 58: Zieh sie einzeln.",
		["Underwater"] = "Unter Wasser",
		["Upstairs"] = "Im Obergeschoss",
		["West to the {area:152} one last time."] = "Noch einmal nach Westen zu {area:152}.",
		["West to the {area:152}."] = "Nach Westen zu {area:152}.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Das hast du beim früheren Besuch der Route hier verpasst: Es kommt jetzt zuerst. Es geht schnell und öffnet die Quests danach.",
		["Zaeldarr lurks just west of {area:2262}."] = "Zaeldarr lauert gleich westlich von {area:2262}.",
		["a message for {npc:11063} at {area:2268}"] = "eine Nachricht für {npc:11063} in der {area:2268}",
		["{area:2268} flight master"] = "Flugmeister in {area:2268}",
		["{area:2277}: kill these as you meet them"] = "{area:2277}: Töte sie, wenn du ihnen begegnest",
		["{area:2627}: kill these as you meet them"] = "{area:2627}: Töte diese, wenn du ihnen begegnest",
		["{area:272} flight master"] = "Flugmeister von {area:272}",
		["{npc:10667}, upstairs"] = "{npc:10667}, oben",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "Der Geist von {npc:10926} steht in den Ruinen von {area:2262}, im Südwesten.",
		["{npc:10927}, upstairs"] = "{npc:10927}, im Obergeschoss",
		["{npc:11016}, below ground"] = "{npc:11016}, unterirdisch",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner; {npc:12384} sits inside the hut."] = "Der Geist {npc:11140} steht bei einer Hütte im {area:2627}, in der Nordwestecke; {npc:12384} sitzt in der Hütte.",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} läuft hier herum: schau in den Kreis auf der Karte",
		["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} steht östlich des Holzfällerlagers; {npc:11611} bewacht die Straße nordöstlich von {npc:11610}, in Richtung {area:190}.\nVorsicht: Wachen stehen am Fuß des Turms, und eine weitere kreist auf Patrouille darum. Räume sie weg, bevor du Durgen angreifst, damit sie nicht in den Kampf eingreifen.",
		["{npc:12384}, inside"] = "{npc:12384}, drinnen",
		["{npc:3033} (Druids) trains on {area:1639}, {npc:246344} (Paladins) in the city too."] = "{npc:3033} (Druiden) lehrt auf {area:1639}, {npc:246344} (Paladine) ebenfalls in der Stadt.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} auf der {area:1639}; {npc:246344}",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it."] = "{quest:5086} sind in {zone:1448}, bei einer späteren Reise: Behalte sie.",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "Die Geister für {quest:5211} kommen mit dem Halt bei {area:2264} später in diesem Guide: Behalte sie.",
		["{quest:5510}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5510}: Die Untoten von {area:2627} lassen sie fallen, solange du {item:12846} trägst",
		["{zone:1423}: kill these as you meet them"] = "{zone:1423}: Töte sie, wenn du ihnen begegnest",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1456} flight master"] = "Flugmeister von {zone:1456}",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Zurück zum Südwindposten und steig auf den Turm. Wenn du oben den Bau aufscheuchst, kommen Wegelagerer des Ashischwarms heraus; einer trägt {item:17346}.",
		["Back to {area:3425}"] = "Zurück nach {area:3425}",
		["Below ground"] = "Unter der Erde",
		["Class trainer"] = "Klassenlehrer",
		["Collect twenty Encrypted Twilight Texts from the cultists here, ten for {npc:15306} and ten for Ortell. Take them from the Twilight Avengers and Geolords; leave the Flamereavers and Stonecallers (59-60)."] = "Sammle zwanzig Verschlüsselte Texte der Twilight von den Kultisten hier, zehn für {npc:15306} und zehn für Ortell. Hol sie dir von den Rächern der Twilight und Geolords; lass die Flamereavers und Stonecallers (59-60) in Ruhe.",
		["Dredge Crushers and Pincers"] = "Baggerbrecher und Steinpanzerzangen",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Baggerschläger, Steinpanzerskorpide und Sandhuscher teilen sich den Sand gleich nördlich der Burg.",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "Trink das {item:11243} auf dem Friedhof direkt östlich von {area:976}: Es tötet dich, und nur als Geist kannst du {npc:9299} sehen, in einer Felsspalte in den Hügeln genau nördlich davon. Sprich dort mit ihm, lauf dann zurück zu deinem Körper und belebe dich wieder: Der Auffällige Grabstein, zu dem er dich schickt, steht auf diesem Friedhof.",
		["Escort {npc:9999}"] = "Eskortiere {npc:9999}",
		["Flayers and Rock Stalkers"] = "Schinder und Felspirscher",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:541}"] = "Flieg nach {area:541}",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Geh nach Norden entlang der westlichen Dünen; Baggerbrecher und Steinpanzerzangen ziehen von hier bis zurück zur Burg umher.",
		["Inside"] = "Drinnen",
		["Inside: {quest:4493}, if you took it in {zone:1454} on the {zone:1447} guide"] = "Drinnen: {quest:4493}, falls du sie im Guide für {zone:1447} in {zone:1454} angenommen hast",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Führ {npc:9999} nach Norden nach {area:541}. Wenn er ohnmächtig wird, benutze {item:11804} an ihm, um ihn zu wecken.",
		["Mar'alith's next errand, Into the Maw of Madness, leads into {area:2744} among elites. Skip it."] = "Mar'aliths nächster Auftrag, Into the Maw of Madness, führt unter Elites nach {area:2744}. Überspring ihn.",
		["Only if you took {quest:4496} in {area:976} on the way here: the Gorishi of the {area:540}, south of {area:537}, drop the Scent Gland, and most of the crater's beasts and plants drop {item:11018}."] = "Nur wenn du auf dem Weg hierher {quest:4496} in {area:976} angenommen hast: Die Gorishi in {area:540} südlich von {area:537} droppen die Duftdrüse, und die meisten Tiere und Pflanzen des Kraters droppen {item:11018}.",
		["Paladin trainer"] = "Paladinlehrer",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Reite nach Osten zum Ort {area:537}, steig hinauf und benutze {npc:10541} am Lavaschlot nahe dem Gipfel; reite dann zurück nach Westen zu {npc:10302}.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Reite nach Nordosten zur {area:3077}; du verlässt {zone:1451} durch den Pass daneben.",
		["Ride north-east to {area:3447}."] = "Reite nach Nordosten zu {area:3447}.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Reite nach Südosten zu {area:3447} unter den Klippen des Un'Goro-Kraters.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "Reite nach Südwesten zu den Ruinen vom {area:2738}. Der {object:179565} für {npc:11801} steht in einem der verfallenen Häuser.",
		["Ride west to the Horde camp north of {area:2744}."] = "Reite nach Westen zum Lager der Horde nördlich vom {area:2744}.",
		["Scare {npc:7583} with {item:12928}"] = "Verscheuche {npc:7583} mit {item:12928}",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Silithystgeysire brechen überall in der südlichen Wüste aus. Lauf in das Silithyst, das einer zurücklässt, und bring es zum Silithyst Extractor der Horde in Kirikas Lager; Kämpfen oder Aufsteigen lässt es fallen.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Steinpanzerschinder und Felspirscher streifen durch die Dünen südwestlich von Kirikas Lager.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Der Pass aus dem Un'Goro-Krater endet an der {area:3077}, dem Friedhof im Nordosten von {zone:1451}. {npc:13220} steht zwischen den Gräbern.",
		["The spare texts from the cultists"] = "Die übrigen Texte von den Kultisten",
		["Twilight Vanguard"] = "Vorhut der Twilight",
		["Use the {item:11833} where the arrow points, inside the Gorishi hive of the {area:540}, to call the {npc:10041} (level 56)."] = "Benutze {item:11833} dort, wo der Pfeil hinzeigt, im Gorishi-Bau von {area:540}, um {npc:10041} (Stufe 56) zu rufen.",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Benutze {item:12928} an {npc:7583}, dem Goblinmädchen in {area:976}. {npc:10977} und {npc:10978} erschreckst du später auf der Route.",
		["ten for each quest: {npc:15306} takes his ten before Ortell"] = "zehn für jede Quest: {npc:15306} nimmt seine zehn vor Ortell",
		["{area:976} flight master"] = "Flugmeister von {area:976}",
		["{item:20377} from {npc:11739}, 130 yd south-west"] = "{item:20377} von {npc:11739}, 130 yd südwestlich",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} schickt dich zu {npc:9298} in {zone:1452}: Behalte es.",
		["{npc:11741} walks around {area:2738}: look inside the circle on the map"] = "{npc:11741} läuft um {area:2738} herum: schau in den Kreis auf der Karte",
		["{npc:11803} walks the Vanguard camp in the far south-west. Keep every {item:20404} the cultists drop: {npc:15306} and Ortell want ten each later."] = "{npc:11803} läuft durch das Lager der Vanguard ganz im Südwesten. Behalte jeden {item:20404}, den die Kultisten fallen lassen: {npc:15306} und Ortell wollen später je zehn.",
		["{npc:11804} stands in the outpost west of {area:3425}. Keep any Encrypted Twilight Texts that drop here too."] = "{npc:11804} steht im Außenposten westlich von {area:3425}. Behalte auch hier alle Encrypted Twilight Texts, die fallen.",
		["{npc:15171} and {npc:15170} camp at Bronzebeard's Encampment, just north of the satchel's mountains. Question them: go through each one's whole conversation; there is no need to fight them."] = "{npc:15171} und {npc:15170} lagern im Lager von Bronzebeard, direkt nördlich der Berge der Tasche. Befrage sie: Geh jedes ganze Gespräch durch; du musst sie nicht bekämpfen.",
		["{npc:15189} and {npc:15190} stand upstairs in their building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} und {npc:15190} stehen oben in ihrem Gebäude: Geht drinnen hinauf, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} steht oben in seinem Gebäude: Geh drinnen hinauf, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} steht oben in seinem Gebäude: Geh drinnen hinauf, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} hält das Lager im Westen.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, auf der Westseite der Burg",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} in {zone:1456}; in {zone:1454} gibt es keinen Paladin-Lehrer",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} lagert an der Straße zur {area:1336}, südlich von {area:976}.",
		["{npc:9117}, below ground"] = "{npc:9117}, unter der Erde",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "Der Unterschlupf von {npc:9684} liegt gleich südlich des Pylons. Benutze dort {npc:9619}s Köder; {npc:9684} ist Stufe 56 und schlägt hart zu, also fang mit voller Gesundheit an.",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} sitzt verirrt und erschöpft auf dem Grat.",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914} geht zurück zu {npc:8737} in Un'Goro: Behalte sie.",
		["{zone:1451}: kill these as you meet them"] = "{zone:1451}: Töte sie, wenn du ihnen begegnest",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Zurück in den Tunnel der Holzschlundfeste und nimm den Ausgang nach {zone:1452}; {npc:9298} lagert gleich draußen bei den heißen Quellen.",
		["Below ground"] = "Unter der Erde",
		["Class trainer"] = "Klassenlehrer",
		["Fly to {area:431}"] = "Flieg nach {area:431}",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Flieg zum {area:431} und reite auf der Straße nach Nordwesten aus {zone:1440} in den {zone:1448}. {area:2479} ist das Lager der Druiden gleich hinter der Grenze.",
		["Frostfire Winterfall camp"] = "Lager der Winterfelle an den Frostfeuerquellen",
		["Ice Thistle yetis"] = "Eisdistelyetis",
		["In the {object:172961}."] = "Im {object:172961}.",
		["North of Donova, at the tunnel's {zone:1452} exit."] = "Nördlich von Donova, am Tunnelausgang nach {zone:1452}.",
		["Ride back west along the road to {area:2246}."] = "Reite auf der Straße zurück nach Westen zu {area:2246}.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Reite auf der Straße nach Norden an {area:1763} vorbei zum {area:1997}.",
		["Ride north to {area:2255}."] = "Reite nach Norden nach {area:2255}.",
		["Scare {npc:10978} with {npc:10980}"] = "Erschrecke {npc:10978} mit {npc:10980}",
		["The runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "Die Läufer gehen in kleinen Gruppen die Straße von {area:1769} in Richtung {area:2244} entlang; warte an der Straße bei {npc:9298} und töte sie, wenn sie vorbeikommen. Jeder trägt eine Kiste.\nVorsicht: Beim Abgeben erscheinen drei oder vier Winterquell-Hinterhalte der Stufen 56-57, die dich angreifen; du kannst ihnen auf einem Reittier, in Tarnung oder mit {spell:5384} entkommen, und dann sammeln sie sich am See, sodass du die nächste Quest annehmen kannst.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Durch den Tunnel der Holzschlundfeste nach {zone:1450}. {npc:11939} liest in einem Haus in {area:2361}.",
		["With 30 {quest:6031} in your bags: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "Mit 30 {quest:6031} in deinen Taschen: Folge der Straße nach Norden zu {area:1769}; {npc:11557} handelt direkt hinter dem Eingang.",
		["grind on {npc:7446}"] = "grinde {npc:7446}",
		["sixty {item:14047}"] = "sechzig {item:14047}",
		["{npc:11556} takes the beads only once {quest:8464} is handed in: any Winterfall furbolg can carry them, and the camps just south of {npc:11556} are the closest."] = "{npc:11556} nimmt die Perlen erst an, wenn {quest:8464} abgegeben ist: Jeder Furbolg der Winterfelle kann sie tragen, und die Lager gleich südlich von {npc:11556} sind am nächsten.",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} läuft hier herum: schau in den Kreis auf der Karte",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}s Die Splitter der Teufelsranke braucht {area:2577}. Überspringe sie.",
		["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939} läuft um {area:2361} umher: Schau in den Kreis auf der Karte",
		["{npc:9116}, inside"] = "{npc:9116}, drinnen",
		["{quest:8464}'s village is north-east of {area:2255}, on this guide's way back from {area:2256}."] = "Das Dorf zu {quest:8464} liegt nordöstlich von {area:2255}, auf dem Rückweg dieses Guides von {area:2256}.",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Gepanzerte Skorpide kriechen über die Ebenen westlich von {area:362}. Zähm einen und kehr dann zu {npc:3171} zurück.",
		["Back east to Sen'jin on the way to the {area:368}."] = "Zurück nach Osten nach Sen'jin auf dem Weg zu den {area:368}.",
		["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Zurück nach Nordwesten zu {area:362}: erst {npc:3139}, dann {npc:3147} im Wachturm, dann {npc:3142} und {npc:266940} auf dem Weg nach Osten zur Küste.",
		["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Zurück über die Brücke und nach Süden am Ufer des Flusses auf der Seite von {zone:1411} entlang, bis ein schmaler Pfad den Berg hinaufführt: {npc:5900} hütet den Schrein oben. Achte auf dem Weg nach oben auf die Ränder und komm auf demselben Pfad wieder herunter.",
		["Back to the Den"] = "Zurück zum Höhlenbau",
		["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Zurück zum Bau: {npc:3143} nimmt die Klaue von {quest:804} entgegen, und {npc:5887} direkt draußen hat jetzt, da du Stufe 4 bist, {quest:1516}.",
		["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Zurück nach {area:362}: {npc:3139}, dann {npc:3142}.",
		["Back to {zone:1411}"] = "Zurück nach {zone:1411}",
		["Below ground"] = "Unter der Erde",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Kultisten der Burning Blade halten die Höhlen von {quest:827}; jeder lässt {item:4871} fallen. {npc:3204}, ein Hexenmeister der Stufe 14, steht tief drinnen und lässt {item:4903} fallen.\nVorsicht: In {quest:827} kämpfen Leerwandler an der Seite der Kultisten der Burning Blade, und {npc:3204} (14) wartet hinten mit seinem eigenen: Zieh die Kultisten für die Halsbänder einzeln nahe dem Eingang. {item:4903} ist optional: Lass {npc:3204} in Ruhe, außer du bist 13 oder hast einen Freund dabei.",
		["Careful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "Vorsicht: Ukorsbane (8) ist Elite und läuft zwischen den Ridgeshade-Spinnen im Lager südlich von {area:362} umher: Zieh die Spinnen von ihm weg.",
		["Class trainer"] = "Klassenlehrer",
		["Deathskip to Northern Durotar"] = "Todessprung ins nördliche Durotar",
		["Deathskip to {area:367}"] = "Todessprung nach {area:367}",
		["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Stirb an den Mobs bei 52.0,21.4 ({npc:3118}): Ein Tod dort schickt dich zu diesem Friedhof. Gib deinen Geist frei und nimm die Wiederbelebung von {npc:6491} an.",
		["Die to the mobs at 66.9,87.2 ({npc:3206}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Stirb an den Mobs bei 66.9,87.2 ({npc:3206}): Ein Tod dort schickt dich zu diesem Friedhof. Gib deinen Geist frei und nimm die Wiederbelebung von {npc:6491} an.",
		["Druid trainer"] = "Druidenlehrer",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Teufelspirscher streifen über den Hang unterhalb der Höhle, auf der Nordseite des Tals.",
		["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle hält das Lager der Brennenden Klinge auf {area:369}, gleich nördlich von Mishas Hütte. Jäger: Zähm unterwegs mit {item:15908} einen {npc:3099}.\nVorsicht: Kultisten der Brennenden Klinge umgeben Fizzle, manche verbunden, sodass sie zu zweit angreifen, und sie respawnen schnell.\nVorsicht: Halikor, eine Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Free {npc:275811} and see her safely out of the crag"] = "Befrei {npc:275811} und bring sie sicher aus dem Felsen",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Geh nach Nordosten zur Straße Richtung {zone:1454}. {npc:3293} lagert daneben; die gestohlenen Säcke liegen entlang der Straße südlich von ihm.",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10."] = "Geh nach Süden über die Inseln. Die Loa-Götzen liegen überall auf den südlichen Inseln; Voodootrolle und Verhexte Trolle halten sie und lassen die Verhexten Anhänger fallen. {quest:826} und Minshinas Käfig sind auf der südlichsten Insel.\nVorsicht: Die Trolle stehen dicht beieinander und die Voodootrolle zaubern aus der Ferne: Zieh sie einzeln. {quest:826} selbst ist Stufe 10.",
		["Inside"] = "Drinnen",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Geh in der Höhle an der ersten Gabelung geradeaus, dann rechts, und folge dem Bach zu deiner Linken bis zum Wasserfall: Die Hacke leuchtet am Wasser, hinter einer Felssäule.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Halte dich in der Höhle immer an der rechten Wand, über den Bach: {npc:3183} wartet am Ende.",
		["Level 10"] = "Stufe 10",
		["Level 11"] = "Stufe 11",
		["Level 7"] = "Stufe 7",
		["Level 9"] = "Stufe 9",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Mishas Hütte steht südlich der Echsen. Die Krokilisken am {area:814} im Westen tragen {item:4891}.",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "Nordöstlich zum Strand unterhalb von {area:370}, nördlich von {npc:275657}: Spitelash Scouts und Attendants halten ihn. Jäger: Zähme einen {npc:3107} am Strand.",
		["Paladin trainer"] = "Paladinlehrer",
		["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "Stacheleber und Späher halten die Hütten westlich des Orts, wo die Kaktusfeigen wachsen; Staubläufer und Schlachtwachen halten die Lager weiter westlich.",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "Savages und Storm Witches nisten in {area:370}, östlich von {npc:3293}. Eine Storm Witch lässt {item:277661} fallen. Schamanen: Die Burning Blade Cultists bei {area:371} am Südende der Schlucht lassen {item:6652} fallen.",
		["Spitelash naga"] = "Naga der Grollflossen",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The Scorpid Workers roam the slope south of {npc:3287}; pick the Cactus Apples by the cactuses on the way.\nThe {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "Die Skorpidarbeiter streifen über den Hang südlich von {npc:3287}; pflücke die Kaktusäpfel bei den Kakteen auf dem Weg.\nDie {quest:792} schwärmen über den Hang unterhalb von {area:365}, der Höhle an der Nordseite des Tals.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Rohrkolben und Speergras wachsen am Wasser im {object:172958}, östlich der Gasse.",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin.\nMakrura and surf crawlers line the beaches north-east of Sen'jin."] = "Die gnomischen Werkzeugkisten liegen im Wrack entlang der Küste östlich und südöstlich von {area:362}. Folge der Küste nach Süden bis Sen'jin.\nMakrura und Surf Crawlers säumen die Strände nordöstlich von Sen'jin.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "Die Burg steht an der Küste südöstlich von {area:362}. Axt, Bogen und Schild der Räuber liegen an ihrem Rand. Matrosen und Marinesoldaten lassen {item:4870} fallen.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Die Waffen liegen um den Höhlenbau und den Übungsplatz; die Scheckigen Eber streifen über den ganzen Talboden.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} steht in {area:817}, zwischen den Kultisten, die du gerade bekämpft hast.",
		["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "Durch Sen'jin auf dem Weg nach Westen zu {area:366}: {npc:3304} nimmt jetzt die Augen und den Schleim entgegen.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Donnerechsen und Blitzechsen grasen auf {area:369}, neben der Straße nach Norden nach {zone:1454}; jede kann {item:6486} fallen lassen. {npc:5810} nimmt sie an, wenn der nächste Guide am {area:379} vorbeikommt.\nVorsicht: Halikor, eine Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Donnerechsen und Blitzechsen grasen auf {area:369}, gleich westlich und südwestlich von {npc:3293}.\nVorsicht: Halikor, eine Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Thunder lizards on the way north"] = "Donnerechsen auf dem Weg nach Norden",
		["To {zone:1454}"] = "Nach {zone:1454}",
		["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "Hol hier Stufe 11 auf, bevor du dich an {npc:3203} (12) und seinen Wichtel wagst: Die Donnerechsen (9-10) grasen auf dem Kamm gleich westlich von Mishas Hütte.",
		["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "Level hier auf Stufe 7, bevor du dich {npc:3192} (8) und den Marinesoldaten oben in der Burg stellst.",
		["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "Level hier auf Stufe 9, bevor du zu den südlichen Inseln gehst: Die Voodoo- und Verhexten Trolle dort sind 8-9 und {quest:826} ist 10.",
		["Training weapons and boars"] = "Übungswaffen und Eber",
		["Underwater"] = "Unter Wasser",
		["Upstairs"] = "Oben",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "Wate hinüber zur nördlichen Echoinsel. Die Matriarchin streift dort zwischen den Raptoren umher.\nDurotartiger streifen über die Insel und das Ufer südlich von Sen'jin, und die Peitschenschwanzeier liegen in Nestern auf den Inseln und entlang des Strands.",
		["Wake {quest:5441} with the {item:16114}"] = "Weck {quest:5441} mit {item:16114}",
		["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "Von {area:362} nach Westen über die Brücke von {area:814}: {npc:3337} und {npc:5810} stehen zusammen bei {area:379} oberhalb davon. Von dort führt die Straße nach Norden durch {zone:1411} nach {zone:1454}.",
		["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Nach Westen über die Brücke von {area:814}, an {area:379} vorbei und weiter entlang des Grats: {npc:5907} steht allein oberhalb des Razormane-Lagers.",
		["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "Nach Westen über die Brücke von {area:814}: {npc:3337} steht bei {area:379} oberhalb davon, auf deinem Weg zu {npc:5907}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:2704} ({object:172958}, 10 Silber); die Nahkampfwaffe eines Jägers besteht hauptsächlich aus ihren Werten, und Zweihandwaffen haben die meisten.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:2704} ({object:172958}, 10 Silber); ein Stab hat beim Leveln mehr Zauberwerte als eine Einhandwaffe.",
		["grind on {npc:3111}"] = "grinde {npc:3111}",
		["grind on {npc:3121}"] = "grinde an {npc:3121}",
		["grind on {npc:3128}"] = "grinde an {npc:3128}",
		["grind on {npc:3130}"] = "Grinde an {npc:3130}",
		["the {object:654925} on the ground beside her"] = "{object:654925} neben ihr auf dem Boden",
		["{area:363}: kill these as you meet them"] = "{area:363}: töte diese, wenn du sie triffst",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} liegt westlich von Sen'jin. Die drei Angriffspläne liegen zwischen den Zentaurenzelten auf dem Boden. {npc:275811} wird ebenfalls am Felsen festgehalten.",
		["{area:368}: kill these as you meet them"] = "{area:368}: töte diese, wenn du sie triffst",
		["{area:369}: kill these as you meet them"] = "{area:369}: töte diese, wenn du sie triffst",
		["{area:373}: kill these as you meet them"] = "{area:373}: töte diese, wenn du sie triffst",
		["{area:817}'s mouth"] = "Eingang von {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, wo du startest",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11025} nimmt sie entgegen, sobald deine Fertigkeit in {skill:202} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, am Holzstapel östlich des Baus",
		["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} in {zone:1456}; in {area:362} gibt es keinen Paladin-Lehrer",
		["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} in {zone:1456}; in {area:363} gibt es keinen Paladin-Lehrer",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} lagert gleich südlich von {area:362}. Setz dich an sein Lagerfeuer (/sit), bis der Buff {spell:1229451} erscheint. Wenn du einen Beruf erlernt hast, bietet {npc:265809} auch dessen Camping 101 an, das der jeweilige Lehrer annimmt: in {area:362} oder in {zone:1454} zu Beginn des nächsten Guides.",
		["{npc:265809}'s campfire"] = "Lagerfeuer von {npc:265809}",
		["{npc:265809}: for Jandi"] = "{npc:265809}: für Jandi",
		["{npc:265809}: for Jhag"] = "{npc:265809}: für Jhag",
		["{npc:265809}: for Karolek"] = "{npc:265809}: für Karolek",
		["{npc:265809}: for Snang"] = "{npc:265809}: für Snang",
		["{npc:265809}: for Thuwd"] = "{npc:265809}: für Thuwd",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: für {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: für {npc:11046}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: für {npc:3175}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: für {npc:5943}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: nur für Verzauberer, die Rückstände werden aus Verhexten Anhängern ({item:275724}) entzaubert",
		["{npc:266940}, inside"] = "{npc:266940}, drinnen",
		["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, auf der Ostseite der Stadt; drinnen",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} steht am Ufer östlich von {area:362}. Dreizack, Banner und Dolch liegen um ihn herum am Strand.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, ein junger Meeresriese, läuft an der Nordküste von {zone:1411} entlang, nördlich des Strandes der Naga. {npc:275666} ist Elite: Gruppe empfohlen.",
		["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} in {zone:1412}; in {area:362} gibt es keinen Druidenlehrer",
		["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} in {zone:1412}; in {area:363} gibt es keinen Druidenlehrer",
		["{npc:3102} hooves"] = "{npc:3102}-Hufe",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, zurück in {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, ein Elite-Meeresriese",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} steht gleich hinter dem Höhleneingang; {npc:3159} hinten in der Höhle hinter ihm.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} wartet im Höhlenbau, dem Gebäude gleich westlich von {npc:10176}.",
		["{npc:3143}, inside"] = "{npc:3143}, drinnen",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, im Wachturm",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, der Kriegerlehrer neben dem Höhlenbau",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, der Jägerlehrer neben dem Höhlenbau",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, der Schurkenlehrer im Höhlenbau",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, der Hexenmeisterlehrer hinten in der Höhle",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, der Schamanenlehrer neben dem Höhlenbau",
		["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, im hinteren Teil der Höhle; unterirdisch",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}: {npc:3352} in {zone:1454} lehrt {spell:5149}",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3175} nimmt sie entgegen, sobald deine Fertigkeit in {skill:186} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191}: Camping 101 verlangt, dass du ihn lernst",
		["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192} wartet oben in der Burg; sein Schlüssel öffnet die Truhe neben ihm, in der {item:4881} liegt.",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} liegt verwundet am Fuß der Hügel nordwestlich des Höhlenbaus.",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875} steht in {object:172960}, der Schlucht unter {object:172982}. Gib ihm {item:6535}, benutze dann {item:7464} am Beschwörungskreis neben ihm und besiege den Leerwandler, um ihn zu binden.\nVorsicht: Der Leerwandler, den du beschwörst, schlägt hart zu, und an diesem Kampf sterben in {zone:1454} die meisten Hexenmeister: Fang mit voller Gesundheit und Mana an, schick deinen Wichtel vor, halte Verderbnis und Feuerbrand auf ihm und benutze einen Gesundheitsstein, falls du einen hast.",
		["{npc:5880}, the mage trainer in Sen'jin"] = "{npc:5880}, der Magierlehrer in Sen'jin",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, die Magierlehrerin, am Eingang zum Höhlenbau",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} steht vor dem Höhlenbau. {area:639} ist der Hügel gleich südlich davon: Trink dort {item:6635}, um {npc:5891} zu sehen, und bring dann {item:6656} zurück zu {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} und dein {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, auf dem {area:639}",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5943} nimmt sie entgegen, sobald deine Fertigkeit in {skill:129} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} steht auf der Straße am östlichen Ausgang des Tals.",
		["{npc:6928}, inside"] = "{npc:6928}, drinnen",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, am Kochfeuer",
		["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "{quest:790}, ein großer Skorpid (Stufe 4), streift über den Hang gleich westlich des Baus, unterhalb von {npc:3287}, auf dem Weg nach Norden zu {area:365}.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} lagert auf dem Hügel westlich des Nagastrands, südlich von {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Das Haupttor von {zone:1454} liegt gleich westlich von {area:817}. {npc:5875} steht in {object:172960}, der Schlucht unter dem {object:172982}.",
		["{zone:1454}'s {object:172982}"] = "{object:172982} von {zone:1454}",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit an {npc:263664}s Lagerfeuer, bis du {spell:1229451} bekommst",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders und die gefallenen Wachen liegen gleich südwestlich des Turms. Nimm Raanis Glücksfeder und das Schattensang-Familiensiegel von den Leichen.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "Zurück in {quest:92529}: Sturmrufer und {npc:251662} füllen das Dorf, die Vorratskisten stehen zwischen den Häusern und {npc:251966} wartet an seinem Südostende.",
		["Back to Boro in {area:16635} with the Signet."] = "Zurück zu Boro in {area:16635} mit dem Siegel.",
		["Back to {area:16635}"] = "Zurück nach {area:16635}",
		["Back to {area:16638}"] = "Zurück nach {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Zurück zu {npc:268592}. Warte, bis er {npc:268762} entzündet, und trag die Flamme dann direkt zu {npc:268679} neben {npc:252382} in {area:16638}, bevor der Timer abläuft.",
		["Back up from the den to {npc:257551} and {npc:251366} in the village before heading south-west to {npc:252095}: the road from her camp leads on south to Shen'dar."] = "Geh von der Höhle zurück zu {npc:257551} und {npc:251366} im Dorf, bevor du nach Südwesten zu {npc:252095} aufbrichst: Die Straße von ihrem Lager führt weiter nach Süden nach Shen'dar.",
		["Below ground"] = "Unter der Erde",
		["Boro and {npc:251373}, while you stand beside them"] = "Boro und {npc:251373}, solange du neben ihnen stehst",
		["Cast {spell:1259686} near the {object:460001}"] = "Wirke {spell:1259686} nahe {object:460001}",
		["Class trainer"] = "Klassenlehrer",
		["Find {npc:258130}"] = "Finde {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "Folge der Straße nach Süden nach {area:16624}, in der Mitte der Insel. {npc:251523} steht auf der Ostseite, {npc:251902} in der Mitte, {npc:254089} gleich nordwestlich von ihr, {npc:263664} am Lagerfeuer auf der Westseite. Wenn du einen Beruf erlernt hast, bietet {npc:263664} auch das passende Camping 101 an: Dessen Lehrer steht im Dorf.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Geh nach Norden in {area:16631}; {npc:257944} lagert an seinem Südrand.",
		["Head north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "Geh nach Nordosten zum {area:17675}. Das Lager der Al'Aketh ist direkt westlich davon, mit {npc:252666} an seinem Nordende. Jeder Kultist kann ein Windsteinamulett fallen lassen.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Geh nach Südwesten zum {area:17674}. {npc:252155} ist oben; {item:254871} liegt neben ihm.",
		["Heal the injured druids in the Nightfang Den"] = "Heile die verletzten Druiden im Nachtfangbau",
		["Hungry Bandits"] = "Hungry Bandits",
		["Innkeeper {npc:255940}, by the west gate"] = "Gastwirt {npc:255940}, am Westtor",
		["Into {zone:1412}"] = "Nach {zone:1412}",
		["Into {zone:1413}"] = "Hinein nach {zone:1413}",
		["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Spring von der Spitze des Wachturms und benutze {spell:1259416}, um zu {npc:251361} westlich des Turms hinabzuschweben.",
		["Learn the flight path from {npc:3615} on the tower platform. {area:380}' own quests come after {zone:1421}, in the {zone:1413} guide."] = "Lerne die Flugroute bei {npc:3615} auf der Turmplattform. Die eigenen Quests von {area:380} kommen nach {zone:1421}, im Guide zu {zone:1413}.",
		["Leave {zone:2521} to {zone:1412}"] = "Verlasse {zone:2521} nach {zone:1412}",
		["Listen to {npc:252448}'s story"] = "Hör dir die Geschichte von {npc:252448} an",
		["Listen to {npc:256083}"] = "Hör {npc:256083} zu",
		["Northern {zone:1412}"] = "Nördliches {zone:1412}",
		["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him."] = "Auf der Straße nach Südosten nach {area:16638} beobachtet {npc:273017} die {quest:98512} direkt nördlich von ihm.",
		["On your way north from Valennia, {npc:255853} waits by the falls north-east of you, just north of the {area:17675}: from the ridge above them, glide down with {spell:1259416}."] = "Auf deinem Weg nach Norden von Valennia wartet {npc:255853} an den Wasserfällen nordöstlich von dir, direkt nördlich von {area:17675}: Gleite vom Grat oberhalb mit {spell:1259416} zu ihnen hinab.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Lästige Zirrusfliegen und {npc:250873} streifen durch den Hain gleich südöstlich des Dorfs.",
		["Portal to {area:16630}"] = "Portal nach {area:16630}",
		["Prideclaws and Galestriders share the meadows around {area:16624}; the Galestriders graze thickest just west of it. They drop both the Small Eggs and the {item:5469} for {npc:251905}."] = "Prideclaws und Galestriders teilen sich die Wiesen rund um {area:16624}; die Galestriders grasen am dichtesten direkt westlich davon. Sie lassen sowohl die Small Eggs als auch {item:5469} für {npc:251905} fallen.",
		["Raw Windstones"] = "Rohe Windsteine",
		["Ripe Stormapples"] = "Ripe Stormapples",
		["Shen'dar bounty board"] = "Kopfgeldtafel von Shen'dar",
		["Skyhoppers"] = "Himmelshüpfer",
		["Skyhoppers hop about the fields just west of Valennia."] = "Himmelshüpfer hüpfen über die Felder gleich westlich von Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Verstreu {item:278078} von der {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Sturmäpfel und Flatterfliegenstaub liegen überall im Obstgarten; Hungrige Banditen plündern ihn. Windschreiter grasen auf den Feldern östlich davon. Das kaputte Konstrukt schwebt am Nordrand des Obstgartens.",
		["Take the Portal to {area:16630} in the shrine up to the heights. Fight east along the ledge to the Peacekeepers at its end, ride the wind current up to the upper terrace and tell {npc:252475} you are ready. Leave the {object:617084} up there alone until Rohash has withdrawn; then it takes you straight back to town."] = "Nimm das Portal nach {area:16630} im Schrein hinauf zu den Höhen. Kämpfe dich nach Osten entlang des Simses zu den Peacekeepers an seinem Ende, reite auf der Windströmung hinauf zur oberen Terrasse und sag {npc:252475}, dass du bereit bist. Lass {object:617084} dort oben in Ruhe, bis Rohash sich zurückgezogen hat; dann bringt es dich direkt zurück in die Stadt.",
		["Take {item:277267} to {npc:268592} at the Shrine of Flames, south-west of {area:16638}, then head west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "Bring {item:277267} zu {npc:268592} am Schrein der Flammen, südwestlich von {area:16638}, und geh dann nach Westen in {area:16623}: {npc:268605}s Zuhause liegt in den Hügeln südlich der Seen der Windsong Crawlers.",
		["Take {zone:1456}'s west lift down: the road at its foot runs south-east across {zone:1412} to the {zone:1413}."] = "Nimm den Westaufzug von {zone:1456} nach unten: Die Straße an seinem Fuß führt nach Südosten durch {zone:1412} ins {zone:1413}.",
		["Tame {npc:250874}"] = "Zähme {npc:250874}",
		["Tame {npc:251707}"] = "Zähme {npc:251707}",
		["Tame {npc:254588}"] = "Zähme {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Sag {npc:252800}, dass du bereit bist",
		["The Al'Aketh camp"] = "Das Lager der Al'Aketh",
		["The Enchanted Gyrozephyrs lie under water far to the north, east of {area:16624} and south-west of {area:16625}."] = "Die Enchanted Gyrozephyrs liegen weit im Norden unter Wasser, östlich von {area:16624} und südwestlich von {area:16625}.",
		["The Highwayman Bandits hold the hills north of {area:16663}; they drop the Blood-Stained Bandit Masks."] = "Die Highwayman Bandits halten die Hügel nördlich von {area:16663}; sie lassen die Blood-Stained Bandit Masks fallen.",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Die Rohen Windsteine sind blaue Kristalle an den Hängen rund ums Dorf.",
		["The apprentices practise north-east of the village.\nThe bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "Die Lehrlinge üben nordöstlich des Dorfes.\nDie Banditenlager sind nordöstlich des Dorfes; „Badwind“ Bennic hält das oberste Lager. Banditen tragen die gestohlenen Windsteine.",
		["The hermit lives at {area:16625}'s west shore."] = "Der Einsiedler lebt am Westufer von {area:16625}.",
		["The hippogryph nests are north-west of the {area:17674}, west of {quest:92529}. The Matriarch sits at their western end; {item:263493} lies on the ground around the nests."] = "Die Hippogryphennester liegen nordwestlich von {area:17674}, westlich von {quest:92529}. Die Matriarch sitzt an ihrem Westende; {item:263493} liegt am Boden rund um die Nester.",
		["The orchard"] = "Der Obstgarten",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "Die Königin schwebt am Südostende des Hains, auf deinem Rückweg von den Steinen.",
		["The road from {zone:1412} meets the {area:458} at {area:378}: {npc:10378}, the wind rider master, stands beside {npc:3418} on your way north to the Crossroads."] = "Die Straße aus {zone:1412} trifft bei {area:378} auf die {area:458}: {npc:10378}, der Windreitermeister, steht neben {npc:3418} auf deinem Weg nach Norden zum Wegekreuz.",
		["The standing stones"] = "Die Menhire",
		["The turncoat"] = "Der Überläufer",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}, just north of {npc:273017}."] = "Das Haus des Überläufers liegt in {area:16626} nordwestlich von {area:16638}, direkt nördlich von {npc:273017}.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629} liegt nördlich von {area:16638}. Kämpf dich durch die Wachen hinauf zu {npc:253576} auf seiner Ostseite.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {item:260881} lies in a cave in the hills north-west of {npc:256083}."] = "{item:260881} liegt in einer Höhle in den Hügeln nordwestlich von {npc:256083}.",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "Nach {zone:1454}",
		["Underwater"] = "Unter Wasser",
		["Upstairs"] = "Oben",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Benutze {item:278078} an der Zeremonienmatte und dem Räuchergefäß an der Südklippe der {area:1641}.",
		["Valennia asks you to hear out both leaders: {npc:251968} of the Horde and {npc:252475} of the Alliance. {npc:252475}'s name shows red to you, but he talks to you all the same, and the quest needs both."] = "Valennia bittet dich, beide Anführer anzuhören: {npc:251968} von der Horde und {npc:252475} von der Allianz. Der Name von {npc:252475} erscheint dir rot, aber er spricht trotzdem mit dir, und die Quest braucht beide.",
		["Warlock trainer"] = "Hexenmeisterlehrer",
		["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:11869} (10 Silber); die Nahkampfwaffe eines Jägers besteht hauptsächlich aus ihren Werten, und Zweihänder bringen am meisten.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Wenn du schon hier bist: Lerne {spell:199} bei {npc:11869} (10 Silber); Zweihandwaffen lassen einen Krieger am schnellsten leveln.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Du verlässt die Insel endgültig. {npc:259119} wartet, wo das Luftschiff landet.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Du wachst in {area:16635} auf, im Norden der Insel. {npc:251362} steht am Pfad, {npc:251361} in der Dorfmitte.",
		["drink the {item:6635} at the {area:16988}, just east of the village, to see the {npc:251166}"] = "trink {item:6635} bei {area:16988}, direkt östlich des Dorfes, um {npc:251166} zu sehen",
		["search the dead cultist in the house"] = "durchsuch den toten Kultisten im Haus",
		["search the wardrobe"] = "durchsuch den Kleiderschrank",
		["talk to {npc:251684}"] = "sprich mit {npc:251684}",
		["talk to {npc:251902}"] = "sprich mit {npc:251902}",
		["talk to {npc:251968}"] = "sprich mit {npc:251968}",
		["talk to {npc:252155}"] = "sprich mit {npc:252155}",
		["talk to {npc:252476}"] = "sprich mit {npc:252476}",
		["talk to {npc:253844}"] = "sprich mit {npc:253844}",
		["talk to {npc:257554}"] = "sprich mit {npc:257554}",
		["tame one with {npc:252389}'s first {item:15908} while you are among them"] = "zähme eines mit der ersten {item:15908} von {npc:252389}, solange du unter ihnen bist",
		["the bounty board"] = "das Kopfgeldbrett",
		["{area:16622}: kill these as you meet them"] = "{area:16622}: Töte diese, sobald du ihnen begegnest",
		["{area:16623}: kill these as you meet them"] = "{area:16623}: Töte diese, sobald du ihnen begegnest",
		["{area:16624} hand-ins"] = "Abgaben in {area:16624}",
		["{area:16624} turn-ins"] = "Abgaben in {area:16624}",
		["{area:16624}: kill these as you meet them"] = "{area:16624}: töte diese, wenn du sie triffst",
		["{area:16626}: kill these as you meet them"] = "{area:16626}: Töte diese, sobald du ihnen begegnest",
		["{area:16631}: kill these as you meet them"] = "{area:16631}: Töte diese, sobald du ihnen begegnest",
		["{area:16635} turn-ins"] = "Abgaben in {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663} liegt westlich von {area:16638} an der Küstenstraße.",
		["{item:251924}: the Al'Aketh in {npc:252095}'s camp carry it"] = "{item:251924}: Die Al'Aketh in {npc:252095}s Lager tragen es",
		["{item:257128} cones grow south of the hermit; the Wind Hollows drift east of the lake and also drop the Wind Hollow Essences for {npc:254344}'s {quest:93736}. The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "{item:257128}-Zapfen wachsen südlich des Einsiedlers; die Wind Hollows treiben östlich des Sees und lassen auch die Wind Hollow Essences für {quest:93736} von {npc:254344} fallen. Die Habseligkeiten der Flüchtlinge liegen am Nordufer von {area:16625}; {npc:259013} ist an dessen Nordwestende.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} wächst um {npc:257944}s Lager, und Kreischlinge fliegen darüber. Das Lager der Al'Aketh östlich von ihr enthält {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, von {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, von {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, von {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, von {npc:3027}",
		["{npc:2127} in {zone:1420}; {area:16638} has no warlock trainer"] = "{npc:2127} in {zone:1420}; in {area:16638} gibt es keinen Hexenmeisterlehrer",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363} steht bei {area:17678}, östlich des Dorfs. {npc:251143} und Konvertiten der Al'Aketh sammeln sich gleich nördlich von ihr. {object:460001} ist gleich nordöstlich von ihr: Wirk daneben deine Volksfähigkeit {spell:1259686}.",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}.\nThe Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "{npc:250926} streifen über die Hänge südwestlich des Dorfes, auf dem Weg zu {npc:252095}.\nDie Höhle der Ursera liegt westlich des Dorfes. {npc:251115}, ihre Matriarchin, sitzt an ihrem hinteren Ende.",
		["{npc:251361}'s errands"] = "{npc:251361}s Besorgungen",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: eine Notiz von deinem Lehrer",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: Untersuche {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: Lies {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, der Druidenlehrer, im Erdgeschoss des Baums hinter {npc:251361}",
		["{npc:251374}, beside {npc:251361}"] = "{npc:251374}, neben {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} und dein {item:5175}",
		["{npc:251376}, beside {npc:251361}"] = "{npc:251376}, neben {npc:251361}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, im Wachturm",
		["{npc:251523} waits in {area:16624} for what you found in the wardrobe."] = "{npc:251523} wartet in {area:16624} auf das, was du im Kleiderschrank gefunden hast.",
		["{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172} and {npc:251523} all stand in {area:16624}. If you are still short of {item:5469}, the Galestriders graze just west of the village; the Al'Aketh camps south and south-east of it are a level or two higher."] = "{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172} und {npc:251523} stehen alle in {area:16624}. Wenn dir noch {item:5469} fehlt, grasen die Galestriders direkt westlich des Dorfes; die Lager der Al'Aketh südlich und südöstlich davon sind ein bis zwei Stufen höher.",
		["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905}: Camping 101 verlangt, dass du es lernst",
		["{npc:251913} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251913} nimmt sie entgegen, sobald deine Fertigkeit in {skill:164} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, im Wachturm",
		["{npc:251968} sends you on to Kalimdor. Once you have trained, board the skycutter at the dock on {area:16638}'s south-west edge: it flies to northern {zone:1412}, where {npc:259119} waits."] = "{npc:251968} schickt dich weiter nach Kalimdor. Nachdem du gelernt hast, besteige den Skycutter am Dock am Südwestrand von {area:16638}: Er fliegt ins nördliche {zone:1412}, wo {npc:259119} wartet.",
		["{npc:251992} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251992} nimmt sie entgegen, sobald deine Fertigkeit in {skill:356} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:251993} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251993} nimmt sie entgegen, sobald deine Fertigkeit in {skill:165} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095} wartet in {area:16622}, südwestlich des Dorfes. Das Lager der Al'Aketh liegt direkt dahinter; {npc:256935} führt es an.\nVorsicht: {npc:256935} wirkt Schocks; zieh ihn von den anderen Kultisten weg, bevor du kämpfst, damit sie nicht eingreifen.",
		["{npc:252359} stands on {area:16638}'s east side. {npc:255853} waits by the falls just north of the {area:17675}: leave town to the north, climb the ridge east of the road and glide down to him with {spell:1259416}."] = "{npc:252359} steht auf der Ostseite von {area:16638}. {npc:255853} wartet an den Wasserfällen direkt nördlich von {area:17675}: Verlasse die Stadt nach Norden, klettere auf den Grat östlich der Straße und gleite mit {spell:1259416} zu ihm hinab.",
		["{npc:252377} stands beside {npc:256083}, just north-west of {area:16638}."] = "{npc:252377} steht neben {npc:256083}, direkt nordwestlich von {area:16638}.",
		["{npc:252377}, beside {npc:256083}: {quest:94003}"] = "{npc:252377}, neben {npc:256083}: {quest:94003}",
		["{npc:252382}, beside {npc:251968}: {quest:97243}"] = "{npc:252382}, neben {npc:251968}: {quest:97243}",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{npc:252383}, upstairs"] = "{npc:252383}, oben",
		["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389} nimmt den ersten {item:15908} zurück und gibt dir zwei weitere, einen nach dem anderen: Ornery Galestriders und Vuldren Alphas streifen über die Felder direkt nördlich von ihr. Zähme jeweils eins mit seinem Stab und bring den Stab zu ihr zurück. {npc:254411}, neben ihr, lehrt {spell:5149}.",
		["{npc:252389}, a few steps west of {npc:257006}: {quest:94978}, the first rod"] = "{npc:252389}, ein paar Schritte westlich von {npc:257006}: {quest:94978}, die erste Rute",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} und {npc:256083}",
		["{npc:252476}, upstairs"] = "{npc:252476}, oben",
		["{npc:253372}, inside"] = "{npc:253372}, drinnen",
		["{npc:253590}, upstairs"] = "{npc:253590}, oben",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} und {npc:258134} sind im Kultlager östlich von {npc:257944}. {npc:254151} steht an seinem Rand. Haalien lässt auch {quest:94490} fallen: Lies ihn, um die nächste Quest zu starten. Für {quest:94489} betrittst du den Nachtfangbau, heilst 7 verletzte Druiden und findest {npc:258130}.",
		["{npc:254344}, beside {npc:251968}"] = "{npc:254344}, neben {npc:251968}",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} lauert südlich des Dorfs zwischen den Rudelkrallen. {npc:254589} ist Elite: Such dir am besten eine Gruppe.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} steht in {area:16626} gleich nordwestlich der Stadt.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} wartet auf der Straße nördlich von {area:16638}, Richtung {area:16629}.",
		["{npc:257006} and {npc:252448}"] = "{npc:257006} und {npc:252448}",
		["{npc:257006} waits inside a house on {area:16638}'s western edge; {npc:252448} is close by."] = "{npc:257006} wartet in einem Haus am Westrand von {area:16638}; {npc:252448} ist in der Nähe.",
		["{npc:257006}, inside"] = "{npc:257006}, drinnen",
		["{npc:257018} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257018} nimmt sie entgegen, sobald deine Fertigkeit in {skill:129} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:257019} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257019} nimmt sie entgegen, sobald deine Fertigkeit in {skill:171} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:257022} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257022} nimmt sie entgegen, sobald deine Fertigkeit in {skill:186} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:257024} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257024} nimmt sie entgegen, sobald deine Fertigkeit in {skill:393} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} hält {item:263993} auf der Westseite des Schreins.",
		["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554} und {npc:263113} stehen oben auf dem Wachturm, ein paar Schritte nordöstlich von {npc:251368}.",
		["{npc:257944} again"] = "Wieder {npc:257944}",
		["{npc:257944}, last time"] = "{npc:257944}, ein letztes Mal",
		["{npc:258443} has her lair in a cave in the bluffs just south of the turncoat's house, where the {area:16623} meet the {area:16626}."] = "{npc:258443} hat ihr Versteck in einer Höhle in den Klippen direkt südlich vom Haus des Überläufers, wo {area:16623} auf {area:16626} treffen.",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, bei der Landestelle: für {npc:3033} in {zone:1456}",
		["{npc:259119}: keep it: Thrall in {zone:1454}, at the start of the next guide"] = "{npc:259119}: Behalte es: Thrall in {zone:1454}, am Anfang des nächsten Guides",
		["{npc:268592}, at the Shrine of Flames just south-east of the orchard"] = "{npc:268592}, am Schrein der Flammen direkt südöstlich des Obstgartens",
		["{npc:268602}, on the hill west of the falls just north of the watchtower"] = "{npc:268602}, auf dem Hügel westlich der Wasserfälle direkt nördlich des Wachturms",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} will Taurenweihrauch: Kauf seine vier Teile bei {npc:3014}, der Kräuterhändlerin, {npc:3012}, der Händlerin für Verzauberkunstbedarf, {npc:3005}, dem Händler für Lederverarbeitungsbedarf, und {npc:3027}, dem Händler für Kochbedarf, und kombiniere sie dann zu {item:278078}.",
		["{npc:5543} stands in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart."] = "{npc:5543} steht in {area:2197}, der Höhle unter {area:1640}: Geh drinnen hinunter, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} liegt südlich von Shen'dar. {npc:257065} trifft dich an seinem Rand; durchsuch den Kleiderschrank im Haus hinter ihm.",
		["{zone:1454}'s {object:172982}"] = "{object:172982} von {zone:1454}",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "/sit an Kagas Lagerfeuer, bis du {spell:1229451} bekommst",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Zurück nach Osten zur {area:358}: Die Schamanen der Borstennacken stehen dort zwischen den Stacheleber.",
		["Back north-west up to {area:221}."] = "Zurück nach Nordwesten hinauf nach {area:221}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Zurück zu {npc:5888} im Lager. {npc:5891} wartet auf dem Tafelberg östlich des Lagers: Trink dort {item:6635}, um sie zu sehen, und bring dann {item:6656} zurück zum Seher.",
		["Back west to the camp."] = "Zurück nach Westen zum Lager.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Kampfeber grasen nördlich des Schreins; die Stacheleber der Borstennacken halten die Schlucht im Nordosten. {npc:8554} steht an ihrem östlichen Ende, und {object:3076} liegt im Lager auf dem Boden.",
		["Below ground"] = "Unter der Erde",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}; der {quest:5930} sitzt in den nordwestlichen Wäldern. {npc:11802} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Class trainer"] = "Klassenlehrer",
		["Class turn-in in {area:1638}"] = "Klassen-Abgabe in {area:1638}",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Zieh nach Nordwesten an {zone:1456} vorbei zum {area:398} im äußersten Norden von {zone:1412}.",
		["Cross to {area:1639}."] = "Geh hinüber nach {area:1639}.",
		["Deathskip to {area:220}"] = "Deathskip nach {area:220}",
		["Die to the mobs at 63.7,78.4 ({npc:2954}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Stirb bei den Mobs auf 63.7,78.4 ({npc:2954}): Ein Tod dort schickt dich zu diesem Friedhof. Gib deinen Geist frei und nimm die Wiederbelebung des {npc:6491} an.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "Folge der Straße nach Norden aus {area:220}. {npc:265810} wartet auf der Straße gleich südlich von {area:222}; /sit an ihrem Lagerfeuer, bis du {spell:1229451} bekommst. Wenn du einen Beruf erlernt hast, bietet Kaga auch ihr Camping 101 an, das dessen Lehrer entgegennimmt: in Bloodhoof oder beim Halt in {zone:1456}.",
		["From {area:1639}, take {zone:1456}'s north lift down: at its foot the way runs east along the ledge, then south-east across {zone:1412} to the {zone:1413}."] = "Nimm von {area:1639} aus den Nordaufzug von {zone:1456} nach unten: An seinem Fuß führt der Weg nach Osten den Felsvorsprung entlang, dann nach Südosten durch {zone:1412} ins {zone:1413}.",
		["Galak centaurs"] = "Zentauren der Galak",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Geh nach Norden zu {area:225}, östlich von {zone:1456}. {npc:3233} steht am Fuß der Felsen; die Eindringlinge der Borstennacken graben auf der Grabstätte, und {npc:2994} wartet oben.",
		["Inside"] = "Drinnen",
		["Into {zone:1412}"] = "Nach {zone:1412}",
		["Into {zone:1413}"] = "Hinein nach {zone:1413}",
		["Leave {zone:1412} by the south-eastern pass and follow the road to the Crossroads. {npc:3448} stands at the south gate, {quest:860} by the inn, {npc:3615} on the tower platform. {area:380}' own quests come after {zone:1421}, in the {zone:1413} guide."] = "Verlasse {zone:1412} über den südöstlichen Pass und folge der Straße zur Kreuzung. {npc:3448} steht am Südtor, {quest:860} beim Gasthaus, {npc:3615} auf der Turmplattform. Die eigenen Quests von {area:380} kommen nach {zone:1421}, im Guide für {zone:1413}.",
		["Over the bridge below {area:379} and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Über die Brücke unter {area:379} und nach Süden am Flussufer auf der Seite von {zone:1411} entlang, bis ein schmaler Pfad den Berg hinaufführt: {npc:5900} hütet den Schrein oben. Achte auf dem Weg nach oben auf die Kanten und komm denselben Pfad wieder herunter.",
		["Plainstriders roam the mesa all around the camp: take their meat and feathers on the way back to {npc:2980}."] = "Ebenenschreiter streifen über die ganze Mesa rund ums Lager: Nimm ihr Fleisch und ihre Federn auf dem Rückweg zu {npc:2980} mit.",
		["Prairie Wolves, Wiry Swoops and Adult Plainstriders roam the plains around the village; the plains just south of it, toward the well, hold them without the Elder Plainstriders (8-9) and Prairie Wolf Alphas (9-10) that roam farther out."] = "Präriewölfe, Drahtige Sturzflieger und Erwachsene Ebenenschreiter streifen über die Ebenen um das Dorf; die Ebenen direkt südlich davon, Richtung Brunnen, haben sie ohne die Alten Ebenenschreiter (8-9) und Präriewolfalphas (9-10), die weiter draußen umherstreifen.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Fahr mit einem Aufzug hinauf zu den Tafelbergen. {npc:2995} hält die Windreiter auf der mittleren Anhöhe; {npc:3057} steht dort im großen Zelt.",
		["Rogue trainer"] = "Schurkenlehrer",
		["Spread the {item:278078} off {area:1641}"] = "Verstreu {item:278078} von der {area:1641}",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Die Gnolle der Bleichmähnen halten den {area:818}, südlich der Grabungsstätte und westlich von Bloodhoof. {npc:272203} wird in ihrem Lager festgehalten: Führ ihn hinaus.",
		["The Seer's tent stands at the foot of the cougars' hills."] = "Das Zelt des Sehers steht am Fuß der Hügel mit den Pumas.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Die Harpyien der Windfurien halten {area:819}, nördlich und westlich des Brunnens.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Die Zwerge der {area:404} tragen die Ausgrabungsleiterhacken. Zerschlag sie an der Schmiede der Zwerge in der Ausgrabungsstätte.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "Der Weihrauch brennt in zehn Minuten ab: Lauf an den südlichen Hügeln entlang direkt nach Osten zum {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "Der Schrein von An'she und Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "Der Stein steht im Pass aus {zone:1412} hinaus, auf deinem Weg nach Osten. Benutze dort {item:15710} und besiege Mondklaue.",
		["The well lies north of the village. Adult Plainstriders graze around it: they drop the {item:287505} for Kyle."] = "Der Brunnen liegt nördlich des Dorfes. Ausgewachsene Ebenenschreiter grasen um ihn herum: Sie lassen das {item:287505} für Kyle fallen.",
		["The well lies south-east of the village. {npc:2988} camps beside it, and {quest:99079} stands on the {area:821} a little east."] = "Der Brunnen liegt südöstlich des Dorfes. {npc:2988} lagert daneben, und {quest:99079} steht ein Stück östlich in den {area:821}.",
		["The {object:177525}"] = "{object:177525}",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes them when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Donnerechsen und Blitzechsen grasen auf {area:369}, neben der Straße nach Norden nach {zone:1454}; jede von ihnen kann {item:6486} fallen lassen. {npc:5810} nimmt sie entgegen, wenn der nächste Guide an {area:379} vorbeikommt.\nVorsicht: Halikor, ein Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Thunder lizards on the way north"] = "Donnerechsen auf dem Weg nach Norden",
		["To {zone:1454}"] = "Nach {zone:1454}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Benutze {item:278078} an der Zeremonienmatte und dem Räuchergefäß an der Südklippe der {area:1641}.",
		["Warlock trainer"] = "Hexenmeisterlehrer",
		["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:11869} (10 Silber); die Nahkampfwaffe eines Jägers besteht hauptsächlich aus ihren Werten, und Zweihänder bringen am meisten.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Wenn du schon hier bist: Lerne {spell:199} bei {npc:11869} (10 Silber); Zweihandwaffen lassen einen Krieger am schnellsten leveln.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Du beginnst auf dem Tafelberg von {area:221}. {npc:2980} und der Häuptling stehen beim großen Zelt in der Mitte.",
		["{area:220}: kill these as you meet them"] = "{area:220}: Töte sie, wenn sie dir begegnen",
		["{area:221}: kill these as you meet them"] = "{area:221}: Töte sie, wenn sie dir begegnen",
		["{area:379} sits above the {area:814} bridge on the road to {zone:1454}: {npc:5810} stands beside {npc:3337}."] = "{area:379} liegt über der Brücke von {area:814} an der Straße nach {zone:1454}: {npc:5810} steht neben {npc:3337}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, von {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, von {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, von {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, von {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, an der Schmiede der Ausgrabungsstätte",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}: Flachlandstreuner streifen über die Ebenen um {area:225}",
		["{npc:10278} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:10278} nimmt sie entgegen, sobald deine Fertigkeit in {skill:164} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:10378}, beside {npc:3418}"] = "{npc:10378}, neben {npc:3418}",
		["{npc:11047} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11047} nimmt sie entgegen, sobald deine Fertigkeit in {skill:171} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:11051} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11051} nimmt sie entgegen, sobald deine Fertigkeit in {skill:197} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:11071} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11071} nimmt sie entgegen, sobald deine Fertigkeit in {skill:333} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:265810}: for {npc:10278}"] = "{npc:265810}: für {npc:10278}",
