		["{npc:265810}: for {npc:5939}"] = "{npc:265810}: für {npc:5939}",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810}: für {npc:6290}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} will Taurenweihrauch: Kauf seine vier Teile bei {npc:3014}, der Kräuterhändlerin, {npc:3012}, der Händlerin für Verzauberkunstbedarf, {npc:3005}, dem Händler für Lederverarbeitungsbedarf, und {npc:3027}, dem Händler für Kochbedarf, und kombiniere sie dann zu {item:278078}.",
		["{npc:277154} runs around the village: give him the {item:287505}"] = "{npc:277154} rennt durchs Dorf: Gib ihm das {item:287505}",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} steht am Nordrand des Dorfs. Kyle will {item:287505} von Ebenenschreitern.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, am Nordende des Dorfs",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, für Hamuul in {zone:1456}",
		["{npc:2950} walks around {area:16677}: look inside the circle on the map"] = "{npc:2950} läuft um {area:16677} herum: Schau im Kreis auf der Karte nach",
		["{npc:2951}, below ground"] = "{npc:2951}, unter der Erde",
		["{npc:2981}, inside"] = "{npc:2981}, drinnen",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} steht am Rand der {area:404}, südlich des Brunnens.",
		["{npc:2987}, beside {npc:269068}"] = "{npc:2987}, neben {npc:269068}",
		["{npc:2988} walks around here: look inside the circle on the map"] = "{npc:2988} läuft hier herum: Schau im Kreis auf der Karte nach",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} sitzt beim Zelt am Ostrand des Lagers; {object:2907} steht neben ihr.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, für {npc:3057} in {zone:1456}",
		["{npc:3001} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3001} nimmt sie entgegen, sobald deine Fertigkeit in {skill:186} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:3013} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3013} nimmt sie entgegen, sobald deine Fertigkeit in {skill:182} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:3033} trains druids in the Cenarion Circle's tent on {area:1639}."] = "{npc:3033} bildet Druiden im Zelt des Cenarischen Zirkels auf {area:1639} aus.",
		["{npc:3039}, beside {npc:3041}"] = "{npc:3039}, neben {npc:3041}",
		["{npc:3057}'s tent"] = "Das Zelt von {npc:3057}",
		["{npc:3059}, the warrior trainer; inside"] = "{npc:3059}, der Kriegerlehrer; drinnen",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, der Druidenlehrer neben ihr",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, die Jägerlehrerin",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, die Schamanenlehrerin im Lager",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Die Quest von {npc:3063}: Besiege drei Kriegernovizen (oder Spieler im Duell) neben ihm.",
		["{npc:3065} stands at the north end of {area:222}. Tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a {npc:2970} to the north-west."] = "{npc:3065} steht am Nordende von {area:222}. Zähme mit der {item:15908}: einen {npc:2956} auf den Ebenen, einen {npc:2959} nördlich des Dorfes, einen {npc:2970} im Nordwesten.",
		["{npc:3067}: Camping 101 asks you to learn it"] = "{npc:3067}: Camping 101 verlangt, dass du es lernst",
		["{npc:3069} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3069} nimmt sie entgegen, sobald deine Fertigkeit in {skill:165} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}, neben {npc:3067}: {quest:97934}",
		["{npc:3155} in {zone:1411}; {zone:1412} has no rogue trainer"] = "{npc:3155} in {zone:1411}; {zone:1412} hat keinen Schurkenlehrer",
		["{npc:3156} in {zone:1411}; {zone:1412} has no warlock trainer"] = "{npc:3156} in {zone:1411}; {zone:1412} hat keinen Hexenmeisterlehrer",
		["{npc:3209} walks around {area:221}: look inside the circle on the map"] = "{npc:3209} läuft um {area:221} herum: Schau im Kreis auf der Karte nach",
		["{npc:3209}, next to {npc:2980}; walks around {area:221}: look inside the circle on the map"] = "{npc:3209}, neben {npc:2980}; läuft um {area:221} herum: Schau im Kreis auf der Karte nach",
		["{npc:3222} walks around {area:222}: look inside the circle on the map"] = "{npc:3222} läuft um {area:222} herum: Schau im Kreis auf der Karte nach",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418} steht bei {area:378}, wo die Straße aus {zone:1412} auf die {area:458} nach Norden zum Wegekreuz trifft.",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}: für {npc:3429} am Wegekreuz",
		["{npc:3429}, by the wind rider tower"] = "{npc:3429}, beim Windreiterturm",
		["{npc:3441}: for {quest:860} at the Crossroads"] = "{npc:3441}: für {quest:860} an der Kreuzung",
		["{npc:3483} sells armor on the north side of the Crossroads. His bundle goes to {npc:3615}, who sends it with you on the flight to {zone:1456} you take for {npc:3033} anyway."] = "{npc:3483} verkauft Rüstungen auf der Nordseite der Kreuzung. Sein Bündel geht an {npc:3615}, der es dir auf dem Flug nach {zone:1456} mitgibt, den du ohnehin für {npc:3033} nimmst.",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, der Windreitermeister",
		["{npc:5543} stands in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart."] = "{npc:5543} steht in {area:2197}, der Höhle unter {area:1640}: Geh drinnen hinunter, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:5769}: for {npc:3448} at the Crossroads"] = "{npc:5769}: für {npc:3448} an der Kreuzung",
		["{npc:5888} stands in {area:221}. {quest:1519} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} steht im {area:221}. {quest:1519} erfordert Stufe 4, die du mit den Abgaben hier erreichst.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} und dein {item:5175}",
		["{npc:5906}, a few steps from {npc:5543} on {area:1640}"] = "{npc:5906}, ein paar Schritte von {npc:5543} auf {area:1640}",
		["{npc:5907} stands alone on the ridge above the Razormane camp, north-east of the Crossroads on the road to {area:379}."] = "{npc:5907} steht allein auf dem Grat über dem Lager der Klingenmähnen, nordöstlich des Wegekreuzes an der Straße nach {area:379}.",
		["{npc:5938} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5938} nimmt sie entgegen, sobald deine Fertigkeit in {skill:356} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:5939} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5939} nimmt sie entgegen, sobald deine Fertigkeit in {skill:129} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:6290} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6290} nimmt sie entgegen, sobald deine Fertigkeit in {skill:393} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}, neben {npc:3067}: {quest:97936}",
		["{npc:6746}, at the south end of the central rise: the hearth from {quest:5922} brings you back here"] = "{npc:6746}, am Südende der zentralen Anhöhe: Der Ruhestein aus {quest:5922} bringt dich hierher zurück",
		["{npc:6746}: {quest:5926}, for {npc:3033} on {area:1639}"] = "{npc:6746}: {quest:5926}, für {npc:3033} auf {area:1639}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775} steht am Westende des Lagers, an der Nordwestecke der Hügel, wo die Bergpumas umherstreifen: Nimm seine Quest an und jag dann die Pumas durch die Hügel nach Süden, zum Zelt des Sehers an ihrem Fuß.",
		["{npc:8359}, by the wind riders on the central rise"] = "{npc:8359}, bei den Windreitern auf der zentralen Anhöhe",
		["{object:2910}, 170 yd east"] = "{object:2910}, 170 yd östlich",
		["{zone:1412}: kill these as you meet them"] = "{zone:1412}: Töte sie, wenn sie dir begegnen",
		["{zone:1454}'s {object:172982}"] = "{object:172982} von {zone:1454}",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Gepanzerte Skorpide kriechen über die Ebenen westlich von {area:362}. Zähm einen und kehr dann zu {npc:3171} zurück.",
		["Back east to Sen'jin on the way to the {area:368}."] = "Zurück nach Osten nach Sen'jin auf dem Weg zu den {area:368}.",
		["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Zurück nach Nordwesten zu {area:362}: erst {npc:3139}, dann {npc:3147} im Wachturm, dann {npc:3142} und {npc:266940} auf dem Weg nach Osten zur Küste.",
		["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Zurück über die Brücke und nach Süden am Ufer des Flusses auf der Seite von {zone:1411} entlang, bis ein schmaler Pfad den Berg hinaufführt: {npc:5900} hütet den Schrein oben. Achte auf dem Weg nach oben auf die Ränder und komm auf demselben Pfad wieder herunter.",
		["Back to the Den"] = "Zurück zum Höhlenbau",
		["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Zurück zum Bau: {npc:3143} nimmt die Klaue von {quest:804} entgegen, und {npc:5887} direkt draußen hat jetzt, da du Stufe 4 bist, {quest:1516}.",
		["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Zurück nach {area:362}: {npc:3139}, dann {npc:3142}.",
		["Back to {zone:1411}"] = "Zurück nach {zone:1411}",
		["Below ground"] = "Unter der Erde",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Kultisten der Burning Blade halten die Höhlen von {quest:827}; jeder lässt {item:4871} fallen. {npc:3204}, ein Hexenmeister der Stufe 14, steht tief drinnen und lässt {item:4903} fallen.\nVorsicht: In {quest:827} kämpfen Leerwandler an der Seite der Kultisten der Burning Blade, und {npc:3204} (14) wartet hinten mit seinem eigenen: Zieh die Kultisten für die Halsbänder einzeln nahe dem Eingang. {item:4903} ist optional: Lass {npc:3204} in Ruhe, außer du bist 13 oder hast einen Freund dabei.",
		["Class trainer"] = "Klassenlehrer",
		["Deathskip to Northern Durotar"] = "Todessprung ins nördliche Durotar",
		["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Stirb an den Mobs bei 52.0,21.4 ({npc:3118}): Ein Tod dort schickt dich zu diesem Friedhof. Gib deinen Geist frei und nimm die Wiederbelebung von {npc:6491} an.",
		["Druid trainer"] = "Druidenlehrer",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Teufelspirscher streifen über den Hang unterhalb der Höhle, auf der Nordseite des Tals.",
		["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle hält das Lager der Brennenden Klinge auf {area:369}, gleich nördlich von Mishas Hütte. Jäger: Zähm unterwegs mit {item:15908} einen {npc:3099}.\nVorsicht: Kultisten der Brennenden Klinge umgeben Fizzle, manche verbunden, sodass sie zu zweit angreifen, und sie respawnen schnell.\nVorsicht: Halikor, eine Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Follow the road east out of the valley to {area:367} on the coast.\nCareful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "Folge der Straße nach Osten aus dem Tal nach {area:367} an der Küste.\nVorsicht: Ukorsbane (8) ist ein Elite und läuft zwischen den Ridgeshade-Spinnen im Lager südlich von {area:362} umher: Zieh die Spinnen von ihm weg.",
		["Free {npc:275811} and see her safely out of the crag"] = "Befrei {npc:275811} und bring sie sicher aus dem Felsen",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Geh nach Nordosten zur Straße Richtung {zone:1454}. {npc:3293} lagert daneben; die gestohlenen Säcke liegen entlang der Straße südlich von ihm.",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10.\nWade back west to the shore south of Sen'jin when the isles are done."] = "Geh nach Süden über die Inseln. Die Loa-Götzen liegen überall auf den südlichen Inseln; Voodootrolle und Verhexte Trolle halten sie und lassen die Verhexten Anhänger fallen. {quest:826} und Minshinas Käfig sind auf der südlichsten Insel.\nVorsicht: Die Trolle stehen dicht beieinander und die Voodootrolle zaubern aus der Ferne: Zieh sie einzeln. {quest:826} selbst ist Stufe 10.\nWate zurück nach Westen zur Küste südlich von Sen'jin, wenn du mit den Inseln fertig bist.",
		["Heal and fortify {npc:12430}"] = "Heile und stärke {npc:12430}",
		["Inside"] = "Drinnen",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Geh in der Höhle an der ersten Gabelung geradeaus, dann rechts, und folge dem Bach zu deiner Linken bis zum Wasserfall: Die Hacke leuchtet am Wasser, hinter einer Felssäule.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Halte dich in der Höhle immer an der rechten Wand, über den Bach: {npc:3183} wartet am Ende.",
		["Level 10"] = "Stufe 10",
		["Level 11"] = "Stufe 11",
		["Level 7"] = "Stufe 7",
		["Level 9"] = "Stufe 9",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin; the Taillasher eggs sit in nests along the beach.\nThe gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "Makrura und Brandungskrabbler säumen die Strände nordöstlich von Sen'jin; die Eier der Peitschenschwänze liegen in Nestern am Strand.\nDie gnomischen Werkzeugkisten liegen im Wrack entlang der Küste östlich und südöstlich von {area:362}. Folge der Küste nach Süden bis Sen'jin.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Mishas Hütte steht südlich der Echsen. Die Krokilisken am {area:814} im Westen tragen {item:4891}.",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "Nordöstlich zum Strand unterhalb von {area:370}, nördlich von {npc:275657}: Spitelash Scouts und Attendants halten ihn. Jäger: Zähme einen {npc:3107} am Strand.",
		["Paladin trainer"] = "Paladinlehrer",
		["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "Stacheleber und Späher halten die Hütten westlich des Orts, wo die Kaktusfeigen wachsen; Staubläufer und Schlachtwachen halten die Lager weiter westlich.",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "Savages und Storm Witches nisten in {area:370}, östlich von {npc:3293}. Eine Storm Witch lässt {item:277661} fallen. Schamanen: Die Burning Blade Cultists bei {area:371} am Südende der Schlucht lassen {item:6652} fallen.",
		["Spitelash naga"] = "Naga der Grollflossen",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The Scorpid Workers roam the slope south of {npc:3287}; pick the Cactus Apples by the cactuses on the way.\nThe {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "Die Skorpidarbeiter streifen über den Hang südlich von {npc:3287}; pflücke die Kaktusäpfel bei den Kakteen auf dem Weg.\nDie {quest:792} schwärmen über den Hang unterhalb von {area:365}, der Höhle an der Nordseite des Tals.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Rohrkolben und Speergras wachsen am Wasser im {object:172958}, östlich der Gasse.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "Die Burg steht an der Küste südöstlich von {area:362}. Axt, Bogen und Schild der Räuber liegen an ihrem Rand. Matrosen und Marinesoldaten lassen {item:4870} fallen.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Die Waffen liegen um den Höhlenbau und den Übungsplatz; die Scheckigen Eber streifen über den ganzen Talboden.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} steht in {area:817}, zwischen den Kultisten, die du gerade bekämpft hast.",
		["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "Durch Sen'jin auf dem Weg nach Westen zu {area:366}: {npc:3304} nimmt jetzt die Augen und den Schleim entgegen.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Donnerechsen und Blitzechsen grasen auf {area:369}, neben der Straße nach Norden nach {zone:1454}; jede kann {item:6486} fallen lassen. {npc:5810} nimmt sie an, wenn der nächste Guide am {area:379} vorbeikommt.\nVorsicht: Halikor, eine Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Donnerechsen und Blitzechsen grasen auf {area:369}, gleich westlich und südwestlich von {npc:3293}.\nVorsicht: Halikor, eine Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Thunder lizards on the way north"] = "Donnerechsen auf dem Weg nach Norden",
		["To {zone:1454}"] = "Nach {zone:1454}",
		["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "Hol hier Stufe 11 auf, bevor du dich an {npc:3203} (12) und seinen Wichtel wagst: Die Donnerechsen (9-10) grasen auf dem Kamm gleich westlich von Mishas Hütte.",
		["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "Level hier auf Stufe 7, bevor du dich {npc:3192} (8) und den Marinesoldaten oben in der Burg stellst.",
		["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "Level hier auf Stufe 9, bevor du zu den südlichen Inseln gehst: Die Voodoo- und Verhexten Trolle dort sind 8-9 und {quest:826} ist 10.",
		["Training weapons and boars"] = "Übungswaffen und Eber",
		["Underwater"] = "Unter Wasser",
		["Upstairs"] = "Oben",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there; Durotar Tigers roam the isle and the shore south of Sen'jin."] = "Wate hinüber zur nördlichen Echoinsel. Die Matriarchin streift dort zwischen den Raptoren umher; Durotartiger laufen auf der Insel und an der Küste südlich von Sen'jin herum.",
		["Wake {quest:5441} with the {item:16114}"] = "Weck {quest:5441} mit {item:16114}",
		["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "Von {area:362} nach Westen über die Brücke von {area:814}: {npc:3337} und {npc:5810} stehen zusammen bei {area:379} oberhalb davon. Von dort führt die Straße nach Norden durch {zone:1411} nach {zone:1454}.",
		["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Nach Westen über die Brücke von {area:814}, an {area:379} vorbei und weiter entlang des Grats: {npc:5907} steht allein oberhalb des Razormane-Lagers.",
		["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "Nach Westen über die Brücke von {area:814}: {npc:3337} steht bei {area:379} oberhalb davon, auf deinem Weg zu {npc:5907}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:2704} ({object:172958}, 10 Silber); die Nahkampfwaffe eines Jägers besteht hauptsächlich aus ihren Werten, und Zweihandwaffen haben die meisten.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Wenn du schon hier bist: Lerne Stäbe bei {npc:2704} ({object:172958}, 10 Silber); ein Stab hat beim Leveln mehr Zauberwerte als eine Einhandwaffe.",
		["grind on {npc:3111}"] = "grinde {npc:3111}",
		["grind on {npc:3121}"] = "grinde an {npc:3121}",
		["grind on {npc:3128}"] = "grinde an {npc:3128}",
		["grind on {npc:3130}"] = "Grinde an {npc:3130}",
		["the {object:654925} on the ground beside her"] = "{object:654925} neben ihr auf dem Boden",
		["{area:363}: kill these as you meet them"] = "{area:363}: töte diese, wenn du sie triffst",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} liegt westlich von Sen'jin. Die drei Angriffspläne liegen zwischen den Zentaurenzelten auf dem Boden. {npc:275811} wird ebenfalls am Felsen festgehalten.",
		["{area:368}: kill these as you meet them"] = "{area:368}: töte diese, wenn du sie triffst",
		["{area:369}: kill these as you meet them"] = "{area:369}: töte diese, wenn du sie triffst",
		["{area:373}: kill these as you meet them"] = "{area:373}: töte diese, wenn du sie triffst",
		["{area:817}'s mouth"] = "Eingang von {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, wo du startest",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11025} nimmt sie entgegen, sobald deine Fertigkeit in {skill:202} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:11378} first, just east of the Den as you come down from the cave; then inside the Den ({npc:3143}, your trainer, {npc:3707}), and {npc:3145} and {npc:5887} at the entrance on the way out east to {npc:6786}."] = "Zuerst {npc:11378}, gleich östlich des Höhlenbaus, wenn du von der Höhle herunterkommst; dann im Höhlenbau ({npc:3143}, dein Lehrer, {npc:3707}), und {npc:3145} und {npc:5887} am Eingang auf dem Weg nach Osten zu {npc:6786}.",
		["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, am Holzstapel östlich des Baus",
		["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430} kniet hinter den Felsen gleich neben der Straße südlich von {area:362}, auf deinem Weg zur Burg. Wirk {spell:613} (Rang 2) auf sie, dann {spell:1243}: Rang 1 von {spell:613} zählt nicht.",
		["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} in {zone:1456}; in {area:362} gibt es keinen Paladin-Lehrer",
		["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} in {zone:1456}; in {area:363} gibt es keinen Paladin-Lehrer",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} lagert gleich südlich von {area:362}. Setz dich an sein Lagerfeuer (/sit), bis der Buff {spell:1229451} erscheint. Wenn du einen Beruf erlernt hast, bietet {npc:265809} auch sein Camping 101 an, das dein Berufslehrer entgegennimmt: in {area:362} oder in {zone:1454} zu Beginn des nächsten Guides.",
		["{npc:265809}'s campfire"] = "Lagerfeuer von {npc:265809}",
		["{npc:265809}: for Jandi"] = "{npc:265809}: für Jandi",
		["{npc:265809}: for Jhag"] = "{npc:265809}: für Jhag",
		["{npc:265809}: for Karolek"] = "{npc:265809}: für Karolek",
		["{npc:265809}: for Snang"] = "{npc:265809}: für Snang",
		["{npc:265809}: for Thuwd"] = "{npc:265809}: für Thuwd",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: für {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: für {npc:11046}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: für {npc:3175}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: für {npc:5943}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: nur für Verzauberer, die Rückstände werden aus Verhexten Anhängern ({item:275724}) entzaubert",
		["{npc:266940}, inside"] = "{npc:266940}, drinnen",
		["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, auf der Ostseite der Stadt; drinnen",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} steht am Ufer östlich von {area:362}. Dreizack, Banner und Dolch liegen um ihn herum am Strand.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, ein junger Meeresriese, läuft an der Nordküste von {zone:1411} entlang, nördlich des Strandes der Naga. {npc:275666} ist Elite: Gruppe empfohlen.",
		["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} in {zone:1412}; in {area:362} gibt es keinen Druidenlehrer",
		["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} in {zone:1412}; in {area:363} gibt es keinen Druidenlehrer",
		["{npc:3102} hooves"] = "{npc:3102}-Hufe",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, zurück in {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, ein Elite-Meeresriese",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} steht gleich hinter dem Höhleneingang; {npc:3159} hinten in der Höhle hinter ihm.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} wartet im Höhlenbau, dem Gebäude gleich westlich von {npc:10176}.",
		["{npc:3143}, inside"] = "{npc:3143}, drinnen",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, im Wachturm",
		["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, im hinteren Teil der Höhle; unterirdisch",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}: {npc:3352} in {zone:1454} lehrt {spell:5149}",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3175} nimmt sie entgegen, sobald deine Fertigkeit in {skill:186} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191}: Camping 101 verlangt, dass du ihn lernst",
		["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192} wartet oben in der Burg; sein Schlüssel öffnet die Truhe neben ihm, in der {item:4881} liegt.",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} liegt verwundet am Fuß der Hügel nordwestlich des Höhlenbaus.",
		["{npc:3706}, beside {npc:266940}: the {item:16606}"] = "{npc:3706}, neben {npc:266940}: {item:16606}",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, für {npc:6018} in {zone:1454}: behalte sie",
		["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}, in der Kaserne neben {npc:266940}",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, der Priesterlehrer am Höhlenbau",
		["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}, der Priesterlehrer am Höhlenbau: für {npc:3706} in {area:362}",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875} steht in {object:172960}, der Schlucht unter {object:172982}. Gib ihm {item:6535}, benutze dann {item:7464} am Beschwörungskreis neben ihm und besiege den Leerwandler, um ihn zu binden.\nVorsicht: Der Leerwandler, den du beschwörst, schlägt hart zu, und an diesem Kampf sterben in {zone:1454} die meisten Hexenmeister: Fang mit voller Gesundheit und Mana an, schick deinen Wichtel vor, halte Verderbnis und Feuerbrand auf ihm und benutze einen Gesundheitsstein, falls du einen hast.",
		["{npc:5880}, the mage trainer in Sen'jin"] = "{npc:5880}, der Magierlehrer in Sen'jin",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} steht vor dem Höhlenbau. {area:639} ist der Hügel gleich südlich davon: Trink dort {item:6635}, um {npc:5891} zu sehen, und bring dann {item:6656} zurück zu {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} und dein {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, auf dem {area:639}",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5943} nimmt sie entgegen, sobald deine Fertigkeit in {skill:129} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} steht auf der Straße am östlichen Ausgang des Tals.",
		["{npc:6928}, inside"] = "{npc:6928}, drinnen",
		["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796} steht gleich vor dem Eingang des Höhlenbaus.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, am Kochfeuer",
		["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "{quest:790}, ein großer Skorpid (Stufe 4), streift über den Hang gleich westlich des Baus, unterhalb von {npc:3287}, auf dem Weg nach Norden zu {area:365}.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} lagert auf dem Hügel westlich des Nagastrands, südlich von {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Das Haupttor von {zone:1454} liegt gleich westlich von {area:817}. {npc:5875} steht in {object:172960}, der Schlucht unter dem {object:172982}.",
		["{zone:1454}'s {object:172982}"] = "{object:172982} von {zone:1454}",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "/sit an ihrem Lagerfeuer, bis du {spell:1229451} bekommst",
		["Ask {npc:10666} for his report"] = "Bitte {npc:10666} um seinen Bericht",
		["Ask {npc:1496} for his report"] = "Bitte {npc:1496} um seinen Bericht",
		["Ask {npc:251001} for his report"] = "Bitte {npc:251001} um seinen Bericht",
		["Back east along the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Zurück die Straße nach Osten nach {area:159}. {npc:2128} (Magier), {npc:2129} (Priester), {npc:2127} (Hexenmeister) und {npc:2130} (Schurken) stehen oben im Gasthaus: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Back to the church"] = "Zurück zur Kirche",
		["Back to {area:154}"] = "Zurück nach {area:154}",
		["Back to {zone:1420}"] = "Zurück nach {zone:1420}",
		["Back up the road and through {area:159} to its west end."] = "Zurück die Straße hinauf und durch {area:159} bis zu seinem Westende.",
		["Back up the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Zurück die Straße hinauf nach {area:159}. {npc:2128} (Magier), {npc:2129} (Priester), {npc:2127} (Hexenmeister) und {npc:2130} (Schurken) stehen oben im Gasthaus: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Back up to the forest's edge south of the keep's gate: {npc:246389} and {npc:259190} take the bones and the crystal."] = "Zurück nach oben zum Waldrand südlich des Festungstors: {npc:246389} und {npc:259190} nehmen die Knochen und den Kristall.",
		["Beat {npc:6784} in the duel"] = "Besiege {npc:6784} im Duell",
		["Below ground"] = "Unter der Erde",
		["Crusader's Outpost"] = "Außenposten der Kreuzzügler",
		["Dry Branches"] = "Trockene Äste",
		["Eleanor camps just south-west of town. With a profession learned, she also offers its Camping 101, which its trainer takes: in {area:159}, at Linnea's camp, or in the {zone:1458} in the next guide."] = "Eleanor lagert direkt südwestlich des Ortes. Wenn du einen Beruf erlernt hast, bietet sie auch das passende Camping 101 an, das sein Lehrer annimmt: in {area:159}, in Linneas Lager oder in {zone:1458} im nächsten Guide.",
		["Eleanor: for {npc:2114}"] = "Eleanor: für {npc:2114}",
		["Eleanor: for {npc:2132}"] = "Eleanor: für {npc:2132}",
		["Eleanor: for {npc:3523}"] = "Eleanor: für {npc:3523}",
		["Eleanor: for {npc:3549}"] = "Eleanor: für {npc:3549}",
		["Eleanor: for {npc:4586}"] = "Eleanor: für {npc:4586}",
		["Eleanor: for {npc:4598}"] = "Eleanor: für {npc:4598}",
		["Eleanor: for {npc:4605}"] = "Eleanor: für {npc:4605}",
		["Eleanor: for {npc:5695}"] = "Eleanor: für {npc:5695}",
		["Eleanor: for {npc:5759}"] = "Eleanor: für {npc:5759}",
		["Eleanor: for {npc:6289}"] = "Eleanor: für {npc:6289}",
		["Escort {npc:275954} out of the outpost"] = "Eskortiere {npc:275954} aus dem Außenposten",
		["Everything here is inside the inn, through its door on the south side: {npc:5688} at the bar, {npc:265944} at the north end of the ground floor, the {npc:1931} in the cellar under that end, and {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) upstairs: take the stairs inside, the arrow cannot tell the floors apart."] = "Alles hier ist im Gasthaus, durch die Tür auf der Südseite: {npc:5688} an der Theke, {npc:265944} am Nordende des Erdgeschosses, der {npc:1931} im Keller unter diesem Ende, und {npc:2128} (Magier), {npc:2129} (Priester), {npc:2127} (Hexenmeister) und {npc:2130} (Schurken) oben: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "Folge dem Pfad nach Norden nach {area:154}; Sarvis steht vor der Kirche.",
		["Follow the road east past the cult's farm. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows: Linnea wants eight of each.\nThe Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them.\nThe spiders lurk in the woods at the far east end of the glades.\nCareful: Riptear (13) is elite and prowls west and north of the Scarlet Friars' camp: watch for him before you pull."] = "Folge der Straße nach Osten am Hof des Kults vorbei. Blutende Schrecken und Wandernde Geister spuken bei den Gräbern auf der Ostseite des Gehöfts, wo das {quest:99142} wächst: Linnea will von jedem acht.\nDie Scharlachroten Ordensmitglieder lagern direkt nordöstlich der Gräber; {npc:1664} steht unter ihnen.\nDie Spinnen lauern in den Wäldern am äußersten Ostende der Auen.\nVorsicht: Riptear (13) ist ein Elite und streift westlich und nördlich des Lagers der Scharlachroten Ordensmitglieder umher: Halte nach ihm Ausschau, bevor du pullst.",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}.\nCareful: Rotting undead and Darkeye Bonecasters near the Agamands can join a fight as adds."] = "Folge der Straße nach Nordwesten zu {area:157}. {npc:1657} läuft über den Friedhof südlich der Mühlen; Nissa, Gregor und {npc:1656} spuken in den Mühlen selbst. Rattlecage und Cracked Skull Soldiers lassen die Rippen fallen, Darkeye Bonecasters die Schädel, und jeder von ihnen kann {item:2839} fallen lassen.\nVorsicht: Verrottende Untote und Darkeye Bonecasters bei den Agamands können als Adds in einen Kampf eingreifen.",
		["Follow the road south-east from {area:159} past the zeppelin towers."] = "Folge der Straße von {area:159} nach Südosten an den Zeppelintürmen vorbei.",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "Folge der Straße von {area:159} nach Südosten an den Zeppelintürmen vorbei. Linnea, Kristof und {npc:3549} lagern an der Straße.",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "Folge der Straße von {area:159} nach Südwesten zum Lager des Scharlachroten Kreuzzugs. {npc:1662} steht an seinem Südende; jeder Scharlachrote dort kann einen Ring fallen lassen.",
		["Free the {npc:271961}"] = "Befreie die {npc:271961}",
		["From level 10 {npc:1738} offers {quest:96895}: {npc:267009} waits at Linnea's camp, the next stop. Below 10 it waits for the {area:159} visit after {area:157}."] = "Ab Stufe 10 bietet {npc:1738} {quest:96895} an: {npc:267009} wartet in Linneas Lager, dem nächsten Halt. Unter Stufe 10 wartet sie auf den Besuch in {area:159} nach {area:157}.",
		["From level 7 {npc:2132}, beside Johaan in the apothecary's house, offers her elixir quest; below 7 it waits for the next {area:159} visit."] = "Ab Stufe 7 bietet {npc:2132}, neben Johaan im Haus des Apothekers, ihre Elixier-Quest an; unter Stufe 7 wartet sie auf den nächsten Besuch in {area:159}.",
		["Head west to the cave. The Young Night Web Spiders sit outside; the Night Web Spiders and the cocooned {npc:271961} are inside.\nCareful: A low-level character can die quickly if it pulls several Night Web Spiders in the cave at the same time."] = "Geh nach Westen zur Höhle. Die Young Night Web Spiders sitzen draußen; die Night Web Spiders und die eingesponnenen {npc:271961} sind drinnen.\nVorsicht: Ein Charakter mit niedriger Stufe kann schnell sterben, wenn er in der Höhle mehrere Night Web Spiders gleichzeitig pullt.",
		["Heal and fortify {npc:12428}"] = "Heile und stärke {npc:12428}",
		["Holland walks around the north side of {area:159}, a few steps from Dillinger."] = "Holland läuft auf der Nordseite von {area:159} herum, ein paar Schritte von Dillinger entfernt.",
		["Inside"] = "Drinnen",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}; {npc:1519} stands by the road just past it."] = "Verlasse {area:154} über die Straße nach Nordosten. {npc:6784} steht beim Bauernhaus auf dem {area:156}; {npc:1519} steht direkt dahinter an der Straße.",
		["Level 6"] = "Stufe 6",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "Hör Leonid und {npc:246378} zu, dann sprich erneut mit ihm",
		["Mindless Zombies"] = "Hirnlose Zombies",
		["Offer aid to the {npc:246143}"] = "Biete dem {npc:246143} Hilfe an",
		["On the way back west, the Cult of the Damned holds the farm just south-east of {npc:1495}'s camp. The Necrotic Crystal Fragments lie on the ground among the cultists, and the cultists carry some too.\nCareful: the cultists (10-12) stand close together and the Neophytes cast: pull one at a time from the edge of the farm."] = "Auf dem Rückweg nach Westen hält der Kult der Verdammten den Hof direkt südöstlich vom Lager von {npc:1495}. Die Nekrotischen Kristallfragmente liegen zwischen den Kultisten am Boden, und die Kultisten tragen auch einige bei sich.\nVorsicht: Die Kultisten (10-12) stehen dicht beieinander und die Neophyten zaubern: Pull einen nach dem anderen vom Rand des Hofs.",
		["Only if the letter dropped"] = "Nur wenn der Brief gedroppt ist",
		["Paladin: {quest:91285}"] = "Paladin: {quest:91285}",
		["Paladin: {quest:96899}"] = "Paladin: {quest:96899}",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side. {npc:1661} wants their paws and wings: kill them as you meet them while you clear the skeletons."] = "Rattlecage Skeletons wandern durch die zerstörten Häuser in der nördlichen Hälfte von {area:154}. Young Scavengers und Duskbats streifen überall ums Dorf; die Ragged Scavengers und Mangy Duskbats sind an seiner Ostseite. {npc:1661} will ihre Pfoten und Flügel: Töte sie, wenn sie dir begegnen, während du die Skelette ausdünnst.",
		["Scarlet Warriors guard the outpost north-west of the pumpkin fields. {npc:275954} is held inside: talk to him and stay with him until he is out.\nCareful: Scarlet Warriors are level 6-7 and not elite. Once their health falls to 15% they run off to bring help, so more of them may join the fight."] = "Scharlachrote Krieger bewachen den Außenposten nordwestlich der Kürbisfelder. {npc:275954} wird dort drinnen festgehalten: Sprich ihn an und bleib bei ihm, bis er draußen ist.\nVorsicht: Scharlachrote Krieger sind Stufe 6-7 und keine Elites. Sobald ihre Gesundheit auf 15% fällt, laufen sie weg, um Hilfe zu holen, sodass weitere von ihnen in den Kampf eingreifen können.",
		["Still in the inn: from level 7 {npc:1500} on the ground floor and {npc:1521} upstairs offer their quests; below 7 they wait for the next {area:159} visit."] = "Weiter im Gasthaus: Ab Stufe 7 bieten {npc:1500} im Erdgeschoss und {npc:1521} oben ihre Quests an; unter Stufe 7 warten sie auf den nächsten Besuch in {area:159}.",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "Die Trockenen Äste liegen am Boden rund um den Südwestrand von {area:159}.",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "Die Scharlachroten Konvertiten und Initianden halten den Bauernhof östlich von {area:154}. {npc:1919} wandert zwischen den Bauernhäusern umher: Seine Überreste sind für {quest:6395}.",
		["The Scarlet camp"] = "Das scharlachrote Lager",
		["The Scarlet farm"] = "Der scharlachrote Bauernhof",
		["The Vile Fin murlocs lurk on the bluffs just east of the keep and in the camps around the lake to the south-west, on the way down to {area:16881}."] = "Die Vile-Fin-Murlocs lauern auf den Klippen direkt östlich der Festung und in den Lagern rund um den See im Südwesten, auf dem Weg hinunter nach {area:16881}.",
		["The Wanted poster beside Zygand"] = "Der Steckbrief neben Zygand",
		["The next guide walks south from {area:159} into {zone:1421}."] = "Der nächste Guide führt von {area:159} nach Süden in {zone:1421}.",
		["The pumpkins grow in the Scarlet-held fields just north-west of the farmhouse.\nCareful: Farmers stand close to the pumpkins, so you can pull more than one at once. Scarlet mobs are found around the edges of the farm and a bit to the northwest. {npc:1936} (8, rare) walks the field."] = "Die Kürbisse wachsen auf den scharlachroten Feldern direkt nordwestlich des Bauernhauses.\nVorsicht: Bauern stehen nah bei den Kürbissen, du kannst also mehr als einen auf einmal pullen. Scharlachrote Mobs findest du an den Rändern der Farm und ein Stück weiter nordwestlich. {npc:1936} (8, Rare) läuft über das Feld.",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "Die Zombies schlurfen über den Friedhof und um die Häuser direkt östlich der Kirche.",
		["The {area:154} trainers stand around the church"] = "Die Lehrer von {area:154} stehen rund um die Kirche",
		["The {area:159} trainers are in the inn ({npc:2131} downstairs, the rest upstairs); {npc:246152}, the Paladin trainer, by the square"] = "Die Lehrer von {area:159} sind im Gasthaus ({npc:2131} unten, die übrigen oben); {npc:246152}, der Paladinlehrer, beim Platz",
		["The {npc:1931}, in the inn's cellar"] = "Der {npc:1931}, im Keller des Gasthauses",
		["The {npc:2211}, in the inn's cellar"] = "Der {npc:2211}, im Keller des Gasthauses",
		["The {npc:246143}"] = "Der {npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "Die {object:164662} liegen neben den zerstörten Häusern im Norden von {area:154}.",
		["Tirisfal Pumpkins"] = "Tirisfalkürbisse",
		["Top up here to level 6 before the pumpkins: the Tirisfal Farmers and Scarlet Warriors in the fields are 6-7. The Decrepit Darkhounds (5-6) roam the hills just east of the farm."] = "Level hier auf Stufe 6, bevor du zu den Kürbissen gehst: Die Bauern von Tirisfal und Scharlachroten Krieger auf den Feldern sind 6-7. Die Altersschwachen Schattenhunde (5-6) streifen über die Hügel direkt östlich des Hofs.",
		["Use the {item:286176} on five idle Deathguards around town"] = "Benutze den {item:286176} an fünf untätigen Todeswachen im Ort",
		["Vile Fin Attackers"] = "Angreifer der Finsterflossen",
		["Vile Fin Seers"] = "Seher der Finsterflossen",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Geh von {area:159} nach Süden zu {area:153} und hinab nach {area:1497}. {npc:4568} steht im {object:36082}. Das scharlachrote Lager liegt direkt westlich der Ruinen.",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Geh von {area:159} nach Süden zu {area:153} und hinab nach {area:1497}. {npc:5675} steht im {object:36082}. Das scharlachrote Lager liegt direkt westlich der Ruinen.",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "Du erwachst in der Gruft am Südende von {area:154}. {npc:1568} wartet direkt draußen.",
		["attack the cocoons inside the cave to free them; below ground"] = "Greife die Kokons in der Höhle an, um sie zu befreien; unter der Erde",
		["grind on {npc:1547}"] = "Grinde an {npc:1547}",
		["the Shadowvale Lurchers and Mystics drop the bones; below ground"] = "die Shadowvale Lurchers und Mystics lassen die Knochen fallen; unter der Erde",
		["the basement under the ruined house"] = "der Keller unter dem zerstörten Haus",
		["the {item:286269}, at the basement's south end"] = "der {item:286269}, am Südende des Kellers",
		["{area:154}: kill these as you meet them"] = "{area:154}: Töte sie, wenn sie dir begegnen",
		["{area:165}: kill these as you meet them"] = "{area:165}: Töte sie, wenn sie dir begegnen",
		["{area:166}: kill these as you meet them"] = "{area:166}: Töte sie, wenn sie dir begegnen",
		["{area:16881} is the hollow at the west edge of the glades, south-west of the {area:16616}. Go down into the big basement under the ruined house (only a floor and a few pillars left, not the two-storey house): the bottles lie on its floor among the Shadowvale Lurchers and Mystics."] = "{area:16881} ist die Senke am Westrand der Auen, südwestlich des {area:16616}. Geh hinunter in den großen Keller unter dem zerstörten Haus (nur noch ein Boden und ein paar Säulen, nicht das zweistöckige Haus): Die Flaschen liegen auf seinem Boden zwischen den Shadowvale Lurchers und Mystics.",
		["{item:16333}, from {npc:1919}"] = "{item:16333}, von {npc:1919}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "{item:2320} von {npc:2118}, für Gretchen",
		["{item:2839}, a rare drop"] = "{item:2839}, ein seltener Drop",
		["{item:3635}; inside"] = "{item:3635}; drinnen",
		["{item:7227}, in the farmstead's garden"] = "{item:7227}, im Garten des Hofs",
		["{npc:10665} walks around {area:159}: look inside the circle on the map"] = "{npc:10665} läuft um {area:159} herum: Schau im Kreis auf der Karte nach",
		["{npc:10666} walks the long road west of {area:159}, past {area:166}, and back: the arrow follows his road west until you meet him."] = "{npc:10666} läuft die lange Straße westlich von {area:159} an {area:166} vorbei und wieder zurück: Der Pfeil folgt seiner Straße nach Westen, bis du ihn triffst.",
		["{npc:10666}, the big abomination, walks the road from here east past {area:166} almost to {area:159}, and back: if he isn't at the arrow, follow the road east until you meet him. The {item:12737} grows along the road around him."] = "{npc:10666}, die große Abscheulichkeit, läuft die Straße von hier nach Osten an {area:166} vorbei fast bis {area:159} und wieder zurück: Ist er nicht am Pfeil, folge der Straße nach Osten, bis du ihn triffst. Das {item:12737} wächst entlang der Straße um ihn herum.",
		["{npc:12428} kneels by the north gate of {area:159}'s graveyard, on your way north. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Fortitude first does not count."] = "{npc:12428} kniet am Nordtor des Friedhofs von {area:159}, auf deinem Weg nach Norden. Wirke {spell:613} (Rang 2) auf ihn, dann {spell:1243}: Seelenstärke zuerst zählt nicht.",
		["{npc:1495}'s camp"] = "Lager von {npc:1495}",
		["{npc:1496} and {npc:1742} stand at the west end of {area:159}, where the road from Solliden comes in."] = "{npc:1496} und {npc:1742} stehen am Westende von {area:159}, wo die Straße von Solliden einmündet.",
		["{npc:1499}, in the town hall"] = "{npc:1499}, im Rathaus",
		["{npc:1499}, inside"] = "{npc:1499}, drinnen",
		["{npc:1500} and {npc:1521}"] = "{npc:1500} und {npc:1521}",
		["{npc:1500}, in the inn"] = "{npc:1500}, im Gasthaus",
		["{npc:1515}, in front of the inn"] = "{npc:1515}, vor dem Gasthaus",
		["{npc:1518} is in the apothecary's house on the west side of the square, {npc:1515} in front of the inn with the Wanted poster beside him, {npc:1499} in the town hall on the square's north side. The inn comes last, in one go."] = "{npc:1518} ist im Haus des Apothekers auf der Westseite des Platzes, {npc:1515} vor dem Gasthaus mit dem Steckbrief neben sich, {npc:1499} im Rathaus auf der Nordseite des Platzes. Das Gasthaus kommt zuletzt, in einem Rutsch.",
		["{npc:1518}, inside"] = "{npc:1518}, drinnen",
		["{npc:1518}: for Renferrel at the {area:228}"] = "{npc:1518}: für Renferrel am {area:228}",
		["{npc:1521}, upstairs"] = "{npc:1521}, oben",
		["{npc:1525} and Ravaged Corpses shamble through the fields just west of {area:159}; Decrepit Darkhounds roam there and on west along the road toward {npc:10666}. Johaan wants their blood, {npc:3549} their hides."] = "{npc:1525} und Ravaged Corpses schlurfen über die Felder direkt westlich von {area:159}; Decrepit Darkhounds streifen dort und weiter westlich an der Straße entlang Richtung {npc:10666}. Johaan will ihr Blut, {npc:3549} ihre Häute.",
		["{npc:1537} walks around here: look inside the circle on the map"] = "{npc:1537} läuft hier herum: Schau im Kreis auf der Karte nach",
		["{npc:1560}, in the inn"] = "{npc:1560}, im Gasthaus",
		["{npc:1569}, inside"] = "{npc:1569}, drinnen",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569}: die Schriftrolle für {npc:244808}",
		["{npc:1570}, in the church"] = "{npc:1570}, in der Kirche",
		["{npc:1655}; upstairs"] = "{npc:1655}; oben",
		["{npc:1661}, beside the church; inside"] = "{npc:1661}, neben der Kirche; drinnen",
		["{npc:1661}, inside"] = "{npc:1661}, drinnen",
		["{npc:1667} stands at the south end of the Scarlet farm.\nCareful: He is flanked by two Scarlet guards, one a convert and the other an initiate, who may join the fight."] = "{npc:1667} steht am Südende der Scharlachroten Farm.\nVorsicht: Zwei scharlachrote Wachen flankieren ihn, ein Konvertit und ein Initiand, die in den Kampf eingreifen können.",
		["{npc:1675} walks around {area:164}: look inside the circle on the map"] = "{npc:1675} läuft um {area:164} herum: Schau im Kreis auf der Karte nach",
		["{npc:1738}, if you were below 10 on the last {area:159} visit"] = "{npc:1738}, falls du beim letzten Besuch in {area:159} unter Stufe 10 warst",
		["{npc:1742}, beside Dillinger"] = "{npc:1742}, neben Dillinger",
		["{npc:2114} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2114} nimmt sie entgegen, sobald deine Fertigkeit in {skill:182} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:2114}, beside Johaan: {quest:97957}"] = "{npc:2114}, neben Johaan: {quest:97957}",
		["{npc:2119}, the warrior trainer; inside"] = "{npc:2119}, der Kriegerlehrer; drinnen",
		["{npc:2122}, the rogue trainer"] = "{npc:2122}, der Schurkenlehrer",
		["{npc:2123}, the priest trainer in the church"] = "{npc:2123}, der Priesterlehrer in der Kirche",
		["{npc:2123}, the priest trainer in the church, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him now: the wounded guard Beryl sends you to needs it."] = "{npc:2123}, der Priesterlehrer in der Kirche, schickt dich zu {npc:2129} in {area:159}. Erlerne jetzt {spell:613} (Rang 2) bei ihm: Die verwundete Wache, zu der Beryl dich schickt, braucht es.",
		["{npc:2123}: for {npc:2129} in {area:159}"] = "{npc:2123}: für {npc:2129} in {area:159}",
		["{npc:2124}, the mage trainer, in the church"] = "{npc:2124}, die Magierlehrerin, in der Kirche",
		["{npc:2126}, the warlock trainer"] = "{npc:2126}, der Hexenmeisterlehrer",
		["{npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:2128} (Magier), {npc:2129} (Priester), {npc:2127} (Hexenmeister) und {npc:2130} (Schurken) stehen oben im Gasthaus: Nimm drinnen die Treppe, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128}: {npc:4568} in {zone:1458} nimmt es an",
		["{npc:2129}, upstairs"] = "{npc:2129}, im Obergeschoss",
		["{npc:2129}, upstairs: the {item:16607}"] = "{npc:2129}, im Obergeschoss: die {item:16607}",
		["{npc:2132} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2132} nimmt sie entgegen, sobald deine Fertigkeit in {skill:171} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:2132}, beside Johaan: {quest:97951}"] = "{npc:2132}, neben Johaan: {quest:97951}",
		["{npc:2132}, beside Johaan; inside"] = "{npc:2132}, neben Johaan; drinnen",
		["{npc:2132}, inside"] = "{npc:2132}, drinnen",
		["{npc:244808}, inside"] = "{npc:244808}, drinnen",
		["{npc:244808}: {spell:635}, once five {npc:259377} are healed"] = "{npc:244808}: {spell:635}, sobald fünf {npc:259377} geheilt sind",
		["{npc:246152}, the Paladin trainer"] = "{npc:246152}, die Paladinlehrerin",
		["{npc:246152}, the Paladin trainer: {quest:91282}, to {quest:96899}"] = "{npc:246152}, der Paladinlehrer: {quest:91282}, nach {quest:96899}",
		["{npc:246349} waits at the keep's gate beside Leonid."] = "{npc:246349} wartet am Tor der Festung neben Leonid.",
		["{npc:246378}, inside the keep"] = "{npc:246378}, in der Festung",
		["{npc:246389} and {npc:259190}"] = "{npc:246389} und {npc:259190}",
		["{npc:259190} and {npc:246389} at the forest's edge, {npc:246349} at the gate, {npc:246393} and {npc:246394} nearby, {npc:246378} inside."] = "{npc:259190} und {npc:246389} am Waldrand, {npc:246349} am Tor, {npc:246393} und {npc:246394} in der Nähe, {npc:246378} drinnen.",
		["{npc:265944}, at the inn's north end: Camping 101 asks you to learn it"] = "{npc:265944}, am Nordende des Gasthauses: Camping 101 verlangt, dass du es lernst",
		["{npc:267009} stands at the camp beside Linnea."] = "{npc:267009} steht im Lager neben Linnea.",
		["{npc:267009} stands at {npc:1495}'s camp, on the road to the cult's farm."] = "{npc:267009} steht in {npc:1495}s Lager, an der Straße zur Farm des Kults.",
		["{npc:275954}, on the top floor"] = "{npc:275954}, im obersten Stockwerk",
		["{npc:3523} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3523} nimmt sie entgegen, sobald deine Fertigkeit in {skill:197} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:3523}, by the road west of {area:159}: {quest:97961}"] = "{npc:3523}, an der Straße westlich von {area:159}: {quest:97961}",
		["{npc:3549} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3549} nimmt sie entgegen, sobald deine Fertigkeit in {skill:165} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:4551}, the bat handler, on the way down from the Ruins"] = "{npc:4551}, der Fledermausführer, auf dem Weg hinunter von den Ruinen",
		["{npc:5675}: he offers {quest:1473} only once this is handed in"] = "{npc:5675}: Er bietet {quest:1473} erst an, wenn dies abgegeben ist",
		["{npc:5695} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5695} nimmt sie entgegen, sobald deine Fertigkeit in {skill:333} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:5724}: {npc:5675} in the {zone:1458} takes it"] = "{npc:5724}: {npc:5675} in {zone:1458} nimmt es an",
		["{npc:5759} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5759} nimmt sie entgegen, sobald deine Fertigkeit in {skill:129} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:5759}, by the bar: {quest:97955}"] = "{npc:5759}, an der Theke: {quest:97955}",
		["{npc:6289} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6289} nimmt sie entgegen, sobald deine Fertigkeit in {skill:393} 20 beträgt: Sammle oder stelle bis dahin her, der Guide geht inzwischen weiter.",
		["{npc:6289}, beside {npc:3549}: {quest:97960}"] = "{npc:6289}, neben {npc:3549}: {quest:97960}",
		["{npc:6390} waits in the mausoleum on the hill just north of town: open the gate and fight him."] = "{npc:6390} wartet im Mausoleum auf dem Hügel direkt nördlich der Stadt: Öffne das Tor und kämpfe gegen ihn.",
		["{npc:6784} stands by the farmhouse at the {area:156}, on the way to the Crusader's Outpost."] = "{npc:6784} steht beim Bauernhaus auf dem {area:156}, auf dem Weg zum Außenposten der Kreuzfahrer.",
		["{npc:6784}, by the farmhouse: talk to him for the duel; he offers it once {npc:5688} has his letter"] = "{npc:6784}, beim Bauernhaus: Sprich ihn für das Duell an; er bietet es an, sobald {npc:5688} seinen Brief hat",
		["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661} liegt unter {area:153}, neben den Zeppelintürmen. {npc:5675} ist im {object:36082}: Benutze die {item:6284} am Beschwörungskreis neben ihm und besiege den Leerwandler. {npc:4606} ist im {object:36070}. {npc:4568} ist ebenfalls im {object:36082}.",
		["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090} liegt auf dem Friedhof von {area:154}, neben der Kirche.",
		["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098} steht neben {npc:1662} am Südende des Lagers.",
		["{quest:90902}: the {npc:259377} lie around the church. Heal five of them with {spell:635}."] = "{quest:90902}: Die {npc:259377} liegen rund um die Kirche. Heile fünf von ihnen mit {spell:635}.",
		["{quest:91208}: the {npc:246143} fled into the hills west of the church, on the way to {area:155}."] = "{quest:91208}: Der {npc:246143} ist in die Hügel westlich der Kirche geflohen, auf dem Weg nach {area:155}.",
		["{zone:1420}: kill these as you meet them"] = "{zone:1420}: Töte sie, wenn sie dir begegnen",
} end)()
t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "Abenteuer: die Weltkarte erkunden",
		["Adventure: {npc:16042}"] = "Abenteuer: {npc:16042}",
		["Adventure: {quest:8999} (Alliance)"] = "Abenteuer: {quest:8999} (Allianz)",
		["Adventure: {quest:9007} (Horde)"] = "Abenteuer: {quest:9007} (Horde)",
		["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new 20-player Forever raid at the top of {zone:2482}, near Nordrassil, open from 9 December; its bosses are not in our data, so tick it off once all 13 are down."] = "Alle 13 Bosse des Hyjal Summit sind einen Punkt wert. Hyjal Summit ist ein neuer Forever-Schlachtzug für 20 Spieler auf dem Gipfel von {zone:2482}, nahe Nordrassil, offen ab dem 9. Dezember; seine Bosse sind nicht in unseren Daten, hake ihn also ab, sobald alle 13 besiegt sind.",
		["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new 10-player Forever raid beneath {zone:2482}, entered from {zone:2482}, {zone:1452} or {area:1216} and open from 9 December; its bosses are not in our data, so tick it off once all 8 are down."] = "Alle 8 Bosse der Barrow Deeps sind einen Punkt wert. Barrow Deeps ist ein neuer Forever-Schlachtzug für 10 Spieler unter {zone:2482}, betreten von {zone:2482}, {zone:1452} oder {area:1216} aus und offen ab dem 9. Dezember; seine Bosse sind nicht in unseren Daten, hake ihn also ab, sobald alle 8 besiegt sind.",
		["City of Dalaran (Forever's, {zone:1416}): {npc:246020}"] = "City of Dalaran (von Forever, {zone:1416}): {npc:246020}",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Klassen geben 27 Punkte: jede Klasse, die 25, 45 und 60 erreicht. Sie zählen einmal pro Klasse im ganzen Account, ein zweiter Charakter einer bereits hochgespielten Klasse bringt also nichts; eine neue Klasse schon. Der erste Charakter auf Stufe 25 schaltet meist das Vermächtnissystem selbst frei.",
		["Classes: level 25"] = "Klassen: Stufe 25",
		["Classes: level 45"] = "Klassen: Stufe 45",
		["Classes: level 60"] = "Klassen: Stufe 60",
		["Dire Maul East"] = "Düsterbruch Ost",
		["Dire Maul North"] = "Düsterbruch Nord",
		["Dire Maul West"] = "Düsterbruch West",
		["Dungeons: level 15-25"] = "Dungeons: Stufe 15-25",
		["Dungeons: level 26-45"] = "Dungeons: Stufe 26-45",
		["Dungeons: level 46-60"] = "Dungeons: Stufe 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Jeder Herstellungsberuf gibt 3 Punkte, bei 150, 225 und 300. Ränge zählen einmal pro Beruf im ganzen Account. Folge dem Polestar-Guide „{skill:171} 1-300“ (Berufe). Ein Herstellungsberuf auf 150 schaltet auch das Vermächtnissystem frei.",
		["Exalted with each of the four battleground factions is worth a point. Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation, Alterac Valley Reputation and Darkspear Islands Reputation (Forever's new battleground, open from level 30). The Diplomat Legacy perk increases reputation gains."] = "Ehrfürchtig bei jeder der vier Schlachtfeld-Fraktionen ist einen Punkt wert. Folge den Polestar-Ruf-Guides Ruf: Warsongschlucht, Ruf: Arathibecken, Ruf: Alteractal und Ruf: Darkspear-Inseln (das neue Schlachtfeld von Forever, ab Stufe 30 offen). Der Vermächtnis-Vorteil „Diplomat“ erhöht den Rufgewinn.",
		["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the {zone:2548}, {zone:2652} and {zone:2482}, a level 60 zone."] = "Die gesamte Weltkarte mit einem Charakter zu erkunden ist einen Punkt wert und kann außerdem das Vermächtnissystem freischalten. Alles muss mit demselben Charakter geschehen. Die neuen Zonen von Forever gehören zur Karte: die {zone:2548}, {zone:2652} und {zone:2482}, eine Zone der Stufe 60.",
		["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it. Exploration: Zephras Isle covers the Skyborne island; whether its map counts towards this challenge is not confirmed yet."] = "Folge den Polestar-Erkundungs-Guides: Erkundung: Östliche Königreiche 1-30, 30-45 und 45-60 sowie Erkundung: Kalimdor 1-30, 30-45 und 45-60. Sie verfolgen jedes Gebiet, sobald du es entdeckst. Erkundung: Zephras Isle behandelt die Insel der Himmelsgeborenen; ob ihre Karte für diese Herausforderung zählt, ist noch nicht bestätigt.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:164} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:165} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:197} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:202} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:333} 1-300“ (Berufe).",
		["Killing {npc:10184} is a point. {area:2159} is a 40-player raid in {zone:1445}, open from 9 December. Every raider needs the {item:16309} in the bags: the Alliance chain starts with Dragonkin Menace in the {zone:1428}, the Horde chain with Blood and Thunder in {area:340} ({zone:1418}); both end in Upper Blackrock Spire with {npc:10363}."] = "{npc:10184} zu töten ist einen Punkt wert. {area:2159} ist ein Schlachtzug für 40 Spieler in {zone:1445}, offen ab dem 9. Dezember. Jeder Schlachtzügler braucht das {item:16309} in den Taschen: Die Kette der Allianz beginnt mit Dragonkin Menace in der {zone:1428}, die der Horde mit Blood and Thunder in {area:340} ({zone:1418}); beide enden in der Oberen Schwarzfelsspitze bei {npc:10363}.",
		["Legacy Challenges"] = "Vermächtnisherausforderungen",
		["Level 45 with this character's class."] = "Stufe 45 mit der Klasse dieses Charakters.",
		["Level 60 with this character's class."] = "Stufe 60 mit der Klasse dieses Charakters.",
		["Lower {area:1583}"] = "Untere {area:1583}",
		["PvP: Field of Honor"] = "PvP: Field of Honor",
		["PvP: battleground reputations (Alliance)"] = "PvP: Schlachtfeld-Ruf (Allianz)",
		["PvP: battleground reputations (Horde)"] = "PvP: Schlachtfeld-Ruf (Horde)",
		["PvP: honor ranks"] = "PvP: Ehrenränge",
		["Raids: Barrow Deeps"] = "Schlachtzüge: Barrow Deeps",
		["Raids: Hyjal Summit"] = "Schlachtzüge: Hyjalgipfel",
		["Raids: {npc:10184}"] = "Schlachtzüge: {npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "Die Ränge 3, 7, 10, 13 und 14 sind je einen Punkt wert. Polestar kann deinen höchsten Rang noch nicht lesen, hak also jeden selbst ab. Die Ehrenregeln von Forever für das Erreichen eines Rangs sind nicht im Detail veröffentlicht; in Classic kommen Ränge aus deiner wöchentlichen Ehrenplatzierung, und 13-14 brauchen viele Wochen Spitzenplatzierung.",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "Die PvP-Saison Field of Honor hat wöchentliche Reisequests; die für die Wochen 4, 7 und 10 abzuschließen ist je einen Punkt wert. Diese Quests sind neu in Forever und nicht in unseren Daten, hak also jede selbst ab.",
		["The final boss of every level 15-25 dungeon earns one point together. {area:2437} and Forever's {area:16919} (in {zone:1455}) count as one: either final boss does. Tick each boss off when you kill it, and check the in-game Legacy panel for the list.\nAlliance: the {area:153}'s entrance is in the ruins beside the {zone:1458}, among Horde guards: go with a group. {area:2437} is inside {zone:1454}: the {area:16919} counts for it. Horde: the {area:16919} is inside {zone:1455}: {area:2437} counts for it."] = "Der letzte Boss jedes Dungeons der Stufen 15-25 bringt zusammen einen Punkt. {area:2437} und Forevers {area:16919} (in {zone:1455}) zählen als einer: Einer der beiden Endbosse genügt. Hake jeden Boss ab, wenn du ihn getötet hast, und sieh im Vermächtnis-Fenster im Spiel nach der Liste.\nAllianz: Der Eingang von {area:153} liegt in den Ruinen neben {zone:1458}, zwischen Wachen der Horde: Geh mit einer Gruppe hin. {area:2437} liegt in {zone:1454}: {area:16919} zählt dafür. Horde: {area:16919} liegt in {zone:1455}: {area:2437} zählt dafür.",
		["The final boss of every level 26-45 dungeon earns one point together. {area:16550} and {area:17780} (in the {zone:2548}) are new in Forever and not in our data: tick them off yourself."] = "Der letzte Boss jedes Dungeons der Stufen 26-45 bringt zusammen einen Punkt. {area:16550} und {area:17780} (in den {zone:2548}) sind neu in Forever und nicht in unseren Daten: Hake sie selbst ab.",
		["The final boss of every level 46-60 dungeon earns one point together. {area:16620}, {area:1216} and the {area:16985} are new in Forever and not in our data: tick them off yourself."] = "Der letzte Boss jedes Dungeons der Stufen 46-60 bringt zusammen einen Punkt. {area:16620}, {area:1216} und die {area:16985} sind neu in Forever und nicht in unseren Daten: Hake sie selbst ab.",
		["The {npc:16042} questline is a point. It is the level 60 dungeon-set chain, from An Earnest Proposition to your class's {quest:8999}: {npc:16013} ({zone:1455}) or {npc:16012} ({zone:1454}) send you through In Search of Anthion and Anthion's Parting Words to {npc:16033} at {area:254}, whose Three Kings of Flame, the Left and Right Pieces of Lord Valthalak's Amulet, Final Preparations and {quest:8995} end with {quest:8996}. {quest:8997} then leads to {quest:8999}."] = "Die Questreihe von {npc:16042} ist einen Punkt wert. Es ist die Kette zum Dungeon-Set der Stufe 60, von An Earnest Proposition bis zur {quest:8999} deiner Klasse: {npc:16013} ({zone:1455}) oder {npc:16012} ({zone:1454}) schicken dich über In Search of Anthion und Anthion's Parting Words zu {npc:16033} am {area:254}, dessen Aufträge Three Kings of Flame, die linke und rechte Hälfte von Lord Valthalak's Amulet, Final Preparations und {quest:8995} mit {quest:8996} enden. {quest:8997} führt dich dann zu {quest:8999}.",
		["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "Dieser Schritt kann die ganze Karte noch nicht selbst prüfen; er wird zu einem verfolgten Ziel, sobald die Vermächtnis-Erfolgs-IDs erfasst sind.",
		["Tradeskills: {skill:164}"] = "Berufe: {skill:164}",
		["Tradeskills: {skill:165}"] = "Berufe: {skill:165}",
		["Tradeskills: {skill:171}"] = "Berufe: {skill:171}",
		["Tradeskills: {skill:197}"] = "Berufe: {skill:197}",
		["Tradeskills: {skill:202}"] = "Berufe: {skill:202}",
		["Tradeskills: {skill:333}"] = "Berufe: {skill:333}",
		["Upper {area:1583}"] = "Obere {area:1583}",
		["all 13 Hyjal Summit bosses"] = "alle 13 Bosse des Hyjalgipfels",
		["all 8 Barrow Deeps bosses"] = "alle 8 Bosse der Hügelgrabtiefen",
		["enemy players and finish the Field of Honor week 10 journey quest"] = "feindliche Spieler und schließe die Reisequest der Woche 10 des Ehrenfelds ab",
		["enemy players and finish the Field of Honor week 4 journey quest"] = "feindliche Spieler und schließe die Reisequest der Woche 4 des Ehrenfelds ab",
		["enemy players and finish the Field of Honor week 7 journey quest"] = "feindliche Spieler und schließe die Reisequest der Woche 7 des Ehrenfelds ab",
		["enemy players for honor until PvP Rank 10"] = "feindliche Spieler für Ehre bis zum PvP-Rang 10",
		["enemy players for honor until PvP Rank 13"] = "feindliche Spieler für Ehre bis zum PvP-Rang 13",
		["enemy players for honor until PvP Rank 14"] = "feindliche Spieler für Ehre bis zum PvP-Rang 14",
		["enemy players for honor until PvP Rank 3"] = "feindliche Spieler für Ehre bis zum PvP-Rang 3",
		["enemy players for honor until PvP Rank 7"] = "feindliche Spieler für Ehre bis zum PvP-Rang 7",
		["the final boss of the {area:16550}"] = "der letzte Boss von {area:16550}",
		["the final boss of the {area:16985}"] = "der letzte Boss der {area:16985}",
		["the final boss of {area:1216}"] = "der letzte Boss von {area:1216}",
		["the final boss of {area:16620}"] = "der letzte Boss von {area:16620}",
		["the final boss of {area:17780}"] = "der letzte Boss von {area:17780}",
		["{area:153} (Forever's, {zone:1420}): {npc:256035}"] = "{area:153} (von Forever, {zone:1420}): {npc:256035}",
		["{area:16919}: {npc:261319} (or {area:2437})"] = "{area:16919}: {npc:261319} (oder {area:2437})",
		["{area:17732} (Forever's): {npc:260326}"] = "{area:17732} (von Forever): {npc:260326}",
		["{area:2279}, Live side"] = "{area:2279}, lebende Seite",
		["{area:2279}, Undead side"] = "{area:2279}, untote Seite",
		["{area:2437}: {npc:11519} (or {area:16919})"] = "{area:2437}: {npc:11519} (oder {area:16919})",
		["{area:718} (appears after the {npc:3678}'s event)"] = "{area:718} (erscheint nach dem Ereignis des {npc:3678})",
		["{area:796}: Armory"] = "{area:796}: Waffenkammer",
		["{area:796}: Cathedral"] = "{area:796}: Kathedrale",
		["{area:796}: Graveyard"] = "{area:796}: Friedhof",
		["{area:796}: Library"] = "{area:796}: Bibliothek",
		["{npc:16012} then offers your class's {quest:9007}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16012} bietet dir dann die {quest:9007} deiner Klasse an, die letzte Quest der Herausforderung: Sie nimmt den Dungeon-Set-Helm und die Brustplatte deiner Klasse und wertet sie auf.",
		["{npc:16013} then offers your class's {quest:8999}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16013} bietet dir dann die {quest:8999} deiner Klasse an, die letzte Quest der Herausforderung: Sie nimmt den Dungeon-Set-Helm und die Brustplatte deiner Klasse und wertet sie auf.",
		["{npc:16033} offers it once {quest:8996} is turned in"] = "{npc:16033} bietet sie an, sobald {quest:8996} abgegeben ist",
		["{npc:16073}, inside Upper Blackrock Spire after Mea Culpa (no spawn in the data: the arrow leads to {npc:16033}'s {area:254})"] = "{npc:16073}, in der Oberen Blackrockspitze nach Mea Culpa (kein Fundort in den Daten: Der Pfeil führt zu {npc:16033} am {area:254})",
} end)()
t.guides["forever/miscellaneous/cozy-sleeping-bag"] = (function() return {
		["A hundred paces north"] = "Hundert Schritte nach Norden",
		["A trail of hidden notes across both continents: the {item:211527} at the end, a 12-slot {item:221498} on the way."] = "Eine Spur versteckter Notizen über beide Kontinente: am Ende {item:211527}, unterwegs eine {item:221498} mit 12 Plätzen.",
		["Along the coast to {zone:1436}"] = "An der Küste entlang nach {zone:1436}",
		["At the gate in {area:1057} between Arathi and {area:287}, turn north and follow the wall on the {area:287} side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through."] = "Wende dich am Tor in {area:1057} zwischen Arathi und {area:287} nach Norden und folge der Mauer auf der Seite von {area:287} zu einem umgestürzten Karren, der an ihr lehnt. Spring auf den Karren und seine Leiter auf die Mauer, dann über die Felsen zum versteckten Lager. Manche Charaktere passen im Lager nicht unter das Frachtnetz; eine andere Rasse oder eine kleinere Gestalt kommt durch.",
		["Careful: off the dam's ledge you land in the river below it, in the {zone:1437}. Climb out on its west bank well before the waterfall at about 65,77: the fall kills. Then head north-west to the road and follow it north over {area:880} into Arathi, or hearth if your Hearthstone is set at {area:272}."] = "Vorsicht: Vom Vorsprung des Damms landest du im Fluss darunter, im {zone:1437}. Klettere lange vor dem Wasserfall bei etwa 65,77 an seinem Westufer heraus: Der Sturz ist tödlich. Geh dann nach Nordwesten zur Straße und folge ihr nach Norden über {area:880} nach Arathi, oder benutze deinen Ruhestein, wenn er in {area:272} gebunden ist.",
		["Fallen cart"] = "Umgestürzter Karren",
		["From {object:3202} follow Stranglethorn's west coast north to {zone:1436}, swimming where the beach runs out. It is shorter than the jungle road north and keeps you clear of Stranglethorn's level 30+ beasts and of {zone:1431}."] = "Folge von {object:3202} aus der Westküste des Schlingendorntals nach Norden bis {zone:1436} und schwimm, wo der Strand endet. Das ist kürzer als die Dschungelstraße nach Norden und hält dich von den Bestien der Stufe 30+ im Schlingendorntal und von {zone:1431} fern.",
		["Its twin in the {zone:1413}"] = "Ihr Zwilling in der {zone:1413}",
		["Its twin in {zone:1436}"] = "Ihr Zwilling in {zone:1436}",
		["Out of the river"] = "Raus aus dem Fluss",
		["Passing {area:272} on the way to {zone:1432}? Set your Hearthstone here: after the dam, it brings you back next to {area:1057} instead of the long walk through the {zone:1437} and Arathi. Skip this step to keep your Hearthstone where it is."] = "Kommst du auf dem Weg nach {zone:1432} an {area:272} vorbei? Binde deinen Ruhestein hier: Nach dem Damm bringt er dich zurück neben {area:1057}, statt des langen Wegs durch {zone:1437} und Arathi. Überspring diesen Schritt, um deinen Ruhestein dort zu lassen, wo er ist.",
		["Path into the hills"] = "Pfad in die Hügel",
		["Stonetalon from the north"] = "Steinkrallengebirge von Norden",
		["Stranglethorn's west coast"] = "Westküste des Schlingendorntals",
		["The chain opens at level 14. A burned-out campfire in the southern {zone:1413}, with a nailed plank beside it."] = "Die Kette beginnt auf Stufe 14. Ein ausgebranntes Lagerfeuer im Süden der {zone:1413}, daneben ein angenageltes Brett.",
		["The chain opens at level 14. A burned-out campfire in western {zone:1436}, with a nailed plank beside it."] = "Die Kette beginnt auf Stufe 14. Ein ausgebranntes Lagerfeuer im Westen von {zone:1436}, daneben ein angenageltes Brett.",
		["The dam in {zone:1432}"] = "Der Damm in {zone:1432}",
		["The figurine is on a ledge just below the top of the {area:146}, on its north face. Step off slowly; walking backwards keeps you from overshooting the ledge."] = "Die Figur liegt auf einem Vorsprung knapp unter der Spitze des {area:146}, an seiner Nordseite. Tritt langsam hinaus; rückwärts zu gehen verhindert, dass du über den Vorsprung hinausschießt.",
		["The hidden camp"] = "Das versteckte Lager",
		["The next hideout is a small camp in the hills north-west of {area:460}, in the middle of the {zone:1442}. Leave the road where a path climbs west into the hills and follow it to the camp; the {object:424005} lies on a crate beside its tent."] = "Das nächste Versteck ist ein kleines Lager in den Hügeln nordwestlich von {area:460}, mitten im {zone:1442}. Verlasse die Straße dort, wo ein Pfad nach Westen in die Hügel führt, und folge ihm zum Lager; das {object:424005} liegt auf einer Kiste neben dem Zelt.",
		["The note in the {zone:1413}"] = "Die Notiz in der {zone:1413}",
		["The note in {zone:1436}"] = "Die Notiz in {zone:1436}",
		["The note's \"twin land\" is the {zone:1413}: the same burned-out campfire stands in the southern {zone:1413}."] = "Das „Zwillingsland“ der Notiz ist die {zone:1413}: Dasselbe ausgebrannte Lagerfeuer steht in der südlichen {zone:1413}.",
		["The note's \"twin land\" is {zone:1436}: the same burned-out campfire stands in western {zone:1436}."] = "Das „Zwillingsland“ der Notiz ist {zone:1436}: Dasselbe ausgebrannte Lagerfeuer steht im Westen von {zone:1436}.",
		["West bank"] = "Westufer",
		["West bank, before the waterfall"] = "Westufer, vor dem Wasserfall",
		["{area:272} on the way"] = "{area:272} auf dem Weg",
		["{zone:1413}' way into Stonetalon runs through {area:1702}, and the road on to the hills passes {area:2539} and {area:460}: all Horde posts. Come in from the north instead. With the {area:467} flight path, fly there and follow the road south. Otherwise fly to {area:415} and walk south-west to the {area:1276}, the tunnel from {zone:1440} into Stonetalon."] = "Von {zone:1413} aus führt der Weg ins Steinkrallengebirge durch {area:1702}, und die Straße weiter zu den Hügeln kommt an {area:2539} und {area:460} vorbei: alles Posten der Horde. Komm stattdessen von Norden. Mit der Flugroute nach {area:467} flieg dorthin und folge der Straße nach Süden. Sonst flieg nach {area:415} und geh nach Südwesten zum {area:1276}, dem Tunnel von {zone:1440} ins Steinkrallengebirge.",
} end)()
t.guides["forever/miscellaneous/library-books"] = (function() return {
		["At {area:118}, the dig in the middle of the {zone:1437}."] = "Bei {area:118}, der Grabungsstätte mitten in den {zone:1437}.",
		["At {area:233}, the mage village in south-eastern Silverpine."] = "Bei {area:233}, dem Magierdorf im Südosten des Silberwalds.",
		["Beside a tent entrance in the troll village in south-eastern Arathi."] = "Neben einem Zelteingang im Trolldorf im Südosten von Arathi.",
		["Cave mouth at {area:387}"] = "Höhleneingang bei {area:387}",
		["Down the stairs at the {area:443} in northern {zone:1439}."] = "Die Treppe hinunter bei den {area:443} im Norden von {zone:1439}.",
		["Eight more books lie in level 55-60 zones; the mage trainers beside the librarians take them, not the librarians. {item:228141} lies on a table in the ruined keep on {area:2298}, above {area:2057} (outside the dungeon); {item:228132} at {area:199}."] = "Acht weitere Bücher liegen in Zonen der Stufen 55-60; die Magierlehrer neben den Bibliothekaren nehmen sie an, nicht die Bibliothekare. {item:228141} liegt auf einem Tisch in der zerstörten Festung auf {area:2298}, oberhalb von {area:2057} (außerhalb des Dungeons); {item:228132} bei {area:199}.",
		["From level 20, with 20 different books handed in, {npc:211033} offers {quest:79536}: {item:281634} or {item:281635}."] = "Ab Stufe 20, mit 20 abgegebenen verschiedenen Büchern, bietet {npc:211033} {quest:79536} an: {item:281634} oder {item:281635}.",
		["From level 35, with 25 different books handed in, {npc:211033} offers the second {quest:79536}: {item:277254}, {item:277258} or {item:277260} (level 40 to equip)."] = "Ab Stufe 35, mit 25 abgegebenen verschiedenen Büchern, bietet {npc:211033} die zweite {quest:79536} an: {item:277254}, {item:277258} oder {item:277260} (zum Anlegen Stufe 40).",
		["Halfway up the {area:91}, east of {area:87}. Nothing hostile inside."] = "Auf halber Höhe im {area:91}, östlich von {area:87}. Nichts Feindliches im Inneren.",
		["Hand in the books so far. {npc:211022} keeps the library in the {object:36082}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Gib die bisherigen Bücher ab. {npc:211022} führt die Bibliothek im {object:36082}. Er bietet die Quest jedes Buchs an, solange das Buch in deinen Taschen ist: Nimm sie an und gib sie ab, eine nach der anderen, damit dein Questlog frei bleibt. Überspringe die Bücher, die du nicht gefunden hast.",
		["Hand in the books so far. {npc:211033} keeps the library at the top of the Wizard's Sanctum in the {object:2101}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Gib die bisherigen Bücher ab. {npc:211033} führt die Bibliothek oben im Wizard's Sanctum im {object:2101}. Er bietet die Quest jedes Buchs an, solange das Buch in deinen Taschen ist: Nimm sie an und gib sie ab, eine nach der anderen, damit dein Questlog frei bleibt. Überspringe die Bücher, die du nicht gefunden hast.",
		["Hand in this part's books. {npc:211022} keeps the library in the {object:36082}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Gib die Bücher dieses Abschnitts ab. {npc:211022} führt die Bibliothek im {object:36082}. Er bietet die Quest jedes Buchs an, solange das Buch in deinen Taschen ist: Nimm sie an und gib sie ab, eine nach der anderen, damit dein Questlog frei bleibt. Überspringe die Bücher, die du nicht gefunden hast.",
		["Hand in this part's books. {npc:211033} keeps the library at the top of the Wizard's Sanctum in the {object:2101}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Gib die Bücher dieses Abschnitts ab. {npc:211033} führt die Bibliothek oben im Wizard's Sanctum im {object:2101}. Er bietet die Quest jedes Buchs an, solange das Buch in deinen Taschen ist: Nimm sie an und gib sie ab, eine nach der anderen, damit dein Questlog frei bleibt. Überspringe die Bücher, die du nicht gefunden hast.",
		["In the troll ruins of {area:353}, in the south of the {zone:1425}."] = "In den Trollruinen von {area:353}, im Süden der {zone:1425}.",
		["Inside a crypt near the middle of the zone, reached from the path to its south."] = "In einer Gruft nahe der Mitte des Gebiets, erreichbar über den Pfad südlich davon.",
		["Inside a hut on the {area:2097} mesa."] = "In einer Hütte auf dem Plateau {area:2097}.",
		["Inside the first tower of the ogre fort at {area:1357}, in the middle of the zone."] = "Im ersten Turm der Ogerfestung bei {area:1357}, in der Mitte der Zone.",
		["Inside {area:254}, not in a dungeon: the book lies on the altar in {npc:8888}'s tomb, near {npc:14387}. The waypoint marks the mountain."] = "Innerhalb von {area:254}, nicht in einem Dungeon: Das Buch liegt auf dem Altar im Grab von {npc:8888}, nahe {npc:14387}. Der Wegpunkt markiert den Berg.",
		["Level 60 books: {area:1769}"] = "Bücher der Stufe 60: {area:1769}",
		["Level 60 books: {area:2255}"] = "Bücher der Stufe 60: {area:2255}",
		["Level 60 books: {area:254}"] = "Bücher der Stufe 60: {area:254}",
		["Level 60 books: {zone:1422}"] = "Bücher der Stufe 60: {zone:1422}",
		["Level 60 books: {zone:1423}"] = "Bücher der Stufe 60: {zone:1423}",
		["Library Books"] = "Bibliotheksbücher",
		["Lost books and scrolls all over the world: each pays experience at the library, and 10, 20 and 25 of them earn a necklace, a ring and an off-hand."] = "Verlorene Bücher und Schriftrollen überall auf der Welt: Jedes bringt in der Bibliothek Erfahrung, und 10, 20 und 25 davon bringen eine Halskette, einen Ring und eine Nebenhand.",
		["On a barrel in a tent at {area:2537}, in the far south-east of the zone."] = "Auf einem Fass in einem Zelt bei {area:2537}, im äußersten Südosten des Gebiets.",
		["On a bench beside the {area:310} entrance, in the middle of the zone."] = "Auf einer Bank neben dem Eingang der {area:310}, mitten im Gebiet.",
		["On a bookshelf in the middle building of the pirate camp on the eastern coast."] = "In einem Bücherregal im mittleren Gebäude des Piratenlagers an der Ostküste.",
		["On a crate in the {area:1236}, in the far west of {zone:1447}."] = "Auf einer Kiste im {area:1236}, im äußersten Westen von {zone:1447}.",
		["On a shelf in {area:159}'s apothecary."] = "Auf einem Regal in der Apotheke von {area:159}.",
		["On a table inside a tent near the middle of the zone."] = "Auf einem Tisch in einem Zelt nahe der Mitte des Gebiets.",
		["On the ground at the eastern side of the murloc camp in north-eastern Dustwallow."] = "Auf dem Boden an der Ostseite des Murlocs-Lagers im Nordosten der Düstermarschen.",
		["On the top walkway of the {area:1477}, outside the dungeon."] = "Auf dem obersten Laufsteg des {area:1477}, vor dem Dungeon.",
		["Rumi of Gnomeregan"] = "Rumi of Gnomeregan",
		["Scrolls in the Mo'grosh ogre cave in the north-east. The ogres in the cave are level 18-19 elites: grouping up is advised. (Rumi of Gnomeregan also lies in {area:144}, if you missed it at {area:108}.)"] = "Schriftrollen in der Höhle der Mo'grosh-Oger im Nordosten. Die Oger in der Höhle sind Elites der Stufe 18-19: Eine Gruppe wird empfohlen. (Rumi of Gnomeregan liegt auch in {area:144}, falls du es bei {area:108} verpasst hast.)",
		["The level 60 books: {npc:5497}"] = "Die Bücher der Stufe 60: {npc:5497}",
		["The level 60 books: {npc:7825}"] = "Die Bücher der Stufe 60: {npc:7825}",
		["The library: first books"] = "Die Bibliothek: erste Bücher",
		["The library: first books (Horde)"] = "Die Bibliothek: erste Bücher (Horde)",
		["The library: second books"] = "Die Bibliothek: zweite Bücher",
		["The library: second books (Horde)"] = "Die Bibliothek: zweite Bücher (Horde)",
		["The library: third books"] = "Die Bibliothek: dritte Bücher",
		["The library: third books (Horde)"] = "Die Bibliothek: dritte Bücher (Horde)",
		["The scrolls lie underground, in the cave below {area:387} by the {area:718} entrance, not inside the dungeon. Go in at the cave mouth in the oasis and follow the cave down; the arrow points at the scrolls from the surface."] = "Die Schriftrollen liegen unterirdisch, in der Höhle unter {area:387} beim Eingang der {area:718}, nicht im Dungeon selbst. Geh am Höhleneingang in der Oase hinein und folge der Höhle nach unten; der Pfeil zeigt von der Oberfläche auf die Schriftrollen.",
		["The second {quest:79536}"] = "Die zweite {quest:79536}",
		["The spellbook lies in the {area:2098}, the crypt in north-western {zone:1431}. Undead fill it; a corpse run works if you are low."] = "Das Zauberbuch liegt in den {area:2098}, der Gruft im Nordwesten von {zone:1431}. Untote füllen sie; ein Leichenlauf funktioniert, wenn du wenig Leben hast.",
		["The {area:718}' cave"] = "Die Höhle der {area:718}",
		["The {object:405149} is the stone tablet leaning against the wall in the {object:172961}, on the way to the mage trainers. Use it to take the book."] = "Der {object:405149} ist die Steintafel, die im {object:172961} an der Wand lehnt, auf dem Weg zu den Magierlehrern. Benutze sie, um das Buch zu nehmen.",
		["Two books: one in a house at {area:20}, one at {area:108} (Alliance only)."] = "Zwei Bücher: eines in einem Haus bei {area:20}, eines bei {area:108} (nur Allianz).",
		["Two books: the manual in the control room at the top of the oil rig at the {area:382}, and the {object:407566} beside Gazlowe in {area:392}."] = "Zwei Bücher: das Handbuch im Kontrollraum oben auf der Ölplattform im {area:382} und der {object:407566} neben Gazlowe in {area:392}.",
		["With 10 different books handed in, the librarian offers {quest:78150}: a choice of two necklaces ({item:277203} or {item:277204}). Take it when it appears."] = "Wenn du 10 verschiedene Bücher abgegeben hast, bietet der Bibliothekar {quest:78150} an: eine Auswahl aus zwei Halsketten ({item:277203} oder {item:277204}). Nimm sie an, sobald sie erscheint.",
		["{item:228133} lies inside {area:254}, in the mine passage towards {area:1584} beyond the {area:2717} quest giver. The waypoint marks the mountain."] = "{item:228133} liegt im {area:254}, im Minengang Richtung {area:1584}, hinter dem Questgeber von {area:2717}. Der Wegpunkt markiert den Berg.",
		["{item:228134} lies inside the {area:1769} tunnel between {zone:1448} and {zone:1452}."] = "{item:228134} liegt im Tunnel {area:1769} zwischen {zone:1448} und {zone:1452}.",
		["{item:228135} is inside {area:2268}. {item:228138} lies at {area:2264}; other copies lie elsewhere in the zone (one by the {area:2279} gates), and you can take only one. {item:228140} is on a table in {area:2277}: wait for the patrolling elite to clear the creatures beside it and walk on."] = "{item:228135} liegt in {area:2268}. {item:228138} liegt bei {area:2264}; weitere Exemplare liegen anderswo in der Zone (eines bei den Toren von {area:2279}), und du kannst nur eines nehmen. {item:228140} liegt auf einem Tisch in {area:2277}: Warte, bis der patrouillierende Elite die Kreaturen daneben beseitigt hat, und geh weiter.",
		["{item:228136} sits on a shelf behind the alchemy supplier in {area:2255}."] = "{item:228136} steht in einem Regal hinter dem Alchemie-Händler in {area:2255}.",
		["{npc:5497}, the mage trainer beside {npc:211033} in the Wizard's Sanctum, takes the level 60 books: she offers each book's quest while the book is in your bags. Hand in {item:228132}, {item:228138} and {item:228140} the same way (their quests are not in Polestar's data yet)."] = "{npc:5497}, die Magierlehrerin neben {npc:211033} im Wizard's Sanctum, nimmt die Bücher der Stufe 60 an: Sie bietet die Quest jedes Buchs an, solange das Buch in deinen Taschen ist. Gib {item:228132}, {item:228138} und {item:228140} auf dieselbe Weise ab (ihre Quests sind noch nicht in den Daten von Polestar).",
		["{npc:7825}, beside {npc:211022} in the {object:36082}, takes the level 60 books: each book's quest is offered while the book is in your bags. Take and hand them in one at a time (Polestar cannot track these quests for the Horde yet)."] = "{npc:7825}, neben {npc:211022} im {object:36082}, nimmt die Bücher der Stufe 60 an: Die Quest jedes Buchs wird angeboten, solange das Buch in deinen Taschen ist. Nimm sie an und gib sie ab, eine nach der anderen (Polestar kann diese Quests für die Horde noch nicht verfolgen).",
} end)()
t.guides["forever/miscellaneous/stalk-with-the-earthmother"] = (function() return {
		["A one-hand blade or mace at 11 from {npc:205729}'s three tests in and around {zone:1456}, for a Tauren of any class."] = "Eine Einhandklinge oder ein Einhandstreitkolben auf Stufe 11 durch die drei Prüfungen von {npc:205729} in und um {zone:1456}, für einen Tauren jeder Klasse.",
		["Back to {npc:205729} in {zone:1456}. He gives you the {item:206176} for his next test."] = "Zurück zu {npc:205729} in {zone:1456}. Er gibt dir den {item:206176} für seine nächste Prüfung.",
		["Back to {npc:205729}. He hands you the {item:206344} for the last test."] = "Zurück zu {npc:205729}. Er gibt dir das {item:206344} für die letzte Prüfung.",
		["Buy a {item:6291} at the Auction House ({npc:8674}, north of the pool), or fish one yourself: {npc:3028} trains {skill:356} and {npc:3029} beside him sells the {item:6256} and a {item:6529}; the pool on the main mesa gives smallfish at any skill. Then use the {item:206344} on it, wherever you are."] = "Kaufe einen {item:6291} im Auktionshaus ({npc:8674}, nördlich des Teichs) oder angle dir einen selbst: {npc:3028} bildet in {skill:356} aus, und {npc:3029} neben ihm verkauft die {item:6256} und einen {item:6529}; der Teich auf der Hauptmesa gibt Fischlein bei jeder Fertigkeit. Benutze dann das {item:206344} an ihm, wo immer du bist.",
		["Ride down the lift and south-east across {zone:1412} to the {area:360}. Put on the disguise, then open the carts of {object:403041} inside the mine and on the slope outside it; stay on the upper levels where you can, the lower tunnels are packed. Five charges."] = "Fahr mit dem Aufzug nach unten und reite durch {zone:1412} nach Südosten zur {area:360}. Zieh die Verkleidung an, öffne dann die Loren mit {object:403041} in der Mine und am Hang davor; bleib möglichst auf den oberen Ebenen, die unteren Tunnel sind überfüllt. Fünf Ladungen.",
		["Take your weapon from {npc:205729}: the {item:277988} or the {item:278002}."] = "Nimm deine Waffe von {npc:205729}: die {item:277988} oder den {item:278002}.",
		["Windfury Cones"] = "Windfury Cones",
		["Windfury Cones lie on the ground under the harpies' nest trees on {area:819}, north-west of {zone:1456}; the harpies do not drop them. The Windfury Sorceresses (level 9-10) and Matriarchs (10-11) there stand close together: pick the cones from the edges. Once you have eight, use the {item:206176} to grind them."] = "Windfury Cones liegen am Boden unter den Nestbäumen der Harpyien auf {area:819}, nordwestlich von {zone:1456}; die Harpyien lassen sie nicht fallen. Die Windfury Sorceresses (Stufe 9-10) und Matriarchs (10-11) dort stehen dicht beieinander: Sammle die Zapfen an den Rändern auf. Hast du acht, zermahle sie mit dem {item:206176}.",
		["fillet the smallfish into {item:206345} (where players did it, on the way back to {npc:205729})"] = "filetiere das Fischlein zu {item:206345} (dort, wo Spieler es taten, auf dem Rückweg zu {npc:205729})",
		["grind the eight cones into the {item:206175}"] = "zermahle die acht Zapfen im {item:206175}",
		["the mortar takes all eight"] = "der Mörser nimmt alle acht",
		["{item:206157}, from the {object:403041}"] = "{item:206157}, von den {object:403041}",
		["{item:6291}: the Auction House, or the pool; the knife takes it"] = "{item:6291}: das Auktionshaus oder der Teich; das Messer nimmt ihn",
		["{npc:205729} hides in stealth on the main mesa of {zone:1456}, south of its pool: walk to where the arrow points until his outline shows. He hands you the {item:206159}. The quest opens at level 4, but the mine holds Venture Co. Workers (level 8-9), Supervisors (9-10) and {npc:3051} (12): go at 9 or 10."] = "{npc:205729} versteckt sich getarnt auf der Hauptmesa von {zone:1456}, südlich des Teichs: Geh dorthin, wohin der Pfeil zeigt, bis seine Umrisse sichtbar werden. Er gibt dir die {item:206159}. Die Quest beginnt auf Stufe 4, aber in der Mine sind Venture Co. Workers (Stufe 8-9), Supervisors (9-10) und {npc:3051} (12): Geh mit Stufe 9 oder 10.",
} end)()
t.guides["forever/miscellaneous/the-drowned-city-alliance"] = (function() return {
		["A dungeon for five players of level 35 to 42. Meet your group at its entrance in {area:17853}, under the {area:104}: due west of {object:3202} and south-west of the reef's tablet. {object:3202} is the Horde's camp: keep clear of its guards. Water breathing helps."] = "Ein Dungeon für fünf Spieler der Stufe 35 bis 42. Triff deine Gruppe an seinem Eingang in {area:17853}, unter dem {area:104}: genau westlich von {object:3202} und südwestlich der Tafel des Riffs. {object:3202} ist das Lager der Horde: Halte Abstand zu seinen Wachen. Wasseratmung hilft.",
		["At the {area:99} in northern Stranglethorn."] = "Am {area:99} im Norden des Schlingendorntals.",
		["Brinescale Explorers and Sorceresses guard the way to {npc:258924}, the second boss. The second tablet is close to him. No Alliance quest asks for him, but once he is dead, disrupt the barrier close to where he fell; you do it once more after {npc:260042}."] = "Salzschuppen-Kundschafter und -Zaubererinnen bewachen den Weg zu {npc:258924}, dem zweiten Boss. Die zweite Tafel liegt nahe bei ihm. Keine Quest der Allianz fragt nach ihm, aber wenn er gestorben ist, störe die Barriere nahe der Stelle, an der er gefallen ist; das machst du nach {npc:260042} noch einmal.",
		["Every Alliance quest of the {area:16550} in one run, lead-ins included."] = "Jede Quest der Allianz in {area:16550} in einem Durchlauf, mit den Vorquests.",
		["First tablet"] = "Erste Tafel",
		["I'lalai Fetishes"] = "I'lalai-Fetische",
		["In the {object:32356}."] = "In {object:32356}.",
		["In {area:271}."] = "In {area:271}.",
		["In {area:279}."] = "In {area:279}.",
		["In {area:279}. He gives this from level 34."] = "In {area:279}. Er gibt dies ab Stufe 34.",
		["In {area:35}. Both factions take his two quests, from level 34."] = "In {area:35}. Beide Fraktionen nehmen seine zwei Quests an, ab Stufe 34.",
		["Once you have the ten artifacts."] = "Sobald du die zehn Artefakte hast.",
		["One pass through the pirates may give fewer than ten: {npc:773} takes the quest whenever you have them."] = "Ein Durchlauf durch die Räuber kann weniger als zehn bringen: {npc:773} nimmt die Quest an, sobald du sie hast.",
		["Past the Champions of the Deep, {npc:260202} fights with his guardians. He drops the idol."] = "Hinter den Champions der Tiefe kämpft {npc:260202} mit seinen Wächtern. Er lässt das Götzenbild fallen.",
		["Past the Makrura Snappers and Chasm Crawlers waits {npc:258905}, the first boss. The first tablet comes soon after him: click it for the rubbing."] = "Hinter den Makrura-Schnappkrebsen und Schluchtkrabblern erwartet dich {npc:258905}, der erste Boss. Die erste Tafel kommt kurz nach ihm: Klicke sie für die Abreibung an.",
		["Risen Sentries, Profane Necromancers and Undying Offerings drop them."] = "Auferstandene Wachen, Profane Nekromanten und Unsterbliche Opfergaben lassen sie fallen.",
		["Skullsplitter trolls"] = "Skullsplitter-Trolle",
		["South-east of the {area:99}. The medicine men, headshrinkers and witch doctors drop the remedies; the {item:2634} is in the {object:263}."] = "Südöstlich des {area:99}. Die Medizinmänner, Kopfschrumpfer und Hexendoktoren lassen die Heilmittel fallen; {item:2634} ist in {object:263}.",
		["The Saltseer pirates hold his ground: Murderers, Manhunters, Cultists and Coroners, and any of them can drop an artifact. The third tablet is among them, before you reach the captain. After he dies, disrupt the barrier a second time."] = "Die Salzhorer-Räuber halten ihr Gebiet: Mörder, Menschenjäger, Kultisten und Leichenschauer, und jeder von ihnen kann ein Artefakt fallen lassen. Die dritte Tafel ist bei ihnen, bevor du den Kapitän erreichst. Nachdem er gestorben ist, störst du die Barriere ein zweites Mal.",
		["The Skullsplitter mystics (level 39 to 40) and witch doctors (41 to 42) in the middle of Stranglethorn drop the fetishes."] = "Die Mystiker der Schädelsplitter (Stufe 39 bis 40) und Hexendoktoren (41 bis 42) in der Mitte des Schlingendorntals lassen die Fetische fallen.",
		["The last boss. The fourth tablet is near him, and its rubbing still counts after he dies."] = "Der letzte Boss. Die vierte Tafel liegt nahe bei ihm, und ihre Abreibung zählt auch nach seinem Tod.",
		["To the {area:16550}"] = "Nach {area:16550}",
		["{area:16550} (Alliance)"] = "{area:16550} (Allianz)",
		["{item:2005}, in the {area:123} north-east of the reef."] = "{item:2005}, in den {area:123} nordöstlich des Riffs.",
		["{item:2006}, further south: the tablet lies on the sea floor of the {area:104}. Mind your breath."] = "{item:2006}, weiter südlich: die Tafel liegt auf dem Meeresgrund des {area:104}. Achte auf deinen Atem.",
		["{item:2007}, a little south-west in the same ruins."] = "{item:2007}, etwas südwestlich in denselben Ruinen.",
		["{item:2008}, west of the {area:99} in the {area:102}, on the hill in the north-west."] = "{item:2008}, westlich des {area:99} in den {area:102}, auf dem Hügel im Nordwesten.",
} end)()
t.guides["forever/miscellaneous/the-drowned-city-horde"] = (function() return {
		["A dungeon for five players of level 35 to 42. Meet your group at its entrance in {area:17853}, under the {area:104}: from the shore west of {object:3202}, swim due west. Water breathing helps."] = "Ein Dungeon für fünf Spieler der Stufe 35 bis 42. Triff deine Gruppe an seinem Eingang in {area:17853}, unter dem {area:104}: Schwimm vom Ufer westlich von {object:3202} genau nach Westen. Wasseratmung hilft.",
		["Brinescale Explorers and Sorceresses guard the way to {npc:258924}, the second boss. The second tablet is close to him. Once he is dead, disrupt the barrier close to where he fell; you do it once more after {npc:260042}."] = "Salzschuppen-Kundschafter und -Zaubererinnen bewachen den Weg zu {npc:258924}, dem zweiten Boss. Die zweite Tafel liegt nahe bei ihm. Sobald er gestorben ist, störe die Barriere nahe der Stelle, an der er gefallen ist; das machst du nach {npc:260042} noch einmal.",
		["Brinescale Skirmishers around the {area:104} drop the tridents. The cavern entrance the quest asks for is under the reef, in {area:17853}: due west of {object:3202} and south-west of the reef's tablet."] = "Salzschuppen-Kämpfer um das {area:104} lassen die Dreizacke fallen. Der Höhleneingang, den die Quest verlangt, liegt unter dem Riff, in {area:17853}: genau westlich von {object:3202} und südwestlich der Tafel des Riffs.",
		["Every Horde quest of the {area:16550} in one run, lead-ins included."] = "Jede Quest der Horde in {area:16550} in einem Durchlauf, mit den Vorquests.",
		["First tablet"] = "Erste Tafel",
		["In the {area:102}, on the hill north of the {area:104}. Click the tablet for the rubbing."] = "In den {area:102}, auf dem Hügel nördlich des {area:104}. Klicke die Tafel für die Abreibung an.",
		["In {area:35}. Both factions take his two quests, from level 34."] = "In {area:35}. Beide Fraktionen nehmen seine zwei Quests an, ab Stufe 34.",
		["Northern {zone:1412}. A long trip, but the idol only drops while his quest is in your log."] = "Im Norden von {zone:1412}. Eine lange Reise, aber das Götzenbild fällt nur, solange seine Quest in deinem Log ist.",
		["Once you have the ten artifacts."] = "Sobald du die zehn Artefakte hast.",
		["One pass through the pirates may give fewer than ten: {npc:773} takes the quest whenever you have them."] = "Ein Durchlauf durch die Räuber kann weniger als zehn bringen: {npc:773} nimmt die Quest an, sobald du sie hast.",
		["Past the Champions of the Deep, {npc:260202} fights with his guardians. He drops the idol."] = "Hinter den Champions der Tiefe kämpft {npc:260202} mit seinen Wächtern. Er lässt das Götzenbild fallen.",
		["Past the Makrura Snappers and Chasm Crawlers waits {npc:258905}, the first boss. The first tablet comes soon after him: click it for the rubbing."] = "Hinter den Makrura-Schnappkrebsen und Schluchtkrabblern erwartet dich {npc:258905}, der erste Boss. Die erste Tafel kommt kurz nach ihm: Klicke sie für die Abreibung an.",
		["The Lost City's entrance"] = "Der Eingang der Verlorenen Stadt",
		["The Saltseer pirates hold his ground: Murderers, Manhunters, Cultists and Coroners, and any of them can drop an artifact. The third tablet is among them, before you reach the captain. After he dies, disrupt the barrier a second time."] = "Die Salzhorer-Räuber halten ihr Gebiet: Mörder, Menschenjäger, Kultisten und Leichenschauer, und jeder von ihnen kann ein Artefakt fallen lassen. Die dritte Tafel ist bei ihnen, bevor du den Kapitän erreichst. Nachdem er gestorben ist, störst du die Barriere ein zweites Mal.",
		["The last boss. The fourth tablet is near him, and its rubbing still counts after he dies."] = "Der letzte Boss. Die vierte Tafel liegt nahe bei ihm, und ihre Abreibung zählt auch nach seinem Tod.",
		["The tablet, {object:58}, lies on the sea floor of the {area:104}, west of {object:3202}. Mind your breath."] = "Die Tafel, {object:58}, liegt auf dem Meeresgrund des {area:104}, westlich von {object:3202}. Achte auf deinen Atem.",
		["To the {area:16550}"] = "Nach {area:16550}",
		["{area:16550} (Horde)"] = "{area:16550} (Horde)",
		["{area:367}, in southern {zone:1411}."] = "{area:367}, im Süden von {zone:1411}.",
} end)()
